public class Solution {
    public int[][] flipAndInvertImage(int[][] image) {
        int n = image.length;
        for (int row = 0; row < n; row++) {
            int[] currentRow = image[row];
            int left = 0;
            int right = n - 1;
            while (left <= right) {
                int leftVal = currentRow[left];
                int rightVal = currentRow[right];
                // Swap and invert
                currentRow[left] = 1 - rightVal;
                currentRow[right] = 1 - leftVal;
                left++;
                right--;
            }
        }
        return image;
    }
}

