import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    /**
     * Returns the number of car fleets that will arrive at the destination.
     *
     * @param target   the distance to the destination
     * @param position array of starting positions of the cars
     * @param speed    array of speeds of the cars
     * @return number of car fleets
     */
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        if (n == 0) {
            return 0;
        }

        // Pair each car's position with its time to reach the target
        Car[] cars = new Car[n];
        for (int i = 0; i < n; i++) {
            double time = (double) (target - position[i]) / speed[i];
            cars[i] = new Car(position[i], time);
        }

        // Sort cars by starting position in descending order (furthest from target first)
        Arrays.sort(cars, Comparator.comparingInt((Car c) -> c.pos).reversed());

        int fleets = 0;
        double lastFleetTime = -1.0;

        // Iterate from the car closest to the target to the farthest
        for (Car car : cars) {
            if (car.time > lastFleetTime) {
                // This car cannot catch up to the fleet ahead; it forms a new fleet
                fleets++;
                lastFleetTime = car.time;
            }
            // else: car joins the current fleet (no action needed)
        }

        return fleets;
    }

    // Helper class to store position and time to reach the target
    private static class Car {
        int pos;
        double time;

        Car(int pos, double time) {
            this.pos = pos;
            this.time = time;
        }
    }
}

