            return 0;
        }
        int n = position.length;
        // Pair each car's position with its time to reach the target
        double[] times = new double[n];
        for (int i = 0; i < n; i++) {
            times[i] = (double) (target - position[i]) / speed[i];
        }

        // Sort cars by starting position in descending order
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) {
            idx[i] = i;
        }
        Arrays.sort(idx, Comparator.comparingInt((Integer i) -> position[i]).reversed());

        int fleets = 0;
        double lastTime = -1.0;
        for (int i : idx) {
            double curTime = times[i];
            // If this car takes longer than the fleet in front, it forms a new fleet
            if (curTime > lastTime) {
                fleets++;
                lastTime = curTime;
            }
            // else it merges into the fleet ahead (no action needed)
        }
        return fleets;
    }
}

