public class Solution {
    public int maxDistToClosest(int[] seats) {
        int maxDist = 0;
        int lastOccupied = -1;
        int n = seats.length;

        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                if (lastOccupied == -1) {
                    // Leading zeros
                    maxDist = i;
                } else {
                    // Middle segment
                    int dist = (i - lastOccupied) / 2;
                    if (dist > maxDist) {
                        maxDist = dist;
                    }
                }
                lastOccupied = i;
            }
        }

        // Trailing zeros
        if (lastOccupied != -1) {
            int trailingDist = n - 1 - lastOccupied;
            if (trailingDist > maxDist) {
                maxDist = trailingDist;
            }
        }

        return maxDist;
    }
}

