        prob += dfs(Math.max(a - 4, 0), b);          // Serve 100 ml A, 0 ml B
        prob += dfs(Math.max(a - 3, 0), Math.max(b - 1, 0)); // Serve 75 ml A, 25 ml B
        prob += dfs(Math.max(a - 2, 0), Math.max(b - 2, 0)); // Serve 50 ml A, 50 ml B
        prob += dfs(Math.max(a - 1, 0), Math.max(b - 3, 0)); // Serve 25 ml A, 75 ml B
        prob *= 0.25; // each operation chosen with equal probability

        memo[a][b] = prob;
