public class Solution {
    public double new21Game(int n, int k, int w) {
        // Edge cases
        if (k == 0) {
            return 1.0;
        }
        // If the maximum possible points after stopping is <= n, probability is 1
        if (n >= k - 1 + w) {
            return 1.0;
        }

        double[] dp = new double[n + 1];
        dp[0] = 1.0;
        double windowSum = 1.0; // sum of probabilities of the last w states that can draw
        double result = 0.0;

        for (int i = 1; i <= n; i++) {
            dp[i] = windowSum / w;

            if (i >= k) {
                // i is a terminal state (Alice stops drawing)
                result += dp[i];
            } else {
                // i is a non‑terminal state, it can contribute to future draws
                windowSum += dp[i];
            }

            // Remove the probability that is now out of the sliding window
            if (i - w >= 0) {
                windowSum -= dp[i - w];
            }
        }

        return result;
    }
}

