public class Solution {
    public int minimumLengthEncoding(String[] words) {
        // Use a set to eliminate duplicates and later remove suffixes
        Set<String> uniqueWords = new HashSet<>(Arrays.asList(words));

        // Remove any word that is a suffix of another word
        for (String word : words) {
            int len = word.length();
            for (int i = 1; i < len; i++) {
                String suffix = word.substring(i);
                uniqueWords.remove(suffix);
            }
        }

        // The length of the encoding is sum of (word length + 1) for each remaining word
        int result = 0;
        for (String w : uniqueWords) {
            result += w.length() + 1; // +1 for the '#' delimiter
        }
        return result;
    }
}

