        int n = arr.length;
        int maxLen = 0;
        int i = 1;
        while (i < n - 1) {
            // check if arr[i] is a peak
            if (arr[i] > arr[i - 1] && arr[i] > arr[i + 1]) {
                int left = i - 1;
                while (left > 0 && arr[left] > arr[left - 1]) {
                    left--;
                }
