public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        // remove outer parentheses
        String inner = s.substring(1, s.length() - 1);
        int n = inner.length();
        // split into left and right parts
        for (int i = 1; i < n; i++) {
            String leftPart = inner.substring(0, i);
            String rightPart = inner.substring(i);
            List<String> leftCandidates = generateNumbers(leftPart);
            List<String> rightCandidates = generateNumbers(rightPart);
            for (String left : leftCandidates) {
                for (String right : rightCandidates) {
                    result.add("(" + left + ", " + right + ")");
                }
            }
        }
        return result;
    }

    private List<String> generateNumbers(String s) {
        List<String> candidates = new ArrayList<>();
        int len = s.length();

        // single digit numbers are always valid
        if (len == 1) {
            candidates.add(s);
            return candidates;
        }

        // integer without decimal point (no leading zero)
        if (s.charAt(0) != '0') {
            candidates.add(s);
        }

        // decimal numbers
        for (int i = 1; i < len; i++) {
            String left = s.substring(0, i);
            String right = s.substring(i);
            // left part must not have leading zeros unless it is exactly "0"
            if (left.charAt(0) == '0' && left.length() > 1) {
                continue;
            }
            // right part must not have trailing zeros
            if (right.charAt(right.length() - 1) == '0') {
                continue;
            }
            candidates.add(left + "." + right);
        }

        return candidates;
    }
