public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        // remove the outer parentheses
        String inner = s.substring(1, s.length() - 1);
        int n = inner.length();

        // split the string into two non‑empty parts
        for (int i = 1; i < n; i++) {
            String leftPart = inner.substring(0, i);
            String rightPart = inner.substring(i);

            List<String> leftCandidates = generateValidNumbers(leftPart);
            List<String> rightCandidates = generateValidNumbers(rightPart);

            for (String left : leftCandidates) {
                for (String right : rightCandidates) {
                    result.add("(" + left + ", " + right + ")");
                }
            }
        }
        return result;
    }

    // Generate all valid representations (integer or decimal) for a numeric string
    private List<String> generateValidNumbers(String num) {
        List<String> candidates = new ArrayList<>();
        int len = num.length();

        // Single digit numbers are always valid as they are
        if (len == 1) {
            candidates.add(num);
            return candidates;
        }

        boolean startsWithZero = num.charAt(0) == '0';
        boolean endsWithZero = num.charAt(len - 1) == '0';

        // If both start and end with zero, no valid representation
        if (startsWithZero && endsWithZero) {
            return candidates; // empty
        }

        // If starts with zero, only a decimal of the form "0.xxx" is possible
        if (startsWithZero) {
            // decimal part must not end with zero (already ensured by endsWithZero check)
            String decimal = "0." + num.substring(1);
            candidates.add(decimal);
            return candidates;
        }

        // If ends with zero, only the integer representation is allowed
        if (endsWithZero) {
            candidates.add(num); // integer only
            return candidates;
        }

        // General case: integer + all possible decimal placements
        candidates.add(num); // integer form
        for (int i = 1; i < len; i++) {
            String left = num.substring(0, i);
            String right = num.substring(i);
            // right part must not end with zero (already true because overall endsWithZero is false)
            candidates.add(left + "." + right);
        }
        return candidates;
    }
}

