            List<String> rightOptions = generate(rightPart);
            for (String left : leftOptions) {
                for (String right : rightOptions) {
                    result.add("(" + left + ", " + right + ")");
                }
            }
        }
        return result;
    }

    private List<String> generate(String s) {
        List<String> res = new ArrayList<>();
        int len = s.length();
        if (len == 0) {
            return res;
        }
        if (len == 1) {
            res.add(s);
            return res;
        }

        boolean leadingZero = s.charAt(0) == '0';
        boolean trailingZero = s.charAt(len - 1) == '0';

        if (leadingZero && trailingZero) {
            // No valid representation for numbers like "00", "000", etc.
            return res;
        }

        if (leadingZero) {
            // Only possible as "0.xxx" if not trailing zero
            if (!trailingZero) {
                res.add("0." + s.substring(1));
            }
            return res;
        }

        if (trailingZero) {
            // Only integer representation allowed
            res.add(s);
            return res;
        }

        // No leading or trailing zero: integer and all possible decimals
        res.add(s); // integer form
        for (int i = 1; i < len; i++) {
            String left = s.substring(0, i);
            String right = s.substring(i);
            // left part must not have leading zeros unless it is exactly "0"
            if (left.length() > 1 && left.charAt(0) == '0') {
                continue;
            }
            // right part (fractional) must not end with zero
            if (right.charAt(right.length() - 1) == '0') {
                continue;
            }
            res.add(left + "." + right);
        }
        return res;
    }
}

