import java.util.*;

public class Solution {
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return;
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        int getSize(int x) {
            int root = find(x);
            return size[root];
        }
    }

    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        int top = total; // virtual top node index

        // copy original grid
        int[][] copy = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, copy[i], 0, n);
        }

        // Apply hits: mark bricks to be removed
        for (int[] hit : hits) {
            int r = hit[0];
            int c = hit[1];
            if (copy[r][c] == 1) {
                copy[r][c] = 0;
            }
        }

        UnionFind uf = new UnionFind(total + 1);

        // Helper to convert (r,c) to index
        int index(int r, int c) {
            return r * n + c;
        }

        // Initial union of remaining bricks
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (copy[r][c] != 1) continue;
                int curIdx = r * n + c;
                if (r == 0) {
                    uf.union(curIdx, top);
                }
                // union with up and left (to avoid double work)
                if (r > 0 && copy[r - 1][c] == 1) {
                    uf.union(curIdx, (r - 1) * n + c);
                }
                if (c > 0 && copy[r][c - 1] == 1) {
                    uf.union(curIdx, r * n + (c - 1));
                }
            }
        }

        int[] result = new int[hits.length];
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Process hits in reverse
        for (int i = hits.length - 1; i >= 0; i--) {
            int r = hits[i][0];
            int c = hits[i][1];
            // If original grid had no brick, nothing falls
            if (grid[r][c] == 0) {
                result[i] = 0;
                continue;
            }

            int beforeTopSize = uf.getSize(top);

            // Restore brick
            copy[r][c] = 1;
            int curIdx = r * n + c;

            // If on top row, connect to virtual top
            if (r == 0) {
                uf.union(curIdx, top);
            }

            // Union with all 4 neighbors if they are present
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                if (copy[nr][nc] == 1) {
                    uf.union(curIdx, nr * n + nc);
                }
            }

            int afterTopSize = uf.getSize(top);
            // Bricks that fell are the increase in top component size minus the brick we just added
            int fallen = Math.max(0, afterTopSize - beforeTopSize - 1);
            result[i] = fallen;
        }

        return result;
    }
}

