import java.util.*;

public class Solution {
    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        int n = indices.length;
        // Map each index to its source and target
        Map<Integer, Integer> indexToPos = new HashMap<>();
        for (int i = 0; i < n; i++) {
            indexToPos.put(indices[i], i);
        }
        // Sort the indices to process from left to right
        int[] sorted = indices.clone();
        Arrays.sort(sorted);
        StringBuilder sb = new StringBuilder();
        int cur = 0;
        for (int idx : sorted) {
            int pos = indexToPos.get(idx);
            String src = sources[pos];
            String tgt = targets[pos];
            // If the source matches at this position, perform replacement
            if (s.startsWith(src, idx)) {
                // Append unchanged part
                sb.append(s, cur, idx);
                // Append target
                sb.append(tgt);
                // Move current pointer past the source substring
                cur = idx + src.length();
            }
        }
        // Append any remaining part of the original string
        sb.append(s.substring(cur));
        return sb.toString();
    }
}

