import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        // Map each index to its operation position
        Map<Integer, Integer> indexToOp = new HashMap<>();
        for (int i = 0; i < indices.length; i++) {
            indexToOp.put(indices[i], i);
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            if (indexToOp.containsKey(i)) {
                int opIdx = indexToOp.get(i);
                String src = sources[opIdx];
                String tgt = targets[opIdx];
                // Check if source matches substring starting at i
                if (i + src.length() <= s.length() && s.substring(i, i + src.length()).equals(src)) {
                    result.append(tgt);
                    i += src.length();
                    continue;
                }
            }
            // No replacement at this position
            result.append(s.charAt(i));
            i++;
        }
        return result.toString();
    }
}

