public class Solution {
    public int surfaceArea(int[][] grid) {
        int n = grid.length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int v = grid[i][j];
                if (v > 0) {
                    // top and bottom faces
                    total += 2;
                    // four side faces
                    total += 4 * v;
                    // subtract shared faces with north neighbor
                    if (i > 0) {
                        total -= 2 * Math.min(v, grid[i - 1][j]);
                    }
                    // subtract shared faces with west neighbor
                    if (j > 0) {
                        total -= 2 * Math.min(v, grid[i][j - 1]);
                    }
                }
            }
        }
        return total;
    }
}

