    public int[][] spiralMatrixIII(int rows, int cols, int y, int x) {
        int total = rows * cols;
        int[][] result = new int[total][2];
        int count = 0;

        // Starting position
        int r = y;
        int c = x;

        // Directions: east, south, west, north
        int[] dr = {0, 1, 0, -1};
        int[] dc = {1, 0, -1, 0};

        // Add starting cell if inside grid
        if (r >= 0 && r < rows && c >= 0 && c < cols) {
            result[count][0] = r;
            result[count][1] = c;
            count++;
        }

        int step = 1;          // number of steps in current direction
        int dirIdx = 0;        // index in direction arrays

        while (count < total) {
            // For each pair of directions we increase the step length
            for (int i = 0; i < 2; i++) {
                int curDir = dirIdx % 4;
                for (int s = 0; s < step; s++) {
                    r += dr[curDir];
                    c += dc[curDir];
                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        result[count][0] = r;
                        result[count][1] = c;
                        count++;
                        if (count == total) {
                            break;
                        }
                    }
                }
                dirIdx++;
                if (count == total) {
                    break;
                }
            }
            step++;
        }

        return result;
    }
}

