public class Solution {
    public boolean backspaceCompare(String s, String t) {
        int i = s.length() - 1;
        int j = t.length() - 1;

        while (i >= 0 || j >= 0) {
            i = getNextValidCharIndex(s, i);
            j = getNextValidCharIndex(t, j);

            if (i < 0 && j < 0) {
                return true; // both strings are traversed completely
            }
            if (i < 0 || j < 0) {
                return false; // one string finished before the other
            }
            if (s.charAt(i) != t.charAt(j)) {
                return false; // mismatch
            }
            i--;
            j--;
        }
        return true;
    }

    private int getNextValidCharIndex(String str, int index) {
        int backspaceCount = 0;
        while (index >= 0) {
            if (str.charAt(index) == '#') {
                backspaceCount++;
                index--;
            } else if (backspaceCount > 0) {
                backspaceCount--;
                index--;
            } else {
                break;
            }
        }
        return index;
    }
}

