public class Solution {
    public String pushDominoes(String dominoes) {
        int n = dominoes.length();
        char[] arr = dominoes.toCharArray();
        StringBuilder result = new StringBuilder();

        char prev = 'L';          // virtual domino to the left
        int prevPos = -1;         // position of the previous non‑dot

        for (int i = 0; i <= n; i++) {
            char cur;
            boolean sentinel = false;
            if (i == n) {
                cur = 'R';        // virtual domino to the right
                sentinel = true;
            } else {
                cur = arr[i];
                if (cur == '.') {
                    continue;
                }
            }

            if (prev == cur) {
                // same direction: fill everything between with that direction
                for (int k = prevPos + 1; k < i; k++) {
                    result.append(prev);
                }
            } else if (prev == 'L' && cur == 'R') {
                // opposite directions, forces cancel: fill with dots
                for (int k = prevPos + 1; k < i; k++) {
                    result.append('.');
                }
            } else { // prev == 'R' && cur == 'L'
                int left = prevPos + 1;
                int right = i - 1;
                while (left < right) {
                    result.append('R');
                    left++;
                    result.append('L');
                    right--;
                }
                if (left == right) {
                    result.append('.');
                }
            }

            if (!sentinel) {
                result.append(cur);
            }

            prev = cur;
            prevPos = i;
        }

        return result.toString();
    }
}

