public class Solution {
    public String pushDominoes(String dominoes) {
        if (dominoes == null || dominoes.length() == 0) {
            return dominoes;
        }
        // Add sentinel characters to simplify handling of edge segments
        String extended = "L" + dominoes + "R";
        char[] arr = extended.toCharArray();
        StringBuilder sb = new StringBuilder();
        int prev = 0; // index of previous non '.' character (sentinel at position 0)

        for (int cur = 1; cur < arr.length; cur++) {
            if (arr[cur] == '.') {
                continue;
            }
            int dots = cur - prev - 1; // number of '.' between prev and cur

            // Append the character at prev (skip the left sentinel)
            if (prev > 0) {
                sb.append(arr[prev]);
            }

            if (arr[prev] == arr[cur]) {
                // Same direction, fill all with that direction
                for (int k = 0; k < dots; k++) {
                    sb.append(arr[prev]);
                }
            } else if (arr[prev] == 'L' && arr[cur] == 'R') {
                // Opposite directions, middle stays vertical
                for (int k = 0; k < dots; k++) {
                    sb.append('.');
                }
            } else { // arr[prev] == 'R' && arr[cur] == 'L'
                // They meet, fill half R, possibly a '.' in the middle, then half L
                int half = dots / 2;
                for (int k = 0; k < half; k++) {
                    sb.append('R');
                }
                if (dots % 2 == 1) {
                    sb.append('.');
                }
                for (int k = 0; k < half; k++) {
                    sb.append('L');
                }
            }

            prev = cur; // move to next segment
        }

        // The loop adds characters for all original positions (excluding the right sentinel)
        // The right sentinel itself is not appended, so the built string length equals original length
        return sb.toString();
    }
}

