            // there is a segment between left and right
            if (arr[left] == arr[right]) {
                // same direction, fill all with that direction
                for (int k = left + 1; k < right; k++) {
                    arr[k] = arr[left];
                }
            } else if (arr[left] == 'R' && arr[right] == 'L') {
                // opposite directions, fill from both sides
                int l = left + 1;
                int r = right - 1;
                while (l < r) {
                    arr[l++] = 'R';
                    arr[r--] = 'L';
                }
                // if l == r, middle stays '.' (balanced)
            } // else left='L' and right='R' -> stay '.' (no change)
            left = right;
