public class Solution {
    public String pushDominoes(String dominoes) {
        String s = "L" + dominoes + "R";
        char[] arr = s.toCharArray();
        int n = arr.length;
        char[] res = new char[n];
        int i = 0;
        while (i < n) {
            int j = i + 1;
            while (j < n && arr[j] == '.') {
                j++;
            }
            // now arr[i] and arr[j] are not '.'
            if (i + 1 == j) {
                // no '.' between
                res[i] = arr[i];
            } else {
                // there are '.' between i and j
                if (arr[i] == arr[j]) {
                    // same direction, fill all with that direction
                    for (int k = i + 1; k < j; k++) {
                        res[k] = arr[i];
                    }
                } else if (arr[i] == 'L' && arr[j] == 'R') {
                    // forces away from each other, remain upright
                    for (int k = i + 1; k < j; k++) {
                        res[k] = '.';
                    }
                } else { // arr[i] == 'R' && arr[j] == 'L'
                    int left = i + 1;
                    int right = j - 1;
                    while (left < right) {
                        res[left++] = 'R';
                        res[right--] = 'L';
                    }
                    if (left == right) {
                        res[left] = '.';
                    }
                }
                res[i] = arr[i];
            }
            i = j;
        }
        // set the last sentinel character
        res[n - 1] = arr[n - 1];
        // extract the result without the added sentinels
        return new String(res, 1, dominoes.length());
    }
