import java.util.PriorityQueue;
import java.util.Collections;

public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        // Max-heap to store fuels of stations we have passed
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        int refuels = 0;
        int prevPosition = 0;
        int fuel = startFuel;

        for (int[] station : stations) {
            int distance = station[0];
            // Need enough fuel to reach this station
            while (fuel < distance - prevPosition) {
                if (maxHeap.isEmpty()) {
                    return -1;
                }
                fuel += maxHeap.poll();
                refuels++;
            }
            // Travel to the station
            fuel -= (distance - prevPosition);
            prevPosition = distance;
            // Add this station's fuel to the heap
            maxHeap.offer(station[1]);
        }

        // After all stations, try to reach the target
        while (fuel < target - prevPosition) {
            if (maxHeap.isEmpty()) {
                return -1;
            }
            fuel += maxHeap.poll();
            refuels++;
        }

        return refuels;
    }
}

