        List<List<Integer>> graph = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] pair : dislikes) {
            int a = pair[0];
            int b = pair[1];
            graph.get(a).add(b);
            graph.get(b).add(a);
        }

        // 0 = uncolored, 1 = color A, -1 = color B
        int[] colors = new int[n + 1];

        // Check each connected component
        for (int i = 1; i <= n; i++) {
            if (colors[i] != 0) {
                continue; // already colored
