            while (!queue.isEmpty()) {
                int cur = queue.poll();
                int curColor = colors[cur];
                int oppositeColor = -curColor;

                for (int neighbor : graph.get(cur)) {
                    if (colors[neighbor] == 0) {
                        colors[neighbor] = oppositeColor;
                        queue.offer(neighbor);
                    } else if (colors[neighbor] != oppositeColor) {
                        // Conflict found: adjacent nodes have same color
                        return false;
                    }
