public class Solution {
    public int consecutiveNumbersSum(int n) {
        // Remove all factors of 2 from n; the remaining odd part determines the count
        long oddPart = n;
        while ((oddPart & 1L) == 0) {
            oddPart >>= 1;
        }

        int count = 0;
        long sqrt = (long) Math.sqrt(oddPart);
        for (long i = 1; i <= sqrt; i++) {
            if (oddPart % i == 0) {
                long j = oddPart / i;
                if (i == j) {
                    count += 1; // perfect square contributes one divisor pair
                } else {
                    count += 2; // i and j are distinct divisors
                }
            }
        }
        return count;
    }
}

