        int side = 0;

        // top view: count cells with value > 0
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    top++;
                }
            }
        }

        // front view (yz plane): max in each row
        for (int i = 0; i < n; i++) {
            int rowMax = 0;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > rowMax) {
                    rowMax = grid[i][j];
                }
            }
            front += rowMax;
        }

        // side view (zx plane): max in each column
        for (int j = 0; j < n; j++) {
            int colMax = 0;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] > colMax) {
                    colMax = grid[i][j];
                }
            }
            side += colMax;
        }

        return top + front + side;
    }
}

