public class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        // Pair difficulty with profit
        int[][] jobs = new int[n][2];
        for (int i = 0; i < n; i++) {
            jobs[i][0] = difficulty[i];
            jobs[i][1] = profit[i];
        }
        // Sort jobs by difficulty ascending
        Arrays.sort(jobs, Comparator.comparingInt(a -> a[0]));

        // Build arrays of difficulty and max profit up to that difficulty
        int[] diffSorted = new int[n];
        int[] maxProfitUpTo = new int[n];
        int maxProfit = 0;
        for (int i = 0; i < n; i++) {
            diffSorted[i] = jobs[i][0];
            maxProfit = Math.max(maxProfit, jobs[i][1]);
            maxProfitUpTo[i] = maxProfit;
        }

        // Sort workers to possibly improve cache locality (optional)
        Arrays.sort(worker);

        long total = 0;
        for (int ability : worker) {
            int idx = binarySearch(diffSorted, ability);
            if (idx >= 0) {
                total += maxProfitUpTo[idx];
            }
        }
        return (int) total;
    }

    // Returns the index of the greatest value <= target, or -1 if none
    private int binarySearch(int[] arr, int target) {
        int lo = 0, hi = arr.length - 1, ans = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (arr[mid] <= target) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
}

