public class Solution {
    public int maxIncreaseKeepingSkyline(int[][] grid) {
        int n = grid.length;
        int[] rowMax = new int[n];
        int[] colMax = new int[n];

        // Compute max for each row and column
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int val = grid[r][c];
                if (val > rowMax[r]) rowMax[r] = val;
                if (val > colMax[c]) colMax[c] = val;
            }
        }

        int totalIncrease = 0;
        // Calculate possible increase for each building
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int allowedHeight = Math.min(rowMax[r], colMax[c]);
                totalIncrease += allowedHeight - grid[r][c];
            }
        }
        return totalIncrease;
    }
}

