import com_github_leetcode.TreeNode;
import java.util.Stack;

public class Solution {
    public TreeNode increasingBST(final TreeNode root) {
        if (root == null) {
            return null;
        }
        Stack<TreeNode> stack = new Stack<>();
        TreeNode node = root;
        TreeNode dummy = new TreeNode(0);
        TreeNode cur = dummy;

        while (!stack.isEmpty() || node != null) {
            while (node != null) {
                stack.push(node);
                node = node.left;
            }
            node = stack.pop();
            // detach left child
            node.left = null;
            // attach to the right of current node
            cur.right = node;
            cur = node;
            // move to right subtree
            node = node.right;
        }
        return dummy.right;
    }
}

