import java.util.Set;
import java.util.Arrays;

public class Solution {
    private static final Set<String> POWER_OF_TWO_DIGIT_SIGNATURES = new HashSet<>();

    static {
        // Pre‑compute the sorted digit signatures of all powers of two that fit in an int.
        // 2^0 = 1 up to 2^30 = 1073741824 (10 digits). 2^31 exceeds int range.
        for (int i = 0; i < 31; i++) {
            int pow = 1 << i; // 2^i
            char[] chars = Integer.toString(pow).toCharArray();
            Arrays.sort(chars);
            POWER_OF_TWO_DIGIT_SIGNATURES.add(new String(chars));
        }
    }

    public boolean reorderedPowerOf2(int n) {
        char[] chars = Integer.toString(n).toCharArray();
        Arrays.sort(chars);
        String signature = new String(chars);
        return POWER_OF_TWO_DIGIT_SIGNATURES.contains(signature);
    }
}

