public class Solution {
    public String orderlyQueue(String s, int k) {
        if (k == 1) {
            return minimalRotation(s);
        } else {
            char[] arr = s.toCharArray();
            Arrays.sort(arr);
            return new String(arr);
        }
    }

    private String minimalRotation(String s) {
        int n = s.length();
        String ss = s + s;
        int i = 0, j = 1, offset = 0;
        while (i < n && j < n && offset < n) {
            char a = ss.charAt(i + offset);
            char b = ss.charAt(j + offset);
            if (a == b) {
                offset++;
                continue;
            }
            if (a > b) {
                i = i + offset + 1;
                if (i <= j) {
                    i = j + 1;
                }
            } else {
                j = j + offset + 1;
                if (j <= i) {
                    j = i + 1;
                }
            }
            offset = 0;
        }
        int start = Math.min(i, j);
        return ss.substring(start, start + n);
    }
}

