public class Solution {
    public int primePalindrome(int n) {
        if (n <= 2) return 2;
        if (n <= 3) return 3;
        if (n <= 5) return 5;
        if (n <= 7) return 7;
        if (n <= 11) return 11; // the only even‑length prime palindrome

        // generate odd‑length palindromes up to 9 digits (since answer ≤ 2·10^8)
        for (int len = 1; len <= 9; len++) {
            if (len % 2 == 0) continue; // skip even lengths (except 11 already handled)

            int halfLen = (len + 1) / 2;
            int start = (int) Math.pow(10, halfLen - 1);
            int end = (int) Math.pow(10, halfLen) - 1;

            for (int i = start; i <= end; i++) {
                int pal = makePalindrome(i, len % 2 == 1);
                if (pal < n) continue;
                if (isPrime(pal)) return pal;
            }
        }
        // According to problem constraints this line is never reached.
        return -1;
    }

    // Build palindrome from the left half.
    // If odd is true, the middle digit (last of left half) is not duplicated.
    private int makePalindrome(int left, boolean odd) {
        int result = left;
        int x = odd ? left / 10 : left;
        while (x > 0) {
            result = result * 10 + (x % 10);
            x /= 10;
        }
        return result;
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num % 2 == 0) return num == 2;
        int limit = (int) Math.sqrt(num);
        for (int i = 3; i <= limit; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

