public class Solution {
    private static class Node {
        String str;
        int steps;
        int heuristic;

        Node(String str, int steps, String target) {
            this.str = str;
            this.steps = steps;
            this.heuristic = mismatches(str, target);
        }

        private static int mismatches(String s, String t) {
            int cnt = 0;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) != t.charAt(i)) cnt++;
            }
            return cnt;
        }
    }

    public int kSimilarity(String a, String b) {
        if (a.equals(b)) return 0;
        int n = a.length();

        PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingInt(
                n1 -> n1.steps + n1.heuristic));
        Set<String> visited = new HashSet<>();

        pq.offer(new Node(a, 0, b));
        visited.add(a);

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.str.equals(b)) {
                return cur.steps;
            }

            // find first mismatched position
            int i = 0;
            while (i < n && cur.str.charAt(i) == b.charAt(i)) i++;
            char[] arr = cur.str.toCharArray();

            for (int j = i + 1; j < n; j++) {
                // only consider swaps that fix the character at i
                if (arr[j] == b.charAt(i) && arr[j] != b.charAt(j)) {
                    swap(arr, i, j);
                    String next = new String(arr);
                    if (!visited.contains(next)) {
                        visited.add(next);
                        pq.offer(new Node(next, cur.steps + 1, b));
                    }
                    swap(arr, i, j); // revert
                }
            }
        }
        return -1; // should never reach here because a and b are anagrams
    }

    private void swap(char[] arr, int i, int j) {
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

