public class Solution {
    public int kSimilarity(String a, String b) {
        if (a.equals(b)) {
            return 0;
        }
        int n = a.length();

        class State {
            String s;
            int steps;
            int priority; // steps + heuristic

            State(String s, int steps) {
                this.s = s;
                this.steps = steps;
                this.priority = steps + heuristic(s, b);
            }
        }

        PriorityQueue<State> pq = new PriorityQueue<>(
                (x, y) -> Integer.compare(x.priority, y.priority));

        Set<String> visited = new HashSet<>();
        pq.offer(new State(a, 0));
        visited.add(a);

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            String s = cur.s;
            int steps = cur.steps;

            if (s.equals(b)) {
                return steps;
            }

            // find first mismatched position
            int i = 0;
            while (i < n && s.charAt(i) == b.charAt(i)) {
                i++;
            }

            char[] arr = s.toCharArray();
            for (int j = i + 1; j < n; j++) {
                if (arr[j] == b.charAt(i) && arr[j] != b.charAt(j)) {
                    // swap i and j
                    swap(arr, i, j);
                    String ns = new String(arr);
                    if (!visited.contains(ns)) {
                        visited.add(ns);
                        pq.offer(new State(ns, steps + 1));
                    }
                    // revert swap for next iteration
                    swap(arr, i, j);
                }
            }
        }
        return -1; // should never happen for valid input
    }

    private static void swap(char[] arr, int i, int j) {
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private static int heuristic(String s, String target) {
        int diff = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != target.charAt(i)) {
                diff++;
            }
        }
        // each swap can fix at most two mismatches
        return (diff + 1) / 2;
    }
