                for (int j = i + 1; j < cur.length(); j++) {
                    // swap only with a character that can fix position i
                    if (cur.charAt(j) == b.charAt(i) && cur.charAt(j) != b.charAt(j)) {
                        String next = swap(cur, i, j);
                        if (visited.add(next)) {
                            queue.offer(next);
                        }
                    }
                }
            }
            steps++;
        }
        return steps;
    }

    private String swap(String s, int i, int j) {
        char[] arr = s.toCharArray();
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
        return new String(arr);
    }
