public class Solution {
    public int minSwap(int[] listA, int[] listB) {
        int n = listA.length;
        if (n == 0) return 0;
        // keep[i]: min swaps to make sequences increasing up to i without swapping at i
        // swap[i]: min swaps to make sequences increasing up to i with swapping at i
        int[] keep = new int[n];
        int[] swap = new int[n];
        final int INF = Integer.MAX_VALUE / 2;

        keep[0] = 0;
        swap[0] = 1;

        for (int i = 1; i < n; i++) {
            keep[i] = INF;
            swap[i] = INF;

            // Case 1: no swap at i, no swap at i-1
            if (listA[i] > listA[i - 1] && listB[i] > listB[i - 1]) {
                keep[i] = Math.min(keep[i], keep[i - 1]);
                swap[i] = Math.min(swap[i], swap[i - 1] + 1);
            }

            // Case 2: swap at i, no swap at i-1 (or vice‑versa)
            if (listA[i] > listB[i - 1] && listB[i] > listA[i - 1]) {
                keep[i] = Math.min(keep[i], swap[i - 1]);
                swap[i] = Math.min(swap[i], keep[i - 1] + 1);
            }
        }

        return Math.min(keep[n - 1], swap[n - 1]);
    }
}

