            return 0;
        }
        // dp0: min swaps till i with no swap at i
        // dp1: min swaps till i with swap at i
        int dp0 = 0;
        int dp1 = 1; // swap at index 0
        for (int i = 1; i < n; i++) {
            int new0 = Integer.MAX_VALUE;
            int new1 = Integer.MAX_VALUE;
            // Case 1: sequences are increasing without swapping at i
            if (listA[i] > listA[i - 1] && listB[i] > listB[i - 1]) {
                new0 = Math.min(new0, dp0);          // no swap at i, no swap at i-1
                new1 = Math.min(new1, dp1 + 1);      // swap at i, swap at i-1 (+1 swap)
            }
            // Case 2: sequences are increasing with a cross swap
            if (listA[i] > listB[i - 1] && listB[i] > listA[i - 1]) {
                new0 = Math.min(new0, dp1);          // no swap at i, swap at i-1
                new1 = Math.min(new1, dp0 + 1);      // swap at i, no swap at i-1 (+1 swap)
            }
            dp0 = new0;
            dp1 = new1;
        }
        return Math.min(dp0, dp1);
    }
}

