public class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int left = 1;
        int right = 0;
        for (int p : piles) {
            if (p > right) {
                right = p;
            }
        }
        while (left < right) {
            int mid = left + (right - left) / 2;
            long hoursNeeded = 0;
            for (int p : piles) {
                hoursNeeded += (p + mid - 1) / mid; // ceiling division
                if (hoursNeeded > h) {
                    break; // no need to continue if already exceeds h
                }
            }
            if (hoursNeeded <= h) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

