public class Solution {
    public int uniqueLetterString(String s) {
        int n = s.length();
        int[] prev = new int[n];
        int[] next = new int[n];
        // Map character to its last occurrence index
        int[] lastPos = new int[256];
        Arrays.fill(lastPos, -1);
        // Compute prev array
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            prev[i] = lastPos[c];
            lastPos[c] = i;
        }
        // Reset for next computation
        Arrays.fill(lastPos, n);
        // Compute next array
        for (int i = n - 1; i >= 0; i--) {
            char c = s.charAt(i);
            next[i] = lastPos[c];
            lastPos[c] = i;
        }
        long result = 0L;
        for (int i = 0; i < n; i++) {
            long left = i - prev[i];
            long right = next[i] - i;
            result += left * right;
        }
        return (int) result;
    }
}

