public class Solution {
    public int uniqueLetterString(String s) {
        int n = s.length();
        // positions for each character (ASCII range)
        List<Integer>[] idx = new ArrayList[256];
        for (int i = 0; i < 256; i++) {
            idx[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            idx[s.charAt(i)].add(i);
        }

        long total = 0L;
        for (int c = 0; c < 256; c++) {
            List<Integer> list = idx[c];
            if (list.isEmpty()) continue;
            // add sentinel values
            list.add(0, -1);
            list.add(n);
            for (int i = 1; i < list.size() - 1; i++) {
                int cur = list.get(i);
                int prev = list.get(i - 1);
                int next = list.get(i + 1);
                long contribution = (long) (cur - prev) * (next - cur);
                total += contribution;
            }
            // remove sentinels to keep the list clean (optional)
            list.remove(list.size() - 1);
            list.remove(0);
        }

        return (int) total;
    }
}

