public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        // Ensure the first column is all 1s by flipping rows where it's 0
        for (int i = 0; i < m; i++) {
            if (grid[i][0] == 0) {
                for (int j = 0; j < n; j++) {
                    grid[i][j] ^= 1;
                }
            }
        }
        int totalScore = 0;
        // The most significant bit (first column) contributes m * 2^(n-1)
        totalScore += m * (1 << (n - 1));
        // Process remaining columns
        for (int col = 1; col < n; col++) {
            int onesCount = 0;
            for (int row = 0; row < m; row++) {
                if (grid[row][col] == 1) {
                    onesCount++;
                }
            }
            int maxOnes = Math.max(onesCount, m - onesCount);
            totalScore += maxOnes * (1 << (n - 1 - col));
        }
        return totalScore;
    }
}

