    }

    private void dfsPost(int node, int parent, List<Integer>[] graph, int[] count, int[] ans) {
        count[node] = 1; // count itself
        for (int neighbor : graph[node]) {
            if (neighbor == parent) continue;
            dfsPost(neighbor, node, graph, count, ans);
            count[node] += count[neighbor];
            ans[0] += count[neighbor]; // distance from root to all nodes in child's subtree
        }
    }

    private void dfsPre(int node, int parent, List<Integer>[] graph, int[] count, int[] ans, int n) {
        for (int neighbor : graph[node]) {
            if (neighbor == parent) continue;
            // When moving root from node to neighbor:
            // nodes in neighbor's subtree get 1 closer, others get 1 farther
            ans[neighbor] = ans[node] - count[neighbor] + (n - count[neighbor]);
            dfsPre(neighbor, node, graph, count, ans, n);
        }
    }
}

