public class Solution {
    private List<Integer>[] graph;
    private int[] count;
    private int[] ans;

    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        if (n == 1) {
            return new int[]{0};
        }
        // build adjacency list
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int a = e[0];
            int b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        count = new int[n];
        ans = new int[n];

        // first dfs: compute count of nodes in each subtree and ans[0] (total distance from root 0)
        dfs1(0, -1);

        // second dfs: reroot to compute answer for all nodes
        dfs2(0, -1, n);

        return ans;
    }

    // post-order traversal
    private void dfs1(int node, int parent) {
        count[node] = 1; // count itself
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            dfs1(nei, node);
            count[node] += count[nei];
            ans[node] += ans[nei] + count[nei];
        }
    }

    // pre-order traversal to propagate answers
    private void dfs2(int node, int parent, int n) {
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            // when moving root from node to nei
            ans[nei] = ans[node] - count[nei] + (n - count[nei]);
            dfs2(nei, node, n);
        }
    }
}

