import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Solution {
    private static final int MOD = 1_000_000_007;

    private static class Event {
        int x;
        int y1;
        int y2;
        int type; // +1 for entering, -1 for leaving

        Event(int x, int y1, int y2, int type) {
            this.x = x;
            this.y1 = y1;
            this.y2 = y2;
            this.type = type;
        }
    }

    private static class SegmentTree {
        private final int[] count;
        private final long[] covered;
        private final int n;
        private final long[] ys; // compressed y coordinates

        SegmentTree(long[] ys) {
            this.ys = ys;
            this.n = ys.length - 1; // number of elementary intervals
            int size = n * 4;
            count = new int[size];
            covered = new long[size];
        }

        void update(int node, int l, int r, int ql, int qr, int val) {
            if (qr <= l || r <= ql) {
                return;
            }
            if (ql <= l && r <= qr) {
                count[node] += val;
                pushUp(node, l, r);
                return;
            }
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ql, qr, val);
            update(node << 1 | 1, mid, r, ql, qr, val);
            pushUp(node, l, r);
        }

        private void pushUp(int node, int l, int r) {
            if (count[node] > 0) {
                covered[node] = ys[r] - ys[l];
            } else if (l + 1 == r) {
                covered[node] = 0;
            } else {
                covered[node] = covered[node << 1] + covered[node << 1 | 1];
            }
        }

        long queryTotalCovered() {
            return covered[1];
        }
    }

    public int rectangleArea(int[][] rectangles) {
        if (rectangles == null || rectangles.length == 0) {
            return 0;
        }

        List<Integer> yList = new ArrayList<>();
        List<Event> events = new ArrayList<>();

        for (int[] rect : rectangles) {
            int x1 = rect[0];
            int y1 = rect[1];
            int x2 = rect[2];
            int y2 = rect[3];
            yList.add(y1);
            yList.add(y2);
            events.add(new Event(x1, y1, y2, 1));   // entering
            events.add(new Event(x2, y1, y2, -1));  // leaving
        }

        // coordinate compression for y
        Collections.sort(yList);
        List<Integer> uniq = new ArrayList<>();
        int prev = Integer.MIN_VALUE;
        for (int v : yList) {
            if (v != prev) {
                uniq.add(v);
                prev = v;
            }
        }
        int m = uniq.size();
        long[] ys = new long[m];
        for (int i = 0; i < m; i++) {
            ys[i] = uniq.get(i);
        }

        // sort events by x
        events.sort(Comparator.comparingInt(e -> e.x));

        SegmentTree segTree = new SegmentTree(ys);
        long area = 0;
        int prevX = events.get(0).x;

        for (Event e : events) {
            int curX = e.x;
            long coveredY = segTree.queryTotalCovered();
            long deltaX = (long) curX - prevX;
            area = (area + coveredY * deltaX) % MOD;

            // update segment tree with current event
            int y1Idx = binarySearch(ys, e.y1);
            int y2Idx = binarySearch(ys, e.y2);
            segTree.update(1, 0, segTree.n, y1Idx, y2Idx, e.type);

            prevX = curX;
        }

        return (int) (area % MOD);
    }

    // binary search for exact value in sorted ys array, returns index
    private int binarySearch(long[] arr, int target) {
        int lo = 0, hi = arr.length - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] == target) {
                return mid;
            } else if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        // target is guaranteed to exist
        return -1;
    }
}

