public class Solution {
    private static final int MOD = 1_000_000_007;

    private static class Event implements Comparable<Event> {
        long x;
        int y1Idx;
        int y2Idx;
        int type; // +1 for entering, -1 for leaving

        Event(long x, int y1Idx, int y2Idx, int type) {
            this.x = x;
            this.y1Idx = y1Idx;
            this.y2Idx = y2Idx;
            this.type = type;
        }

        @Override
        public int compareTo(Event o) {
            return Long.compare(this.x, o.x);
        }
    }

    private static class SegmentTree {
        private final int n;               // number of elementary y-intervals
        private final long[] yVals;        // compressed y coordinates
        private final int[] count;         // cover count
        private final long[] length;       // covered length in this node

        SegmentTree(long[] yVals) {
            this.yVals = yVals;
            this.n = yVals.length - 1; // intervals between points
            int size = n * 4;
            count = new int[size];
            length = new long[size];
        }

        void update(int node, int l, int r, int ql, int qr, int val) {
            if (qr <= l || r <= ql) {
                return;
            }
            if (ql <= l && r <= qr) {
                count[node] += val;
                pushUp(node, l, r);
                return;
            }
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ql, qr, val);
            update(node << 1 | 1, mid, r, ql, qr, val);
            pushUp(node, l, r);
        }

        private void pushUp(int node, int l, int r) {
            if (count[node] > 0) {
                length[node] = yVals[r] - yVals[l];
            } else if (l + 1 == r) {
                length[node] = 0;
            } else {
                length[node] = length[node << 1] + length[node << 1 | 1];
            }
        }

        long queryTotalCoveredLength() {
            return length[1];
        }
    }

    public int rectangleArea(int[][] rectangles) {
        int m = rectangles.length;
        if (m == 0) return 0;

        // Collect all y coordinates for compression
        List<Long> yList = new ArrayList<>();
        for (int[] rec : rectangles) {
            yList.add((long) rec[1]);
            yList.add((long) rec[3]);
        }
        long[] yVals = yList.stream().distinct().sorted().mapToLong(Long::longValue).toArray();

        // Map y to index
        // Since yVals is sorted, we can use binary search
        List<Event> events = new ArrayList<>(2 * m);
        for (int[] rec : rectangles) {
            int y1Idx = Arrays.binarySearch(yVals, rec[1]);
            int y2Idx = Arrays.binarySearch(yVals, rec[3]);
            events.add(new Event(rec[0], y1Idx, y2Idx, 1));   // entering
            events.add(new Event(rec[2], y1Idx, y2Idx, -1));  // leaving
        }

        Event[] evArray = events.toArray(new Event[0]);
        Arrays.sort(evArray);

        SegmentTree segTree = new SegmentTree(yVals);

        long area = 0;
        for (int i = 0; i < evArray.length - 1; i++) {
            Event e = evArray[i];
            segTree.update(1, 0, segTree.n, e.y1Idx, e.y2Idx, e.type);
            long coveredY = segTree.queryTotalCoveredLength();
            long dx = evArray[i + 1].x - e.x;
            area = (area + (coveredY % MOD) * (dx % MOD)) % MOD;
        }

        // Process the last event (no further width, but we still need to apply its update to keep structure consistent)
        // Not necessary for area calculation.
        return (int) (area % MOD);
    }
}

