import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    private static class Event {
        int x, y1, y2, type;
        Event(int x, int y1, int y2, int type) {
            this.x = x;
            this.y1 = y1;
            this.y2 = y2;
            this.type = type;
        }
    }

    private static class SegmentTree {
        private final int[] count;
        private final long[] length;
        private final int[] yVals;

        SegmentTree(int[] yVals) {
            this.yVals = yVals;
            int n = yVals.length;
            // intervals are (n-1), tree size 4*(n-1) is enough
            this.count = new int[4 * n];
            this.length = new long[4 * n];
        }

        void update(int node, int l, int r, int ql, int qr, int val) {
            if (ql > r || qr < l) return;
            if (ql <= l && r <= qr) {
                count[node] += val;
                pushUp(node, l, r);
                return;
            }
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ql, qr, val);
            update(node << 1 | 1, mid + 1, r, ql, qr, val);
            pushUp(node, l, r);
        }

        private void pushUp(int node, int l, int r) {
            if (count[node] > 0) {
                // fully covered
                length[node] = (long) yVals[r + 1] - yVals[l];
            } else if (l == r) {
                length[node] = 0;
            } else {
                length[node] = length[node << 1] + length[node << 1 | 1];
            }
        }

        long queryTotal() {
            return length[1];
        }
    }

    public int rectangleArea(int[][] rectangles) {
        if (rectangles == null || rectangles.length == 0) return 0;

        List<Event> events = new ArrayList<>();
        List<Integer> yList = new ArrayList<>();

        for (int[] rect : rectangles) {
            int x1 = rect[0], y1 = rect[1], x2 = rect[2], y2 = rect[3];
            events.add(new Event(x1, y1, y2, 1));
            events.add(new Event(x2, y1, y2, -1));
            yList.add(y1);
            yList.add(y2);
        }

        Collections.sort(yList);
        int[] yVals = yList.stream().distinct().mapToInt(Integer::intValue).toArray();

        if (yVals.length < 2) return 0; // no vertical span

        Collections.sort(events, (a, b) -> Integer.compare(a.x, b.x));

        SegmentTree tree = new SegmentTree(yVals);
        long area = 0;
        int prevX = events.get(0).x;
        int maxIntervalIdx = yVals.length - 2; // last interval index

        for (Event e : events) {
            int curX = e.x;
            long coveredY = tree.queryTotal();
            long deltaX = curX - prevX;
            area = (area + coveredY * deltaX) % MOD;

            int y1Idx = Arrays.binarySearch(yVals, e.y1);
            int y2Idx = Arrays.binarySearch(yVals, e.y2);
            // update intervals [y1Idx, y2Idx-1]
            tree.update(1, 0, maxIntervalIdx, y1Idx, y2Idx - 1, e.type);

            prevX = curX;
        }

        return (int) (area % MOD);
    }
}

