import java.util.HashSet;
import java.util.Set;

public class Solution {
    public boolean buddyStrings(String s, String goal) {
        if (s == null || goal == null) {
            return false;
        }
        if (s.length() != goal.length()) {
            return false;
        }
        int n = s.length();
        if (n < 2) {
            return false;
        }

        // If strings are equal, need at least one duplicate character
        if (s.equals(goal)) {
            Set<Character> seen = new HashSet<>();
            for (int i = 0; i < n; i++) {
                char c = s.charAt(i);
                if (seen.contains(c)) {
                    return true; // duplicate found, swapping duplicates keeps string unchanged
                }
                seen.add(c);
            }
            return false; // all characters are unique, no valid swap
        }

        // Find the positions where s and goal differ
        int first = -1, second = -1;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) != goal.charAt(i)) {
                if (first == -1) {
                    first = i;
                } else if (second == -1) {
                    second = i;
                } else {
                    // More than two mismatches
                    return false;
                }
            }
        }

        // Must have exactly two mismatched positions and they must cross-match
        return second != -1
                && s.charAt(first) == goal.charAt(second)
                && s.charAt(second) == goal.charAt(first);
    }
}

