import java.util.Arrays;

public class Solution {
    public int[] advantageCount(int[] nums1, int[] nums2) {
        int n = nums1.length;
        // Frequency map for nums1 values
        TreeMap<Integer, Integer> map = new TreeMap<>();
        for (int v : nums1) {
            map.merge(v, 1, Integer::sum);
        }

        // Indices of nums2 sorted by descending value
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            order[i] = i;
        }
        Arrays.sort(order, (a, b) -> Integer.compare(nums2[b], nums2[a]));

        int[] result = new int[n];
        for (int idx : order) {
            int target = nums2[idx];
            Integer chosen = map.higherKey(target); // smallest > target
            if (chosen == null) {
                chosen = map.firstKey(); // sacrifice smallest
            }
            result[idx] = chosen;
            int cnt = map.get(chosen);
            if (cnt == 1) {
                map.remove(chosen);
            } else {
                map.put(chosen, cnt - 1);
            }
        }
        return result;
    }
}

