import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int[] advantageCount(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[] result = new int[n];

        // Sort nums1
        Arrays.sort(nums1);
        Deque<Integer> small = new ArrayDeque<>();
        Deque<Integer> large = new ArrayDeque<>();
        for (int num : nums1) {
            small.addLast(num);
            large.addLast(num);
        }

        // Indices of nums2 sorted by value descending
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) {
            idx[i] = i;
        }
        Arrays.sort(idx, (a, b) -> Integer.compare(nums2[b], nums2[a]));

        // Greedy assignment
        for (int i : idx) {
            if (large.peekLast() > nums2[i]) {
                // Use the smallest number that can beat nums2[i]
                // Since large.peekLast() is the largest remaining,
                // we need the smallest that is > nums2[i]. We can take from large's end
                // because we are iterating nums2 in descending order.
                result[i] = large.pollLast();
            } else {
                // Cannot beat, use the smallest number
                result[i] = small.pollFirst();
                // Also remove it from large to keep structures consistent
                large.removeFirst();
            }
        }

        return result;
    }
}

