public class Solution {
    public String shiftingLetters(String s, int[][] shifts) {
        int n = s.length();
        int[] diff = new int[n + 1];

        for (int[] shift : shifts) {
            int start = shift[0];
            int end = shift[1];
            int direction = shift[2];
            int val = direction == 1 ? 1 : -1;

            diff[start] = (diff[start] + val) % 26;
            if (end + 1 < n) {
                diff[end + 1] = (diff[end + 1] - val) % 26;
            }
        }

        StringBuilder result = new StringBuilder();
        int curShift = 0;
        for (int i = 0; i < n; i++) {
            curShift = (curShift + diff[i]) % 26;
            if (curShift < 0) {
                curShift += 26;
            }
            char original = s.charAt(i);
            int shiftedPos = (original - 'a' + curShift) % 26;
            result.append((char) ('a' + shiftedPos));
        }

        return result.toString();
    }
}

