import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public int distinctSequences(int n) {
        if (n <= 0) return 0;
        if (n == 1) return 6; // any face

        // Pre‑compute which pairs have gcd == 1
        boolean[][] coprime = new boolean[7][7];
        for (int i = 1; i <= 6; i++) {
            for (int j = 1; j <= 6; j++) {
                coprime[i][j] = (gcd(i, j) == 1);
            }
        }

        // n == 2 : count pairs (a,b) with a!=b and coprime
        if (n == 2) {
            long cnt = 0;
            for (int a = 1; a <= 6; a++) {
                for (int b = 1; b <= 6; b++) {
                    if (a != b && coprime[a][b]) cnt++;
                }
            }
            return (int) (cnt % MOD);
        }

        // dp[last][secondLast] after processing current position
        long[][] dp = new long[7][7];
        // initialise for first two rolls
        for (int a = 1; a <= 6; a++) {          // second last (position 1)
            for (int b = 1; b <= 6; b++) {      // last (position 2)
                if (a != b && coprime[a][b]) {
                    dp[b][a] = 1;
                }
            }
        }

        // iterate from position 3 to n
        for (int pos = 3; pos <= n; pos++) {
            long[][] ndp = new long[7][7];
            for (int last = 1; last <= 6; last++) {
                for (int second = 1; second <= 6; second++) {
                    long ways = dp[last][second];
                    if (ways == 0) continue;
                    for (int cur = 1; cur <= 6; cur++) {
                        if (cur == last || cur == second) continue; // distance >2 rule
                        if (!coprime[last][cur]) continue;          // gcd rule
                        ndp[cur][last] = (ndp[cur][last] + ways) % MOD;
                    }
                }
            }
            dp = ndp;
        }

        long ans = 0;
        for (int last = 1; last <= 6; last++) {
            for (int second = 1; second <= 6; second++) {
                ans = (ans + dp[last][second]) % MOD;
            }
        }
        return (int) ans;
    }
}

