                        next[np1][np2] = (next[np1][np2] + cur) % MOD;
                    }
                }
            }
            dp = next;
        }

        long ans = 0;
        for (int p1 = 0; p1 <= 6; p1++) {
            for (int p2 = 0; p2 <= 6; p2++) {
                ans += dp[p1][p2];
                if (ans >= MOD) ans -= MOD;
            }
        }
        return (int) ans;
