        for (int v1 = 1; v1 <= MAX_VAL; v1++) {
            for (int v2 = 1; v2 <= MAX_VAL; v2++) {
                if (v1 != v2 && GCD[v1][v2] == 1) {
                    dp[v1][v2] = 1;
                }
            }
        }

        if (n == 2) {
            long ans = 0;
            for (int a = 1; a <= MAX_VAL; a++) {
                for (int b = 1; b <= MAX_VAL; b++) {
                    ans = (ans + dp[a][b]) % MOD;
                }
            }
            return (int) ans;
        }

        // Build sequences for lengths >= 3
        for (int len = 3; len <= n; len++) {
            long[][] next = new long[MAX_VAL + 1][MAX_VAL + 1];
            for (int a = 1; a <= MAX_VAL; a++) {
                for (int b = 1; b <= MAX_VAL; b++) {
                    long cur = dp[a][b];
                    if (cur == 0) continue;
                    for (int c = 1; c <= MAX_VAL; c++) {
                        if (c != b && c != a && GCD[b][c] == 1) {
                            next[b][c] = (next[b][c] + cur) % MOD;
                        }
                    }
                }
            }
            dp = next;
        }

        long result = 0;
        for (int a = 1; a <= MAX_VAL; a++) {
            for (int b = 1; b <= MAX_VAL; b++) {
                result = (result + dp[a][b]) % MOD;
            }
        }
        return (int) result;
    }
