public class Solution {
    public long taskSchedulerII(int[] tasks, int space) {
        HashMap<Integer, Long> lastDay = new HashMap<>();
        long day = 0L; // the day we are ready to schedule the next task
        long gap = (long) space + 1L; // minimum distance between same tasks

        for (int t : tasks) {
            if (lastDay.containsKey(t)) {
                long earliest = lastDay.get(t) + gap;
                if (day < earliest) {
                    day = earliest; // take breaks until allowed
                }
            }
            // perform the task on 'day'
            lastDay.put(t, day);
            day++; // move to the next day
        }
        return day;
    }
}

