        for (int i = m - 2; i >= 0; i--) {
            int[] newDp = new int[n];
            for (int j = 0; j < n; j++) {
                int cellValue = grid[i][j];
                int best = Integer.MAX_VALUE;
                // Try moving to every column k in the next row.
                for (int k = 0; k < n; k++) {
                    int cost = moveCost[cellValue][k] + dp[k];
                    if (cost < best) {
                        best = cost;
                    }
                }
                newDp[j] = cellValue + best;
            }
            dp = newDp;
        }
        // The answer is the minimum cost starting from any cell in the first row.
        int answer = Integer.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            if (dp[j] < answer) {
                answer = dp[j];
            }
        }
        return answer;
    }
