import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maximumSum(int[] nums) {
        Map<Integer, int[]> best = new HashMap<>();
        for (int num : nums) {
            int sum = digitSum(num);
            int[] pair = best.get(sum);
            if (pair == null) {
                pair = new int[]{num, -1};
                best.put(sum, pair);
            } else {
                if (num > pair[0]) {
                    pair[1] = pair[0];
                    pair[0] = num;
                } else if (num > pair[1]) {
                    pair[1] = num;
                }
            }
        }
        int answer = -1;
        for (int[] pair : best.values()) {
            if (pair[1] != -1) {
                answer = Math.max(answer, pair[0] + pair[1]);
            }
        }
        return answer;
    }

    private int digitSum(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
}

