import com_github_leetcode.TreeNode;
import java.util.*;

public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        if (root == null) {
            return 0;
        }

        // Build undirected adjacency list for the tree
        Map<Integer, List<Integer>> adj = new HashMap<>();
        buildAdjacency(root, adj);

        // BFS from the start node to find the farthest distance
        Queue<Integer> queue = new ArrayDeque<>();
        Set<Integer> visited = new HashSet<>();

        queue.offer(start);
        visited.add(start);
        int minutes = -1;

        while (!queue.isEmpty()) {
            int size = queue.size();
            minutes++;
            for (int i = 0; i < size; i++) {
                int cur = queue.poll();
                for (int neighbor : adj.getOrDefault(cur, Collections.emptyList())) {
                    if (!visited.contains(neighbor)) {
                        visited.add(neighbor);
                        queue.offer(neighbor);
                    }
                }
            }
        }

        return minutes;
    }

    private void buildAdjacency(TreeNode node, Map<Integer, List<Integer>> adj) {
        if (node == null) {
            return;
        }
        adj.computeIfAbsent(node.val, k -> new ArrayList<>());

        if (node.left != null) {
            adj.computeIfAbsent(node.left.val, k -> new ArrayList<>());
            adj.get(node.val).add(node.left.val);
            adj.get(node.left.val).add(node.val);
            buildAdjacency(node.left, adj);
        }

        if (node.right != null) {
            adj.computeIfAbsent(node.right.val, k -> new ArrayList<>());
            adj.get(node.val).add(node.right.val);
            adj.get(node.right.val).add(node.val);
            buildAdjacency(node.right, adj);
        }
    }
}

