import java.util.Set;
import java.util.Queue;
import java.util.ArrayDeque;
import com_github_leetcode.TreeNode;

public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        if (root == null) {
            return 0;
        }

        // Build adjacency list for the tree and map values to nodes
        Map<TreeNode, List<TreeNode>> graph = new HashMap<>();
        Map<Integer, TreeNode> valueToNode = new HashMap<>();
        buildGraph(root, null, graph, valueToNode);

        TreeNode startNode = valueToNode.get(start);
        if (startNode == null) {
            return 0;
        }

        // BFS from the start node to find the farthest distance
        Queue<TreeNode> queue = new ArrayDeque<>();
        Set<TreeNode> visited = new HashSet<>();

        queue.offer(startNode);
        visited.add(startNode);
        int minutes = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            boolean expanded = false;
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                List<TreeNode> neighbours = graph.getOrDefault(node, new ArrayList<>());
                for (TreeNode nb : neighbours) {
                    if (!visited.contains(nb)) {
                        visited.add(nb);
                        queue.offer(nb);
                        expanded = true;
                    }
                }
            }
            if (expanded) {
                minutes++;
            }
        }

        return minutes;
    }

    private void buildGraph(TreeNode node, TreeNode parent,
                            Map<TreeNode, List<TreeNode>> graph,
                            Map<Integer, TreeNode> valueToNode) {
        if (node == null) {
            return;
        }

        valueToNode.put(node.val, node);
        graph.computeIfAbsent(node, k -> new ArrayList<>());
        if (parent != null) {
            graph.get(node).add(parent);
            graph.get(parent).add(node);
        }

        if (node.left != null) {
            buildGraph(node.left, node, graph, valueToNode);
        }
        if (node.right != null) {
            buildGraph(node.right, node, graph, valueToNode);
        }
    }
}

