import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
import com_github_leetcode.TreeNode;

public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        if (root == null) {
            return 0;
        }
        // Map each node to its parent
        Map<TreeNode, TreeNode> parentMap = new HashMap<>();
        TreeNode startNode = buildParentMap(root, null, start, parentMap);
        if (startNode == null) {
            return 0; // start value not found, should not happen per constraints
        }

        // BFS from startNode
        Queue<TreeNode> queue = new LinkedList<>();
        Set<TreeNode> visited = new HashSet<>();
        queue.offer(startNode);
        visited.add(startNode);
        int minutes = -1; // start at -1 because first level is minute 0

        while (!queue.isEmpty()) {
            int size = queue.size();
            minutes++;
            for (int i = 0; i < size; i++) {
                TreeNode curr = queue.poll();
                // left child
                if (curr.left != null && !visited.contains(curr.left)) {
                    visited.add(curr.left);
                    queue.offer(curr.left);
                }
                // right child
                if (curr.right != null && !visited.contains(curr.right)) {
                    visited.add(curr.right);
                    queue.offer(curr.right);
                }
                // parent
                TreeNode parent = parentMap.get(curr);
                if (parent != null && !visited.contains(parent)) {
                    visited.add(parent);
                    queue.offer(parent);
                }
            }
        }
        return minutes;
    }

    private TreeNode buildParentMap(TreeNode node, TreeNode parent,
                                    int start,
                                    Map<TreeNode, TreeNode> parentMap) {
        if (node == null) {
            return null;
        }
        if (parent != null) {
            parentMap.put(node, parent);
        }
        if (node.val == start) {
            return node;
        }
        TreeNode leftResult = buildParentMap(node.left, node, start, parentMap);
        if (leftResult != null) {
            return leftResult;
        }
        return buildParentMap(node.right, node, start, parentMap);
    }
}

