            String key = Arrays.toString(grid[i]);
            rowCount.put(key, rowCount.getOrDefault(key, 0) + 1);
        }

        int result = 0;
        // Build each column and check against row representations
        for (int col = 0; col < n; col++) {
            int[] columnArray = new int[n];
            for (int row = 0; row < n; row++) {
                columnArray[row] = grid[row][col];
            }
            String key = Arrays.toString(columnArray);
            result += rowCount.getOrDefault(key, 0);
        }

        return result;
    }
}

