public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        int n = edges.length;
        int[] dist1 = new int[n];
        int[] dist2 = new int[n];
        Arrays.fill(dist1, Integer.MAX_VALUE);
        Arrays.fill(dist2, Integer.MAX_VALUE);
        computeDistances(edges, node1, dist1);
        computeDistances(edges, node2, dist2);
        int bestNode = -1;
        int bestDist = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (dist1[i] == Integer.MAX_VALUE || dist2[i] == Integer.MAX_VALUE) {
                continue;
            }
            int cur = Math.max(dist1[i], dist2[i]);
            if (cur < bestDist || (cur == bestDist && i < bestNode)) {
                bestDist = cur;
                bestNode = i;
            }
        }
        return bestNode;
    }

    private void computeDistances(int[] edges, int start, int[] dist) {
        int step = 0;
        int node = start;
        while (node != -1 && dist[node] == Integer.MAX_VALUE) {
            dist[node] = step++;
            node = edges[node];
        }
    }
}

