import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Solution {
    public boolean matchReplacement(String s, String sub, char[][] mappings) {
        if (sub.length() > s.length()) {
            return false;
        }

        // Build mapping from old character to set of possible new characters
        Map<Character, Set<Character>> map = new HashMap<>();
        for (char[] pair : mappings) {
            if (pair == null || pair.length < 2) continue;
            char oldChar = pair[0];
            char newChar = pair[1];
            map.computeIfAbsent(oldChar, k -> new HashSet<>()).add(newChar);
        }

        int n = s.length();
        int m = sub.length();

        // Try each possible starting index in s
        for (int i = 0; i <= n - m; i++) {
            boolean ok = true;
            for (int j = 0; j < m; j++) {
                char sc = s.charAt(i + j);
                char subc = sub.charAt(j);
                if (sc == subc) {
                    continue;
                }
                Set<Character> possible = map.get(subc);
                if (possible == null || !possible.contains(sc)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return true;
            }
        }
        return false;
    }
}

