import java.util.*;

public class Solution {
    private static class SegmentTree {
        private final int n;
        private final int[] tree;

        SegmentTree(int size, int initVal) {
            this.n = size;
            this.tree = new int[4 * size];
            build(1, 1, n, initVal);
        }

        private void build(int node, int l, int r, int val) {
            if (l == r) {
                tree[node] = val;
                return;
            }
            int mid = (l + r) >>> 1;
            build(node << 1, l, mid, val);
            build(node << 1 | 1, mid + 1, r, val);
            tree[node] = Math.min(tree[node << 1], tree[node << 1 | 1]);
        }

        void update(int idx, int val) {
            update(1, 1, n, idx, val);
        }

        private void update(int node, int l, int r, int idx, int val) {
            if (l == r) {
                tree[node] = val;
                return;
            }
            int mid = (l + r) >>> 1;
            if (idx <= mid) {
                update(node << 1, l, mid, idx, val);
            } else {
                update(node << 1 | 1, mid + 1, r, idx, val);
            }
            tree[node] = Math.min(tree[node << 1], tree[node << 1 | 1]);
        }

        int queryMin() {
            return tree[1];
        }
    }

    public int shortestSequence(int[] rolls, int k) {
        int n = rolls.length;
        int[] dp = new int[n + 1];
        dp[n] = 1; // from empty suffix, any single number is impossible

        // segment tree storing candidate values for each number 1..k
        SegmentTree seg = new SegmentTree(k, 1); // initially all candidates are dp[n] = 1

        boolean[] seen = new boolean[k + 1];
        int missing = k; // numbers not yet seen in the current suffix

        for (int i = n - 1; i >= 0; --i) {
            int v = rolls[i];
            if (!seen[v]) {
                seen[v] = true;
                missing--;
            }
            // update candidate for value v: after taking v at position i, we continue from i+1
            seg.update(v, dp[i + 1]);

            if (missing > 0) {
                dp[i] = 1; // some number is absent in this suffix
            } else {
                int minCand = seg.queryMin();
                dp[i] = 1 + minCand;
            }
        }
        return dp[0];
    }
}

