import java.util.Arrays;

public class Solution {
    public int shortestSequence(int[] rolls, int k) {
        int n = rolls.length;
        int[] dp = new int[n + 1];
        dp[n] = 1; // beyond the end, any single value is missing

        int[] nextIdx = new int[k + 1];
        Arrays.fill(nextIdx, n); // no occurrence after the end

        int[] cnt = new int[k + 1];
        int distinct = 0;

        for (int i = n - 1; i >= 0; i--) {
            int val = rolls[i];
            if (cnt[val] == 0) {
                distinct++;
            }
            cnt[val]++;

            if (distinct < k) {
                // at least one value never appears in the suffix starting at i
                dp[i] = 1;
            } else {
                int min = Integer.MAX_VALUE;
                for (int v = 1; v <= k; v++) {
                    int pos = (v == val) ? i : nextIdx[v];
                    // pos cannot be n here because all values are present in the suffix
                    int candidate = dp[pos + 1];
                    if (candidate < min) {
                        min = candidate;
                    }
                    // early exit if we already found the minimal possible value (which is 1)
                    if (min == 1) {
                        break;
                    }
                }
                dp[i] = 1 + min;
            }

            // update next occurrence for the current value
            nextIdx[val] = i;
        }

        return dp[0];
    }
}

