public class Solution {
    private static final int MOD = 1_000_000_007;

    public int peopleAwareOfSecret(int n, int delay, int forget) {
        // Arrays to store how many people start sharing and forget on each day
        long[] startSharing = new long[n + forget + 2];
        long[] forgetDay = new long[n + forget + 2];
        long[] newPeople = new long[n + 2];

        // Day 1: one person knows the secret
        newPeople[1] = 1;
        // This person will start sharing after 'delay' days and forget after 'forget' days
        if (1 + delay <= n) {
            startSharing[1 + delay] = (startSharing[1 + delay] + 1) % MOD;
        }
        if (1 + forget <= n) {
            forgetDay[1 + forget] = (forgetDay[1 + forget] + 1) % MOD;
        }

        long activeSharers = 0; // people who can share today
        long totalAware = 1;    // total people who still know the secret

        for (int day = 2; day <= n; day++) {
            // Update active sharers: add those who start sharing today, remove those who forget today
            activeSharers = (activeSharers + startSharing[day] - forgetDay[day]) % MOD;
            if (activeSharers < 0) activeSharers += MOD;

            // New people learn the secret today
            newPeople[day] = activeSharers;
            totalAware = (totalAware + newPeople[day]) % MOD;

            // Schedule their future start sharing and forgetting
            int startDay = day + delay;
            int forgetAt = day + forget;
            if (startDay <= n) {
                startSharing[startDay] = (startSharing[startDay] + newPeople[day]) % MOD;
            }
            if (forgetAt <= n) {
                forgetDay[forgetAt] = (forgetDay[forgetAt] + newPeople[day]) % MOD;
            }
        }

        return (int) (totalAware % MOD);
    }
}

