     * Remaining cells are filled with -1.
     *
     * @param m    number of rows
     * @param n    number of columns
     * @param head head of the linked list containing integer values
     * @return the generated matrix
     */
    public int[][] spiralMatrix(int m, int n, ListNode head) {
        int[][] matrix = new int[m][n];
        // Initialize all cells to -1
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                matrix[i][j] = -1;
            }
        }

        int top = 0, bottom = m - 1;
        int left = 0, right = n - 1;
        int filled = 0;
        int total = m * n;
        ListNode cur = head;

        while (filled < total) {
            // left to right
            for (int col = left; col <= right && filled < total; col++) {
                if (cur != null) {
                    matrix[top][col] = cur.val;
                    cur = cur.next;
                }
                filled++;
            }
            top++;

            // top to bottom
            for (int row = top; row <= bottom && filled < total; row++) {
                if (cur != null) {
                    matrix[row][right] = cur.val;
                    cur = cur.next;
                }
                filled++;
            }
            right--;

            // right to left
            for (int col = right; col >= left && filled < total; col--) {
                if (cur != null) {
                    matrix[bottom][col] = cur.val;
                    cur = cur.next;
                }
                filled++;
            }
            bottom--;

            // bottom to top
            for (int row = bottom; row >= top && filled < total; row--) {
                if (cur != null) {
                    matrix[row][left] = cur.val;
                    cur = cur.next;
                }
                filled++;
            }
            left++;
        }

        return matrix;
    }
