public class Solution {
    private int best;

    public int distributeCookies(int[] c, int k) {
        int n = c.length;
        if (k >= n) {
            int max = 0;
            for (int v : c) max = Math.max(max, v);
            return max;
        }
        // sort descending to improve pruning
        Integer[] bags = new Integer[n];
        for (int i = 0; i < n; i++) bags[i] = c[i];
        Arrays.sort(bags, Collections.reverseOrder());
        int[] cookies = new int[n];
        for (int i = 0; i < n; i++) cookies[i] = bags[i];

        best = Integer.MAX_VALUE;
        int[] sums = new int[k];
        dfs(0, cookies, sums);
        return best;
    }

    private void dfs(int idx, int[] cookies, int[] sums) {
        if (idx == cookies.length) {
            int curMax = 0;
            for (int s : sums) curMax = Math.max(curMax, s);
            best = Math.min(best, curMax);
            return;
        }

        int val = cookies[idx];
        // try to assign to each child
        for (int i = 0; i < sums.length; i++) {
            // pruning: if adding to this child already exceeds current best, skip
            if (sums[i] + val >= best) continue;
            // symmetry pruning: avoid putting into empty child when previous child also empty
            if (i > 0 && sums[i] == 0 && sums[i - 1] == 0) continue;

            sums[i] += val;
            dfs(idx + 1, cookies, sums);
            sums[i] -= val;
        }
    }
}

