import java.util.*;

public class Solution {
    public int distributeCookies(int[] c, int k) {
        int n = c.length;
        int totalMasks = 1 << n;
        int[] sum = new int[totalMasks];
        for (int mask = 1; mask < totalMasks; mask++) {
            int lsb = mask & -mask;
            int idx = Integer.numberOfTrailingZeros(lsb);
            sum[mask] = sum[mask ^ lsb] + c[idx];
        }

        int[][] memo = new int[totalMasks][k + 1];
        for (int i = 0; i < totalMasks; i++) {
            Arrays.fill(memo[i], -1);
        }

        return dfs((1 << n) - 1, k, sum, memo);
    }

    private int dfs(int mask, int kids, int[] sum, int[][] memo) {
        if (memo[mask][kids] != -1) {
            return memo[mask][kids];
        }
        if (kids == 1) {
            memo[mask][kids] = sum[mask];
            return memo[mask][kids];
        }

        int best = Integer.MAX_VALUE;
        // iterate over non‑empty proper submasks
        for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
            if (sub == mask) continue; // need at least one bag for remaining kids
            int remain = mask ^ sub;
            int cur = Math.max(sum[sub], dfs(remain, kids - 1, sum, memo));
            if (cur < best) {
                best = cur;
            }
        }

        memo[mask][kids] = best;
        return best;
    }
}

