public class Solution {
    public int garbageCollection(String[] garbage, int[] travel) {
        int n = garbage.length;
        // Prefix sum of travel distances: distance from house 0 to house i
        int[] prefix = new int[n];
        for (int i = 1; i < n; i++) {
            prefix[i] = prefix[i - 1] + travel[i - 1];
        }

        // Count total units and last occurrence index for each type
        int totalUnits = 0;
        int lastM = -1, lastP = -1, lastG = -1;

        for (int i = 0; i < n; i++) {
            String s = garbage[i];
            for (int j = 0; j < s.length(); j++) {
                char c = s.charAt(j);
                totalUnits++; // each character represents one unit of garbage
                if (c == 'M') {
                    lastM = i;
                } else if (c == 'P') {
                    lastP = i;
                } else if (c == 'G') {
                    lastG = i;
                }
            }
        }

        int travelTime = 0;
        if (lastM != -1) travelTime += prefix[lastM];
        if (lastP != -1) travelTime += prefix[lastP];
        if (lastG != -1) travelTime += prefix[lastG];

        return totalUnits + travelTime;
    }
}

