public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();

        // previous smaller element
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }

        stack.clear();
        // next smaller element
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            right[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }

        for (int i = 0; i < n; i++) {
            int v = nums[i];
            if (v == 0) {
                continue; // cannot satisfy v > threshold/k when v == 0 unless threshold < 0, ignore for simplicity
            }
            int required = threshold / v + 1; // smallest k such that v > threshold/k
            if (required <= 0) {
                required = 1;
            }
            int maxLen = right[i] - left[i] - 1;
            if (required <= maxLen) {
                return required;
            }
        }
        return -1;
    }
}

