public class Solution {
    private int find(int[] parent, int x) {
        if (parent[x] != x) {
            parent[x] = find(parent, parent[x]);
        }
        return parent[x];
    }

    private void union(int[] parent, int[] size, int a, int b) {
        int ra = find(parent, a);
        int rb = find(parent, b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int tmp = ra;
            ra = rb;
            rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        // sort indices by value descending
        Arrays.sort(order, (i, j) -> Integer.compare(nums[j], nums[i]));

        int[] parent = new int[n];
        int[] sz = new int[n];
        boolean[] active = new boolean[n];

        for (int idx : order) {
            active[idx] = true;
            parent[idx] = idx;
            sz[idx] = 1;

            if (idx > 0 && active[idx - 1]) {
                union(parent, sz, idx, idx - 1);
            }
            if (idx + 1 < n && active[idx + 1]) {
                union(parent, sz, idx, idx + 1);
            }

            int root = find(parent, idx);
            int compSize = sz[root];

            // smallest k such that nums[idx] > threshold / k
            // need k > threshold / nums[idx]
            int minK = threshold / nums[idx] + 1;
            if (minK <= compSize) {
                return minK;
            }
        }
        return -1;
    }
}

