public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        if (n == 0) {
            return -1;
        }
        int left = 1, right = n;
        int answer = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (existsSize(nums, threshold, mid)) {
                answer = mid;
                // we can break here because any valid size is acceptable,
                // but we continue searching for a smaller one (optional).
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return answer;
    }

    private boolean existsSize(int[] nums, int threshold, int k) {
        int consecutive = 0;
        for (int value : nums) {
            // Use long to avoid overflow when multiplying.
            if ((long) value * k > threshold) {
                consecutive++;
                if (consecutive >= k) {
                    return true;
                }
            } else {
                consecutive = 0;
            }
        }
        return false;
    }
}

