import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countPaths(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dp = new int[m][n];

        List<int[]> cells = new ArrayList<>(m * n);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells.add(new int[]{grid[i][j], i, j});
            }
        }

        Collections.sort(cells, Comparator.comparingInt(a -> a[0]));

        int[] dirs = {-1, 0, 1, 0, -1};
        long answer = 0;

        for (int[] cell : cells) {
            int val = cell[0];
            int i = cell[1];
            int j = cell[2];

            long ways = 1; // path consisting of the cell itself
            for (int d = 0; d < 4; d++) {
                int ni = i + dirs[d];
                int nj = j + dirs[d + 1];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] < val) {
                    ways += dp[ni][nj];
                }
            }
            dp[i][j] = (int) (ways % MOD);
            answer += dp[i][j];
            if (answer >= MOD) answer -= MOD;
        }

        return (int) answer;
    }
}

