        memo = new long[len][1 << 10];
        for (int i = 0; i < len; i++) {
            for (int j = 0; j < (1 << 10); j++) {
                memo[i][j] = -1L;
            }
        }
        long ans = dfs(0, true, true, 0);
        return (int) ans;
    }

    private long dfs(int pos, boolean tight, boolean leadingZero, int mask) {
        if (pos == len) {
            // if the whole number is just leading zeros, it represents 0 which is not counted
            return leadingZero ? 0 : 1;
        }
        if (!tight && memo[pos][mask] != -1) {
            return memo[pos][mask];
        }
        int limit = tight ? digits[pos] : 9;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            boolean nextLeadingZero = leadingZero && d == 0;
            if (!nextLeadingZero) {
                if ((mask & (1 << d)) != 0) {
                    continue; // digit already used
                }
            }
            boolean nextTight = tight && d == limit;
            int nextMask = nextLeadingZero ? mask : (mask | (1 << d));
            res += dfs(pos + 1, nextTight, nextLeadingZero, nextMask);
        }
        if (!tight) {
            memo[pos][mask] = res;
        }
        return res;
    }
