public class Solution {
    public int countSpecialNumbers(int n) {
        int[] digits = toDigits(n);
        int len = digits.length;
        int total = 0;

        // Count numbers with fewer digits than n
        for (int k = 1; k < len; k++) {
            total += 9 * perm(9, k - 1);
        }

        // Count numbers with the same length
        boolean[] used = new boolean[10];
        for (int i = 0; i < len; i++) {
            int cur = digits[i];
            int start = (i == 0) ? 1 : 0;
            for (int d = start; d < cur; d++) {
                if (!used[d]) {
                    int remainingPositions = len - i - 1;
                    int availableDigits = 10 - (i + 1);
                    total += perm(availableDigits, remainingPositions);
                }
            }
            if (used[cur]) {
                // current digit already used, cannot continue
                return total;
            }
            used[cur] = true;
        }
        // n itself has all distinct digits
        return total + 1;
    }

    // Convert integer to array of its digits (most significant first)
    private int[] toDigits(int n) {
        String s = Integer.toString(n);
        int[] d = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            d[i] = s.charAt(i) - '0';
        }
        return d;
    }

    // Permutation: mPk = m * (m-1) * ... * (m-k+1)
    private int perm(int m, int k) {
        int res = 1;
        for (int i = 0; i < k; i++) {
            res *= (m - i);
        }
        return res;
    }
}

