        dp = new int[len + 1][2][2][1 << 10];
        for (int i = 0; i <= len; i++) {
            for (int j = 0; j < 2; j++) {
                for (int k = 0; k < 2; k++) {
                    Arrays.fill(dp[i][j][k], -1);
                }
            }
        }
        return dfs(0, 1, 0, 1);
    }

    private int dfs(int pos, int tight, int mask, int leadingZero) {
        if (pos == digits.length) {
            // valid number only if we have placed at least one non‑zero digit
            return leadingZero == 0 ? 1 : 0;
        }
        if (dp[pos][tight][leadingZero][mask] != -1) {
            return dp[pos][tight][leadingZero][mask];
        }
        int limit = tight == 1 ? digits[pos] : 9;
        int res = 0;
        for (int d = 0; d <= limit; d++) {
            int nextTight = (tight == 1 && d == limit) ? 1 : 0;
            int nextLeadingZero = (leadingZero == 1 && d == 0) ? 1 : 0;

            if (nextLeadingZero == 1) {
                // still leading zeros, mask unchanged
                res += dfs(pos + 1, nextTight, mask, 1);
            } else {
                // digit is part of the number; must be unused
                if ((mask & (1 << d)) != 0) {
                    continue; // digit already used
                }
                res += dfs(pos + 1, nextTight, mask | (1 << d), 0);
            }
        }
        dp[pos][tight][leadingZero][mask] = res;
        return res;
    }
