public class Solution {
    // number n as an array, splitted by each digit
    public int countSpecialNumbers(int n) {
        char[] chars = Integer.toString(n).toCharArray();
        int len = chars.length;
        int[] digits = new int[len];
        for (int i = 0; i < len; i++) {
            digits[i] = chars[i] - '0';
        }

        // memo[pos][mask] for the case when tight == false and leadingZero == false
        // we store -1 when not computed
        int[][] memo = new int[len + 1][1 << 10];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }

        return (int) dfs(0, 0, true, true, digits, memo);
    }

    private long dfs(int pos, int mask, boolean tight, boolean leadingZero,
                     int[] digits, int[][] memo) {
        if (pos == digits.length) {
            // if the whole number is just leading zeros, it represents 0 which we don't count
            return leadingZero ? 0 : 1;
        }

        if (!tight && !leadingZero && memo[pos][mask] != -1) {
            return memo[pos][mask];
        }

        int limit = tight ? digits[pos] : 9;
        long total = 0;
        for (int d = 0; d <= limit; d++) {
            boolean nextLeadingZero = leadingZero && d == 0;
            boolean nextTight = tight && d == limit;

