import java.util.*;

public class Solution {
    public long kSum(int[] nums, int k) {
        // Min-heap to keep the k largest sums
        PriorityQueue<Long> minHeap = new PriorityQueue<>();
        // Start with the empty subsequence sum = 0
        minHeap.offer(0L);

        for (int num : nums) {
            // Snapshot of current sums in the heap
            List<Long> current = new ArrayList<>(minHeap);
            for (long sum : current) {
                long newSum = sum + num;
                minHeap.offer(newSum);
                if (minHeap.size() > k) {
                    minHeap.poll(); // remove smallest to keep only k largest
                }
            }
        }

        // If total number of possible sums is less than k, the heap size will be smaller.
        // In that case, the k-th largest sum is the smallest sum we have (the only element left after removals).
        return minHeap.peek();
    }
}

