import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    private static class Node {
        long sum;
        int idx;
        Node(long sum, int idx) {
            this.sum = sum;
            this.idx = idx;
        }
    }

    public long kSum(int[] nums, int k) {
        int n = nums.length;
        // sort in descending order
        Arrays.sort(nums);
        for (int i = 0; i < n / 2; i++) {
            int tmp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = tmp;
        }

        long initialSum = 0L;
        for (int v : nums) {
            if (v > 0) {
                initialSum += v;
            } else {
                break; // since sorted descending, once non‑positive appears all following are ≤0
            }
        }

        PriorityQueue<Node> pq = new PriorityQueue<>(
                (a, b) -> Long.compare(b.sum, a.sum)   // max‑heap based on sum
        );
        pq.offer(new Node(initialSum, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            long curSum = cur.sum;
            int i = cur.idx;
            k--;
            if (k == 0) {
                return curSum;
            }
            if (i >= n) {
                continue;
            }
            // Exclude nums[i] from the current sum
            pq.offer(new Node(curSum - nums[i], i + 1));
            // Exclude nums[i] and include nums[i+1] (if exists)
            if (i + 1 < n) {
                pq.offer(new Node(curSum - nums[i] + nums[i + 1], i + 1));
            }
        }
        // Should never reach here if k is valid
        return 0L;
    }
}

