import java.util.Arrays;
import java.util.HashSet;
import java.util.PriorityQueue;
import java.util.Objects;

public class Solution {
    private static class Node implements Comparable<Node> {
        long sum;
        int idx;

        Node(long sum, int idx) {
            this.sum = sum;
            this.idx = idx;
        }

        @Override
        public int compareTo(Node o) {
            return Long.compare(this.sum, o.sum);
        }
    }

    private static class Pair {
        long sum;
        int idx;

        Pair(long sum, int idx) {
            this.sum = sum;
            this.idx = idx;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return sum == pair.sum && idx == pair.idx;
        }

        @Override
        public int hashCode() {
            return Objects.hash(sum, idx);
        }
    }

    public long kSum(int[] nums, int k) {
        long base = 0;
        int n = nums.length;
        long[] costs = new long[n];
        for (int i = 0; i < n; i++) {
            if (nums[i] > 0) base += nums[i];
            costs[i] = Math.abs((long) nums[i]);
        }
        Arrays.sort(costs);

        // The smallest subset sum is 0 (empty selection)
        if (k == 1) {
            return base;
        }

        PriorityQueue<Node> pq = new PriorityQueue<>();
        HashSet<Pair> visited = new HashSet<>();

        if (n > 0) {
            Node first = new Node(costs[0], 0);
            pq.offer(first);
            visited.add(new Pair(first.sum, first.idx));
        }

        long kthSmallest = 0;
        int count = 1; // count of subset sums already considered (0 is already counted)

        while (count < k && !pq.isEmpty()) {
            Node cur = pq.poll();
            kthSmallest = cur.sum;
            count++;

            int i = cur.idx;
            if (i + 1 < n) {
                // Replace current element with the next one
                Node replace = new Node(cur.sum - costs[i] + costs[i + 1], i + 1);
                Pair rp = new Pair(replace.sum, replace.idx);
                if (!visited.contains(rp)) {
                    visited.add(rp);
                    pq.offer(replace);
                }

                // Add the next element in addition to current set
                Node add = new Node(cur.sum + costs[i + 1], i + 1);
                Pair ap = new Pair(add.sum, add.idx);
                if (!visited.contains(ap)) {
                    visited.add(ap);
                    pq.offer(add);
                }
            }
        }

        return base - kthSmallest;
    }
}

