import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    private static class Node implements Comparable<Node> {
        long sum;
        int idx;
        Node(long sum, int idx) {
            this.sum = sum;
            this.idx = idx;
        }
        @Override
        public int compareTo(Node o) {
            return Long.compare(this.sum, o.sum);
        }
    }

    public long kSum(int[] nums, int k) {
        if (nums == null || nums.length == 0) {
            // only empty subsequence exists
            return 0L;
        }

        long base = 0L; // sum of all positive numbers (maximum possible subsequence sum)
        long[] absVals = new long[nums.length];
        for (int i = 0; i < nums.length; i++) {
            int v = nums[i];
            if (v > 0) {
                base += v;
            }
            absVals[i] = Math.abs((long) v);
        }

        Arrays.sort(absVals); // ascending order

        // Find the (k‑1)‑th smallest subset sum of absVals (0‑based, 0 corresponds to empty subset)
        long smallSum;
        if (k == 1) {
            smallSum = 0L; // empty subset
        } else {
            PriorityQueue<Node> pq = new PriorityQueue<>();
            pq.offer(new Node(absVals[0], 0));
            int count = 1; // we have already counted the empty subset sum = 0
            long curSum = 0L;
            while (count < k) {
                Node cur = pq.poll();
                curSum = cur.sum;
                count++;
                int idx = cur.idx;
                if (idx + 1 < absVals.length) {
                    // include next element
                    pq.offer(new Node(curSum + absVals[idx + 1], idx + 1));
                    // replace current element with next element
                    pq.offer(new Node(curSum - absVals[idx] + absVals[idx + 1], idx + 1));
                }
            }
            smallSum = curSum;
        }

        // The k‑th largest subsequence sum is base minus the (k‑1)‑th smallest subset sum of absVals
        return base - smallSum;
    }
}

