import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    private static class Node {
        long sum;
        int idx;
        Node(long sum, int idx) {
            this.sum = sum;
            this.idx = idx;
        }
    }

    public long kSum(int[] nums, int k) {
        long base = 0L;
        long[] costs = new long[nums.length];
        int m = 0;
        for (int num : nums) {
            if (num > 0) {
                base += num;
                costs[m++] = num;            // cost of excluding this positive number
            } else {
                costs[m++] = - (long) num;   // cost of including this negative number
            }
        }
        // Trim and sort costs
        costs = Arrays.copyOf(costs, m);
        Arrays.sort(costs);

        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> {
            if (a.sum == b.sum) return Integer.compare(a.idx, b.idx);
            return Long.compare(a.sum, b.sum);
        });

        pq.offer(new Node(0L, 0));
        long kthCost = 0L;

        for (int count = 0; count < k; count++) {
            Node cur = pq.poll();
            kthCost = cur.sum;
            int i = cur.idx;
            if (i < m) {
                // take costs[i]
                pq.offer(new Node(cur.sum + costs[i], i + 1));
                // replace previous taken element with costs[i] (if i > 0)
                if (i > 0) {
                    pq.offer(new Node(cur.sum - costs[i - 1] + costs[i], i + 1));
                }
            }
        }

        return base - kthCost;
    }
}

