        @SuppressWarnings("unchecked")
        Set<String>[] groups = new Set[26];
        for (int i = 0; i < 26; i++) {
            groups[i] = new HashSet<>();
        }

        // Populate groups
        for (String idea : ideas) {
            if (idea == null || idea.isEmpty()) continue;
            int idx = idea.charAt(0) - 'a';
            String suffix = idea.substring(1);
            groups[idx].add(suffix);
        }

        long result = 0L;

        // Compare each pair of different starting letters
        for (int i = 0; i < 26; i++) {
            for (int j = i + 1; j < 26; j++) {
                Set<String> setI = groups[i];
                Set<String> setJ = groups[j];
                if (setI.isEmpty() || setJ.isEmpty()) continue;

                int uniqueInI = 0;
                for (String s : setI) {
                    if (!setJ.contains(s)) {
                        uniqueInI++;
                    }
                }

                int uniqueInJ = 0;
                for (String s : setJ) {
                    if (!setI.contains(s)) {
                        uniqueInJ++;
                    }
                }

                // Each ordered pair contributes two distinct company names
                result += (long) uniqueInI * uniqueInJ * 2;
            }
        }

