public class Solution {
    public long distinctNames(String[] ideas) {
        // groups of suffixes indexed by first character (0-25)
        @SuppressWarnings("unchecked")
        Set<String>[] groups = new Set[26];
        for (int i = 0; i < 26; i++) {
            groups[i] = new HashSet<>();
        }

        // Fill groups with suffixes (the part after the first character)
        for (String idea : ideas) {
            char first = idea.charAt(0);
            String suffix = idea.substring(1);
            groups[first - 'a'].add(suffix);
        }

        long result = 0L;

        // Compare each pair of different first letters
        for (int i = 0; i < 26; i++) {
            if (groups[i].isEmpty()) continue;
            for (int j = i + 1; j < 26; j++) {
                if (groups[j].isEmpty()) continue;

                Set<String> setI = groups[i];
                Set<String> setJ = groups[j];

                // Count common suffixes
                int common = 0;
                // iterate over the smaller set for efficiency
                if (setI.size() < setJ.size()) {
                    for (String s : setI) {
                        if (setJ.contains(s)) {
                            common++;
                        }
                    }
                } else {
                    for (String s : setJ) {
                        if (setI.contains(s)) {
                            common++;
                        }
                    }
                }

                long onlyI = setI.size() - common;
                long onlyJ = setJ.size() - common;

                // Each ordered pair (i->j, j->i) is counted, hence *2
                result += onlyI * onlyJ * 2;
            }
        }

        return result;
    }
}

