public class Solution {
    public long countSubarrays(int[] nums, long k) {
        int n = nums.length;
        long ans = 0;
        long sum = 0;
        int r = 0; // exclusive right bound of the current window

        for (int l = 0; l < n; l++) {
            // expand the window as far as the condition holds
            while (r < n) {
                long newSum = sum + nums[r];
                long len = r - l + 1; // length after adding nums[r]
                long limit = k / len;
                boolean ok;
                if (newSum < limit) {
                    ok = true;
                } else if (newSum == limit && k % len != 0) {
                    ok = true;
                } else {
                    ok = false;
                }
                if (ok) {
                    sum = newSum;
                    r++;
                } else {
                    break;
                }
            }

            // all subarrays starting at l and ending before r satisfy the condition
            ans += r - l;

            // shrink window from the left for the next iteration
            if (r > l) {
                sum -= nums[l];
            } else {
                // window is empty, move r to the next position
                r = l + 1;
            }
        }

        return ans;
    }
}

