public class Solution {
    public long countSubarrays(int[] nums, long k) {
        if (k <= 0) {
            return 0L;
        }
        long count = 0L;
        long sum = 0L;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            while (left <= right) {
                int len = right - left + 1;
                long ceilDiv = (k + len - 1) / len; // smallest sum that makes product >= k
                if (sum < ceilDiv) {
                    break;
                }
                sum -= nums[left];
                left++;
            }
            count += (right - left + 1);
        }
        return count;
    }
}

