public class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        // Compute GCD of all elements in numsDivide
        int g = 0;
        for (int val : numsDivide) {
            g = gcd(g, val);
        }

        // Sort nums to consider deletions from smallest to largest
        Arrays.sort(nums);

        int deletions = 0;
        for (int num : nums) {
            if (g % num == 0) {
                return deletions;
            }
            deletions++;
        }
        // No element can divide the GCD
        return -1;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

