public class Solution {
    private int[] xorSub;
    private int[] parent;
    private int[] tin;
    private int[] tout;
    private int timer;
    private List<Integer>[] graph;

    private void dfs(int node, int par, int[] nums) {
        parent[node] = par;
        tin[node] = timer++;
        int curXor = nums[node];
        for (int nb : graph[node]) {
            if (nb == par) continue;
            dfs(nb, node, nums);
            curXor ^= xorSub[nb];
        }
        xorSub[node] = curXor;
        tout[node] = timer++;
    }

    private boolean isAncestor(int u, int v) {
        return tin[u] <= tin[v] && tout[v] <= tout[u];
    }

    public int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        xorSub = new int[n];
        parent = new int[n];
        tin = new int[n];
        tout = new int[n];
        timer = 0;
        dfs(0, -1, nums);
        int totalXor = xorSub[0];

        int answer = Integer.MAX_VALUE;
        for (int i = 1; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int a, b, c;
                if (isAncestor(i, j)) {
                    a = xorSub[j];
                    b = xorSub[i] ^ xorSub[j];
                    c = totalXor ^ xorSub[i];
                } else if (isAncestor(j, i)) {
                    a = xorSub[i];
                    b = xorSub[j] ^ xorSub[i];
                    c = totalXor ^ xorSub[j];
                } else {
                    a = xorSub[i];
                    b = xorSub[j];
                    c = totalXor ^ a ^ b;
                }
                int max = Math.max(a, Math.max(b, c));
                int min = Math.min(a, Math.min(b, c));
                answer = Math.min(answer, max - min);
            }
        }
        return answer;
    }
}

