                    y = xorSub[j] ^ xorSub[i];
                    z = totalXor ^ xorSub[j];
                } else {
                    // disjoint subtrees
                    x = xorSub[i];
                    y = xorSub[j];
                    z = totalXor ^ xorSub[i] ^ xorSub[j];
                }

                int max = Math.max(x, Math.max(y, z));
