        subXor[node] = xor;
        tout[node] = timer++;
    }

    private boolean inSubtree(int node, int anc) {
        return tin[anc] <= tin[node] && tout[node] <= tout[anc];
    }

    public int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        parent = new int[n];
        tin = new int[n];
        tout = new int[n];
        subXor = new int[n];
        timer = 0;
        dfs(0, -1, graph, nums);

        int totalXor = subXor[0];
        int answer = Integer.MAX_VALUE;

        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            int child;
            if (parent[u] == v) {
                child = u;
            } else if (parent[v] == u) {
                child = v;
            } else {
                continue; // should not happen
            }
            int childXor = subXor[child];
            int restXor = totalXor ^ childXor;

            for (int j = 0; j < edges.length; j++) {
                if (i == j) continue;
                int a = edges[j][0];
                int b = edges[j][1];
                boolean aIn = inSubtree(a, child);
                boolean bIn = inSubtree(b, child);

                if (aIn && bIn) {
                    // second edge inside the child component
                    int deeper = (parent[a] == b) ? a : b;
                    int part1 = subXor[deeper];
                    int part2 = childXor ^ part1;
                    int part3 = restXor;
                    int max = Math.max(part1, Math.max(part2, part3));
                    int min = Math.min(part1, Math.min(part2, part3));
                    answer = Math.min(answer, max - min);
                } else if (!aIn && !bIn) {
                    // second edge inside the remaining component
                    int deeper = (parent[a] == b) ? a : b;
                    int part1 = subXor[deeper];
                    int part2 = restXor ^ part1;
                    int part3 = childXor;
                    int max = Math.max(part1, Math.max(part2, part3));
                    int min = Math.min(part1, Math.min(part2, part3));
                    answer = Math.min(answer, max - min);
                }
                // edges crossing the cut are ignored
            }
        }

        return answer;
    }
}

