        timer = 0;

        dfs(0, -1, nums);
        totalXor = subtreeXor[0];

        int answer = Integer.MAX_VALUE;

        // consider each node (except root) as a possible first cut edge (node - parent[node])
        for (int i = 1; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
