public class Solution {
    public String largestPalindromic(String num) {
        int[] cnt = new int[10];
        for (int i = 0; i < num.length(); i++) {
            cnt[num.charAt(i) - '0']++;
        }

        StringBuilder left = new StringBuilder();

        // add pairs for digits 9 to 1 (non‑zero) first
        for (int d = 9; d >= 1; d--) {
            int pairs = cnt[d] / 2;
            for (int i = 0; i < pairs; i++) {
                left.append((char) ('0' + d));
            }
            cnt[d] -= pairs * 2;
        }

        // handle zeros: they can be used only if we already have some non‑zero digit in the left part
        int zeroPairs = cnt[0] / 2;
        if (left.length() > 0) {
            for (int i = 0; i < zeroPairs; i++) {
                left.append('0');
            }
            cnt[0] -= zeroPairs * 2;
        }

        // choose the middle digit (largest remaining digit with odd count)
        char middle = 0;
        for (int d = 9; d >= 0; d--) {
            if (cnt[d] > 0) {
                middle = (char) ('0' + d);
                break;
            }
        }

        // build the palindrome
        String leftStr = left.toString();
        StringBuilder result = new StringBuilder();
        result.append(leftStr);
        if (middle != 0) {
            result.append(middle);
        }
        result.append(new StringBuilder(leftStr).reverse());

        // if nothing was added (only zeros were available), return "0"
        if (result.length() == 0) {
            return "0";
        }
        // when result consists only of zeros (e.g., "000"), collapse to single "0"
        int i = 0;
        while (i < result.length() - 1 && result.charAt(i) == '0') {
            i++;
        }
        if (i > 0) {
            // all characters are zero
            return "0";
        }
        return result.toString();
    }
}

