        // Build the left half using the highest possible digits
        for (int d = 9; d >= 0; d--) {
            int pairs = cnt[d] / 2;
            if (pairs == 0) continue;

            // Do not place leading zeros unless we already have a non‑zero digit in the left half
            if (d == 0 && left.length() == 0) {
                continue;
