public class Solution {
    private class UF {
        int[] parent;
        long[] sum;

        UF(int n) {
            parent = new int[n];
            sum = new long[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                sum[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            // attach rb to ra
            parent[rb] = ra;
            sum[ra] += sum[rb];
        }

        void setSum(int x, long value) {
            sum[x] = value;
        }

        long getSum(int x) {
            return sum[find(x)];
        }
    }

    public long[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        UF uf = new UF(n);
        boolean[] active = new boolean[n];
        long[] answer = new long[n];
