        for (int i = n - 1; i >= 0; i--) {
            answer[i] = curMax;
            int idx = removeQueries[i];
            active[idx] = true;
            uf.setSum(idx, nums[idx]);

            if (idx > 0 && active[idx - 1]) {
                uf.union(idx, idx - 1);
            }
            if (idx + 1 < n && active[idx + 1]) {
                uf.union(idx, idx + 1);
            }

            curMax = Math.max(curMax, uf.getSum(idx));
        }

        return answer;
