public class Solution {
    // Union-Find (Disjoint Set Union) structure that also tracks the sum of each component
    private static class DSU {
        int[] parent;
        int[] size;
        long[] sum;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            sum = new long[n];
            Arrays.fill(parent, -1); // -1 indicates not yet activated
        }

        // initialize a single element component
        void makeSet(int x, long value) {
            parent[x] = x;
            size[x] = 1;
            sum[x] = value;
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            // union by size
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
            sum[ra] += sum[rb];
        }

        long componentSum(int x) {
            return sum[find(x)];
        }
    }

    /**
     * Returns the maximum segment sum after each removal.
     *
     * @param nums          the original array of positive integers
     * @param removeQueries indices to be removed in order
     * @return an array where answer[i] is the maximum segment sum after the i‑th removal
     */
    public long[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        long[] answer = new long[n];
        DSU dsu = new DSU(n);
        boolean[] active = new boolean[n];
        long currentMax = 0L;

        // Process removals in reverse: we add elements back one by one
        for (int i = n - 1; i >= 0; i--) {
            answer[i] = currentMax;               // max sum after i‑th removal
            int idx = removeQueries[i];
            active[idx] = true;
            dsu.makeSet(idx, nums[idx]);

            // try to merge with left neighbor
            if (idx > 0 && active[idx - 1]) {
                dsu.union(idx, idx - 1);
            }
            // try to merge with right neighbor
            if (idx + 1 < n && active[idx + 1]) {
                dsu.union(idx, idx + 1);
            }

            long segmentSum = dsu.componentSum(idx);
            if (segmentSum > currentMax) {
                currentMax = segmentSum;
            }
        }
        return answer;
    }
}

