public class Solution {
    private static final int MOD = 1_000_000_007;

    private long modPow(long a, long e) {
        long res = 1;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * a) % MOD;
            }
            a = (a * a) % MOD;
            e >>= 1;
        }
        return res;
    }

    public int idealArrays(int n, int maxValue) {
        // Pre‑compute proper divisors for each number up to maxValue
        List<Integer>[] divisors = new ArrayList[maxValue + 1];
        for (int i = 1; i <= maxValue; i++) {
            divisors[i] = new ArrayList<>();
        }
        for (int d = 1; d <= maxValue; d++) {
            for (int multiple = d * 2; multiple <= maxValue; multiple += d) {
                divisors[multiple].add(d); // d is a proper divisor of multiple
            }
        }

        // The longest strictly increasing divisor chain cannot exceed log2(maxValue) + 1
        int maxLen = Math.min(n, 14); // 2^14 = 16384 > 10^4, safe upper bound

        long[][] dp = new long[maxLen + 1][maxValue + 1];
        // Length 1 chains: each value alone
        for (int v = 1; v <= maxValue; v++) {
            dp[1][v] = 1;
        }

        // Build DP for longer strictly increasing chains
        for (int len = 2; len <= maxLen; len++) {
            for (int v = 1; v <= maxValue; v++) {
                long sum = 0;
                for (int d : divisors[v]) {
                    sum += dp[len - 1][d];
                    if (sum >= MOD) sum -= MOD;
                }
                dp[len][v] = sum;
            }
        }

        // Pre‑compute factorials and inverse factorials for combinations
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        // Helper to compute C(a, b)
        java.util.function.BiFunction<Integer, Integer, Long> comb = (a, b) -> {
            if (b < 0 || b > a) return 0L;
            return fact[a] * invFact[b] % MOD * invFact[a - b] % MOD;
        };

        long answer = 0;
        for (int len = 1; len <= maxLen; len++) {
            long waysToPlace = comb.apply(n - 1, len - 1);
            if (waysToPlace == 0) continue;
            long sum = 0;
            for (int v = 1; v <= maxValue; v++) {
                sum += dp[len][v];
                if (sum >= MOD) sum -= MOD;
            }
            answer = (answer + sum * waysToPlace) % MOD;
        }

        return (int) answer;
    }
}

