        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        // Helper to compute C(n-1, k-1)
        java.util.function.BiFunction<Integer, Integer, Long> comb = (nn, kk) -> {
            if (kk < 0 || kk > nn) return 0L;
            return fact[nn] * invFact[kk] % MOD * invFact[nn - kk] % MOD;
        };

        long answer = 0;
        for (int v = 1; v <= maxValue; v++) {
            for (int k = 1; k <= maxLen; k++) {
                long waysChain = dp[k][v];
                if (waysChain == 0) continue;
                long waysPlace = comb.apply(n - 1, k - 1);
                if (waysPlace == 0) continue;
                answer = (answer + waysChain * waysPlace) % MOD;
            }
        }
        return (int) answer;
    }

    private long modPow(long base, long exp) {
        long result = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * b % MOD;
            }
            b = b * b % MOD;
            exp >>= 1;
        }
        return result;
    }
}

