public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        // 0 = unvisited, 1 = visiting (in current recursion stack), 2 = visited (finished)
        int[] state = new int[n];
        // depth when node was first visited in the current traversal
        int[] depth = new int[n];
        int maxLen = -1;

        for (int i = 0; i < n; i++) {
            if (state[i] != 0) {
                continue;
            }
            int cur = i;
            int step = 0;
            while (cur != -1 && state[cur] == 0) {
                state[cur] = 1;          // mark as visiting
                depth[cur] = step;       // record step index
                step++;
                cur = edges[cur];
            }

            // If we stopped because we reached a node that is currently being visited,
            // we have found a cycle.
            if (cur != -1 && state[cur] == 1) {
                int cycleLen = step - depth[cur];
                if (cycleLen > maxLen) {
                    maxLen = cycleLen;
                }
            }

            // Walk again from the start node to mark all nodes in this traversal as finished.
            cur = i;
            while (cur != -1 && state[cur] == 1) {
                state[cur] = 2; // finished
                cur = edges[cur];
            }
        }

        return maxLen;
    }
}

