                state[cur] = 1;               // mark as visiting
                depth[cur] = step++;
                path.add(cur);
                cur = edges[cur];
            }

            if (cur != -1 && state[cur] == 1) {
                // found a cycle; length = current step - depth of the node where cycle starts
                int cycleLen = step - depth[cur];
                if (cycleLen > longest) {
                    longest = cycleLen;
                }
            }

            // mark all nodes in the traversed path as processed
            for (int node : path) {
                state[node] = 2;
            }
        }

        return longest;
    }
