    public int longestCycle(int[] edges) {
        int n = edges.length;
        int[] visitId = new int[n];
        int[] step = new int[n];
        int traversal = 1;
        int maxLen = -1;

        for (int i = 0; i < n; i++) {
            if (visitId[i] != 0) {
                continue;
            }
            int cur = i;
            int curStep = 1;
            while (cur != -1 && visitId[cur] == 0) {
                visitId[cur] = traversal;
                step[cur] = curStep++;
                cur = edges[cur];
            }
            if (cur != -1 && visitId[cur] == traversal) {
                int cycleLen = curStep - step[cur];
                if (cycleLen > maxLen) {
                    maxLen = cycleLen;
                }
            }
            traversal++;
        }
        return maxLen;
    }
}

