public class Solution {
    public double calculateTax(int[][] brackets, int income) {
        double tax = 0.0;
        int previousUpper = 0;
        for (int i = 0; i < brackets.length; i++) {
            int upper = brackets[i][0];
            int percent = brackets[i][1];
            int taxable = Math.min(income, upper) - previousUpper;
            if (taxable > 0) {
                tax += taxable * percent / 100.0;
            }
            previousUpper = upper;
            if (income <= upper) {
                return tax;
            }
        }
        // If income exceeds the last bracket's upper bound
        if (income > previousUpper) {
            int lastPercent = brackets[brackets.length - 1][1];
            tax += (income - previousUpper) * lastPercent / 100.0;
        }
        return tax;
    }
}

