public class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;
        for (int i = 0; i < n; i++) {
            if (grid[i].length != n) {
                // Not a square matrix, but per problem constraints this shouldn't happen.
                return false;
            }
            for (int j = 0; j < n; j++) {
                boolean isDiagonal = (i == j) || (i + j == n - 1);
                if (isDiagonal) {
                    if (grid[i][j] == 0) {
                        return false;
                    }
                } else {
                    if (grid[i][j] != 0) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

