import java.util.Collections;
import java.util.TreeMap;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        TreeMap<Integer, Long> freq = new TreeMap<>(Collections.reverseOrder());

        for (int i = 0; i < n; i++) {
            int diff = Math.abs(nums1[i] - nums2[i]);
            if (diff > 0) {
                freq.put(diff, freq.getOrDefault(diff, 0L) + 1);
            }
        }

        long k = (long) k1 + k2;

        while (k > 0 && !freq.isEmpty() && freq.firstKey() > 0) {
            int curDiff = freq.firstKey();
            long count = freq.get(curDiff);
            freq.remove(curDiff);

            Integer nextKeyObj = freq.isEmpty() ? null : freq.firstKey();
            int nextDiff = (nextKeyObj == null) ? 0 : nextKeyObj;

            long stepsToNext = (long) (curDiff - nextDiff) * count;

            if (k >= stepsToNext) {
                // Reduce all current diffs down to nextDiff
                freq.put(nextDiff, freq.getOrDefault(nextDiff, 0L) + count);
                k -= stepsToNext;
            } else {
                long delta = k / count;          // full reductions for each element
                long remainder = k % count;      // extra reductions for 'remainder' elements

                int reducedDiff = curDiff - (int) delta; // diff after full reductions

                // Elements that get only 'delta' reductions
                if (reducedDiff > 0) {
                    freq.put(reducedDiff, freq.getOrDefault(reducedDiff, 0L) + (count - remainder));
                }

                // Elements that get one extra reduction
                int extraReducedDiff = reducedDiff - 1;
                if (extraReducedDiff > 0) {
                    freq.put(extraReducedDiff, freq.getOrDefault(extraReducedDiff, 0L) + remainder);
                }
                // If extraReducedDiff == 0, those become zero and can be ignored

                k = 0; // all operations used
            }
        }

        long result = 0L;
        for (var entry : freq.entrySet()) {
            int diff = entry.getKey();
            long cnt = entry.getValue();
            result += (long) diff * diff * cnt;
        }
        return result;
    }
}

