import java.util.*;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        int maxDiff = 0;
        int[] diffs = new int[n];
        for (int i = 0; i < n; i++) {
            int d = Math.abs(nums1[i] - nums2[i]);
            diffs[i] = d;
            if (d > maxDiff) {
                maxDiff = d;
            }
        }

        long totalOps = (long) k1 + (long) k2;
        if (maxDiff == 0) {
            // all differences are already zero; no need to use operations
            return 0L;
        }

        // frequency array for each possible difference value
        long[] freq = new long[maxDiff + 1];
        for (int d : diffs) {
            freq[d]++;
        }

        int current = maxDiff;
        while (totalOps > 0 && current > 0) {
            if (freq[current] == 0) {
                current--;
                continue;
            }
            long move = Math.min(totalOps, freq[current]);
            freq[current] -= move;
            freq[current - 1] += move;
            totalOps -= move;
            // stay at same current if there are still items at this level,
            // otherwise the loop will decrement current in next iteration.
        }

        long result = 0L;
        for (int i = 0; i <= maxDiff; i++) {
            if (freq[i] != 0) {
                result += freq[i] * (long) i * (long) i;
            }
        }
        return result;
    }
}

