import java.util.Arrays;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        long[] diffs = new long[n];
        long totalDiff = 0;
        for (int i = 0; i < n; i++) {
            long d = Math.abs((long) nums1[i] - (long) nums2[i]);
            diffs[i] = d;
            totalDiff += d;
        }

        long k = (long) k1 + (long) k2;
        if (k >= totalDiff) {
            return 0L;
        }

        Arrays.sort(diffs); // ascending
        int idx = n - 1;                 // current highest index
        long level = diffs[idx];         // current value of the highest group

        while (k > 0 && idx >= 0) {
            long cur = diffs[idx];
            int start = idx;
            while (start >= 0 && diffs[start] == cur) {
                start--;
            }
            int groupSize = idx - start;               // number of elements with value cur
            long next = (start >= 0) ? diffs[start] : 0; // value to bring this group down to
            long need = (cur - next) * groupSize;      // operations needed to reach next level

            if (k >= need) {
                // we can bring the whole group down to 'next'
                k -= need;
                level = next;
                idx = start; // move to the next lower group
            } else {
                // we can only partially reduce this group
                long decEach = k / groupSize;
                long newVal = cur - decEach;
                long remainder = k % groupSize; // these many elements get one extra decrement

                long result = 0L;
                // sum for elements lower than current group (indices 0..start)
                for (int i = 0; i <= start; i++) {
                    long d = diffs[i];
                    result += d * d;
                }

                long cntHigher = remainder;
                long cntLower = groupSize - remainder;
                long valHigher = newVal - 1;
                long valLower = newVal;

                result += cntHigher * (valHigher * valHigher);
                result += cntLower * (valLower * valLower);
                return result;
            }
        }

        // If we exit the loop, either k == 0 or all differences are reduced to zero
        long result = 0L;
        // sum for elements up to idx (they retain original values)
        for (int i = 0; i <= idx; i++) {
            long d = diffs[i];
            result += d * d;
        }
        // remaining elements (if any) have been reduced to 'level'
        if (idx < n - 1) {
            long highCount = n - (idx + 1);
            result += highCount * (level * level);
        }
        return result;
    }
}

