import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.Collections;

public class Solution {
    public List<List<Integer>> mergeSimilarItems(int[][] arr1, int[][] arr2) {
        Map<Integer, Integer> weightMap = new HashMap<>();

        // Process first array
        for (int[] item : arr1) {
            int value = item[0];
            int weight = item[1];
            weightMap.put(value, weightMap.getOrDefault(value, 0) + weight);
        }

        // Process second array
        for (int[] item : arr2) {
            int value = item[0];
            int weight = item[1];
            weightMap.put(value, weightMap.getOrDefault(value, 0) + weight);
        }

        // Sort keys
        List<Integer> values = new ArrayList<>(weightMap.keySet());
        Collections.sort(values);

        // Build result
        List<List<Integer>> result = new ArrayList<>();
        for (int val : values) {
            List<Integer> pair = new ArrayList<>(2);
            pair.add(val);
            pair.add(weightMap.get(val));
            result.add(pair);
        }

        return result;
    }
}

