import java.util.*;

public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        if (matrix == null || matrix.length == 0) return 0;
        int m = matrix.length;
        int n = matrix[0].length;
        if (numSelect > n) numSelect = n;

        int size = 1 << n;
        int[] freq = new int[size];

        // Build frequency of each row mask
        for (int[] row : matrix) {
            int mask = 0;
            for (int col = 0; col < n; col++) {
                if (row[col] == 1) {
                    mask |= (1 << col);
                }
            }
            freq[mask]++;
        }

        // SOS DP: dp[mask] = sum of freq[submask] where submask ⊆ mask
        int[] dp = Arrays.copyOf(freq, size);
        for (int i = 0; i < n; i++) {
            for (int mask = 0; mask < size; mask++) {
                if ((mask & (1 << i)) != 0) {
                    dp[mask] += dp[mask ^ (1 << i)];
                }
            }
        }

        int maxRows = 0;
        for (int mask = 0; mask < size; mask++) {
            if (Integer.bitCount(mask) == numSelect) {
                if (dp[mask] > maxRows) {
                    maxRows = dp[mask];
                }
            }
        }
        return maxRows;
    }
}

