import java.util.*;

public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        if (m == 0) return 0;
        int n = matrix[0].length;
        if (numSelect > n) numSelect = n; // just in case

        // Build frequency of row masks
        int size = 1 << n;
        int[] cnt = new int[size];
        for (int[] row : matrix) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (row[j] == 1) {
                    mask |= (1 << j);
                }
            }
            cnt[mask]++;
        }

        int maxCovered = 0;

        // Enumerate all column subsets of size numSelect
        if (numSelect == 0) {
            // only rows with mask 0 are covered
            return cnt[0];
        }

        // initial subset: lowest numSelect bits set
        int subset = (1 << numSelect) - 1;
        int limit = 1 << n;
        while (subset < limit) {
            // sum counts of all row masks that are submasks of subset
            int covered = 0;
            int sub = subset;
            while (true) {
                covered += cnt[sub];
                if (sub == 0) break;
                sub = (sub - 1) & subset;
            }
            if (covered > maxCovered) {
                maxCovered = covered;
            }
            // Gosper's hack: generate next combination with same bit count
            int c = subset & -subset;
            int r = subset + c;
            if (r == 0) break; // overflow
            subset = (((r ^ subset) >>> 2) / c) | r;
        }

        return maxCovered;
    }
}

