public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        if (m == 0) return 0;
        int n = matrix[0].length;
        if (numSelect >= n) {
            // selecting all columns covers every row
            return m;
        }

        // If n is small enough, use SOS DP on bit masks
        if (n <= 20) {
            int totalMasks = 1 << n;
            int[] cnt = new int[totalMasks];
            for (int[] row : matrix) {
                int mask = 0;
                for (int col = 0; col < n; col++) {
                    if (row[col] == 1) {
                        mask |= (1 << col);
                    }
                }
                cnt[mask]++;
            }

            int[] subMaskSum = cnt.clone();
            for (int i = 0; i < n; i++) {
                for (int mask = 0; mask < totalMasks; mask++) {
                    if ((mask & (1 << i)) != 0) {
                        subMaskSum[mask] += subMaskSum[mask ^ (1 << i)];
                    }
                }
