public class Solution {
    private int n;
    private int numSelect;
    private List<Long> masks;
    private List<Integer> counts;
    private int zeroRows;
    private int maxCovered;

    public int maximumRows(int[][] matrix, int numSelect) {
        this.n = matrix[0].length;
        this.numSelect = Math.min(numSelect, n); // cannot select more than n columns
        Map<Long, Integer> freq = new HashMap<>();

        for (int[] row : matrix) {
            long mask = 0L;
            for (int col = 0; col < n; col++) {
                if (row[col] == 1) {
                    mask |= 1L << col;
                }
            }
            freq.merge(mask, 1, Integer::sum);
        }

        zeroRows = freq.getOrDefault(0L, 0);
        freq.remove(0L);

        masks = new ArrayList<>(freq.keySet());
        counts = new ArrayList<>();
        for (Long m : masks) {
            counts.add(freq.get(m));
        }

        if (this.numSelect == 0) {
            return zeroRows;
        }
        if (this.numSelect >= n) {
            // all columns can be selected, every row is covered
            return zeroRows + masks.stream().mapToInt(i -> counts.get(masks.indexOf(i))).sum();
        }

        maxCovered = zeroRows;
        dfs(0, 0, 0L);
        return maxCovered;
    }

    private void dfs(int start, int selected, long curMask) {
        if (selected == numSelect) {
            evaluate(curMask);
            return;
        }
        // prune: not enough columns left
        for (int i = start; i <= n - (numSelect - selected); i++) {
            dfs(i + 1, selected + 1, curMask | (1L << i));
        }
    }

    private void evaluate(long selectedMask) {
        int covered = zeroRows;
        for (int i = 0; i < masks.size(); i++) {
            long rowMask = masks.get(i);
            if ((rowMask & ~selectedMask) == 0) {
                covered += counts.get(i);
            }
        }
        if (covered > maxCovered) {
            maxCovered = covered;
        }
    }
}

