public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        if (m == 0) {
            return 0;
        }
        int n = matrix[0].length;
        if (numSelect > n) {
            numSelect = n;
        }

        List<Long> rowMasks = new ArrayList<>();
        int zeroRows = 0;

        for (int i = 0; i < m; i++) {
            long mask = 0L;
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    mask |= (1L << j);
                }
            }
            if (mask == 0L) {
                zeroRows++;
            } else {
                rowMasks.add(mask);
            }
        }

        if (numSelect == 0) {
            return zeroRows;
        }

        int maxCovered = 0;
        int[] comb = new int[numSelect];
        for (int i = 0; i < numSelect; i++) {
            comb[i] = i;
        }

        while (true) {
            long selectedMask = 0L;
            for (int idx : comb) {
                selectedMask |= (1L << idx);
            }

            int covered = zeroRows;
            for (long rowMask : rowMasks) {
                if ((rowMask & ~selectedMask) == 0L) {
                    covered++;
                }
            }
            if (covered > maxCovered) {
                maxCovered = covered;
            }

            // generate next combination
            int i;
            for (i = numSelect - 1; i >= 0; i--) {
                if (comb[i] != i + n - numSelect) {
                    break;
                }
            }
            if (i < 0) {
                break; // all combinations have been processed
            }
            comb[i]++;
            for (int j = i + 1; j < numSelect; j++) {
                comb[j] = comb[j - 1] + 1;
            }
        }

        return maxCovered;
    }
}

