public class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        long[][] priceMap = new long[m + 1][n + 1];
        for (int[] p : prices) {
            int h = p[0];
            int w = p[1];
            int price = p[2];
            if (h <= m && w <= n) {
                if (price > priceMap[h][w]) {
                    priceMap[h][w] = price;
                }
            }
        }

        long[][] dp = new long[m + 1][n + 1];

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                long best = priceMap[i][j]; // sell as whole if possible

                // vertical cuts
                for (int cut = 1; cut < j; cut++) {
                    long candidate = dp[i][cut] + dp[i][j - cut];
                    if (candidate > best) {
                        best = candidate;
                    }
                }

                // horizontal cuts
                for (int cut = 1; cut < i; cut++) {
                    long candidate = dp[cut][j] + dp[i - cut][j];
                    if (candidate > best) {
                        best = candidate;
                    }
                }

                dp[i][j] = best;
            }
        }

        return dp[m][n];
    }
}

