public class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        long[][] dp = new long[m + 1][n + 1];

        // Initialize with given prices (keep the maximum if duplicates exist)
        for (int[] p : prices) {
            int h = p[0];
            int w = p[1];
            int price = p[2];
            if (h <= m && w <= n) {
                dp[h][w] = Math.max(dp[h][w], price);
            }
        }

        // Bottom‑up DP: compute best profit for every sub‑rectangle
        for (int height = 1; height <= m; height++) {
            for (int width = 1; width <= n; width++) {
                // Try vertical cuts (split the height)
                for (int cut = 1; cut <= height / 2; cut++) {
                    long candidate = dp[cut][width] + dp[height - cut][width];
                    if (candidate > dp[height][width]) {
                        dp[height][width] = candidate;
                    }
                }
                // Try horizontal cuts (split the width)
                for (int cut = 1; cut <= width / 2; cut++) {
                    long candidate = dp[height][cut] + dp[height][width - cut];
                    if (candidate > dp[height][width]) {
                        dp[height][width] = candidate;
                    }
                }
            }
        }

        return dp[m][n];
    }
}

