import java.util.*;

public class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        // priceMap[h][w] = max price for that exact size
        int[][] priceMap = new int[m + 1][n + 1];
        for (int[] p : prices) {
            int h = p[0];
            int w = p[1];
            int price = p[2];
            if (h <= m && w <= n) {
                priceMap[h][w] = Math.max(priceMap[h][w], price);
            }
        }

        long[][] memo = new long[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            Arrays.fill(memo[i], -1L);
        }

        return dfs(m, n, priceMap, memo);
    }

    private long dfs(int h, int w, int[][] priceMap, long[][] memo) {
        if (memo[h][w] != -1L) {
            return memo[h][w];
        }

        long best = priceMap[h][w]; // may be 0 if no direct price

        // vertical cuts
        for (int cut = 1; cut < w; cut++) {
            long left = dfs(h, cut, priceMap, memo);
            long right = dfs(h, w - cut, priceMap, memo);
            best = Math.max(best, left + right);
        }

        // horizontal cuts
        for (int cut = 1; cut < h; cut++) {
            long top = dfs(cut, w, priceMap, memo);
            long bottom = dfs(h - cut, w, priceMap, memo);
            best = Math.max(best, top + bottom);
        }

        memo[h][w] = best;
        return best;
    }
}

