public class Solution {
    public int[][] buildMatrix(int k, int[][] rowC, int[][] colC) {
        int[] rowOrder = topologicalSort(k, rowC);
        int[] colOrder = topologicalSort(k, colC);
        if (rowOrder == null || colOrder == null) {
            return new int[0][0];
        }

        Map<Integer, Integer> rowPos = new HashMap<>();
        Map<Integer, Integer> colPos = new HashMap<>();
        for (int i = 0; i < k; i++) {
            rowPos.put(rowOrder[i], i);
            colPos.put(colOrder[i], i);
        }

        int[][] matrix = new int[k][k];
        for (int num = 1; num <= k; num++) {
            int r = rowPos.get(num);
            int c = colPos.get(num);
            matrix[r][c] = num;
        }
        return matrix;
    }

    private int[] topologicalSort(int k, int[][] conditions) {
        List<List<Integer>> graph = new ArrayList<>(k + 1);
        for (int i = 0; i <= k; i++) {
            graph.add(new ArrayList<>());
        }
        int[] indegree = new int[k + 1];

        for (int[] cond : conditions) {
            int from = cond[0];
            int to = cond[1];
            graph.get(from).add(to);
            indegree[to]++;
        }

        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 1; i <= k; i++) {
            if (indegree[i] == 0) {
                queue.offer(i);
            }
        }

        int[] order = new int[k];
        int idx = 0;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            order[idx++] = node;
            for (int nei : graph.get(node)) {
                indegree[nei]--;
                if (indegree[nei] == 0) {
                    queue.offer(nei);
                }
            }
        }

        return idx == k ? order : null;
    }
}

