        for (int i = 0; i <= k; i++) {
            graph.add(new ArrayList<>());
        }
        int[] indegree = new int[k + 1];
        for (int[] cond : conditions) {
            int from = cond[0];
            int to = cond[1];
            graph.get(from).add(to);
            indegree[to]++;
        }

        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 1; i <= k; i++) {
            if (indegree[i] == 0) {
                queue.offer(i);
            }
        }

        List<Integer> order = new ArrayList<>(k);
        while (!queue.isEmpty()) {
            int node = queue.poll();
            order.add(node);
            for (int nei : graph.get(node)) {
                indegree[nei]--;
                if (indegree[nei] == 0) {
                    queue.offer(nei);
                }
            }
        }

        return order.size() == k ? order : null;
    }
}

