public class Solution {
    public int[] numberOfPairs(int[] nums) {
        if (nums == null || nums.length == 0) {
            return new int[]{0, 0};
        }
        Arrays.sort(nums);
        int pairs = 0;
        int i = 0;
        int n = nums.length;
        while (i < n - 1) {
            if (nums[i] == nums[i + 1]) {
                pairs++;
                i += 2; // skip the paired elements
            } else {
                i++;
            }
        }
        int leftovers = n - pairs * 2;
        return new int[]{pairs, leftovers};
    }
}

