public class Solution {
    public int minimumNumbers(int nums, int k) {
        // If the target sum is zero, the empty set satisfies the condition.
        if (nums == 0) {
            return 0;
        }

        // When k is 0, every allowed number ends with 0, i.e., is a multiple of 10.
        // The sum must therefore be a multiple of 10, and a single number equal to nums works.
        if (k == 0) {
            return (nums % 10 == 0) ? 1 : -1;
        }

        // Try to use i numbers that end with digit k.
        // The remaining part of the sum must be divisible by 10 (can be formed by numbers ending with 0).
        // It is sufficient to check i from 1 to 10 because the unit digit repeats every 10.
        for (int i = 1; i <= 10; i++) {
            int remaining = nums - i * k;
            if (remaining < 0) {
                continue;
            }
            if (remaining % 10 == 0) {
                return i;
            }
        }

        // No suitable count found.
        return -1;
    }
}

