        // Pre‑compute trimmed strings for every possible trim length
        String[][] trimmed = new String[len + 1][n];
        for (int t = 1; t <= len; t++) {
            int start = len - t;
            for (int i = 0; i < n; i++) {
                trimmed[t][i] = nums[i].substring(start);
            }
        }

        for (int i = 0; i < q; i++) {
            int k = queries[i][0];
            int trim = queries[i][1];

            Integer[] idx = new Integer[n];
            for (int j = 0; j < n; j++) {
                idx[j] = j;
            }

            Arrays.sort(idx, (a, b) -> {
                int cmp = trimmed[trim][a].compareTo(trimmed[trim][b]);
                if (cmp != 0) {
                    return cmp;
                }
                return Integer.compare(a, b);
            });

            answer[i] = idx[k - 1];
        }

        return answer;
    }
}

