import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    // Fast doubling method to compute (F(n), F(n+1)) modulo MOD
    private long[] fib(long n) {
        if (n == 0) {
            return new long[]{0, 1};
        }
        long[] half = fib(n >> 1);
        long a = half[0]; // F(k)
        long b = half[1]; // F(k+1)

        long c = (a * ((2 * b % MOD - a + MOD) % MOD)) % MOD; // F(2k)
        long d = (a * a % MOD + b * b % MOD) % MOD;           // F(2k+1)

        if ((n & 1) == 0) {
            return new long[]{c, d};
        } else {
            return new long[]{d, (c + d) % MOD};
        }
    }

    public int countHousePlacements(int n) {
        // Number of valid configurations on one side = Fib(n + 2)
        long waysOneSide = fib((long) n + 2)[0];
        long result = (waysOneSide * waysOneSide) % MOD;
        return (int) result;
    }
}

