public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int countHousePlacements(int n) {
        // dp0 = ways for length i-2, dp1 = ways for length i-1
        long dpPrevPrev = 1; // f(0)
        long dpPrev = 2;     // f(1)

        if (n == 0) {
            long ans = (dpPrevPrev * dpPrevPrev) % MOD;
            return (int) ans;
        }
        if (n == 1) {
            long ans = (dpPrev * dpPrev) % MOD;
            return (int) ans;
        }

        long current = 0;
        for (int i = 2; i <= n; i++) {
            current = (dpPrevPrev + dpPrev) % MOD; // f(i) = f(i-1) + f(i-2)
            dpPrevPrev = dpPrev;
            dpPrev = current;
        }

        long result = (dpPrev * dpPrev) % MOD;
        return (int) result;
    }
}

