public class Solution {
    public int[] answerQueries(int[] nums, int[] queries) {
        // Sort the numbers to consider the smallest elements first
        Arrays.sort(nums);
        int n = nums.length;
        // Build prefix sums (use long to avoid overflow)
        long[] prefix = new long[n];
        for (int i = 0; i < n; i++) {
            prefix[i] = nums[i] + (i > 0 ? prefix[i - 1] : 0L);
        }

        int m = queries.length;
        int[] answer = new int[m];
        for (int i = 0; i < m; i++) {
            long q = queries[i];
            // Binary search for the largest index where prefix[idx] <= q
            int lo = 0, hi = n - 1, pos = -1;
            while (lo <= hi) {
                int mid = lo + (hi - lo) / 2;
                if (prefix[mid] <= q) {
                    pos = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            answer[i] = pos + 1; // if pos == -1, result is 0
        }
        return answer;
    }
}

