public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);
        Set<Integer> passengerSet = new HashSet<>();
        for (int p : passengers) {
            passengerSet.add(p);
        }

        int pIdx = 0;
        int lastBoardedOnLastBus = -1;
        int boardedOnLastBus = 0;

        for (int bIdx = 0; bIdx < buses.length; bIdx++) {
            int busTime = buses[bIdx];
            int boarded = 0;
            while (pIdx < passengers.length && passengers[pIdx] <= busTime && boarded < capacity) {
                lastBoardedOnLastBus = passengers[pIdx];
                pIdx++;
                boarded++;
            }
            if (bIdx == buses.length - 1) {
                boardedOnLastBus = boarded;
            }
        }

        int answer;
        if (boardedOnLastBus < capacity) {
            answer = buses[buses.length - 1];
        } else {
            answer = lastBoardedOnLastBus - 1;
        }

        while (passengerSet.contains(answer)) {
            answer--;
        }
        return answer;
    }
}

