import java.util.HashSet;

public class Solution {
    public int countDistinctIntegers(int[] nums) {
        HashSet<Integer> distinct = new HashSet<>();
        for (int num : nums) {
            distinct.add(num);
            distinct.add(reverse(num));
        }
        return distinct.size();
    }

    private int reverse(int x) {
        int rev = 0;
        while (x > 0) {
            rev = rev * 10 + (x % 10);
            x /= 10;
        }
        return rev;
    }
}

