public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        int low = 0, high = n, ans = 0;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canForm(s, n, k, mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }

    private boolean canForm(String s, int n, int k, int len) {
        if (len == 0) return true;
        char[] stack = new char[len];
        int sz = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            while (sz > 0 && stack[sz - 1] > c && (sz - 1) + (n - i - 1) >= len) {
                sz--;
            }
            if (sz < len) {
                stack[sz++] = c;
            }
        }
        long val = 0;
        for (int i = 0; i < len; i++) {
            val = (val << 1) + (stack[i] - '0');
            if (val > k) return false;
        }
        return true;
    }
}

