public class Solution {
    public int longestSubsequence(String s, int k) {
        long cur = 0;
        int exponent = 0;
        int ans = 0;
        boolean canAddOnes = true;

        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c == '0') {
                ans++;
                exponent++;
            } else { // c == '1'
                if (!canAddOnes) {
                    continue;
                }
                if (exponent >= 63) {
                    canAddOnes = false;
                    continue;
                }
                long add = 1L << exponent;
                if (cur + add <= k) {
                    cur += add;
                    ans++;
                    exponent++;
                }
                // else: skip this '1' (do not increase exponent)
            }
        }
        return ans;
    }
}

