public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        int maxLen = 31; // maximum length of a subsequence containing at least one '1' that can be <= k
        long INF = Long.MAX_VALUE / 4;

        // dp[i][l] = minimal value achievable using a subsequence of length l from suffix starting at i
        long[][] dp = new long[n + 1][maxLen + 1];
        for (int l = 0; l <= maxLen; l++) {
            dp[n][l] = (l == 0) ? 0 : INF;
        }

        for (int i = n - 1; i >= 0; i--) {
            // inherit values when skipping current character
            for (int l = 0; l <= maxLen; l++) {
                dp[i][l] = dp[i + 1][l];
            }
            int bit = s.charAt(i) - '0';
            // take current character
            for (int l = 1; l <= maxLen; l++) {
                long prev = dp[i + 1][l - 1];
                if (prev != INF) {
                    long val = prev * 2 + bit;
                    if (val < dp[i][l]) {
                        dp[i][l] = val;
                    }
                }
            }
        }

        // prefix count of zeros
        int[] prefixZeros = new int[n];
        int zeroCnt = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0') {
                zeroCnt++;
            }
            prefixZeros[i] = zeroCnt;
        }

        int answer = zeroCnt; // all zeros subsequence

        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '1') {
                int leadingZeros = (i == 0) ? 0 : prefixZeros[i - 1];
                // r = number of additional bits after this leading '1' (core length = 1 + r)
                for (int r = 0; r <= maxLen - 1; r++) {
                    long suffixVal = dp[i + 1][r];
                    if (suffixVal == INF) {
                        continue;
                    }
                    long value = (1L << r) + suffixVal; // minimal value when this '1' is the first kept bit
                    if (value <= k) {
                        int totalLen = leadingZeros + 1 + r;
                        if (totalLen > answer) {
                            answer = totalLen;
                        }
                    }
                }
            }
        }

        return answer;
    }
}

