public class Solution {
    public int longestSubsequence(String s, int k) {
        long cur = 0L;               // current value of the subsequence
        long power = 1L;             // value contributed by a '1' at the next position (2^len)
        int count = 0;               // length of the subsequence built so far

        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c == '1') {
                if (cur + power <= k) {
                    cur += power;
                    count++;
                    // shift to next higher bit, guard against overflow
                    if (power <= (1L << 60)) {
                        power <<= 1;
                    }
                }
                // if we cannot take the '1', we simply skip it; power stays unchanged
            } else { // c == '0'
                count++;
                if (power <= (1L << 60)) {
                    power <<= 1;
                }
            }
        }
        return count;
    }
}

