public class Solution {
    public int countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int pos = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == k) {
                pos = i;
                break;
            }
        }
        // Count prefix balances to the left of k (including empty prefix)
        Map<Integer, Integer> leftCount = new HashMap<>();
        int balance = 0;
        leftCount.put(0, 1); // empty prefix
        for (int i = pos - 1; i >= 0; i--) {
            if (nums[i] > k) {
                balance++;
            } else if (nums[i] < k) {
                balance--;
            }
            leftCount.put(balance, leftCount.getOrDefault(balance, 0) + 1);
        }

        // Scan to the right, including k itself
        long ans = 0;
        balance = 0;
        for (int i = pos; i < n; i++) {
            if (i != pos) {
                if (nums[i] > k) {
                    balance++;
                } else if (nums[i] < k) {
                    balance--;
                }
            }
            // Need total balance (left + right) to be 0 or 1
            ans += leftCount.getOrDefault(-balance, 0);
            ans += leftCount.getOrDefault(1 - balance, 0);
        }
        return (int) ans;
    }
}

