import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public TreeNode reverseOddLevels(TreeNode root) {
        if (root == null) {
            return null;
        }
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int level = 0; // root is level 0 (even)
        while (!queue.isEmpty()) {
            int size = queue.size();
            List<TreeNode> currentLevelNodes = new ArrayList<>(size);
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                if (level % 2 == 1) {
                    currentLevelNodes.add(node);
                }
                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }
            if (level % 2 == 1) {
                int n = currentLevelNodes.size();
                for (int i = 0; i < n / 2; i++) {
                    int tmp = currentLevelNodes.get(i).val;
                    currentLevelNodes.get(i).val = currentLevelNodes.get(n - 1 - i).val;
                    currentLevelNodes.get(n - 1 - i).val = tmp;
                }
            }
            level++;
        }
        return root;
    }
}

