public class Solution {
    public int deleteGreatestValue(int[][] grid) {
        if (grid == null || grid.length == 0) {
            return 0;
        }
        int m = grid.length;
        int n = grid[0].length;
        // Sort each row in ascending order; we'll access from the end to get descending order.
        for (int i = 0; i < m; i++) {
            Arrays.sort(grid[i]);
        }
        int answer = 0;
