        for (int step = 0; step < n; step++) {
            int currentMax = 0;
            for (int row = 0; row < m; row++) {
                int value = grid[row][n - 1 - step]; // element removed at this step for this row
                if (value > currentMax) {
                    currentMax = value;
                }
            }
            answer += currentMax;
        }
        return answer;
    }
}

