public class Solution {
    public int unequalTriplets(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }

        long n = nums.length;
        long totalTriplets = n * (n - 1) * (n - 2) / 6; // C(n,3)

        long bad = 0;
        for (int c : freq.values()) {
            if (c >= 2) {
                // two equal, one different
                bad += (long) c * (c - 1) / 2 * (n - c);
            }
            if (c >= 3) {
                // all three equal
                bad += (long) c * (c - 1) * (c - 2) / 6;
            }
        }

        long good = totalTriplets - bad;
        return (int) good;
    }
}

