public class Solution {
    public int unequalTriplets(int[] nums) {
        // Count frequencies of each distinct number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.merge(num, 1, Integer::sum);
        }

        long answer = 0;
        long sumPrev = 0;      // sum of frequencies of processed distinct values
        long pairPrev = 0;     // sum of products of frequencies of all processed distinct pairs

        for (int freq : freqMap.values()) {
            // Each new value can form triplets with any previous pair
            answer += (long) freq * pairPrev;

            // Update pairPrev to include pairs formed with the current value
            pairPrev += (long) freq * sumPrev;

            // Update sumPrev to include current frequency
            sumPrev += freq;
        }

        return (int) answer;
    }
}

