public class Solution {
    public int unequalTriplets(int[] nums) {
        // Count frequency of each distinct number
        Map<Integer, Long> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0L) + 1);
        }

        long sum = 0L;          // Σ f_i
        long sumSq = 0L;        // Σ f_i^2
        long sumCube = 0L;      // Σ f_i^3

        for (long cnt : freqMap.values()) {
            sum += cnt;
            sumSq += cnt * cnt;
            sumCube += cnt * cnt * cnt;
        }

        // Number of triplets with three distinct values:
        // (S^3 - 3*S*Sq + 2*Cube) / 6
        long total = (sum * sum * sum - 3L * sum * sumSq + 2L * sumCube) / 6L;

        return (int) total;
    }
}

