public class Solution {
    public int unequalTriplets(int[] nums) {
        int n = nums.length;
        if (n < 3) {
            return 0;
        }

        // Count frequency of each distinct value
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.merge(num, 1, Integer::sum);
        }

        // Total number of ways to pick any three indices: C(n,3)
        long totalTriplets = ((long) n * (n - 1) * (n - 2)) / 6;

        long duplicateTriplets = 0; // triplets where at least two values are equal

        for (int f : freqMap.values()) {
            if (f >= 2) {
                // Triplets with exactly two equal values: C(f,2) * (n - f)
                long twoEqual = ((long) f * (f - 1) / 2) * (n - f);
                duplicateTriplets += twoEqual;
            }
            if (f >= 3) {
                // Triplets with all three equal values: C(f,3)
                long threeEqual = ((long) f * (f - 1) * (f - 2)) / 6;
                duplicateTriplets += threeEqual;
            }
        }

        long result = totalTriplets - duplicateTriplets;
        return (int) result;
    }
}

