public class Solution {
    public long numberOfPairs(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = (long) nums1[i] - (long) nums2[i];
        }
        return countWhileMergeSort(a, 0, n - 1, diff);
    }

    private long countWhileMergeSort(long[] arr, int left, int right, int diff) {
        if (left >= right) {
            return 0;
        }
        int mid = left + (right - left) / 2;
        long count = 0;
        count += countWhileMergeSort(arr, left, mid, diff);
        count += countWhileMergeSort(arr, mid + 1, right, diff);
        count += countCrossPairs(arr, left, mid, right, diff);
        merge(arr, left, mid, right);
        return count;
    }

    private long countCrossPairs(long[] arr, int left, int mid, int right, int diff) {
        long cnt = 0;
        int j = mid + 1;
        for (int i = left; i <= mid; i++) {
            while (j <= right && arr[j] < arr[i] - diff) {
                j++;
            }
            cnt += (right - j + 1);
        }
        return cnt;
    }

    private void merge(long[] arr, int left, int mid, int right) {
        int n1 = mid - left + 1;
        int n2 = right - mid;
        long[] leftArr = new long[n1];
        long[] rightArr = new long[n2];
        System.arraycopy(arr, left, leftArr, 0, n1);
        System.arraycopy(arr, mid + 1, rightArr, 0, n2);
        int i = 0, j = 0, k = left;
        while (i < n1 && j < n2) {
            if (leftArr[i] <= rightArr[j]) {
                arr[k++] = leftArr[i++];
            } else {
                arr[k++] = rightArr[j++];
            }
        }
        while (i < n1) {
            arr[k++] = leftArr[i++];
        }
        while (j < n2) {
            arr[k++] = rightArr[j++];
        }
    }
}

