public class Solution {
    public long numberOfPairs(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = (long) nums1[i] - (long) nums2[i];
        }

        // collect values for compression: a[i] and a[i] + diff
        long[] vals = new long[2 * n];
        for (int i = 0; i < n; i++) {
            vals[2 * i] = a[i];
            vals[2 * i + 1] = a[i] + diff;
        }
        Arrays.sort(vals);
        int m = 0;
        for (int i = 0; i < vals.length; i++) {
            if (i == 0 || vals[i] != vals[i - 1]) {
                vals[m++] = vals[i];
            }
        }
        long[] uniq = Arrays.copyOf(vals, m);

        FenwickTree bit = new FenwickTree(m);
        long ans = 0L;

        for (int i = 0; i < n; i++) {
            long threshold = a[i] + diff;
            int idx = upperBound(uniq, threshold);
            if (idx >= 0) {
                ans += bit.query(idx + 1); // BIT is 1‑based
            }
            int pos = Arrays.binarySearch(uniq, a[i]);
            bit.update(pos + 1, 1);
        }

        return ans;
    }

    // returns index of last element <= target, or -1 if none
    private int upperBound(long[] arr, long target) {
        int lo = 0, hi = arr.length - 1, res = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                res = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return res;
    }

    // Fenwick Tree for prefix sums
    private static class FenwickTree {
        private final long[] tree;
        private final int n;

        FenwickTree(int size) {
            n = size;
            tree = new long[n + 1];
        }

        void update(int idx, long delta) {
            while (idx <= n) {
                tree[idx] += delta;
                idx += idx & -idx;
            }
        }

        long query(int idx) {
            long sum = 0;
            while (idx > 0) {
                sum += tree[idx];
                idx -= idx & -idx;
            }
            return sum;
        }
    }
}

