        int n = nums1.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = (long) nums1[i] - (long) nums2[i];
        }

        // coordinate compression
        long[] allVals = a.clone();
        Arrays.sort(allVals);
        int m = 1;
        for (int i = 1; i < allVals.length; i++) {
            if (allVals[i] != allVals[m - 1]) {
                allVals[m++] = allVals[i];
            }
        }
        long[] uniq = Arrays.copyOf(allVals, m);

        FenwickTree bit = new FenwickTree(m);
        long totalInserted = 0;
        long res = 0;

        for (int i = n - 1; i >= 0; i--) {
            long target = a[i] - diff; // we need A[j] >= target
            int pos = lowerBound(uniq, target); // first index with value >= target
            long prefix = (pos == 0) ? 0 : bit.query(pos);
            long count = totalInserted - prefix;
            res += count;

            int idxInsert = lowerBound(uniq, a[i]); // exact position of a[i]
            bit.update(idxInsert + 1, 1);
            totalInserted++;
        }

        return res;
    }

    // Returns first index in sorted array where value >= key
    private int lowerBound(long[] arr, long key) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < key) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    // Fenwick Tree (Binary Indexed Tree) for prefix sums
    private static class FenwickTree {
        private final long[] tree;
        private final int n;

        FenwickTree(int size) {
            n = size;
            tree = new long[n + 1];
        }

        // add delta at position idx (1‑based)
        void update(int idx, long delta) {
            while (idx <= n) {
                tree[idx] += delta;
                idx += idx & -idx;
            }
        }

        // sum of first idx elements (1‑based)
        long query(int idx) {
            long sum = 0;
            while (idx > 0) {
                sum += tree[idx];
                idx -= idx & -idx;
            }
            return sum;
        }
    }
