        }
        int mid = left + (right - left) / 2;
        long count = 0;
        count += mergeSort(arr, temp, left, mid, diff);
        count += mergeSort(arr, temp, mid + 1, right, diff);

        // Count cross pairs
        int j = mid + 1;
        for (int i = left; i <= mid; i++) {
            while (j <= right && arr[j] < arr[i] - diff) {
                j++;
            }
            count += (right - j + 1);
        }

        // Merge step
        int i = left, p = mid + 1, k = left;
        while (i <= mid && p <= right) {
            if (arr[i] <= arr[p]) {
                temp[k++] = arr[i++];
            } else {
                temp[k++] = arr[p++];
            }
        }
        while (i <= mid) {
            temp[k++] = arr[i++];
        }
        while (p <= right) {
            temp[k++] = arr[p++];
        }
        for (i = left; i <= right; i++) {
            arr[i] = temp[i];
        }

        return count;
    }
}

