            String key = buildDiffKey(word);
            diffCount.put(key, diffCount.getOrDefault(key, 0) + 1);
            // store the first word that produced this key
            diffToWord.putIfAbsent(key, word);
        }

        // Find the key that appears only once
        for (Map.Entry<String, Integer> entry : diffCount.entrySet()) {
            if (entry.getValue() == 1) {
                return diffToWord.get(entry.getKey());
            }
        }

        // Fallback (should not happen according to problem statement)
