        int n = word.length();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n - 1; i++) {
            int diff = word.charAt(i + 1) - word.charAt(i);
            if (i > 0) {
                sb.append('#');
            }
            sb.append(diff);
        }
        return sb.toString();
    }
