import java.util.*;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        int n = robot.size();
        // sort robots
        int[] robots = new int[n];
        for (int i = 0; i < n; i++) robots[i] = robot.get(i);
        Arrays.sort(robots);
        // sort factories by position
        Arrays.sort(f, Comparator.comparingInt(a -> a[0]));
        // prefix sums of robot positions (1‑based)
        long[] pref = new long[n + 1];
        for (int i = 1; i <= n; i++) pref[i] = pref[i - 1] + robots[i - 1];

        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int[] factory : f) {
            int pos = factory[0];
            int cap = factory[1];
            long[] ndp = new long[n + 1];
            Arrays.fill(ndp, INF);
            // for each number of robots assigned so far
            for (int i = 0; i <= n; i++) {
                if (dp[i] == INF) continue;
                // we can assign k robots (0..cap) to this factory
                ndp[i] = Math.min(ndp[i], dp[i]); // assign none
                long cur = dp[i];
                for (int k = 1; k <= cap && i + k <= n; k++) {
                    long cost = segmentCost(robots, pref, i + 1, i + k, pos);
                    cur = dp[i] + cost;
                    ndp[i + k] = Math.min(ndp[i + k], cur);
                }
            }
            dp = ndp;
        }
        return dp[n];
    }

    // robots is sorted array, pref is 1‑based prefix sum of robots
    private long segmentCost(int[] robots, long[] pref, int l, int r, int p) {
        // l and r are 1‑based inclusive indices into robots array
        // find the last index <= p within [l, r]
        int left = l, right = r, mIdx = l - 1;
        while (left <= right) {
            int mid = (left + right) >>> 1;
            if (robots[mid - 1] <= p) {
                mIdx = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        long cost = 0;
        // robots <= p
        if (mIdx >= l) {
            long sumLeft = pref[mIdx] - pref[l - 1];
            cost += (long) p * (mIdx - l + 1) - sumLeft;
        }
        // robots > p
        if (mIdx < r) {
            long sumRight = pref[r] - pref[mIdx];
            cost += sumRight - (long) p * (r - mIdx);
        }
        return cost;
    }
}

