import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        // Convert robot list to array and sort
        int n = robot.size();
        int[] robots = new int[n];
        for (int i = 0; i < n; i++) {
            robots[i] = robot.get(i);
        }
        java.util.Arrays.sort(robots);

        // Sort factories by position
        List<int[]> factories = new ArrayList<>();
        for (int[] arr : f) {
            factories.add(arr);
        }
        factories.sort(Comparator.comparingInt(a -> a[0]));

        // Expand factories according to their limits
        List<Integer> expanded = new ArrayList<>();
        for (int[] fac : factories) {
            int pos = fac[0];
            int limit = fac[1];
            for (int i = 0; i < limit; i++) {
                expanded.add(pos);
            }
        }

        // It is guaranteed that expanded.size() >= n
        int m = expanded.size();

        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            dp[i] = INF;
        }
        dp[0] = 0;

        // DP: for each factory position, try to assign a robot to it
        for (int idx = 0; idx < m; idx++) {
            int factoryPos = expanded.get(idx);
            // iterate robots count backwards to avoid overwriting needed values
            for (int i = n; i >= 1; i--) {
                if (dp[i - 1] != INF) {
                    long cost = dp[i - 1] + Math.abs((long) robots[i - 1] - factoryPos);
                    if (cost < dp[i]) {
                        dp[i] = cost;
                    }
                }
            }
        }

        return dp[n];
    }
}

