import com_github_leetcode.TreeNode;
import java.util.*;

public class Solution {
    public int[] treeQueries(TreeNode root, int[] queries) {
        // Collect all nodes and build child arrays
        List<TreeNode> nodes = new ArrayList<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            TreeNode cur = stack.pop();
            nodes.add(cur);
            if (cur.left != null) stack.push(cur.left);
            if (cur.right != null) stack.push(cur.right);
        }
        int n = nodes.size();
        int[] depth = new int[n + 1];
        int[] down = new int[n + 1];
        int[] leafDepth = new int[n + 1];
        int[] left = new int[n + 1];
        int[] right = new int[n + 1];
        Arrays.fill(left, -1);
        Arrays.fill(right, -1);
        for (TreeNode node : nodes) {
            if (node.left != null) left[node.val] = node.left.val;
            if (node.right != null) right[node.val] = node.right.val;
        }

        // First DFS: compute depth, down (height of subtree), leafDepth
        dfs1(root, 0, depth, down, leafDepth, left, right);

        // Compute best1 and best2 for each node among its own depth and children's leafDepth
        int[] best1 = new int[n + 1];
        int[] best2 = new int[n + 1];
        for (TreeNode node : nodes) {
            int v = node.val;
            int b1 = depth[v];
            int b2 = Integer.MIN_VALUE;

            int l = left[v];
            if (l != -1) {
                int cand = leafDepth[l];
                if (cand > b1) {
                    b2 = b1;
                    b1 = cand;
                } else if (cand > b2) {
                    b2 = cand;
                }
            }
            int r = right[v];
            if (r != -1) {
                int cand = leafDepth[r];
                if (cand > b1) {
                    b2 = b1;
                    b1 = cand;
                } else if (cand > b2) {
                    b2 = cand;
                }
            }
            best1[v] = b1;
            best2[v] = b2;
        }

        // Second DFS: compute outside depth for each node
        int[] outside = new int[n + 1];
        Arrays.fill(outside, Integer.MIN_VALUE);
        outside[root.val] = Integer.MIN_VALUE;
        dfs2(root, outside, best1, best2, leafDepth, left, right);

        // Answer queries
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            ans[i] = outside[queries[i]];
        }
        return ans;
    }

    private void dfs1(TreeNode node, int d, int[] depth, int[] down, int[] leafDepth,
                      int[] left, int[] right) {
        if (node == null) return;
        int v = node.val;
        depth[v] = d;
        int maxChild = -1;
        int l = left[v];
        if (l != -1) {
            dfs1(node.left, d + 1, depth, down, leafDepth, left, right);
            maxChild = Math.max(maxChild, down[l] + 1);
        }
        int r = right[v];
        if (r != -1) {
            dfs1(node.right, d + 1, depth, down, leafDepth, left, right);
            maxChild = Math.max(maxChild, down[r] + 1);
        }
        down[v] = Math.max(0, maxChild);
        leafDepth[v] = depth[v] + down[v];
    }

    private void dfs2(TreeNode node, int[] outside, int[] best1, int[] best2,
                      int[] leafDepth, int[] left, int[] right) {
        if (node == null) return;
        int v = node.val;
        int l = left[v];
        if (l != -1) {
            int siblingBest = (leafDepth[l] == best1[v]) ? best2[v] : best1[v];
            outside[l] = Math.max(outside[v], siblingBest);
            dfs2(node.left, outside, best1, best2, leafDepth, left, right);
        }
        int r = right[v];
        if (r != -1) {
            int siblingBest = (leafDepth[r] == best1[v]) ? best2[v] : best1[v];
            outside[r] = Math.max(outside[v], siblingBest);
            dfs2(node.right, outside, best1, best2, leafDepth, left, right);
        }
    }
}

