import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    private final Map<Integer, Integer> depth = new HashMap<>();
    private final Map<Integer, Integer> subtreeHeight = new HashMap<>();
    private final Map<Integer, Integer> upHeight = new HashMap<>();
    private final Map<Integer, TreeNode> nodeMap = new HashMap<>();

    private void dfsCompute(TreeNode node, int d) {
        if (node == null) {
            return;
        }
        nodeMap.put(node.val, node);
        depth.put(node.val, d);
        dfsCompute(node.left, d + 1);
        dfsCompute(node.right, d + 1);

        int leftHeight = node.left != null ? 1 + subtreeHeight.get(node.left.val) : 0;
        int rightHeight = node.right != null ? 1 + subtreeHeight.get(node.right.val) : 0;
        subtreeHeight.put(node.val, Math.max(leftHeight, rightHeight));
    }

    private void dfsUp(TreeNode node, int up) {
        if (node == null) {
            return;
        }
        upHeight.put(node.val, up);

        int leftHeight = node.left != null ? 1 + subtreeHeight.get(node.left.val) : -1;
        int rightHeight = node.right != null ? 1 + subtreeHeight.get(node.right.val) : -1;

        if (node.left != null) {
            int siblingHeight = rightHeight;
            int candidate = -1;
            if (siblingHeight != -1) {
                candidate = depth.get(node.val) + siblingHeight;
            }
            int childUp = Math.max(up, candidate);
            dfsUp(node.left, childUp);
        }

        if (node.right != null) {
            int siblingHeight = leftHeight;
            int candidate = -1;
            if (siblingHeight != -1) {
                candidate = depth.get(node.val) + siblingHeight;
            }
            int childUp = Math.max(up, candidate);
            dfsUp(node.right, childUp);
        }
    }

    public int[] treeQueries(TreeNode root, int[] queries) {
        dfsCompute(root, 0);
        dfsUp(root, 0);

        int m = queries.length;
        int[] answer = new int[m];
        for (int i = 0; i < m; i++) {
            answer[i] = upHeight.get(queries[i]);
        }
        return answer;
    }
}

