import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int[] treeQueries(TreeNode root, int[] queries) {
        // maps to store needed information
        Map<Integer, Integer> depthMap = new HashMap<>();          // depth from root
        Map<Integer, Integer> deepestMap = new HashMap<>();       // deepest absolute depth in subtree
        Map<Integer, Integer> subHeightMap = new HashMap<>();     // height of subtree (deepest - depth)
        Map<Integer, Integer> max1Map = new HashMap<>();          // largest child subtree height
        Map<Integer, Integer> max2Map = new HashMap<>();          // second largest child subtree height
        Map<Integer, Integer> outsideDepthMap = new HashMap<>();  // max depth reachable without this subtree

        // First DFS: compute depths, deepest nodes, subtree heights and top two child heights
        computeFirstDFS(root, 0, depthMap, deepestMap, subHeightMap, max1Map, max2Map);

        // Second DFS: propagate outside depths
        propagateOutsideDepth(root, -1, depthMap, subHeightMap, max1Map, max2Map, outsideDepthMap);

        // Build answer array
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            ans[i] = outsideDepthMap.get(queries[i]);
        }
        return ans;
    }

    private int computeFirstDFS(TreeNode node, int depth,
                                Map<Integer, Integer> depthMap,
                                Map<Integer, Integer> deepestMap,
                                Map<Integer, Integer> subHeightMap,
                                Map<Integer, Integer> max1Map,
                                Map<Integer, Integer> max2Map) {
        if (node == null) {
            return depth - 1; // return an invalid depth for null
        }
        depthMap.put(node.val, depth);

        int leftDeep = computeFirstDFS(node.left, depth + 1, depthMap, deepestMap, subHeightMap, max1Map, max2Map);
        int rightDeep = computeFirstDFS(node.right, depth + 1, depthMap, deepestMap, subHeightMap, max1Map, max2Map);

        int deepest = depth;
        if (node.left != null) deepest = Math.max(deepest, deepestMap.get(node.left.val));
        if (node.right != null) deepest = Math.max(deepest, deepestMap.get(node.right.val));
        deepestMap.put(node.val, deepest);

        int subHeight = deepest - depth;
        subHeightMap.put(node.val, subHeight);

        // Determine the two largest child subtree heights
        int max1 = -1, max2 = -1;
        if (node.left != null) {
            int h = subHeightMap.get(node.left.val);
            if (h > max1) {
                max2 = max1;
                max1 = h;
            } else if (h > max2) {
                max2 = h;
            }
        }
        if (node.right != null) {
            int h = subHeightMap.get(node.right.val);
            if (h > max1) {
                max2 = max1;
                max1 = h;
            } else if (h > max2) {
                max2 = h;
            }
        }
        max1Map.put(node.val, max1);
        max2Map.put(node.val, max2);

        return deepest;
    }

    private void propagateOutsideDepth(TreeNode node, int outsideDepth,
                                       Map<Integer, Integer> depthMap,
                                       Map<Integer, Integer> subHeightMap,
                                       Map<Integer, Integer> max1Map,
                                       Map<Integer, Integer> max2Map,
                                       Map<Integer, Integer> outsideDepthMap) {
        if (node == null) return;

        int nodeDepth = depthMap.get(node.val);
        outsideDepthMap.put(node.val, outsideDepth);

        // Process left child
        if (node.left != null) {
            int childHeight = subHeightMap.get(node.left.val);
            int max1 = max1Map.get(node.val);
            int max2 = max2Map.get(node.val);
            int siblingBest = (childHeight == max1) ? max2 : max1;

            int candSibling = (siblingBest == -1) ? Integer.MIN_VALUE : nodeDepth + 1 + siblingBest;
            int childOutside = Math.max(Math.max(outsideDepth, nodeDepth), candSibling);
            propagateOutsideDepth(node.left, childOutside, depthMap, subHeightMap, max1Map, max2Map, outsideDepthMap);
        }

        // Process right child
        if (node.right != null) {
            int childHeight = subHeightMap.get(node.right.val);
            int max1 = max1Map.get(node.val);
            int max2 = max2Map.get(node.val);
            int siblingBest = (childHeight == max1) ? max2 : max1;

            int candSibling = (siblingBest == -1) ? Integer.MIN_VALUE : nodeDepth + 1 + siblingBest;
            int childOutside = Math.max(Math.max(outsideDepth, nodeDepth), candSibling);
            propagateOutsideDepth(node.right, childOutside, depthMap, subHeightMap, max1Map, max2Map, outsideDepthMap);
        }
    }
}

