        int left = computeHeight(node.left);
        int right = computeHeight(node.right);
        int h = Math.max(left, right) + 1;
        heightMap.put(node.val, h);
        return h;
    }

    private void dfs(TreeNode node, int bestAbove, int depth) {
        // bestAbove: maximum depth of any node not in the current subtree
        answerMap.put(node.val, bestAbove);

        int leftHeight = node.left != null ? heightMap.get(node.left.val) : -1;
        int rightHeight = node.right != null ? heightMap.get(node.right.val) : -1;

        if (node.left != null) {
            int siblingHeight = rightHeight;
            int candidate = Math.max(bestAbove, depth);
            if (siblingHeight != -1) {
                candidate = Math.max(candidate, depth + 1 + siblingHeight);
            }
            dfs(node.left, candidate, depth + 1);
        }

        if (node.right != null) {
            int siblingHeight = leftHeight;
            int candidate = Math.max(bestAbove, depth);
            if (siblingHeight != -1) {
                candidate = Math.max(candidate, depth + 1 + siblingHeight);
            }
            dfs(node.right, candidate, depth + 1);
        }
    }
}

