import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    private final Map<Integer, Integer> depthMap = new HashMap<>();
    private final Map<Integer, Integer> subMaxMap = new HashMap<>();
    private final Map<Integer, Integer> bestAboveMap = new HashMap<>();

    private void dfsCompute(TreeNode node, int depth) {
        if (node == null) return;
        depthMap.put(node.val, depth);
        int subMax = depth;
        if (node.left != null) {
            dfsCompute(node.left, depth + 1);
            subMax = Math.max(subMax, subMaxMap.get(node.left.val));
        }
        if (node.right != null) {
            dfsCompute(node.right, depth + 1);
            subMax = Math.max(subMax, subMaxMap.get(node.right.val));
        }
        subMaxMap.put(node.val, subMax);
    }

    private void dfsBestAbove(TreeNode node, int bestFromParent) {
        if (node == null) return;

        // store bestAbove for current node
        bestAboveMap.put(node.val, bestFromParent);

        // Determine the two largest candidate depths among:
        // - depth of current node
        // - subtree max depths of its children
        int max1 = depthMap.get(node.val);
        int max2 = -1;
        int max1Child = -1; // which child contributed max1, -1 if it's the node itself

        if (node.left != null) {
            int childSub = subMaxMap.get(node.left.val);
            if (childSub > max1) {
                max2 = max1;
                max1 = childSub;
                max1Child = node.left.val;
            } else if (childSub > max2) {
                max2 = childSub;
            }
        }
        if (node.right != null) {
            int childSub = subMaxMap.get(node.right.val);
            if (childSub > max1) {
                max2 = max1;
                max1 = childSub;
                max1Child = node.right.val;
            } else if (childSub > max2) {
                max2 = childSub;
            }
        }

        // Propagate to left child
        if (node.left != null) {
            int excl = (max1Child == node.left.val) ? max2 : max1;
            int childBest = Math.max(bestFromParent, excl);
            dfsBestAbove(node.left, childBest);
        }

        // Propagate to right child
        if (node.right != null) {
            int excl = (max1Child == node.right.val) ? max2 : max1;
            int childBest = Math.max(bestFromParent, excl);
            dfsBestAbove(node.right, childBest);
        }
    }

    public int[] treeQueries(TreeNode root, int[] queries) {
        if (root == null) {
            return new int[queries.length];
        }

        // First pass: compute depth and subtree maximum depth
        dfsCompute(root, 0);

        // Second pass: compute bestAbove for each node
        dfsBestAbove(root, -1); // root has no nodes above it

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            answer[i] = bestAboveMap.getOrDefault(queries[i], 0);
        }
        return answer;
    }
}

