public class Solution {
    public int minGroups(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return 0;
        }
        // Sort intervals by start time
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        // Min-heap to keep track of current groups' end times
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        int maxGroups = 0;
        for (int[] interval : intervals) {
            int start = interval[0];
            int end = interval[1];
            // If the earliest ending group finishes before the current start (strictly less),
            // we can reuse that group. Because intervals are inclusive, they intersect when start <= end.
            if (!heap.isEmpty() && start > heap.peek()) {
                heap.poll();
            }
            heap.offer(end);
            maxGroups = Math.max(maxGroups, heap.size());
        }
        return maxGroups;
    }
}

