public class Solution {
    public int[] applyOperations(int[] nums) {
        int n = nums.length;
        // Apply the operations sequentially
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] == nums[i + 1]) {
                nums[i] <<= 1; // multiply by 2
                nums[i + 1] = 0;
            }
        }
        // Shift all zeros to the end while preserving order of non-zero elements
        int insertPos = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] != 0) {
                nums[insertPos++] = nums[i];
            }
        }
        // Fill the remaining positions with zeros
        while (insertPos < n) {
            nums[insertPos++] = 0;
        }
        return nums;
    }
}

