public class Solution {
    private static final long BASE = 91138233L;

    public int deleteString(String s) {
        int n = s.length();
        long[] prefix = new long[n + 1];
        long[] power = new long[n + 1];
        power[0] = 1;
        for (int i = 0; i < n; i++) {
            int val = s.charAt(i) - 'a' + 1;
            prefix[i + 1] = prefix[i] * BASE + val;
            power[i + 1] = power[i] * BASE;
        }

        int[] dp = new int[n + 1];
        dp[n] = 0; // empty suffix needs 0 operations

        for (int i = n - 1; i >= 0; i--) {
            dp[i] = 1; // delete the whole suffix in one operation
            // try to delete a prefix of length len where the next len characters are equal
            for (int len = 1; i + len * 2 <= n; len++) {
                if (hash(prefix, power, i, i + len) == hash(prefix, power, i + len, i + 2 * len)) {
                    dp[i] = Math.max(dp[i], 1 + dp[i + len]);
                }
            }
        }
        return dp[0];
    }

    private long hash(long[] prefix, long[] power, int l, int r) {
        // returns hash of s[l..r-1]
        return prefix[r] - prefix[l] * power[r - l];
    }
}

