            pref1[i + 1] = (pref1[i] * BASE + c) % MOD1;
            pref2[i + 1] = (pref2[i] * BASE + c) % MOD2;
        }

        // Helper to get hash of substring [l, r) (0‑based, r exclusive)
        class Hash {
