                Hash second = getHash.apply(i + len, i + 2 * len);
                if (first.h1 == second.h1 && first.h2 == second.h2) {
                    dp[i] = Math.max(dp[i], 1 + dp[i + len]);
                }
            }
        }

        return dp[0];
    }
}

