            pref[i + 1] = (pref[i] * BASE + (s.charAt(i) - 'a' + 1)) % MOD;
            pow[i + 1] = (pow[i] * BASE) % MOD;
        }

        int[] dp = new int[n + 1];
        dp[n] = 0; // empty suffix needs 0 operations

        for (int i = n - 1; i >= 0; i--) {
            int best = 1; // delete the whole remaining string in one operation
            int maxLen = (n - i) / 2;
            for (int len = 1; len <= maxLen; len++) {
                if (equal(i, i + len, len, pref, pow)) {
                    best = Math.max(best, 1 + dp[i + len]);
                }
            }
            dp[i] = best;
        }

        return dp[0];
    }

    private boolean equal(int l1, int l2, int len, long[] pref, long[] pow) {
        long hash1 = (pref[l1 + len] - pref[l1] * pow[len]) % MOD;
        if (hash1 < 0) hash1 += MOD;
        long hash2 = (pref[l2 + len] - pref[l2] * pow[len]) % MOD;
        if (hash2 < 0) hash2 += MOD;
        return hash1 == hash2;
    }
}

