public class Solution {
    public List<List<Integer>> closestNodes(TreeNode root, List<Integer> queries) {
        TreeSet<Integer> values = new TreeSet<>();
        inorder(root, values);
        List<List<Integer>> answer = new ArrayList<>(queries.size());
        for (int q : queries) {
            Integer lower = values.floor(q);
            Integer higher = values.ceiling(q);
            List<Integer> pair = new ArrayList<>(2);
            pair.add(lower != null ? lower : -1);
            pair.add(higher != null ? higher : -1);
            answer.add(pair);
        }
        return answer;
    }

    private void inorder(TreeNode node, TreeSet<Integer> set) {
        if (node == null) {
            return;
        }
        inorder(node.left, set);
        set.add(node.val);
        inorder(node.right, set);
    }
}

