public class Solution {
    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;
        int[] suffixOR = new int[n];
        int curOr = 0;
        for (int i = n - 1; i >= 0; i--) {
            curOr |= nums[i];
            suffixOR[i] = curOr;
        }

        int[] answer = new int[n];
        int[] nextPos = new int[32];
        Arrays.fill(nextPos, -1);

        for (int i = n - 1; i >= 0; i--) {
            int val = nums[i];
            for (int b = 0; b < 32; b++) {
                if ((val & (1 << b)) != 0) {
                    nextPos[b] = i;
                }
            }

            int maxPos = i;
            int target = suffixOR[i];
            for (int b = 0; b < 32; b++) {
                if ((target & (1 << b)) != 0) {
                    maxPos = Math.max(maxPos, nextPos[b]);
                }
            }
            answer[i] = maxPos - i + 1;
        }

        return answer;
    }
}

