public class Solution {
    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;
        int[] suffixOr = new int[n];
        int cur = 0;
        for (int i = n - 1; i >= 0; i--) {
            cur |= nums[i];
            suffixOr[i] = cur;
        }

        // nextPos[bit][i] = earliest index >= i where this bit is set, or n if none
        int[][] nextPos = new int[31][n + 1];
        for (int b = 0; b < 31; b++) {
            nextPos[b][n] = n; // sentinel
        }
        for (int i = n - 1; i >= 0; i--) {
            int val = nums[i];
            for (int b = 0; b < 31; b++) {
                if ((val & (1 << b)) != 0) {
                    nextPos[b][i] = i;
                } else {
                    nextPos[b][i] = nextPos[b][i + 1];
                }
            }
        }

        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            int needOr = suffixOr[i];
            if (needOr == 0) {
                answer[i] = 1;
                continue;
            }
            int maxIdx = i;
            for (int b = 0; b < 31; b++) {
                if ((needOr & (1 << b)) != 0) {
                    int pos = nextPos[b][i];
                    if (pos > maxIdx) {
                        maxIdx = pos;
                    }
                }
            }
            answer[i] = maxIdx - i + 1;
        }
        return answer;
    }
}

