import java.util.PriorityQueue;

public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        int n = costs.length;
        PriorityQueue<int[]> leftHeap = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return a[0] - b[0];
            return a[1] - b[1];
        });
        PriorityQueue<int[]> rightHeap = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return a[0] - b[0];
            return a[1] - b[1];
        });

        int leftPtr = 0;
        int rightPtr = n - 1;

        int leftInit = Math.min(candidates, n);
        int rightInit = Math.min(candidates, n - leftInit);

        for (int i = 0; i < leftInit; i++) {
            leftHeap.offer(new int[]{costs[leftPtr], leftPtr});
            leftPtr++;
        }
        for (int i = 0; i < rightInit; i++) {
            rightHeap.offer(new int[]{costs[rightPtr], rightPtr});
            rightPtr--;
        }

        long total = 0L;
        while (k > 0) {
            int[] leftTop = leftHeap.peek();
            int[] rightTop = rightHeap.peek();

            boolean takeFromLeft;
            if (leftTop == null) {
                takeFromLeft = false;
            } else if (rightTop == null) {
                takeFromLeft = true;
            } else {
                if (leftTop[0] < rightTop[0]) {
                    takeFromLeft = true;
                } else if (leftTop[0] > rightTop[0]) {
                    takeFromLeft = false;
                } else {
                    takeFromLeft = leftTop[1] < rightTop[1];
                }
            }

            if (takeFromLeft) {
                int[] cur = leftHeap.poll();
                total += cur[0];
                if (leftPtr <= rightPtr) {
                    leftHeap.offer(new int[]{costs[leftPtr], leftPtr});
                    leftPtr++;
                }
            } else {
                int[] cur = rightHeap.poll();
                total += cur[0];
                if (leftPtr <= rightPtr) {
                    rightHeap.offer(new int[]{costs[rightPtr], rightPtr});
                    rightPtr--;
                }
            }
            k--;
        }

        return total;
    }
}

