                        leftPQ.offer(new Worker(costs[leftPtr], leftPtr));
                        leftPtr++;
                    }
                } else {
                    chosen = rightPQ.poll();
                    if (leftPtr <= rightPtr) {
                        rightPQ.offer(new Worker(costs[rightPtr], rightPtr));
                        rightPtr--;
                    }
                }
            }
            total += chosen.cost;
        }

        return total;
    }
}

