import java.util.*;

public class Solution {
    // Disjoint Set Union (Union-Find) implementation
    private static class DSU {
        int[] parent;
        int[] rank;

        DSU(int size) {
            parent = new int[size + 1];
            rank = new int[size + 1];
            for (int i = 1; i <= size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return;
            if (rank[rootA] < rank[rootB]) {
                parent[rootA] = rootB;
            } else if (rank[rootA] > rank[rootB]) {
                parent[rootB] = rootA;
            } else {
                parent[rootB] = rootA;
                rank[rootA]++;
            }
        }
    }

    public int minScore(int n, int[][] roads) {
        DSU dsu = new DSU(n);
        // Unite all connected cities
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            dsu.union(a, b);
        }

        int rootOfStart = dsu.find(1);
        int minScore = Integer.MAX_VALUE;

        // Find the minimum edge weight within the component containing city 1 (and thus city n)
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            int dist = road[2];
            if (dsu.find(a) == rootOfStart) {
                // Both endpoints are in the same component as city 1
                minScore = Math.min(minScore, dist);
            }
        }

        // According to problem statement, there is always at least one path,
        // so minScore will have been updated.
        return minScore;
    }
}

