public class Solution {
    private static class VideoInfo {
        int maxViews;
        String bestId;

        VideoInfo(int views, String id) {
            this.maxViews = views;
            this.bestId = id;
        }

        void update(int views, String id) {
            if (views > maxViews) {
                maxViews = views;
                bestId = id;
            } else if (views == maxViews && id.compareTo(bestId) < 0) {
                bestId = id;
            }
        }
    }

    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        int n = creators.length;
        Map<String, Long> totalViews = new HashMap<>();
        Map<String, VideoInfo> bestVideo = new HashMap<>();

        for (int i = 0; i < n; i++) {
            String creator = creators[i];
            String id = ids[i];
            int view = views[i];

            totalViews.put(creator, totalViews.getOrDefault(creator, 0L) + view);

            VideoInfo info = bestVideo.get(creator);
            if (info == null) {
                bestVideo.put(creator, new VideoInfo(view, id));
            } else {
                info.update(view, id);
            }
        }

        long maxPopularity = 0;
        for (long v : totalViews.values()) {
            if (v > maxPopularity) {
                maxPopularity = v;
            }
        }

        List<List<String>> answer = new ArrayList<>();
        for (Map.Entry<String, Long> entry : totalViews.entrySet()) {
            if (entry.getValue() == maxPopularity) {
                String creator = entry.getKey();
                String bestId = bestVideo.get(creator).bestId;
                List<String> pair = new ArrayList<>(2);
                pair.add(creator);
                pair.add(bestId);
                answer.add(pair);
            }
        }

