public class Solution {
    public int destroyTargets(int[] nums, int space) {
        if (nums == null || nums.length == 0) {
            return -1; // undefined, but per problem constraints this should not happen
        }
        HashMap<Integer, Integer> countMap = new HashMap<>();
        HashMap<Integer, Integer> minMap = new HashMap<>();

        for (int num : nums) {
            int rem = num % space;
            countMap.put(rem, countMap.getOrDefault(rem, 0) + 1);
            if (!minMap.containsKey(rem) || num < minMap.get(rem)) {
                minMap.put(rem, num);
            }
        }

        int maxCount = -1;
        int answer = Integer.MAX_VALUE;

        for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
            int rem = entry.getKey();
            int cnt = entry.getValue();
            int candidate = minMap.get(rem);
            if (cnt > maxCount) {
                maxCount = cnt;
                answer = candidate;
            } else if (cnt == maxCount && candidate < answer) {
                answer = candidate;
            }
        }

        return answer;
    }
}

