        Map<Integer, int[]> map = new HashMap<>();
        for (int num : nums) {
            int residue = num % space;
            int[] info = map.get(residue);
            if (info == null) {
                // count = 1, min = num
                map.put(residue, new int[]{1, num});
            } else {
                info[0]++; // increment count
                if (num < info[1]) {
                    info[1] = num; // update minimum seed for this residue
                }
            }
