import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int destroyTargets(int[] nums, int space) {
        if (space == 0) {
            // If space is zero, only the exact seed value can destroy itself.
            // Return the smallest number (any seed destroys only itself).
            int min = Integer.MAX_VALUE;
            for (int num : nums) {
                if (num < min) min = num;
            }
            return min;
        }

        HashMap<Integer, Integer> countMap = new HashMap<>();
        HashMap<Integer, Integer> minMap = new HashMap<>();

        for (int num : nums) {
            int rem = num % space;
            countMap.put(rem, countMap.getOrDefault(rem, 0) + 1);
            minMap.put(rem, Math.min(minMap.getOrDefault(rem, Integer.MAX_VALUE), num));
        }

        int maxCount = 0;
        int answer = Integer.MAX_VALUE;

        for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
            int rem = entry.getKey();
            int cnt = entry.getValue();
            int candidate = minMap.get(rem);
            if (cnt > maxCount) {
                maxCount = cnt;
                answer = candidate;
            } else if (cnt == maxCount) {
                answer = Math.min(answer, candidate);
            }
        }

        return answer;
    }
}

