public class Solution {
    public int destroyTargets(int[] nums, int space) {
        // Map remainder -> list of numbers with that remainder
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int num : nums) {
            int r = num % space;
            groups.computeIfAbsent(r, k -> new ArrayList<>()).add(num);
        }

        int bestCount = -1;
        int bestSeed = Integer.MAX_VALUE;

        for (List<Integer> list : groups.values()) {
            Collections.sort(list);
            int size = list.size();
            for (int i = 0; i < size; i++) {
                int seed = list.get(i);
                int count = size - i; // all numbers from i to end are >= seed
                if (count > bestCount || (count == bestCount && seed < bestSeed)) {
                    bestCount = count;
                    bestSeed = seed;
                }
            }
        }

        return bestSeed;
    }
}

