import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int destroyTargets(int[] nums, int space) {
        if (space == 0) {
            // When space is 0, only exact matches can be destroyed.
            Map<Integer, Integer> freq = new HashMap<>();
            for (int v : nums) {
                freq.put(v, freq.getOrDefault(v, 0) + 1);
            }
            int maxCount = 0;
            int answer = Integer.MAX_VALUE;
            for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
                int val = e.getKey();
                int cnt = e.getValue();
                if (cnt > maxCount || (cnt == maxCount && val < answer)) {
                    maxCount = cnt;
                    answer = val;
                }
            }
            return answer;
        }

        // Map from residue to an array: [count, minValue]
        Map<Integer, int[]> map = new HashMap<>();
        for (int v : nums) {
            int residue = v % space;
            int[] data = map.get(residue);
            if (data == null) {
                data = new int[]{1, v};
                map.put(residue, data);
            } else {
                data[0]++;                 // increase count
                if (v < data[1]) {
                    data[1] = v;           // keep smallest value for this residue
                }
            }
        }

        int bestCount = 0;
        int bestValue = Integer.MAX_VALUE;
        for (int[] data : map.values()) {
            int cnt = data[0];
            int val = data[1];
            if (cnt > bestCount || (cnt == bestCount && val < bestValue)) {
                bestCount = cnt;
                bestValue = val;
            }
        }
        return bestValue;
    }
}

