public class Solution {
    public int longestNiceSubarray(int[] nums) {
        int n = nums.length;
        int[] bitCount = new int[31];
        int left = 0;
        int maxLen = 0;
        int conflict = 0; // number of bits that appear in more than one element

        for (int right = 0; right < n; right++) {
            int val = nums[right];
            for (int b = 0; b < 31; b++) {
                if (((val >> b) & 1) == 1) {
                    bitCount[b]++;
                    if (bitCount[b] == 2) {
                        conflict++;
                    }
                }
            }

            while (conflict > 0) {
                int leftVal = nums[left];
                for (int b = 0; b < 31; b++) {
                    if (((leftVal >> b) & 1) == 1) {
                        if (bitCount[b] == 2) {
                            conflict--;
                        }
                        bitCount[b]--;
                    }
                }
                left++;
            }

            int currentLen = right - left + 1;
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
        }

        return maxLen;
    }
}

