                int len = right - left + 1;
                boolean conflict = false;
                for (int b = 0; b < 31; b++) {
                    // conflict if the bit appears in more than one element
                    // but not in all elements of the window
                    if (bitCnt[b] > 1 && bitCnt[b] < len) {
                        conflict = true;
                        break;
                    }
                }
                if (!conflict) {
                    break;
                }
                int leftVal = nums[left];
