import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public long minimumFuelCost(int[][] roads, int seats) {
        int n = roads.length + 1; // number of cities
        if (n == 1) {
            return 0L;
        }

        // Build adjacency list
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        int[] parent = new int[n];
        int[] order = new int[n];
        int idx = 0;

        // Iterative DFS to get parent array and traversal order
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        parent[0] = -1;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            order[idx++] = node;
            for (int nei : graph[node]) {
                if (nei == parent[node]) continue;
                parent[nei] = node;
                stack.push(nei);
            }
        }

        long[] subtreeSize = new long[n];
        long answer = 0L;

        // Process nodes in reverse order (post-order)
        for (int i = n - 1; i >= 0; i--) {
            int node = order[i];
            // each city contributes its own representative
            subtreeSize[node] += 1;
            int p = parent[node];
            if (p != -1) {
                // fuel needed for edge node-p
                long trips = (subtreeSize[node] + seats - 1) / seats;
                answer += trips;
                subtreeSize[p] += subtreeSize[node];
            }
        }

        return answer;
    }
}

