                if (taken >= maxNumberOfEdges) break;
                if (val <= 0) break; // adding non‑positive does not improve the sum
                sum += val;
                taken++;
            }
            if (sum > best) {
                best = (int) sum;
            }
        }
        return best;
    }
}

