import com_github_leetcode.TreeNode;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int minimumOperations(TreeNode root) {
        if (root == null) {
            return 0;
        }
        int operations = 0;
        ArrayDeque<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            List<Integer> values = new ArrayList<>(levelSize);
            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                values.add(node.val);
                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }
            operations += minSwapsToSort(values);
        }
        return operations;
    }

    private int minSwapsToSort(List<Integer> list) {
        int n = list.size();
        if (n <= 1) {
            return 0;
        }
        // Create a copy and sort it
        List<Integer> sorted = new ArrayList<>(list);
        Collections.sort(sorted);
        // Map value to its index in the sorted list
        Map<Integer, Integer> valueToIndex = new HashMap<>(n);
        for (int i = 0; i < n; i++) {
            valueToIndex.put(sorted.get(i), i);
        }
        boolean[] visited = new boolean[n];
        int swaps = 0;
        for (int i = 0; i < n; i++) {
            if (visited[i]) {
                continue;
            }
            int current = i;
            int cycleSize = 0;
            while (!visited[current]) {
                visited[current] = true;
                int value = list.get(current);
                int next = valueToIndex.get(value);
                current = next;
                cycleSize++;
            }
            if (cycleSize > 1) {
                swaps += cycleSize - 1;
            }
        }
        return swaps;
    }
}

