public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        // dpPrev[j][r] – number of ways to reach cell (i‑1, j) with sum % k == r
        int[][] dpPrev = new int[n][k];
        // dpCurr[j][r] – number of ways to reach cell (i, j) with sum % k == r
        int[][] dpCurr = new int[n][k];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int[] cur = new int[k];

                if (i == 0 && j == 0) {
                    int r = ((grid[0][0] % k) + k) % k;
                    cur[r] = 1;
                } else {
                    // from top
                    if (i > 0) {
                        int[] top = dpPrev[j];
                        for (int r = 0; r < k; r++) {
                            int ways = top[r];
                            if (ways != 0) {
                                int nr = (r + grid[i][j]) % k;
                                if (nr < 0) nr += k;
                                cur[nr] = (cur[nr] + ways) % MOD;
                            }
                        }
                    }
                    // from left
                    if (j > 0) {
                        int[] left = dpCurr[j - 1];
                        for (int r = 0; r < k; r++) {
                            int ways = left[r];
                            if (ways != 0) {
                                int nr = (r + grid[i][j]) % k;
                                if (nr < 0) nr += k;
                                cur[nr] = (cur[nr] + ways) % MOD;
                            }
                        }
                    }
                }

                dpCurr[j] = cur;
            }
            // prepare for next row
            dpPrev = dpCurr;
            dpCurr = new int[n][k];
        }

        return dpPrev[n - 1][0];
    }
}

