public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        // dpPrev[col][rem] = number of ways to reach cell (previous row, col) with remainder rem
        int[][] dpPrev = new int[n][k];
        int[][] dpCurr = new int[n][k];

        for (int i = 0; i < m; i++) {
            // clear current row dp
            for (int col = 0; col < n; col++) {
                Arrays.fill(dpCurr[col], 0);
            }

            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    int rem = ((grid[0][0] % k) + k) % k;
                    dpCurr[0][rem] = 1;
                    continue;
                }

                // From top (i-1, j)
                if (i > 0) {
                    int[] fromTop = dpPrev[j];
                    for (int r = 0; r < k; r++) {
                        int cnt = fromTop[r];
                        if (cnt != 0) {
                            int newRem = (r + grid[i][j]) % k;
                            dpCurr[j][newRem] = (dpCurr[j][newRem] + cnt) % MOD;
                        }
                    }
                }

                // From left (i, j-1)
                if (j > 0) {
                    int[] fromLeft = dpCurr[j - 1];
                    for (int r = 0; r < k; r++) {
                        int cnt = fromLeft[r];
                        if (cnt != 0) {
                            int newRem = (r + grid[i][j]) % k;
                            dpCurr[j][newRem] = (dpCurr[j][newRem] + cnt) % MOD;
                        }
                    }
                }
            }

            // Prepare for next iteration: current row becomes previous row
            int[][] temp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = temp;
        }

        return dpPrev[n - 1][0];
    }
}

