public class Solution {
    public int maxJump(int[] stones) {
        int n = stones.length;
        if (n <= 1) {
            return 0;
        }
        if (n == 2) {
            return stones[1] - stones[0];
        }
        int max = 0;
        // consider jumps that skip one stone
        for (int i = 0; i + 2 < n; i++) {
            int jump = stones[i + 2] - stones[i];
            if (jump > max) {
                max = jump;
            }
        }
        // also handle the first and last adjacent jumps just in case
        int firstAdj = stones[1] - stones[0];
        int lastAdj = stones[n - 1] - stones[n - 2];
        if (firstAdj > max) {
            max = firstAdj;
        }
        if (lastAdj > max) {
            max = lastAdj;
        }
        return max;
    }
}

