import java.util.*;

public class Solution {
    private List<Integer>[] graph;
    private int[] amount;
    private int[] bobTime;
    private int maxProfit;

    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        this.amount = amount;
        this.graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        // parent and depth from root (0)
        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        int[] depth = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        parent[0] = 0;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            for (int nb : graph[node]) {
                if (parent[nb] == -1) {
                    parent[nb] = node;
                    depth[nb] = depth[node] + 1;
                    stack.push(nb);
                }
            }
        }

        // compute bobTime for nodes on bob's path to root
        bobTime = new int[n];
        Arrays.fill(bobTime, Integer.MAX_VALUE);
        int cur = bob;
        int dist = 0;
        while (true) {
            bobTime[cur] = dist;
            if (cur == 0) break;
            cur = parent[cur];
            dist++;
        }

        maxProfit = Integer.MIN_VALUE;
        dfs(0, -1, 0, 0);
        return maxProfit;
    }

    private void dfs(int node, int parent, int aliceDepth, int currentSum) {
        int contribution;
        if (bobTime[node] == Integer.MAX_VALUE) {
            contribution = amount[node];
        } else {
            if (aliceDepth < bobTime[node]) {
                contribution = amount[node];
            } else if (aliceDepth == bobTime[node]) {
                contribution = amount[node] / 2;
            } else {
                contribution = 0;
            }
        }
        int newSum = currentSum + contribution;

        boolean isLeaf = (node != 0 && graph[node].size() == 1) || (node == 0 && graph[node].isEmpty());
        if (isLeaf) {
            maxProfit = Math.max(maxProfit, newSum);
            return;
        }

        for (int nb : graph[node]) {
            if (nb == parent) continue;
            dfs(nb, node, aliceDepth + 1, newSum);
        }
    }
}

