import java.util.*;

public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        int[] parent = new int[n];
        int[] depth = new int[n];
        Arrays.fill(parent, -1);
        bfsParentDepth(graph, parent, depth);

        // bobTime[i] = time when Bob reaches node i, INF if never
        int INF = Integer.MAX_VALUE;
        int[] bobTime = new int[n];
        Arrays.fill(bobTime, INF);
        int cur = bob;
        int t = 0;
        while (cur != -1) {
            bobTime[cur] = t;
            cur = parent[cur];
            t++;
        }

        // DFS from root to compute max profit
        boolean[] visited = new boolean[n];
        return dfs(0, 0, graph, visited, amount, depth, bobTime);
    }

    private void bfsParentDepth(List<Integer>[] graph, int[] parent, int[] depth) {
        Queue<Integer> q = new ArrayDeque<>();
        q.offer(0);
        parent[0] = -1;
        depth[0] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                depth[v] = depth[u] + 1;
                q.offer(v);
            }
        }
    }

    private int dfs(int node, int curProfit, List<Integer>[] graph, boolean[] visited,
                    int[] amount, int[] depth, int[] bobTime) {
        visited[node] = true;

        // compute contribution at this node
        int contrib;
        if (bobTime[node] == Integer.MAX_VALUE) {
            contrib = amount[node];
        } else if (depth[node] < bobTime[node]) {
            contrib = amount[node];
        } else if (depth[node] == bobTime[node]) {
            contrib = amount[node] / 2;
        } else {
            contrib = 0;
        }
        curProfit += contrib;

        boolean isLeaf = true;
        int maxProfit = Integer.MIN_VALUE;
        for (int nb : graph[node]) {
            if (!visited[nb]) {
                isLeaf = false;
                int profit = dfs(nb, curProfit, graph, visited, amount, depth, bobTime);
                if (profit > maxProfit) maxProfit = profit;
            }
        }

        visited[node] = false; // backtrack for other paths

        if (isLeaf) {
            return curProfit;
        }
        return maxProfit;
    }
