    public int beautifulPartitions(String s, int k, int l) {
        int n = s.length();
        if (n == 0) return 0;

        boolean[] isPrimeDigit = new boolean[10];
        isPrimeDigit[2] = true;
        isPrimeDigit[3] = true;
        isPrimeDigit[5] = true;
        isPrimeDigit[7] = true;

        boolean[] primeStart = new boolean[n];
        boolean[] nonPrimeEnd = new boolean[n];

        for (int i = 0; i < n; i++) {
            int d = s.charAt(i) - '0';
            primeStart[i] = isPrimeDigit[d];
            nonPrimeEnd[i] = !isPrimeDigit[d];
        }

        // first character must be prime to start any partition
        if (!primeStart[0]) return 0;

        long[] dpPrev = new long[n];
        // initialize for the first segment (cnt = 1)
        for (int end = l - 1; end < n; end++) {
            if (nonPrimeEnd[end]) {
                dpPrev[end] = 1;
            }
        }

        // iterate for remaining segments
        for (int cnt = 2; cnt <= k; cnt++) {
            long[] prefixStart = new long[n];
            long cum = 0;
            for (int i = 0; i < n; i++) {
                if (primeStart[i]) {
                    if (i - 1 >= 0) {
                        cum += dpPrev[i - 1];
                        if (cum >= MOD) cum -= MOD;
                    }
                }
                prefixStart[i] = cum;
            }

            long[] dpCurr = new long[n];
            for (int end = 0; end < n; end++) {
                if (nonPrimeEnd[end]) {
                    int maxStartIdx = end - l + 1;
                    if (maxStartIdx >= 0) {
                        dpCurr[end] = prefixStart[maxStartIdx];
                    }
                }
            }
            dpPrev = dpCurr;
        }

        return (int) (dpPrev[n - 1] % MOD);
    }
}

