                prefix[i + 1] = (prefix[i] + (startPrime[i] ? dp[i] : 0)) % MOD;
            }

            long[] next = new long[n + 1];
            for (int e = 1; e <= n; e++) {
                if (!endNonPrime[e - 1]) continue;
                int idx = e - l;
                if (idx < 0) continue;
                next[e] = prefix[idx + 1]; // prefix up to idx inclusive
            }
            dp = next;
        }

        return (int) (dp[n] % MOD);
    }
