import java.util.*;

public class Solution {
    private static final long MOD1 = 1_000_000_007L;
    private static final long MOD2 = 1_000_000_009L;
    private static final long BASE = 91138233L;

    public int maxPalindromes(String s, int k) {
        int n = s.length();
        if (k > n) return 0;
        char[] ch = s.toCharArray();

        // pre‑compute powers
        long[] pow1 = new long[n + 1];
        long[] pow2 = new long[n + 1];
        pow1[0] = pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow1[i] = (pow1[i - 1] * BASE) % MOD1;
            pow2[i] = (pow2[i - 1] * BASE) % MOD2;
        }

        // forward hashes
        long[] pref1 = new long[n + 1];
        long[] pref2 = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref1[i + 1] = (pref1[i] * BASE + ch[i]) % MOD1;
            pref2[i + 1] = (pref2[i] * BASE + ch[i]) % MOD2;
        }

        // reverse hashes
        long[] rev1 = new long[n + 1];
        long[] rev2 = new long[n + 1];
        for (int i = 0; i < n; i++) {
            rev1[i + 1] = (rev1[i] * BASE + ch[n - 1 - i]) % MOD1;
            rev2[i + 1] = (rev2[i] * BASE + ch[n - 1 - i]) % MOD2;
        }

        // helper to get hash of substring [l, r] inclusive (0‑based)
        java.util.function.BiFunction<Integer, Integer, long[]> hashForward = (l, r) -> {
            int len = r - l + 1;
            long h1 = (pref1[r + 1] - pref1[l] * pow1[len]) % MOD1;
            if (h1 < 0) h1 += MOD1;
            long h2 = (pref2[r + 1] - pref2[l] * pow2[len]) % MOD2;
            if (h2 < 0) h2 += MOD2;
            return new long[]{h1, h2};
        };

        java.util.function.BiFunction<Integer, Integer, long[]> hashReverse = (l, r) -> {
            // corresponds to original indices l..r, map to reversed string positions
            int rl = n - 1 - r;
            int rr = n - 1 - l;
            int len = rr - rl + 1;
            long h1 = (rev1[rr + 1] - rev1[rl] * pow1[len]) % MOD1;
            if (h1 < 0) h1 += MOD1;
            long h2 = (rev2[rr + 1] - rev2[rl] * pow2[len]) % MOD2;
            if (h2 < 0) h2 += MOD2;
            return new long[]{h1, h2};
        };

        // minimal palindrome length >=k starting at each position, -1 if none
        int[] minLen = new int[n];
        Arrays.fill(minLen, -1);

        for (int i = 0; i < n; i++) {
            int low = k;
            int high = n - i;
            int best = -1;
            while (low <= high) {
                int mid = (low + high) >>> 1;
                long[] fh = hashForward.apply(i, i + mid - 1);
                long[] rh = hashReverse.apply(i, i + mid - 1);
                if (fh[0] == rh[0] && fh[1] == rh[1]) {
                    best = mid;
                    high = mid - 1; // try shorter
                } else {
                    low = mid + 1;
                }
            }
            if (best != -1) {
                minLen[i] = best;
            }
        }

        int[] dp = new int[n + 1];
        Arrays.fill(dp, -1_000_000);
        dp[0] = 0;

        for (int i = 0; i < n; i++) {
            // skip character i
            dp[i + 1] = Math.max(dp[i + 1], dp[i]);

            if (minLen[i] != -1) {
                int nxt = i + minLen[i];
                dp[nxt] = Math.max(dp[nxt], dp[i] + 1);
            }
        }

        return dp[n];
    }
}

