        }

        int[] minLenEnd = new int[n];
        Arrays.fill(minLenEnd, Integer.MAX_VALUE);

        PriorityQueue<int[]> heapOdd = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        PriorityQueue<int[]> heapEven = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));

        for (int e = 0; e < n; e++) {
            for (int[] it : startOdd[e]) {
                heapOdd.add(new int[]{it[0], it[1]});
            }
            while (!heapOdd.isEmpty() && heapOdd.peek()[1] < e) {
                heapOdd.poll();
            }
            for (int[] it : startEven[e]) {
                heapEven.add(new int[]{it[0], it[1]});
            }
            while (!heapEven.isEmpty() && heapEven.peek()[1] < e) {
                heapEven.poll();
            }
            int best = Integer.MAX_VALUE;
            if (!heapOdd.isEmpty()) {
                best = Math.min(best, 2 * e + heapOdd.peek()[0]);
            }
            if (!heapEven.isEmpty()) {
                best = Math.min(best, 2 * e + heapEven.peek()[0]);
            }
            minLenEnd[e] = best;
        }

        int[] dp = new int[n + 1];
        for (int i = 0; i < n; i++) {
            dp[i + 1] = Math.max(dp[i + 1], dp[i]); // skip position i
            int len = minLenEnd[i];
            if (len != Integer.MAX_VALUE) {
                int start = i - len + 1;
                if (start >= 0) {
                    dp[i + 1] = Math.max(dp[i + 1], dp[start] + 1);
                }
            }
        }
        return dp[n];
    }

    private static int[] manacherOdd(String s) {
        int n = s.length();
        int[] d = new int[n];
        int l = 0, r = -1;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 1 : Math.min(d[l + r - i], r - i + 1);
            while (i - k >= 0 && i + k < n && s.charAt(i - k) == s.charAt(i + k)) {
                k++;
            }
            d[i] = k - 1;
            if (i + d[i] > r) {
                l = i - d[i];
                r = i + d[i];
            }
        }
        return d;
    }

    private static int[] manacherEven(String s) {
        int n = s.length();
        int[] d = new int[n];
        int l = 0, r = -1;
        for (int i = 0; i < n; i++) {
            int k = (i > r) ? 0 : Math.min(d[l + r - i + 1], r - i + 1);
            while (i - k - 1 >= 0 && i + k < n && s.charAt(i - k - 1) == s.charAt(i + k)) {
                k++;
            }
            d[i] = k;
            if (i + d[i] - 1 > r) {
                l = i - d[i];
                r = i + d[i] - 1;
            }
        }
        return d;
    }
}

