import java.util.*;

public class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();
        int[] minLen = new int[n];
        Arrays.fill(minLen, Integer.MAX_VALUE);
        char[] ch = s.toCharArray();

        // Expand around each center for odd length palindromes
        for (int center = 0; center < n; center++) {
            int l = center, r = center;
            while (l >= 0 && r < n && ch[l] == ch[r]) {
                int len = r - l + 1;
                if (len >= k && len < minLen[l]) {
                    minLen[l] = len;
                }
                l--;
                r++;
            }
        }

        // Expand around each center for even length palindromes
        for (int center = 0; center < n - 1; center++) {
            int l = center, r = center + 1;
            while (l >= 0 && r < n && ch[l] == ch[r]) {
                int len = r - l + 1;
                if (len >= k && len < minLen[l]) {
                    minLen[l] = len;
                }
                l--;
                r++;
            }
        }

        int[] dp = new int[n + 1];
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            dp[i] = dp[i + 1]; // skip position i
            if (minLen[i] != Integer.MAX_VALUE) {
                int next = i + minLen[i];
                if (next <= n) {
                    dp[i] = Math.max(dp[i], 1 + dp[next]);
                }
            }
        }
        return dp[0];
    }
}

