public class Solution {
    /**
     * Returns the minimum total cost to make all elements of {@code nums} equal.
     * Changing {@code nums[i]} by one unit costs {@code cost[i]}.
     *
     * @param nums the array of values
     * @param cost the array of per‑unit costs
     * @return the minimal total cost
     */
    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        // Pair each number with its cost
        long[][] pairs = new long[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums[i];
            pairs[i][1] = cost[i];
        }
        // Sort by the number value
        Arrays.sort(pairs, Comparator.comparingLong(a -> a[0]));

        // Compute total weight (sum of costs)
        long totalWeight = 0;
        for (long[] p : pairs) {
            totalWeight += p[1];
        }

        // Find weighted median
        long prefix = 0;
        long median = pairs[n - 1][0];
        for (int i = 0; i < n; i++) {
            prefix += pairs[i][1];
            if (prefix * 2 >= totalWeight) { // reaches at least half of total weight
                median = pairs[i][0];
                break;
            }
        }

        // Compute total cost using the median as target
        long answer = 0;
        for (int i = 0; i < n; i++) {
            long diff = Math.abs((long) nums[i] - median);
            answer += diff * (long) cost[i];
        }
        return answer;
    }
}

