public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        // Build parent array and post‑order traversal list
        int[] parent = new int[n];
        int[] order = new int[n];
        int idx = 0;
        int[] stack = new int[n];
        stack[idx++] = 0;
        parent[0] = -1;
        int orderPos = 0;
        while (idx > 0) {
            int node = stack[--idx];
            order[orderPos++] = node;
            for (int nb : graph[node]) {
                if (nb == parent[node]) continue;
                parent[nb] = node;
                stack[idx++] = nb;
            }
        }
        // order now is preorder, reverse it for postorder
        for (int i = 0; i < n / 2; i++) {
            int tmp = order[i];
            order[i] = order[n - 1 - i];
            order[n - 1 - i] = tmp;
        }

        long total = 0;
        for (int v : nums) total += v;

        // Try number of components from n down to 1
        for (int k = n; k >= 1; k--) {
            if (total % k != 0) continue;
            long target = total / k;
            long[] sum = new long[n];
            int cutCount = 0;
            for (int node : order) {
                long cur = nums[node];
                for (int nb : graph[node]) {
                    if (nb == parent[node]) continue;
                    cur += sum[nb];
                }
                if (cur == target) {
                    cutCount++;
                    sum[node] = 0;
                } else {
                    sum[node] = cur;
                }
            }
            if (cutCount == k && sum[0] == 0) {
                return k - 1; // maximum deletable edges
            }
        }
        return 0; // fallback, should never reach here
    }
}

