import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Stack;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        // Build adjacency list
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int a = e[0];
            int b = e[1];
            adj[a].add(b);
            adj[b].add(a);
        }

        long total = 0L;
        for (int v : nums) total += v;

        // If total sum is zero, we can cut all edges
        if (total == 0L) {
            return n - 1;
        }

        // Collect all positive divisors of total (component sum candidates)
        List<Long> divisors = new ArrayList<>();
        for (long d = 1; d * d <= total; d++) {
            if (total % d == 0) {
                divisors.add(d);
                if (d != total / d) {
                    divisors.add(total / d);
                }
            }
        }
        Collections.sort(divisors); // ascending -> smallest target first (max components)

        // Pre‑process order and parent for post‑order traversal (once)
        int[] parent = new int[n];
        int[] order = new int[n];
        int idx = 0;
        Stack<Integer> stack = new Stack<>();
        stack.push(0);
        parent[0] = -1;
        while (!stack.isEmpty()) {
            int node = stack.pop();
            order[idx++] = node;
            for (int nb : adj[node]) {
                if (nb == parent[node]) continue;
                parent[nb] = node;
                stack.push(nb);
            }
        }

        // Try each possible component sum (target)
        for (long target : divisors) {
            if (canPartition(target, nums, adj, parent, order)) {
                long components = total / target;
                return (int) (components - 1); // deletions = components - 1
            }
        }

        // Fallback (should never reach because target = total always works)
        return 0;
    }

    private boolean canPartition(long target, int[] nums, List<Integer>[] adj,
                                 int[] parent, int[] order) {
        int n = nums.length;
        long[] sub = new long[n];

        // Process nodes in post‑order (reverse of the stored order)
        for (int i = n - 1; i >= 0; i--) {
            int node = order[i];
            long cur = nums[node];
            for (int nb : adj[node]) {
                if (nb == parent[node]) continue;
                cur += sub[nb];
            }
            if (cur == target) {
                sub[node] = 0; // this subtree becomes a separate component
            } else if (cur < target) {
                sub[node] = cur; // propagate upward
            } else {
                return false; // exceeds target, impossible
            }
        }
        // If root also forms a component, its sum must be zero
        return sub[0] == 0;
    }
}

