public class Solution {
    private List<Integer>[] graph;
    private int[] values;
    private long targetSum;
    private int componentCnt;

    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        values = nums;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        long total = 0L;
        for (int v : nums) total += v;

        // Special case when total sum is zero
        if (total == 0L) {
            targetSum = 0L;
            componentCnt = 0;
            dfs(0, -1);
            // componentCnt includes the whole tree as a component
            return componentCnt - 1;
        }

        int maxDeleted = 0;
        long absTotal = Math.abs(total);
        for (long i = 1; i * i <= absTotal; i++) {
            if (absTotal % i == 0) {
                long[] possibleCounts = {i, absTotal / i};
                for (long cnt : possibleCounts) {
                    if (cnt > n) continue;
                    long candTarget = total / cnt; // will be integer
                    targetSum = candTarget;
                    componentCnt = 0;
                    long rem = dfs(0, -1);
                    if (rem == 0L) {
                        maxDeleted = Math.max(maxDeleted, (int) (cnt - 1));
                    }
                }
            }
        }
        return maxDeleted;
    }

    // Returns the sum of the current subtree after cutting off completed components.
    private long dfs(int u, int parent) {
        long sum = values[u];
        for (int v : graph[u]) {
            if (v == parent) continue;
            sum += dfs(v, u);
        }
        if (sum == targetSum) {
            componentCnt++;
            return 0L; // cut here, component formed
        }
        return sum;
    }
}

