        long sum = nums[node];
        for (int nei : graph[node]) {
            if (nei == parent) {
                continue;
            }
            long childSum = dfs(nei, node, target, graph, nums);
            sum += childSum;
        }
        if (!possible) {
            return 0;
        }
        if (sum == target) {
            // this subtree forms a component; cut it from its parent
            return 0;
        }
        if (sum > target) {
            possible = false;
            return 0;
        }
        // sum < target, propagate upwards
        return sum;
    }
}

