public class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        if (digitSum(n) <= target) {
            return 0L;
        }
        long answer = 0L;
        long power = 1L;
        long current = n;
        while (digitSum(current) > target) {
            long digit = (current / power) % 10;
            long add = (10 - digit) % 10;
            if (add == 0) {
                power *= 10;
                continue;
            }
            long increment = add * power;
            answer += increment;
            current += increment;
            power *= 10;
        }
        return answer;
    }

    private long digitSum(long x) {
        long sum = 0;
        while (x > 0) {
            sum += x % 10;
            x /= 10;
        }
        return sum;
    }
}

