public class Solution {

    // Segment Tree for range maximum query and point update (max)
    private static class SegTree {
        private final int n;
        private final int[] tree;

        public SegTree(int n) {
            this.n = n;
            // allocate 4 * n to be safe
            this.tree = new int[4 * n];
        }

        // point update: set position idx to max(current, value)
        public void update(int idx, int value) {
            update(1, 0, n - 1, idx, value);
        }

        private void update(int node, int l, int r, int idx, int value) {
            if (l == r) {
                tree[node] = Math.max(tree[node], value);
                return;
            }
            int mid = (l + r) >>> 1;
            if (idx <= mid) {
                update(node << 1, l, mid, idx, value);
            } else {
                update(node << 1 | 1, mid + 1, r, idx, value);
            }
            tree[node] = Math.max(tree[node << 1], tree[node << 1 | 1]);
        }

        // range maximum query on [ql, qr]
        public int query(int ql, int qr) {
            if (ql > qr) return 0;
            return query(1, 0, n - 1, ql, qr);
        }

        private int query(int node, int l, int r, int ql, int qr) {
            if (qr < l || r < ql) return 0;
            if (ql <= l && r <= qr) return tree[node];
            int mid = (l + r) >>> 1;
            return Math.max(query(node << 1, l, mid, ql, qr),
                            query(node << 1 | 1, mid + 1, r, ql, qr));
        }
    }

    /**
     * Returns the length of the longest strictly increasing subsequence where
     * the difference between adjacent elements is at most k.
     *
     * @param nums input array
     * @param k    maximum allowed difference between consecutive elements
     * @return length of the longest valid subsequence
     */
    public int longestSubsequence(int[] nums, int k) {
        if (nums == null || nums.length == 0) return 0;

        // Coordinate compression of all values appearing in nums
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int[] uniq = Arrays.stream(sorted).distinct().toArray();

        int m = uniq.length;
        SegTree seg = new SegTree(m);

        int answer = 0;
        for (int x : nums) {
            // Find the range of previous values y such that:
            // y < x and x - y <= k  =>  y in [x - k, x - 1]
            int leftVal = x - k;
            int rightVal = x - 1;

            int leftIdx = lowerBound(uniq, leftVal);
            int rightIdx = lowerBound(uniq, x) - 1;

            int bestPrev = 0;
            if (leftIdx <= rightIdx) {
                bestPrev = seg.query(leftIdx, rightIdx);
            }

            int curLen = bestPrev + 1;

            // Update the position of x with the best length ending at x
            int pos = Arrays.binarySearch(uniq, x);
            seg.update(pos, curLen);

            answer = Math.max(answer, curLen);
        }
        return answer;
    }

    // Returns first index i such that arr[i] >= target
    private int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

