public class Solution {
    // Segment Tree for range maximum query and point update (max)
    private static class SegTree {
        private final int n;
        private final int[] tree;

        public SegTree(int size) {
            this.n = size;
            this.tree = new int[4 * size];
        }

        // point update: set position idx to max(current, value)
        public void update(int idx, int value) {
            update(1, 0, n - 1, idx, value);
        }

        private void update(int node, int l, int r, int idx, int value) {
            if (l == r) {
                tree[node] = Math.max(tree[node], value);
                return;
            }
            int mid = (l + r) >>> 1;
            if (idx <= mid) {
                update(node << 1, l, mid, idx, value);
            } else {
                update(node << 1 | 1, mid + 1, r, idx, value);
            }
            tree[node] = Math.max(tree[node << 1], tree[node << 1 | 1]);
        }

        // query maximum in [ql, qr]
        public int query(int ql, int qr) {
            if (ql > qr) return 0;
            return query(1, 0, n - 1, ql, qr);
        }

        private int query(int node, int l, int r, int ql, int qr) {
            if (qr < l || r < ql) return 0;
            if (ql <= l && r <= qr) return tree[node];
            int mid = (l + r) >>> 1;
            int left = query(node << 1, l, mid, ql, qr);
            int right = query(node << 1 | 1, mid + 1, r, ql, qr);
            return Math.max(left, right);
        }
    }

    /**
     * Returns the length of the longest strictly increasing subsequence where
     * the difference between adjacent elements is at most k.
     *
     * @param nums input array
     * @param k    maximum allowed difference between consecutive elements
     * @return length of the longest valid subsequence
     */
    public int longestSubsequence(int[] nums, int k) {
        if (nums == null || nums.length == 0) return 0;

        // Coordinate compression of all distinct numbers in nums
        int n = nums.length;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int uniqCount = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                sorted[uniqCount++] = sorted[i];
            }
        }
        int[] values = Arrays.copyOf(sorted, uniqCount);

        SegTree segTree = new SegTree(uniqCount);
        int answer = 0;

        for (int num : nums) {
            // Determine the range of previous values that are < num and >= num - k
            int leftVal = num - k;
            int rightVal = num - 1;

            int leftIdx = lowerBound(values, leftVal);
            int rightIdx = upperBound(values, rightVal) - 1;

            int bestPrev = 0;
            if (leftIdx <= rightIdx) {
                bestPrev = segTree.query(leftIdx, rightIdx);
            }

            int curLen = bestPrev + 1;
            int pos = lowerBound(values, num); // exact position of num
            segTree.update(pos, curLen);
            answer = Math.max(answer, curLen);
        }

        return answer;
    }

    // first index >= target
    private int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    // first index > target
    private int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

