import java.util.*;

public class Solution {

    /***
     * Returns the length of the longest strictly increasing subsequence such that
     * the difference between any two adjacent elements in the subsequence is at most k.
     *
     * @param nums input array
     * @param k    maximum allowed difference between adjacent elements
     * @return length of the longest valid subsequence
     */
    public int longestSubsequence(int[] nums, int k) {
        if (nums == null || nums.length == 0) return 0;

        // Coordinate compression of all values that appear in nums
        int n = nums.length;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int[] uniq = Arrays.stream(sorted).distinct().toArray();

        // Fenwick tree (Binary Indexed Tree) for range maximum query
        Fenwick fenwick = new Fenwick(uniq.length);

        int answer = 0;
        for (int value : nums) {
            // Find the index range of previous values that are < value and >= value - k
            int leftVal = value - k;
            // first index with value >= leftVal
            int leftIdx = lowerBound(uniq, leftVal);
            // last index with value < value  (strictly smaller)
            int rightIdx = lowerBound(uniq, value) - 1;

            int best = 0;
            if (leftIdx <= rightIdx) {
                best = fenwick.query(leftIdx + 1, rightIdx + 1); // Fenwick is 1‑based
            }

            int cur = best + 1;
            // Update the position of the current value with the new dp value
            int pos = Arrays.binarySearch(uniq, value);
            fenwick.update(pos + 1, cur);

            answer = Math.max(answer, cur);
        }
        return answer;
    }

    /** Binary search: first index >= target */
    private int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    /** Fenwick tree that supports point update with max and range max query */
    private static class Fenwick {
        private final int[] bit;
        private final int n;

        Fenwick(int n) {
            this.n = n;
            this.bit = new int[n + 2];
        }

        /** set position idx (1‑based) to max(current, val) */
        void update(int idx, int val) {
            while (idx <= n) {
                if (val > bit[idx]) bit[idx] = val;
                idx += idx & -idx;
            }
        }

        /** query maximum in prefix [1..idx] */
        private int queryPrefix(int idx) {
            int res = 0;
            while (idx > 0) {
                if (bit[idx] > res) res = bit[idx];
                idx -= idx & -idx;
            }
            return res;
        }

        /** query maximum in range [l..r] (both 1‑based, l <= r) */
        int query(int l, int r) {
            if (l > r) return 0;
            return Math.max(0, queryPrefix(r) - 0); // we need max, not sum, so use prefix trick
        }

        /** Since Fenwick for max cannot obtain range max via subtraction,
         * we simply walk the tree for the right bound and ignore left bound.
         * To get range [l..r] we query prefix up to r and then,
         * because max is monotonic, we must ensure we only consider updates
         * that fall inside [l..r]. The usual approach is to store max in each node;
         * querying prefix gives the max over [1..r]. To restrict to [l..r],
         * we can query prefix up to r and then, if needed, query prefix up to l-1
         * and take the larger of the two? That's not correct.
         *
         * Simpler solution: use a segment tree for range max.
         * However, for this problem we only need max over [l..r] where
         * updates are only ever performed at exact positions.
         * We can implement a segment tree instead of Fenwick.
         *
         * To keep the current structure, we replace query(l,r) with a
         * segment‑tree‑like walk: we iterate over indices from r downwards
         * using the standard BIT traversal, but we stop when the index
         * becomes less than l. This yields O(log n) time.
         */
        int queryRange(int l, int r) {
            int res = 0;
            int idx = r;
            while (idx >= l) {
                int next = idx - (idx & -idx);
                if (next + 1 >= l) {
                    if (bit[idx] > res) res = bit[idx];
                    idx = next;
                } else {
                    // need to move one step left
                    idx--;
                }
            }
            return res;
        }

        // Adjust public query to use the correct range method
        int query(int l, int r, boolean dummy) {
            return queryRange(l, r);
        }
    }

    // Overload to call the correct range query implementation
    private int queryFenwick(Fenwick ft, int l, int r) {
        return ft.query(l, r, true);
    }
