import java.util.*;

public class Solution {

    private static class SegTree {
        private final int n;
        private final int[] tree;

        SegTree(int n) {
            this.n = n;
            this.tree = new int[4 * n];
        }

        void update(int idx, int val) {
            update(1, 0, n - 1, idx, val);
        }

        private void update(int node, int l, int r, int idx, int val) {
            if (l == r) {
                tree[node] = Math.max(tree[node], val);
                return;
            }
            int mid = (l + r) >>> 1;
            if (idx <= mid) {
                update(node * 2, l, mid, idx, val);
            } else {
                update(node * 2 + 1, mid + 1, r, idx, val);
            }
            tree[node] = Math.max(tree[node * 2], tree[node * 2 + 1]);
        }

        int query(int ql, int qr) {
            if (ql > qr) return 0;
            return query(1, 0, n - 1, ql, qr);
        }

        private int query(int node, int l, int r, int ql, int qr) {
            if (qr < l || r < ql) return 0;
            if (ql <= l && r <= qr) return tree[node];
            int mid = (l + r) >>> 1;
            return Math.max(
                    query(node * 2, l, mid, ql, qr),
                    query(node * 2 + 1, mid + 1, r, ql, qr)
            );
        }
    }

    /**
     * Returns the length of the longest strictly increasing subsequence
     * where the difference between adjacent elements is at most k.
     *
     * @param nums the input array
     * @param k    the maximum allowed difference between consecutive elements
     * @return the maximal length of such a subsequence
     */
    public int longestSubsequence(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return 0;

        // Coordinate compression: collect all nums[i] and nums[i] - k
        long[] tmp = new long[2 * n];
        int p = 0;
        for (int v : nums) {
            tmp[p++] = v;
            tmp[p++] = (long) v - (long) k;
        }
        Arrays.sort(tmp);
        int m = 0;
        for (int i = 0; i < tmp.length; i++) {
            if (i == 0 || tmp[i] != tmp[i - 1]) {
                tmp[m++] = tmp[i];
            }
        }
        long[] values = Arrays.copyOf(tmp, m);

        SegTree seg = new SegTree(m);
        int answer = 0;

        for (int v : nums) {
            long low = (long) v - (long) k;
            int left = lowerBound(values, low);
            int right = lowerBound(values, v) - 1;

            int bestPrev = (left <= right) ? seg.query(left, right) : 0;
            int cur = bestPrev + 1;

            int pos = lowerBound(values, v);
            seg.update(pos, cur);

            if (cur > answer) answer = cur;
        }

        return answer;
    }

    private int lowerBound(long[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < target) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    }
}

