public class Solution {

    // Segment Tree for range maximum query
    private static class SegTree {
        private final int n;
        private final int[] tree;

        public SegTree(int n) {
            this.n = n;
            this.tree = new int[4 * n];
        }

        // point update: set position idx to max(current, value)
        public void update(int idx, int value) {
            update(1, 0, n - 1, idx, value);
        }

        private void update(int node, int l, int r, int idx, int value) {
            if (l == r) {
                tree[node] = Math.max(tree[node], value);
                return;
            }
            int mid = (l + r) >>> 1;
            if (idx <= mid) {
                update(node << 1, l, mid, idx, value);
            } else {
                update(node << 1 | 1, mid + 1, r, idx, value);
            }
            tree[node] = Math.max(tree[node << 1], tree[node << 1 | 1]);
        }

        // query maximum in [ql, qr]
        public int query(int ql, int qr) {
            if (ql > qr) return 0;
            return query(1, 0, n - 1, ql, qr);
        }

        private int query(int node, int l, int r, int ql, int qr) {
            if (qr < l || r < ql) return 0;
            if (ql <= l && r <= qr) return tree[node];
            int mid = (l + r) >>> 1;
            return Math.max(query(node << 1, l, mid, ql, qr),
                            query(node << 1 | 1, mid + 1, r, ql, qr));
        }
    }

    // Helper: first index with value >= target
    private static int lowerBound(List<Integer> list, int target) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    // Helper: first index with value > target
    private static int upperBound(List<Integer> list, int target) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    /**
     * Returns the length of the longest strictly increasing subsequence where
     * the difference between adjacent elements is at most k.
     *
     * @param nums input array
     * @param k    maximum allowed difference between consecutive elements
     * @return length of the longest valid subsequence
     */
    public int longestSubsequence(int[] nums, int k) {
        if (nums == null || nums.length == 0) return 0;

        // Coordinate compression of all distinct values in nums
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        List<Integer> uniq = new ArrayList<>();
        for (int v : sorted) {
            if (uniq.isEmpty() || uniq.get(uniq.size() - 1) != v) {
                uniq.add(v);
            }
        }

        SegTree seg = new SegTree(uniq.size());
        int answer = 0;

        for (int v : nums) {
            int leftVal = v - k;
            int rightVal = v - 1; // strictly increasing

            int l = lowerBound(uniq, leftVal);
            int r = upperBound(uniq, rightVal) - 1;

            int best = (l <= r) ? seg.query(l, r) : 0;
            int cur = best + 1;

            int idx = lowerBound(uniq, v); // position of v itself
            seg.update(idx, cur);

            if (cur > answer) answer = cur;
        }

        return answer;
    }
}

