import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    private static class UnionFind {
        int[] parent;
        int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    }

    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            adj[a].add(b);
            adj[b].add(a);
        }

        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        java.util.Arrays.sort(order, (i, j) -> Integer.compare(vals[i], vals[j]));

        UnionFind uf = new UnionFind(n);
        int answer = n; // each single node is a good path

        int idx = 0;
        while (idx < n) {
            int curVal = vals[order[idx]];
            int end = idx;
            // union step for all nodes with current value
            while (end < n && vals[order[end]] == curVal) {
                int node = order[end];
                for (int nb : adj[node]) {
                    if (vals[nb] <= curVal) {
                        uf.union(node, nb);
                    }
                }
                end++;
            }

            // count nodes of this value per component
            Map<Integer, Integer> compCount = new HashMap<>();
            for (int i = idx; i < end; i++) {
                int node = order[i];
                int root = uf.find(node);
                compCount.put(root, compCount.getOrDefault(root, 0) + 1);
            }

            for (int cnt : compCount.values()) {
                answer += cnt * (cnt - 1) / 2;
            }

            idx = end;
        }

        return answer;
    }
}

