            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int tmp = ra; ra = rb; rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    }

    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            adj[a].add(b);
            adj[b].add(a);
        }

        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> vals[i]));

        DSU dsu = new DSU(n);
        long goodPaths = n; // each single node

        int i = 0;
        while (i < n) {
            int curVal = vals[order[i]];
            int j = i;
            // union nodes with value <= curVal
            while (j < n && vals[order[j]] == curVal) {
                int node = order[j];
                for (int nb : adj[node]) {
                    if (vals[nb] <= curVal) {
                        dsu.union(node, nb);
                    }
                }
                j++;
            }
            // count nodes of this value per component
            Map<Integer, Integer> compCount = new HashMap<>();
            for (int k = i; k < j; k++) {
                int root = dsu.find(order[k]);
                compCount.merge(root, 1, Integer::sum);
            }
            for (int cnt : compCount.values()) {
                goodPaths += (long) cnt * (cnt - 1) / 2;
            }
            i = j;
        }

        return (int) goodPaths;
    }
