public class Solution {
    public int minimizeXor(int num1, int num2) {
        int need = Integer.bitCount(num2);
        int cnt1 = Integer.bitCount(num1);
        int x = 0;

        if (need <= cnt1) {
            // Keep the highest 'need' set bits of num1
            for (int i = 31; i >= 0 && need > 0; i--) {
                if (((num1 >> i) & 1) == 1) {
                    x |= (1 << i);
                    need--;
                }
            }
        } else {
            // Take all set bits from num1
            x = num1;
            int remaining = need - cnt1;
            // Add lowest zero bits
            for (int i = 0; i < 32 && remaining > 0; i++) {
                if (((num1 >> i) & 1) == 0) {
                    x |= (1 << i);
                    remaining--;
                }
            }
        }
        return x;
    }
}

