public class Solution {
    public int maximumValue(String[] strs) {
        int max = 0;
        if (strs == null) {
            return max;
        }
        for (String s : strs) {
            if (s == null) {
                continue;
            }
            int value;
            if (isAllDigits(s)) {
                try {
                    value = Integer.parseInt(s);
                } catch (NumberFormatException e) {
                    // If the number exceeds int range, treat its value as Integer.MAX_VALUE
                    value = Integer.MAX_VALUE;
                }
            } else {
                value = s.length();
            }
            if (value > max) {
                max = value;
            }
        }
        return max;
    }

    private boolean isAllDigits(String s) {
        if (s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }
}

