                        value = Integer.MIN_VALUE;
                    } else {
                        value = (int) num;
                    }
                } catch (NumberFormatException e) {
                    // Fallback to length if parsing fails (very large number)
                    value = s.length();
                }
            } else {
                value = s.length();
            }
            if (value > max) {
                max = value;
            }
        }
        return max;
    }
