public class Solution {
    public int magnificentSets(int n, int[][] edges) {
        // Build adjacency list
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int a = e[0];
            int b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        boolean[] visited = new boolean[n + 1];
        int[] color = new int[n + 1]; // 0 or 1, -1 = uncolored
        for (int i = 1; i <= n; i++) {
            color[i] = -1;
        }

        int answer = 0;

        for (int i = 1; i <= n; i++) {
            if (visited[i]) continue;

            // Gather nodes of this component and check bipartite
            List<Integer> componentNodes = new ArrayList<>();
            Queue<Integer> q = new LinkedList<>();
            q.offer(i);
            visited[i] = true;
            color[i] = 0;
            boolean isBipartite = true;

            while (!q.isEmpty()) {
                int cur = q.poll();
                componentNodes.add(cur);
                for (int nb : graph[cur]) {
                    if (color[nb] == -1) {
                        color[nb] = color[cur] ^ 1;
                    } else if (color[nb] == color[cur]) {
                        isBipartite = false;
                    }
                    if (!visited[nb]) {
                        visited[nb] = true;
                        q.offer(nb);
                    }
                }
            }

            if (!isBipartite) {
                return -1;
            }

            // Compute the maximum distance (diameter) within this component
            int componentDiameter = 0;
            for (int node : componentNodes) {
                int far = bfsFarthest(node, graph, n);
                if (far > componentDiameter) {
                    componentDiameter = far;
                }
            }

            answer += componentDiameter + 1; // groups = diameter + 1
        }

        return answer;
    }

    // BFS from src, returns the farthest distance reachable within its component
    private int bfsFarthest(int src, List<Integer>[] graph, int n) {
        int[] dist = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            dist[i] = -1;
        }
        Queue<Integer> q = new LinkedList<>();
        q.offer(src);
        dist[src] = 0;
        int maxDist = 0;

        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int nb : graph[cur]) {
                if (dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    if (dist[nb] > maxDist) {
                        maxDist = dist[nb];
                    }
                    q.offer(nb);
                }
            }
        }
        return maxDist;
    }
}

