import java.util.PriorityQueue;
import java.util.Arrays;

public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        // Sort meetings by original start time
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[0], b[0]));

        // Priority queue for available rooms (by smallest index)
        PriorityQueue<Integer> available = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            available.offer(i);
        }

        // Priority queue for occupied rooms (by earliest free time, then by index)
        // Each element: long[] {freeTime, roomIndex}
        PriorityQueue<long[]> occupied = new PriorityQueue<>(
                (a, b) -> {
                    if (a[0] != b[0]) {
                        return Long.compare(a[0], b[0]);
                    }
                    return Integer.compare((int) a[1], (int) b[1]);
                });

        int[] count = new int[n];

        for (int[] meeting : meetings) {
            int start = meeting[0];
            int end = meeting[1];
            int duration = end - start;

            // Release rooms that have become free by the meeting's original start time
            while (!occupied.isEmpty() && occupied.peek()[0] <= start) {
                long[] freed = occupied.poll();
                available.offer((int) freed[1]);
            }

            int room;
            long actualStart;
            if (!available.isEmpty()) {
                // Assign the lowest-numbered free room
                room = available.poll();
                actualStart = start;
            } else {
                // Delay: take the room that becomes free the earliest
                long[] earliest = occupied.poll();
                room = (int) earliest[1];
                actualStart = earliest[0]; // start when the room becomes free
            }

            long actualEnd = actualStart + duration;
            count[room]++;

            // Mark the room as occupied until actualEnd
            occupied.offer(new long[]{actualEnd, room});
        }

        // Find the room with the maximum meetings count (lowest index on tie)
        int bestRoom = 0;
        for (int i = 1; i < n; i++) {
            if (count[i] > count[bestRoom]) {
                bestRoom = i;
            }
        }
        return bestRoom;
    }
}

