            this.index = index;
        }
    }

    public int mostBooked(int n, int[][] meetings) {
        // sort meetings by original start time
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[0], b[0]));

        // available rooms ordered by smallest index
        PriorityQueue<Integer> available = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            available.offer(i);
        }

        // busy rooms ordered by earliest end time, tie by smaller index
        PriorityQueue<Room> busy = new PriorityQueue<>(
                (r1, r2) -> {
                    if (r1.endTime != r2.endTime) {
                        return Integer.compare(r1.endTime, r2.endTime);
                    }
                    return Integer.compare(r1.index, r2.index);
                });

        int[] count = new int[n];

        for (int[] meeting : meetings) {
            int start = meeting[0];
            int end = meeting[1];
            int duration = end - start;

            // free rooms whose meetings have ended by current start time
            while (!busy.isEmpty() && busy.peek().endTime <= start) {
                Room freed = busy.poll();
                available.offer(freed.index);
            }

            int roomIdx;
            int newEndTime;

            if (!available.isEmpty()) {
                // assign to the lowest‑numbered free room
                roomIdx = available.poll();
                newEndTime = end;
            } else {
                // delay the meeting: take the room that becomes free the earliest
                Room earliest = busy.poll();
                roomIdx = earliest.index;
                int delayedStart = earliest.endTime;
                newEndTime = delayedStart + duration;
            }

            count[roomIdx]++;                     // this room held another meeting
            busy.offer(new Room(newEndTime, roomIdx));
        }

        // find the room with the maximum count (lowest index on tie)
        int bestRoom = 0;
        for (int i = 1; i < n; i++) {
            if (count[i] > count[bestRoom]) {
                bestRoom = i;
            }
        }
        return bestRoom;
    }
