public class Solution {
    private static class Room implements Comparable<Room> {
        long endTime;
        int index;

        Room(long endTime, int index) {
            this.endTime = endTime;
            this.index = index;
        }

        @Override
        public int compareTo(Room other) {
            if (this.endTime != other.endTime) {
                return Long.compare(this.endTime, other.endTime);
            }
            return Integer.compare(this.index, other.index);
        }
    }

    public int mostBooked(int n, int[][] meetings) {
        // sort meetings by original start time
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[0], b[0]));

        // available rooms (by smallest index)
        PriorityQueue<Integer> available = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            available.offer(i);
        }

        // occupied rooms (by earliest finishing time)
        PriorityQueue<Room> occupied = new PriorityQueue<>();

        int[] count = new int[n];

        for (int[] m : meetings) {
            long start = m[0];
            long end = m[1];
            long duration = end - start;

            // free rooms that have become available by current start time
            while (!occupied.isEmpty() && occupied.peek().endTime <= start) {
                Room freed = occupied.poll();
                available.offer(freed.index);
            }

            int roomIdx;
            long newEndTime;

            if (!available.isEmpty()) {
                // assign the smallest indexed free room
                roomIdx = available.poll();
                newEndTime = end;
            } else {
                // delay the meeting: take the earliest finishing occupied room
                Room earliest = occupied.poll();
                roomIdx = earliest.index;
                long delayedStart = earliest.endTime;
                newEndTime = delayedStart + duration;
            }

            count[roomIdx]++;
            occupied.offer(new Room(newEndTime, roomIdx));
        }

        // find the room with the maximum count (lowest index on ties)
        int bestRoom = 0;
        int maxMeetings = count[0];
        for (int i = 1; i < n; i++) {
            if (count[i] > maxMeetings) {
                maxMeetings = count[i];
                bestRoom = i;
            }
        }
        return bestRoom;
    }
}

