public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        // Sort meetings by original start time
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[0], b[0]));

        // Min‑heap for free rooms (by room index)
        PriorityQueue<Integer> freeRooms = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            freeRooms.offer(i);
        }

        // Min‑heap for occupied rooms (by finishing time, then room index)
        PriorityQueue<long[]> occupied = new PriorityQueue<>(
                (x, y) -> {
                    if (x[0] == y[0]) {
                        return Long.compare(x[1], y[1]);
                    }
                    return Long.compare(x[0], y[0]);
                });

        long[] cnt = new long[n]; // count of meetings per room

        for (int[] meeting : meetings) {
            int start = meeting[0];
            int end = meeting[1];
            long duration = (long) end - start;

            // Release rooms that have become free by the current start time
            while (!occupied.isEmpty() && occupied.peek()[0] <= start) {
                long[] freed = occupied.poll();
                freeRooms.offer((int) freed[1]);
            }

            int room;
            long actualStart;

            if (!freeRooms.isEmpty()) {
                // Assign the lowest‑numbered free room
                room = freeRooms.poll();
                actualStart = start;
            } else {
                // Delay the meeting: take the room that becomes free the earliest
                long[] earliest = occupied.poll();
                room = (int) earliest[1];
                actualStart = earliest[0]; // meeting starts when the room is free
            }

            long actualEnd = actualStart + duration;
            occupied.offer(new long[]{actualEnd, room});
            cnt[room]++;
        }

        // Find the room with the maximum count (tie → smallest index)
        int bestRoom = 0;
        long bestCnt = cnt[0];
        for (int i = 1; i < n; i++) {
            if (cnt[i] > bestCnt) {
                bestCnt = cnt[i];
                bestRoom = i;
            }
        }
        return bestRoom;
    }
