public class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        long result = 0L;
        int lastInvalid = -1;   // index of last element that breaks the [minK, maxK] range
        int lastMin = -1;       // last index where nums[i] == minK
        int lastMax = -1;       // last index where nums[i] == maxK

        for (int i = 0; i < nums.length; i++) {
            int val = nums[i];

            // If current value is outside the allowed range, reset the window
            if (val < minK || val > maxK) {
                lastInvalid = i;
                lastMin = -1;
                lastMax = -1;
                continue;
            }

            if (val == minK) {
                lastMin = i;
            }
            if (val == maxK) {
                lastMax = i;
            }

            // Number of valid subarrays ending at i is determined by the
            // earliest of the last minK/maxK positions after the last invalid index
            int validStart = Math.min(lastMin, lastMax);
            if (validStart > lastInvalid) {
                result += (validStart - lastInvalid);
            }
        }

        return result;
    }
}

