import java.util.List;

public class Solution {
    private static final int MOD = 1_000_000_007;

    private long modPow(long base, long exp) {
        long result = 1L;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public int[] productQueries(int n, int[][] queries) {
        // Extract exponents of set bits (powers of two) in increasing order
        List<Integer> exponents = new ArrayList<>();
        int idx = 0;
        int temp = n;
        while (temp > 0) {
            if ((temp & 1) == 1) {
                exponents.add(idx);
            }
            temp >>= 1;
            idx++;
        }

        int m = exponents.size();
        long[] prefix = new long[m];
        for (int i = 0; i < m; i++) {
            prefix[i] = exponents.get(i) + (i > 0 ? prefix[i - 1] : 0);
        }

        int q = queries.length;
        int[] answers = new int[q];
        for (int i = 0; i < q; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            long sumExp = prefix[right] - (left > 0 ? prefix[left - 1] : 0);
            answers[i] = (int) modPow(2L, sumExp);
        }
        return answers;
    }
}

