public class Solution {
    private static final long MOD = 1_000_000_007L;

    private long modPow(long base, long exp) {
        long result = 1L;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    private long modInv(long x) {
        // MOD is prime, use Fermat's little theorem
        return modPow(x, MOD - 2);
    }

    public int[] productQueries(int n, int[][] queries) {
        // Build the powers array from the set bits of n (ascending order)
        List<Long> powersList = new ArrayList<>();
        for (int i = 0; (1L << i) <= n; i++) {
            if (((n >> i) & 1) == 1) {
                powersList.add(1L << i);
            }
        }

        int m = powersList.size();
        long[] prefix = new long[m];
        for (int i = 0; i < m; i++) {
            long val = powersList.get(i) % MOD;
            if (i == 0) {
                prefix[i] = val;
            } else {
                prefix[i] = (prefix[i - 1] * val) % MOD;
            }
        }

        int q = queries.length;
        int[] answers = new int[q];
        for (int idx = 0; idx < q; idx++) {
            int left = queries[idx][0];
            int right = queries[idx][1];
            long prod;
            if (left == 0) {
                prod = prefix[right];
            } else {
                prod = (prefix[right] * modInv(prefix[left - 1])) % MOD;
            }
            answers[idx] = (int) prod;
        }

        return answers;
    }
}

