    public int[] productQueries(int n, int[][] queries) {
        // Build the powers array (sorted in non‑decreasing order)
        List<Long> powers = new ArrayList<>();
        int pos = 0;
        int temp = n;
        while (temp > 0) {
            if ((temp & 1) == 1) {
                powers.add(1L << pos);
            }
            temp >>= 1;
            pos++;
        }

        int m = powers.size();
        long[] prefix = new long[m + 1];
        prefix[0] = 1L;
        for (int i = 0; i < m; i++) {
            prefix[i + 1] = (prefix[i] * (powers.get(i) % MOD)) % MOD;
        }

        int q = queries.length;
        int[] answers = new int[q];
        for (int i = 0; i < q; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            long prod = prefix[right + 1];
            long inv = modPow(prefix[left], MOD - 2);
            prod = (prod * inv) % MOD;
            answers[i] = (int) prod;
        }
        return answers;
    }

    private static long modPow(long base, long exp) {
        long result = 1L;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1L) == 1L) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            e >>= 1;
        }
        return result;
    }
}

