public class Solution {
    /**
     * Returns all words from {@code queries} that can be transformed into a word from {@code dictionary}
     * with at most two character edits (Hamming distance ≤ 2). The order of the returned list follows
     * the original order of {@code queries}.
     *
     * @param queries    array of query words (all same length)
     * @param dictionary array of dictionary words (all same length)
     * @return list of matching query words
     */
    public List<String> findWords(String[] queries, String[] dictionary) {
        List<String> result = new ArrayList<>();
        if (queries == null || dictionary == null) {
            return result;
        }

        for (String query : queries) {
            if (matchesDictionary(query, dictionary)) {
                result.add(query);
            }
        }
        return result;
    }

    /**
     * Checks whether the given query word matches any word in the dictionary with at most two edits.
     *
     * @param query      the query word
     * @param dictionary the dictionary array
     * @return true if a match exists, false otherwise
     */
    private boolean matchesDictionary(String query, String[] dictionary) {
        for (String dictWord : dictionary) {
            if (hammingDistanceAtMostTwo(query, dictWord)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Determines if the Hamming distance between two equal‑length strings is ≤ 2.
     * The method stops early as soon as more than two mismatches are found.
     *
     * @param a first string
     * @param b second string
     * @return true if distance ≤ 2, false otherwise
     */
    private boolean hammingDistanceAtMostTwo(String a, String b) {
        int mismatches = 0;
        int len = a.length(); // both strings have the same length by problem statement
        for (int i = 0; i < len; i++) {
            if (a.charAt(i) != b.charAt(i)) {
                mismatches++;
                if (mismatches > 2) {
                    return false;
                }
            }
        }
        return true;
    }
}

