import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Solution {
    public long minimumMoney(int[][] transactions) {
        List<int[]> gain = new ArrayList<>();
        List<int[]> loss = new ArrayList<>();

        for (int[] t : transactions) {
            if (t[1] >= t[0]) {
                gain.add(t);
            } else {
                loss.add(t);
            }
        }

        // Gain transactions: sort by cost ascending
        gain.sort(Comparator.comparingInt(a -> a[0]));
        long needGain = 0;
        for (int[] t : gain) {
            needGain = Math.max(needGain, t[0]);
        }

        // Loss transactions: sort by cashback descending
        loss.sort((a, b) -> Integer.compare(b[1], a[1]));
        long needLoss = 0;
        long cur = 0;
        for (int[] t : loss) {
            int cost = t[0];
            int cash = t[1];
            needLoss = Math.max(needLoss, cost - cur);
            cur = cur - cost + cash;
        }

        return Math.max(needGain, needLoss);
    }
}

