                gain.add(t);
            } else {
                loss.add(t);
            }
        }

        long needFromGain = 0;
        for (int[] g : gain) {
            needFromGain = Math.max(needFromGain, (long) g[0]);
        }

        // sort loss transactions by (cost - cashback) descending
        Collections.sort(loss, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                int diffA = a[0] - a[1];
                int diffB = b[0] - b[1];
                return Integer.compare(diffB, diffA);
            }
        });

        long cur = 0; // net change after processed loss transactions
        long needFromLoss = 0;
        for (int[] t : loss) {
            long cost = t[0];
            long cashback = t[1];
            needFromLoss = Math.max(needFromLoss, cost - cur);
            cur += cashback - cost; // this is negative or zero
        }

        return Math.max(needFromGain, needFromLoss);
    }
}

