public class Solution {
    public long minimumMoney(int[][] transactions) {
        long totalLoss = 0L;
        int maxCashbackLoss = 0;          // max cashback among transactions with positive loss
        int maxCostGainOrZero = 0;        // max cost among transactions with non‑positive loss

        for (int[] t : transactions) {
            int cost = t[0];
            int cashback = t[1];
            int loss = cost - cashback;
            if (loss > 0) {
                totalLoss += loss;
                if (cashback > maxCashbackLoss) {
                    maxCashbackLoss = cashback;
                }
            } else {
                if (cost > maxCostGainOrZero) {
                    maxCostGainOrZero = cost;
                }
            }
        }

        long extra = Math.max(maxCashbackLoss, maxCostGainOrZero);
        return totalLoss + extra;
    }
}

