public class Solution {
    public long minimumMoney(int[][] transactions) {
        List<int[]> loss = new ArrayList<>();
        List<int[]> profit = new ArrayList<>();

        for (int[] t : transactions) {
            if (t[0] > t[1]) {
                loss.add(t);
            } else {
                profit.add(t);
            }
        }

        // Loss transactions: larger net loss first
        Collections.sort(loss, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                int diffA = a[0] - a[1];
                int diffB = b[0] - b[1];
                return Integer.compare(diffB, diffA); // descending
            }
        });

        // Profit transactions: smaller cost first
        Collections.sort(profit, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                return Integer.compare(a[0], b[0]); // ascending cost
            }
        });

        long extraNeeded = 0; // total initial money required
        long current = 0;     // money after using the extraNeeded

        for (int[] t : loss) {
            int cost = t[0];
            int cash = t[1];
            extraNeeded = Math.max(extraNeeded, current + cost);
            current = current - cost + cash;
        }

        for (int[] t : profit) {
            int cost = t[0];
            int cash = t[1];
            extraNeeded = Math.max(extraNeeded, current + cost);
            current = current - cost + cash;
        }

        return extraNeeded;
    }
}

