public class Solution {
    public boolean equalFrequency(String word) {
        int[] freq = new int[26];
        for (int i = 0; i < word.length(); i++) {
            freq[word.charAt(i) - 'a']++;
        }

        for (int i = 0; i < 26; i++) {
            if (freq[i] == 0) continue;

            // remove one occurrence of character i
            freq[i]--;

            int target = -1;
            boolean ok = true;
            for (int j = 0; j < 26; j++) {
                if (freq[j] == 0) continue;
                if (target == -1) {
                    target = freq[j];
                } else if (freq[j] != target) {
                    ok = false;
                    break;
                }
            }

            // if all frequencies are zero after removal, it's not a valid case
            if (target == -1) ok = false;

            // restore frequency for next iteration
            freq[i]++;

            if (ok) return true;
        }

        return false;
    }
}

