public class Solution {
    public boolean equalFrequency(String word) {
        int[] cnt = new int[26];
        for (char c : word.toCharArray()) {
            cnt[c - 'a']++;
        }

        // Try removing one occurrence from each possible character
        for (int i = 0; i < 26; i++) {
            if (cnt[i] == 0) continue;

            cnt[i]--; // remove one occurrence

            if (allFrequenciesEqual(cnt)) {
                cnt[i]++; // restore before returning
                return true;
            }

            cnt[i]++; // restore for next iteration
        }
        return false;
    }

    private boolean allFrequenciesEqual(int[] cnt) {
        Set<Integer> freqSet = new HashSet<>();
        for (int f : cnt) {
            if (f > 0) {
                freqSet.add(f);
                if (freqSet.size() > 1) {
                    return false;
                }
            }
        }
        // freqSet.size() can be 0 (empty string) or 1 (all equal)
        return true;
    }
}

