public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countPalindromes(String s) {
        int n = s.length();
        int[][] rightPair = new int[n][100]; // flatten 10x10 as idx = a*10 + b
        int[] suffixCount = new int[10];
        int[][] suffixPair = new int[10][10];

        // Build suffix structures
        for (int i = n - 1; i >= 0; i--) {
            // store current suffix pair counts for position i
            for (int a = 0; a < 10; a++) {
                for (int b = 0; b < 10; b++) {
                    rightPair[i][a * 10 + b] = suffixPair[a][b];
                }
            }
            int cur = s.charAt(i) - '0';
            // update suffix pairs with current character as second element
            for (int d = 0; d < 10; d++) {
                suffixPair[d][cur] = (int) ((suffixPair[d][cur] + suffixCount[d]) % MOD);
            }
            suffixCount[cur] = (suffixCount[cur] + 1) % MOD;
        }

        int[] leftCount = new int[10];
        int[][] leftPair = new int[10][10];
        long ans = 0L;

        for (int k = 0; k < n; k++) {
            // combine left pairs with right pairs for this middle position
            for (int a = 0; a < 10; a++) {
                for (int b = 0; b < 10; b++) {
                    long leftWays = leftPair[a][b];
                    long rightWays = rightPair[k][b * 10 + a];
                    ans = (ans + leftWays * rightWays) % MOD;
                }
            }

            int cur = s.charAt(k) - '0';
            // update left pairs with current character as second element
            for (int d = 0; d < 10; d++) {
                leftPair[d][cur] = (int) ((leftPair[d][cur] + leftCount[d]) % MOD);
            }
            leftCount[cur] = (leftCount[cur] + 1) % MOD;
        }

        return (int) ans;
    }
}

