public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countPalindromes(String s) {
        int n = s.length();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = s.charAt(i) - '0';
        }

        // suffixCount[i][d] = count of digit d in substring i..n-1
        int[][] suffixCount = new int[n + 1][10];
        // suffixPair[i][b][a] = number of ordered pairs (first digit b, second digit a) inside substring i..n-1
        int[][][] suffixPair = new int[n + 1][10][10];

        // Build suffix structures
        for (int i = n - 1; i >= 0; i--) {
            // copy from i+1
            System.arraycopy(suffixCount[i + 1], 0, suffixCount[i], 0, 10);
            for (int b = 0; b < 10; b++) {
                System.arraycopy(suffixPair[i + 1][b], 0, suffixPair[i][b], 0, 10);
            }

            int digit = arr[i];
            // add pairs where first = digit, second = a (a appears after i)
            for (int a = 0; a < 10; a++) {
                int val = suffixPair[i][digit][a] + suffixCount[i + 1][a];
                if (val >= MOD) val -= MOD;
                suffixPair[i][digit][a] = val;
            }
            // increase count of digit
            suffixCount[i][digit] = (suffixCount[i][digit] + 1) % MOD;
        }

        // left side structures
        int[] leftCount = new int[10];
        int[][] leftPair = new int[10][10];

        long answer = 0L;

        for (int i = 0; i < n; i++) {
            // use suffix structures for positions > i
            int[][] rightPair = suffixPair[i + 1];

            // accumulate contributions
            for (int a = 0; a < 10; a++) {
                for (int b = 0; b < 10; b++) {
                    long left = leftPair[a][b];
                    long right = rightPair[b][a];
                    if (left != 0 && right != 0) {
                        answer += (left * right) % MOD;
                        if (answer >= MOD) answer -= MOD;
                    }
                }
            }

            // update left structures with current digit
            int d = arr[i];
            for (int a = 0; a < 10; a++) {
                int val = leftPair[a][d] + leftCount[a];
                if (val >= MOD) val -= MOD;
                leftPair[a][d] = val;
            }
            leftCount[d] = (leftCount[d] + 1) % MOD;
