public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countPalindromes(String s) {
        int n = s.length();
        if (n == 0) return 0;

        int[][] next = new int[n][10];
        int[][] prev = new int[n][10];

        // Build next occurrence array
        int[] nextPos = new int[10];
        for (int d = 0; d < 10; d++) nextPos[d] = n; // sentinel for "not found"
        for (int i = n - 1; i >= 0; i--) {
            System.arraycopy(nextPos, 0, next[i], 0, 10);
            int digit = s.charAt(i) - '0';
            nextPos[digit] = i;
        }

        // Build previous occurrence array
        int[] prevPos = new int[10];
        for (int d = 0; d < 10; d++) prevPos[d] = -1; // sentinel for "not found"
        for (int i = 0; i < n; i++) {
            System.arraycopy(prevPos, 0, prev[i], 0, 10);
            int digit = s.charAt(i) - '0';
            prevPos[digit] = i;
        }

        long[][] dp = new long[n][n];

        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1; // single character palindrome
            for (int j = i + 1; j < n; j++) {
                if (s.charAt(i) != s.charAt(j)) {
                    dp[i][j] = dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1];
                } else {
                    int c = s.charAt(i) - '0';
                    int low = (i + 1 < n) ? next[i + 1][c] : n;
                    int high = (j - 1 >= 0) ? prev[j - 1][c] : -1;

                    if (low > high) { // no same character inside
                        dp[i][j] = dp[i + 1][j - 1] * 2 + 2;
                    } else if (low == high) { // exactly one same character inside
                        dp[i][j] = dp[i + 1][j - 1] * 2 + 1;
                    } else { // at least two same characters inside
                        dp[i][j] = dp[i + 1][j - 1] * 2 - dp[low + 1][high - 1];
                    }
                }
                dp[i][j] %= MOD;
                if (dp[i][j] < 0) dp[i][j] += MOD;
            }
        }

        return (int) dp[0][n - 1];
    }
}

