public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countPalindromes(String s) {
        int n = s.length();
        int[][] suffixCount = new int[n + 1][10];
        // Build suffix counts
        for (int i = n - 1; i >= 0; i--) {
            System.arraycopy(suffixCount[i + 1], 0, suffixCount[i], 0, 10);
            int d = s.charAt(i) - '0';
            suffixCount[i][d]++;
        }

        // Build suffix pair counts: suffixPairs[i][a][b] = #pairs (l,m) with l>=i, m>l, s[l]=b, s[m]=a
        int[][][] suffixPairs = new int[n + 1][10][10];
        // suffixPairs[n] is already zero
        for (int i = n - 1; i >= 0; i--) {
            // copy from i+1
            for (int a = 0; a < 10; a++) {
                System.arraycopy(suffixPairs[i + 1][a], 0, suffixPairs[i][a], 0, 10);
            }
            int b = s.charAt(i) - '0';
            // add pairs where l == i
            for (int a = 0; a < 10; a++) {
                int add = suffixCount[i + 1][a]; // count of digit a after position i
                if (add != 0) {
                    suffixPairs[i][a][b] = (int) ((suffixPairs[i][a][b] + (long) add) % MOD);
                }
            }
        }

        int[] leftCount = new int[10];
        int[][] leftPairs = new int[10][10];
        long ans = 0;

        for (int k = 0; k < n; k++) {
            // contribution from middle position k
            for (int a = 0; a < 10; a++) {
                for (int b = 0; b < 10; b++) {
                    long left = leftPairs[a][b];
                    long right = suffixPairs[k + 1][a][b];
                    if (left != 0 && right != 0) {
                        ans += (left * right) % MOD;
                        if (ans >= MOD) ans -= MOD;
                    }
                }
            }

            // update left structures with s[k]
            int d = s.charAt(k) - '0';
            for (int a = 0; a < 10; a++) {
                if (leftCount[a] != 0) {
                    leftPairs[a][d] = (int) ((leftPairs[a][d] + (long) leftCount[a]) % MOD);
                }
            }
            leftCount[d]++;
        }

        return (int) (ans % MOD);
    }
}

