public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countPalindromes(String s) {
        int n = s.length();
        if (n == 0) return 0;
        int[][] dp = new int[n][n];
        int[][] next = new int[n + 1][10];
        int[][] prev = new int[n][10];

        // Initialize next array
        for (int c = 0; c < 10; c++) {
            next[n][c] = n;
        }
        for (int i = n - 1; i >= 0; i--) {
            for (int c = 0; c < 10; c++) {
                next[i][c] = next[i + 1][c];
            }
            int digit = s.charAt(i) - '0';
            next[i][digit] = i;
        }

        // Initialize prev array
        for (int c = 0; c < 10; c++) {
            prev[0][c] = -1;
        }
        for (int i = 0; i < n; i++) {
            if (i > 0) {
                for (int c = 0; c < 10; c++) {
                    prev[i][c] = prev[i - 1][c];
                }
            }
            int digit = s.charAt(i) - '0';
            prev[i][digit] = i;
        }

        // Base case: length 1
        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
        }

        // Fill DP for lengths >= 2
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j)) {
                    int c = s.charAt(i) - '0';
                    int low = (i + 1 <= j) ? next[i + 1][c] : n;
                    int high = (i <= j - 1) ? prev[j - 1][c] : -1;

                    if (low > high) { // no same character inside
                        dp[i][j] = (int) ((2L * dp[i + 1][j - 1] + 2) % MOD);
                    } else if (low == high) { // exactly one same character inside
                        dp[i][j] = (int) ((2L * dp[i + 1][j - 1] + 1) % MOD);
                    } else { // at least two same characters inside
                        int inner = (low + 1 <= high - 1) ? dp[low + 1][high - 1] : 0;
                        dp[i][j] = (int) ((2L * dp[i + 1][j - 1] - inner) % MOD);
                        if (dp[i][j] < 0) dp[i][j] += MOD;
                    }
                } else {
                    dp[i][j] = (int) ((dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1]) % MOD);
                    if (dp[i][j] < 0) dp[i][j] += MOD;
                }
            }
        }

        return dp[0][n - 1];
    }
}

