public class Solution {
    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        // minimal suffix length is "<1/1>" = 5
        if (limit < 5) {
            return new String[0];
        }
        // try possible total parts b from 1 up to n (cannot need more parts than characters)
        for (int b = 1; b <= n; b++) {
            int digitsB = digits(b);
            // each part must have non‑negative content length:
            // limit >= 2*digitsB + 3  (so that even the longest index fits)
            if (limit < 2 * digitsB + 3) {
                continue;
            }
            int base = limit - digitsB - 3; // limit - digits(b) - 3
            // sum of digits from 1 to x
            long sumDigitsPrev = sumDigits(b - 1);
            long sumPrev = (long) (b - 1) * base - sumDigitsPrev; // characters needed for first b‑1 parts
            if (sumPrev < 0) {
                continue;
            }
            long sumDigitsAll = sumDigits(b);
            long total = (long) b * base - sumDigitsAll; // max characters we can place in all parts
            if (sumPrev <= n && n <= total) {
                // construct the answer
                String[] res = new String[b];
                int idx = 0;
                for (int i = 1; i <= b; i++) {
                    int contentLen = base - digits(i);
                    int take;
                    if (i < b) {
                        take = contentLen;
                    } else {
                        take = n - idx; // remaining characters for the last part
                    }
                    String part = message.substring(idx, idx + take) + "<" + i + "/" + b + ">";
                    res[i - 1] = part;
                    idx += take;
                }
                return res;
            }
        }
        return new String[0];
    }

    // number of decimal digits of x (x >= 1)
    private int digits(int x) {
        int cnt = 0;
        while (x > 0) {
            cnt++;
            x /= 10;
        }
        return cnt;
    }

    // sum_{i=1}^{x} digits(i)
    private long sumDigits(int x) {
        if (x <= 0) return 0L;
        long sum = 0L;
        int len = digits(x);
        int pow10 = 1;
        for (int d = 1; d < len; d++) {
            int cnt = 9 * pow10;
            sum += (long) cnt * d;
            pow10 *= 10;
        }
        // numbers with the maximal length
        int remaining = x - pow10 + 1;
        sum += (long) remaining * len;
        return sum;
    }
}

