import java.util.ArrayList;
import java.util.List;

public class Solution {
    public String[] splitMessage(String message, int limit) {
        if (message == null) return new String[0];
        int n = message.length();

        // minimal suffix length for any part is 5 ("<1/1>")
        if (limit < 5) return new String[0];

        // check if it fits in a single part
        int suffixOne = suffixLength(1, 1);
        if (n + suffixOne <= limit) {
            String part = message + "<1/1>";
            return new String[]{part};
        }

        // binary search for minimal b
        int left = 2, right = n; // at most n parts (one char each)
        int answer = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (canSplit(message, limit, mid)) {
                answer = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        if (answer == -1) return new String[0];

        return buildParts(message, limit, answer);
    }

    private boolean canSplit(String message, int limit, int b) {
        int digitsB = digits(b);
        // suffix for any part must fit
        if (limit < 2 * digitsB + 3) return false;

        long sumDigits = sumDigits(b - 1);
        long totalPrev = (long) (b - 1) * (limit - digitsB - 3) - sumDigits;
        if (totalPrev < 0) return false; // not enough room for previous parts

        long remaining = message.length() - totalPrev;
        if (remaining < 0) return false; // message shorter than required for previous parts

        int lastCap = limit - (2 * digitsB + 3);
        return remaining <= lastCap;
    }

    private String[] buildParts(String message, int limit, int b) {
        List<String> parts = new ArrayList<>(b);
        int pos = 0;
        for (int i = 1; i <= b; i++) {
            String suffix = "<" + i + "/" + b + ">";
            int cap = limit - suffix.length();
            int take;
            if (i == b) {
                take = Math.min(message.length() - pos, cap);
            } else {
                take = cap;
            }
            String part = message.substring(pos, pos + take) + suffix;
            parts.add(part);
            pos += take;
        }
        return parts.toArray(new String[0]);
    }

    private int suffixLength(int a, int b) {
        return digits(a) + digits(b) + 3;
    }

    private int digits(int x) {
        // x > 0
        int cnt = 0;
        while (x > 0) {
            cnt++;
            x /= 10;
        }
        return cnt;
    }

    private long sumDigits(int n) {
        // sum of number of decimal digits for all numbers from 1 to n
        long sum = 0;
        long start = 1;
        int len = 1;
        while (start <= n) {
            long end = Math.min(n, start * 10 - 1);
            sum += (end - start + 1) * len;
            start *= 10;
            len++;
        }
        return sum;
    }
}

