        long total = 0;
        for (int i = 1; i <= parts; i++) {
            int cap = limit - suffixLen(i, parts);
            if (cap < 0) {
                return false;
            }
            total += cap;
            if (total >= message.length()) {
                return true;
            }
        }
        return total >= message.length();
    }

    private String[] buildParts(String message, int limit, int parts) {
        String[] res = new String[parts];
        int idx = 0;
        for (int i = 1; i <= parts; i++) {
