            int remaining = message.length() - idx;
            int take = Math.min(cap, remaining);
            String partContent = message.substring(idx, idx + take);
            idx += take;
            String suffix = "<" + i + "/" + parts + ">";
            res[i - 1] = partContent + suffix;
        }
        return res;
    }

