import java.util.HashSet;
import java.util.Set;

public class Solution {
    public long maximumSubarraySum(int[] nums, int k) {
        if (nums == null || k <= 0 || k > nums.length) {
            return 0L;
        }
        Set<Integer> set = new HashSet<>();
        long sum = 0;
        long max = 0;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            // Ensure all elements in the window are distinct
            while (set.contains(nums[right])) {
                set.remove(nums[left]);
                sum -= nums[left];
                left++;
            }
            set.add(nums[right]);
            sum += nums[right];

            // When window size reaches k, evaluate and slide forward
            if (right - left + 1 == k) {
                if (sum > max) {
                    max = sum;
                }
                // Move left to keep the window size for the next iteration
                set.remove(nums[left]);
                sum -= nums[left];
                left++;
            }
        }
        return max;
    }
}

