public class Solution {
    public long maximumSubarraySum(int[] nums, int k) {
        if (nums == null || nums.length < k) {
            return -1L;
        }

        Set<Integer> window = new HashSet<>();
        long currentSum = 0L;
        long maxSum = Long.MIN_VALUE;
        int left = 0;

        for (int right = 0; right < nums.length; right++) {
            int val = nums[right];

            // If duplicate, shrink from left until it is removed
            while (window.contains(val)) {
                int leftVal = nums[left];
                window.remove(leftVal);
                currentSum -= leftVal;
                left++;
            }

            // Add current element
            window.add(val);
            currentSum += val;

            // When window size reaches k, evaluate and slide forward
            if (right - left + 1 == k) {
                // All elements are distinct by construction
                if (currentSum > maxSum) {
                    maxSum = currentSum;
                }
                // Move left pointer to prepare for next window
                int leftVal = nums[left];
                window.remove(leftVal);
                currentSum -= leftVal;
                left++;
            }
        }

        return maxSum == Long.MIN_VALUE ? -1L : maxSum;
    }
