                if (lcm > k) {
                    break;
                }
                if (k % lcm != 0) {
                    break;
                }
                if (lcm == k) {
                    count++;
                }
            }
        }
        return count;
    }

    private long lcm(long a, long b) {
        if (a == 0 || b == 0) return 0;
        long g = gcd(a, b);
        // To avoid overflow, check before multiplication
        long div = a / g;
        if (div > Long.MAX_VALUE / b) {
            return Long.MAX_VALUE;
        }
        return div * b;
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            long tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

