import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public String robotWithString(String s) {
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++) {
            freq[s.charAt(i) - 'a']++;
        }

        Deque<Character> stack = new ArrayDeque<>();
        StringBuilder result = new StringBuilder();

        int idx = 0; // index in s
        while (idx < s.length() || !stack.isEmpty()) {
            // Push next character from s if any
            if (idx < s.length()) {
                char c = s.charAt(idx++);
                stack.push(c);
                freq[c - 'a']--;
            }

            // Determine the smallest remaining character in s
            char smallest = '{'; // char after 'z'
            for (int i = 0; i < 26; i++) {
                if (freq[i] > 0) {
                    smallest = (char) (i + 'a');
                    break;
                }
            }

            // Pop from stack while top <= smallest
            while (!stack.isEmpty() && (smallest == '{' || stack.peek() <= smallest)) {
                result.append(stack.pop());
            }
        }

        return result.toString();
    }
}

