public class Solution {
    public String robotWithString(String s) {
        int n = s.length();
        if (n == 0) {
            return "";
        }

        char[] suffixMin = new char[n];
        suffixMin[n - 1] = s.charAt(n - 1);
        for (int i = n - 2; i >= 0; i--) {
            suffixMin[i] = (char) Math.min(s.charAt(i), suffixMin[i + 1]);
        }

        StringBuilder result = new StringBuilder();
        Deque<Character> stack = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            stack.push(s.charAt(i));
            char nextMin = (i + 1 < n) ? suffixMin[i + 1] : 0; // 0 is smaller than any lowercase letter
            while (!stack.isEmpty() && (i + 1 == n || stack.peek() <= nextMin)) {
                result.append(stack.pop());
            }
        }

        return result.toString();
    }
}

