public class Solution {
    public ListNode removeNodes(ListNode head) {
        if (head == null) {
            return null;
        }

        // Reverse the linked list
        ListNode prev = null;
        ListNode curr = head;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        ListNode reversedHead = prev;

        // Remove nodes that are smaller than the maximum seen so far
        ListNode node = reversedHead;
        int max = node.val;
        while (node != null && node.next != null) {
            if (node.next.val < max) {
                node.next = node.next.next;
            } else {
                node = node.next;
                max = node.val;
            }
        }

        // Reverse again to restore original order
        prev = null;
        curr = reversedHead;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }

        return prev;
    }
}

