        ListNode reversed = reverse(head);
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        int max = Integer.MIN_VALUE;

        // Keep nodes that are >= current max (i.e., no greater value to their right in original list)
        while (reversed != null) {
            if (reversed.val >= max) {
                max = reversed.val;
                tail.next = reversed;
                tail = reversed;
            }
            reversed = reversed.next;
        }
        // Terminate the filtered list
        tail.next = null;

        // Reverse again to restore original order
        return reverse(dummy.next);
    }

