        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        int min = Integer.MAX_VALUE;

        // Make all numbers even and find initial minimum
        for (int num : nums) {
            if ((num & 1) == 1) { // odd
                num <<= 1; // multiply by 2
            }
            maxHeap.offer(num);
            if (num < min) {
                min = num;
            }
        }

        int answer = Integer.MAX_VALUE;

        while (true) {
            int currentMax = maxHeap.poll();
            answer = Math.min(answer, currentMax - min);

            // If the current maximum is odd, we cannot reduce it further
            if ((currentMax & 1) == 1) {
                break;
            }

            // Reduce the maximum by dividing by 2
            int reduced = currentMax >> 1;
            min = Math.min(min, reduced);
            maxHeap.offer(reduced);
        }

        return answer;
    }
}

