import java.util.*;

public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        // Build adjacency list for left side (indices of nums1) to right side (indices of nums2)
        List<Integer>[] adj = new List[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (nums1[i] != nums2[j]) {
                    adj[i].add(j);
                }
            }
        }

        // Hopcroft‑Karp for maximum bipartite matching
        int[] pairU = new int[n]; // match for left vertices, -1 if free
        int[] pairV = new int[n]; // match for right vertices, -1 if free
        int[] dist = new int[n];
        Arrays.fill(pairU, -1);
        Arrays.fill(pairV, -1);

        int matching = 0;
        while (bfs(adj, pairU, pairV, dist)) {
            for (int u = 0; u < n; u++) {
                if (pairU[u] == -1) {
                    if (dfs(u, adj, pairU, pairV, dist)) {
                        matching++;
                    }
                }
            }
        }

        if (matching != n) {
            return -1L;
        }
        // Minimum possible total cost equals sum of all indices (0 + 1 + ... + n-1)
        return (long) n * (n - 1) / 2;
    }

    private boolean bfs(List<Integer>[] adj, int[] pairU, int[] pairV, int[] dist) {
        Queue<Integer> queue = new ArrayDeque<>();
        for (int u = 0; u < adj.length; u++) {
            if (pairU[u] == -1) {
                dist[u] = 0;
                queue.offer(u);
            } else {
                dist[u] = -1;
            }
        }
        boolean foundFree = false;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj[u]) {
                int pu = pairV[v];
                if (pu != -1 && dist[pu] == -1) {
                    dist[pu] = dist[u] + 1;
                    queue.offer(pu);
                }
                if (pu == -1) {
                    foundFree = true;
                }
            }
        }
        return foundFree;
    }

    private boolean dfs(int u, List<Integer>[] adj, int[] pairU, int[] pairV, int[] dist) {
        for (int v : adj[u]) {
            int pu = pairV[v];
            if (pu == -1 || (dist[pu] == dist[u] + 1 && dfs(pu, adj, pairU, pairV, dist))) {
                pairU[u] = v;
                pairV[v] = u;
                return true;
            }
        }
        dist[u] = -1;
        return false;
    }
}

