import java.util.*;

public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        List<Integer> badIndices = new ArrayList<>();
        long sumBad = 0L;
        Map<Integer, Integer> freq = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) {
                badIndices.add(i);
                sumBad += i;
                freq.merge(nums2[i], 1, Integer::sum);
            }
        }
        int badCount = badIndices.size();
        if (badCount == 0) {
            return 0L;
        }
        // Find value with maximum frequency among bad positions
        int maxFreq = 0;
        int maxVal = 0;
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            if (e.getValue() > maxFreq) {
                maxFreq = e.getValue();
                maxVal = e.getKey();
            }
        }
        // If we can pair all bad positions among themselves
        if (maxFreq <= badCount / 2) {
            return sumBad;
        }
        // Need to use some good positions
        int excess = 2 * maxFreq - badCount; // number of bad positions to resolve with good ones
        List<Integer> goodCandidates = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums1[i] != nums2[i]) {
                // good position, check compatibility with maxVal
                if (nums1[i] != maxVal && nums2[i] != maxVal) {
                    goodCandidates.add(i);
                }
            }
        }
        if (goodCandidates.size() < excess) {
            return -1L;
        }
        Collections.sort(goodCandidates);
        long extra = 0L;
        for (int i = 0; i < excess; i++) {
            extra += goodCandidates.get(i);
        }
        return sumBad + extra;
    }
}

