public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sumConf = 0;
        List<Integer> conflictIndices = new ArrayList<>();
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) {
                conflictIndices.add(i);
                sumConf += i;
                cnt.put(nums2[i], cnt.getOrDefault(nums2[i], 0) + 1);
            }
        }
        int conflictCount = conflictIndices.size();
        if (conflictCount == 0) {
            return 0L;
        }
        // find most frequent value among conflict positions
        int overValue = -1;
        int maxCount = 0;
        for (Map.Entry<Integer, Integer> e : cnt.entrySet()) {
            if (e.getValue() > maxCount) {
                maxCount = e.getValue();
                overValue = e.getKey();
            }
        }
        // if we can pair all conflicts without extra cost
        if (maxCount <= conflictCount / 2) {
            return sumConf;
        }
        // need an extra index to break the surplus of overValue
        int minExtraIdx = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (nums1[i] != overValue && nums2[i] != overValue) {
                minExtraIdx = Math.min(minExtraIdx, i);
            }
        }
        if (minExtraIdx == Integer.MAX_VALUE) {
            return -1L;
        }
        return sumConf + minExtraIdx;
    }
}

