import java.util.*;

public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        // Check if already satisfied
        boolean already = true;
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) {
                already = false;
                break;
            }
        }
        if (already) return 0L;

        // Build frequency map of values in nums1
        Map<Integer, Integer> freq1 = new HashMap<>();
        for (int v : nums1) freq1.put(v, freq1.getOrDefault(v, 0) + 1);

        // Count positions where a particular value is forbidden (nums2)
        Map<Integer, Integer> forbidden = new HashMap<>();
        for (int v : nums2) forbidden.put(v, forbidden.getOrDefault(v, 0) + 1);

        // Feasibility check: for each value, its count must not exceed
        // the number of positions where it is allowed.
        for (Map.Entry<Integer, Integer> e : freq1.entrySet()) {
            int val = e.getKey();
            int cnt = e.getValue();
            int allowed = n - forbidden.getOrDefault(val, 0);
            if (cnt > allowed) return -1L;
        }

        // Positions that are currently bad (nums1[i] == nums2[i])
        List<Integer> bad = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) bad.add(i);
        }

        // If there are no bad positions we already returned 0.
        // We will try to fix bad positions using cheapest possible swaps.
        // The strategy:
        //   - Pair bad positions together when swapping resolves both.
        //   - Otherwise use the smallest index that can act as a buffer.
        // This greedy approach yields the minimal total cost.

        // Prepare a set of indices that can be used as buffers (any index).
        TreeSet<Integer> available = new TreeSet<>();
        for (int i = 0; i < n; i++) available.add(i);

        long totalCost = 0L;
        boolean[] fixed = new boolean[n];
        // Initially mark already good positions as fixed.
        for (int i = 0; i < n; i++) {
            if (nums1[i] != nums2[i]) fixed[i] = true;
        }

        // Helper to check if swapping i and j would fix both positions.
        // It also updates the arrays and fixed flags.
        while (!bad.isEmpty()) {
            int i = bad.remove(bad.size() - 1); // take a bad index
            if (fixed[i]) continue; // may have been fixed already

            // Try to find another bad index j that can be paired.
            Integer partner = null;
            for (int j : bad) {
                if (i == j) continue;
                if (nums1[j] != nums2[i] && nums1[i] != nums2[j]) {
                    partner = j;
                    break;
                }
            }
            if (partner != null) {
                // Perform direct swap i <-> partner
                int j = partner;
                totalCost += i + j;

                // swap values
                int tmp = nums1[i];
                nums1[i] = nums1[j];
                nums1[j] = tmp;

                // mark as fixed if now different
                if (nums1[i] != nums2[i]) fixed[i] = true;
                if (nums1[j] != nums2[j]) fixed[j] = true;

                // remove partner from bad list
                bad.remove((Integer) j);
            } else {
                // Need a buffer index k (could be any index not equal to i)
                // Choose the smallest possible k that after swapping makes i good.
                Integer k = null;
                for (int cand : available) {
                    if (cand == i) continue;
                    if (nums1[cand] != nums2[i]) {
                        k = cand;
                        break;
                    }
                }
                if (k == null) return -1L; // should not happen after feasibility check

                int j = k;
                totalCost += i + j;

                // swap values
                int tmp = nums1[i];
                nums1[i] = nums1[j];
                nums1[j] = tmp;

                // update fixed status
                if (nums1[i] != nums2[i]) fixed[i] = true;
                if (nums1[j] != nums2[j]) fixed[j] = true;

                // if j became bad after the swap, add it to bad list
                if (!fixed[j]) bad.add(j);
            }
        }

        return totalCost;
    }
}

