import java.util.*;

public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        // Overall feasibility check
        Map<Integer, Integer> totalCount = new HashMap<>();
        for (int i = 0; i < n; i++) {
            totalCount.merge(nums1[i], 1, Integer::sum);
            totalCount.merge(nums2[i], 1, Integer::sum);
        }
        for (int cnt : totalCount.values()) {
            if (cnt > n) {
                return -1L;
            }
        }

        List<Integer> bad = new ArrayList<>();
        List<Integer> good = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) {
                bad.add(i);
            } else {
                good.add(i);
            }
        }

        long cost = 0L;
        int size = bad.size();

        Map<Integer, Integer> cnt1 = new HashMap<>();
        Map<Integer, Integer> cnt2 = new HashMap<>();
        int curMax = 0;

        for (int idx : bad) {
            cost += idx;
            int v1 = nums1[idx];
            int v2 = nums2[idx];
            int c1 = cnt1.getOrDefault(v1, 0) + 1;
            cnt1.put(v1, c1);
            int c2 = cnt2.getOrDefault(v2, 0) + 1;
            cnt2.put(v2, c2);
            int sum = c1 + cnt2.getOrDefault(v1, 0);
            curMax = Math.max(curMax, sum);
            sum = cnt1.getOrDefault(v2, 0) + c2;
            curMax = Math.max(curMax, sum);
        }

        // good indices are already in increasing order
        int ptr = 0;
        while (size < curMax) {
            if (ptr >= good.size()) {
                // Should not happen if overall feasibility holds
                return -1L;
            }
            int idx = good.get(ptr++);
            cost += idx;
            size++;

            int v1 = nums1[idx];
            int v2 = nums2[idx];

            int c1 = cnt1.getOrDefault(v1, 0) + 1;
            cnt1.put(v1, c1);
            int sum = c1 + cnt2.getOrDefault(v1, 0);
            curMax = Math.max(curMax, sum);

            int c2 = cnt2.getOrDefault(v2, 0) + 1;
            cnt2.put(v2, c2);
            sum = cnt1.getOrDefault(v2, 0) + c2;
            curMax = Math.max(curMax, sum);
        }

        return cost;
    }
}

package referenz;


import java.util.*;

public class Solution {
    private int m, n, total, maxMask;
    private int[] pow3;
    private int[][][][][] dp;
    private final int[] base = {0, 120, 40};
    private final int[][] delta = new int[3][3];

    public Solution() {
        // interaction values (cur + neighbor)
        delta[1][1] = -60; // intro-intro
        delta[1][2] = -10; // intro-extro
        delta[2][1] = -10; // extro-intro
        delta[2][2] = 40;  // extro-extro
    }

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        this.m = m;
        this.n = n;
        this.total = m * n;
        this.pow3 = new int[n + 1];
        pow3[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow3[i] = pow3[i - 1] * 3;
        }
        this.maxMask = pow3[n];

        dp = new int[total + 1][maxMask][introvertsCount + 1][extrovertsCount + 1][3];
        for (int i = 0; i <= total; i++) {
            for (int j = 0; j < maxMask; j++) {
                for (int a = 0; a <= introvertsCount; a++) {
                    for (int b = 0; b <= extrovertsCount; b++) {
                        Arrays.fill(dp[i][j][a][b], Integer.MIN_VALUE);
                    }
                }
            }
        }

        return dfs(0, 0, introvertsCount, extrovertsCount, 0);
    }

    private int dfs(int pos, int mask, int iLeft, int eLeft, int prev) {
        if (pos == total) {
            return 0;
        }
        if (dp[pos][mask][iLeft][eLeft][prev] != Integer.MIN_VALUE) {
            return dp[pos][mask][iLeft][eLeft][prev];
        }

        int col = pos % n;
        int above = (mask / pow3[col]) % 3;

        int best = 0; // option: leave empty

        // leave empty
        int nextMaskEmpty = mask - above * pow3[col];
        int nextPrevEmpty = (col == n - 1) ? 0 : 0;
        best = Math.max(best, dfs(pos + 1, nextMaskEmpty, iLeft, eLeft, nextPrevEmpty));

        // place introvert
        if (iLeft > 0) {
            int cur = 1;
            int add = base[cur];
            if (above != 0) add += delta[cur][above];
            if (prev != 0) add += delta[cur][prev];
            int nextMask = mask - above * pow3[col] + cur * pow3[col];
            int nextPrev = (col == n - 1) ? 0 : cur;
            best = Math.max(best, add + dfs(pos + 1, nextMask, iLeft - 1, eLeft, nextPrev));
        }

        // place extrovert
        if (eLeft > 0) {
            int cur = 2;
            int add = base[cur];
            if (above != 0) add += delta[cur][above];
            if (prev != 0) add += delta[cur][prev];
            int nextMask = mask - above * pow3[col] + cur * pow3[col];
            int nextPrev = (col == n - 1) ? 0 : cur;
            best = Math.max(best, add + dfs(pos + 1, nextMask, iLeft, eLeft - 1, nextPrev));
        }

        dp[pos][mask][iLeft][eLeft][prev] = best;
        return best;
    }
}

package referenz;


import java.util.*;

public class Solution {
    private static final int EMPTY = 0;
    private static final int INTRO = 1;
    private static final int EXTRO = 2;
    private int m, n;
    private int totalMask;
    private int[] pow3;
    private int[] cntIntro;
    private int[] cntExtro;
    private int[] rowScore;
    private int[][] verticalScore;
    private int[][][] memo; // row, prevMask, introLeft, extroLeft

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        this.m = m;
        this.n = n;
        pow3 = new int[n + 1];
        pow3[0] = 1;
        for (int i = 1; i <= n; i++) pow3[i] = pow3[i - 1] * 3;
        totalMask = pow3[n];

        cntIntro = new int[totalMask];
        cntExtro = new int[totalMask];
        rowScore = new int[totalMask];
        verticalScore = new int[totalMask][totalMask];

        precomputeMasks();
        precomputeVertical();

        // memo dimensions: row (0..m), prevMask (0..totalMask-1), intro left (0..introvertsCount), extro left (0..extrovertsCount)
        memo = new int[m + 1][totalMask][introvertsCount + 1][extrovertsCount + 1];
        for (int[][][] a : memo)
            for (int[][] b : a)
                for (int[] c : b)
                    Arrays.fill(c, Integer.MIN_VALUE);

        return dfs(0, 0, introvertsCount, extrovertsCount);
    }

    private void precomputeMasks() {
        for (int mask = 0; mask < totalMask; mask++) {
            int tmp = mask;
            int[] types = new int[n];
            int intro = 0, extro = 0, score = 0;
            for (int col = 0; col < n; col++) {
                int t = tmp % 3;
                types[col] = t;
                tmp /= 3;
                if (t == INTRO) {
                    intro++;
                    score += 120;
                } else if (t == EXTRO) {
                    extro++;
                    score += 40;
                }
            }
            // horizontal neighbor contributions
            for (int col = 1; col < n; col++) {
                int left = types[col - 1];
                int right = types[col];
                if (left != EMPTY && right != EMPTY) {
                    score += pairContribution(left, right);
                }
            }
            cntIntro[mask] = intro;
            cntExtro[mask] = extro;
            rowScore[mask] = score;
        }
    }

    private void precomputeVertical() {
        for (int prev = 0; prev < totalMask; prev++) {
            int[] prevTypes = decode(prev);
            for (int cur = 0; cur < totalMask; cur++) {
                int[] curTypes = decode(cur);
                int add = 0;
                for (int col = 0; col < n; col++) {
                    int up = prevTypes[col];
                    int down = curTypes[col];
                    if (up != EMPTY && down != EMPTY) {
                        add += pairContribution(up, down);
                    }
                }
                verticalScore[prev][cur] = add;
            }
        }
    }

    private int[] decode(int mask) {
        int[] types = new int[n];
        int tmp = mask;
        for (int i = 0; i < n; i++) {
            types[i] = tmp % 3;
            tmp /= 3;
        }
        return types;
    }

    private int pairContribution(int a, int b) {
        // both are non-empty
        if (a == INTRO && b == INTRO) return -60;          // -30 -30
        if (a == EXTRO && b == EXTRO) return 40;           // +20 +20
        // one intro, one extro
        return -10; // -30 +20
    }

    private int dfs(int row, int prevMask, int introLeft, int extroLeft) {
        if (row == m) return 0;
        if (memo[row][prevMask][introLeft][extroLeft] != Integer.MIN_VALUE) {
            return memo[row][prevMask][introLeft][extroLeft];
        }
        int best = 0; // we can always choose to leave remaining rows empty
        for (int curMask = 0; curMask < totalMask; curMask++) {
            int needIntro = cntIntro[curMask];
            int needExtro = cntExtro[curMask];
            if (needIntro > introLeft || needExtro > extroLeft) continue;
            int curScore = rowScore[curMask] + verticalScore[prevMask][curMask];
            int total = curScore + dfs(row + 1, curMask, introLeft - needIntro, extroLeft - needExtro);
            if (total > best) best = total;
        }
        memo[row][prevMask][introLeft][extroLeft] = best;
        return best;
    }
}

