import java.util.*;

public class Solution {
    private static final int[] POW3 = new int[6]; // up to n=5
    private static final int[] TYPE_BASE_HAPPY = {0, 120, 40}; // index: 0 empty,1 intro,2 extro

    private int effect(int a, int b) {
        // a and b are 1 (intro) or 2 (extro)
        int ha = (a == 1) ? -30 : 20;
        int hb = (b == 1) ? -30 : 20;
        return ha + hb;
    }

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int maxMask = (int) Math.pow(3, n);
        POW3[0] = 1;
        for (int i = 1; i <= n; i++) {
            POW3[i] = POW3[i - 1] * 3;
        }

        int[] introCnt = new int[maxMask];
        int[] extroCnt = new int[maxMask];
        int[] internalHappy = new int[maxMask];

        // pre‑compute per‑row mask data
        for (int mask = 0; mask < maxMask; mask++) {
            int tmp = mask;
            int[] cells = new int[n];
            for (int i = 0; i < n; i++) {
                cells[i] = tmp % 3;
                tmp /= 3;
                if (cells[i] == 1) introCnt[mask]++;
                else if (cells[i] == 2) extroCnt[mask]++;
            }

            int happy = 0;
            // base happiness
            for (int type : cells) {
                happy += TYPE_BASE_HAPPY[type];
            }
            // horizontal neighbor effects
            for (int i = 0; i < n - 1; i++) {
                int a = cells[i];
                int b = cells[i + 1];
                if (a != 0 && b != 0) {
                    happy += effect(a, b);
                }
            }
            internalHappy[mask] = happy;
        }

        // pre‑compute vertical interaction between two masks
        int[][] verticalHappy = new int[maxMask][maxMask];
        for (int up = 0; up < maxMask; up++) {
            for (int down = 0; down < maxMask; down++) {
                int sum = 0;
                for (int col = 0; col < n; col++) {
                    int a = (up / POW3[col]) % 3;
                    int b = (down / POW3[col]) % 3;
                    if (a != 0 && b != 0) {
                        sum += effect(a, b);
                    }
                }
                verticalHappy[up][down] = sum;
            }
        }

        // dp[row][iLeft][eLeft][prevMask] = max happiness
        int INF = Integer.MIN_VALUE / 2;
        int[][][] dpPrev = new int[introvertsCount + 1][extrovertsCount + 1][maxMask];
        int[][][] dpCurr = new int[introvertsCount + 1][extrovertsCount + 1][maxMask];
        for (int i = 0; i <= introvertsCount; i++) {
            for (int e = 0; e <= extrovertsCount; e++) {
                Arrays.fill(dpPrev[i][e], INF);
                Arrays.fill(dpCurr[i][e], INF);
            }
        }
        dpPrev[introvertsCount][extrovertsCount][0] = 0; // start with empty previous row

        for (int row = 0; row < m; row++) {
            // reset current layer
            for (int i = 0; i <= introvertsCount; i++) {
                for (int e = 0; e <= extrovertsCount; e++) {
                    Arrays.fill(dpCurr[i][e], INF);
                }
            }

            for (int iLeft = 0; iLeft <= introvertsCount; iLeft++) {
                for (int eLeft = 0; eLeft <= extrovertsCount; eLeft++) {
                    for (int prevMask = 0; prevMask < maxMask; prevMask++) {
                        int curVal = dpPrev[iLeft][eLeft][prevMask];
                        if (curVal == INF) continue;
                        // try all possible masks for this row
                        for (int curMask = 0; curMask < maxMask; curMask++) {
                            int needIntro = introCnt[curMask];
                            int needExtro = extroCnt[curMask];
                            if (needIntro > iLeft || needExtro > eLeft) continue;
                            int newI = iLeft - needIntro;
                            int newE = eLeft - needExtro;
                            int added = internalHappy[curMask] + verticalHappy[prevMask][curMask];
                            int nextVal = curVal + added;
                            if (nextVal > dpCurr[newI][newE][curMask]) {
                                dpCurr[newI][newE][curMask] = nextVal;
                            }
                        }
                    }
                }
            }

            // swap layers
            int[][][] tmp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = tmp;
        }

        int answer = 0;
        for (int i = 0; i <= introvertsCount; i++) {
            for (int e = 0; e <= extrovertsCount; e++) {
                for (int mask = 0; mask < maxMask; mask++) {
                    answer = Math.max(answer, dpPrev[i][e][mask]);
                }
            }
        }
        return answer;
    }
}

