import java.util.*;

public class Solution {
    private int m, n, total;
    private int[] pow3;
    private int[][][][] dp; // dp[pos][intro][extro][mask]

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        this.m = m;
        this.n = n;
        this.total = m * n;
        pow3 = new int[n + 1];
        pow3[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow3[i] = pow3[i - 1] * 3;
        }
        int maskSize = pow3[n];
        dp = new int[total + 1][introvertsCount + 1][extrovertsCount + 1][maskSize];
        for (int i = 0; i <= total; i++) {
            for (int ii = 0; ii <= introvertsCount; ii++) {
                for (int ee = 0; ee <= extrovertsCount; ee++) {
                    Arrays.fill(dp[i][ii][ee], Integer.MIN_VALUE);
                }
            }
        }
        return dfs(0, introvertsCount, extrovertsCount, 0);
    }

    private int dfs(int pos, int introLeft, int extroLeft, int mask) {
        if (pos == total) {
            return 0;
        }
        if (dp[pos][introLeft][extroLeft][mask] != Integer.MIN_VALUE) {
            return dp[pos][introLeft][extroLeft][mask];
        }

        int row = pos / n;
        int col = pos % n;

        int up = mask / pow3[n - 1];                // most significant digit
        int left = (col == 0) ? 0 : (mask % 3);     // least significant digit, ignored at row start

        int best = dfs(pos + 1, introLeft, extroLeft, (mask % pow3[n - 1]) * 3); // leave empty

        // place introvert
        if (introLeft > 0) {
            int cur = 1;
            int delta = 120;
            if (left != 0) {
                delta += (cur == 1 ? -30 : 20);
                delta += (left == 1 ? -30 : 20);
            }
            if (up != 0) {
                delta += (cur == 1 ? -30 : 20);
                delta += (up == 1 ? -30 : 20);
            }
            int newMask = (mask % pow3[n - 1]) * 3 + cur;
            best = Math.max(best, delta + dfs(pos + 1, introLeft - 1, extroLeft, newMask));
        }

        // place extrovert
        if (extroLeft > 0) {
            int cur = 2;
            int delta = 40;
            if (left != 0) {
                delta += (cur == 1 ? -30 : 20);
                delta += (left == 1 ? -30 : 20);
            }
            if (up != 0) {
                delta += (cur == 1 ? -30 : 20);
                delta += (up == 1 ? -30 : 20);
            }
            int newMask = (mask % pow3[n - 1]) * 3 + cur;
            best = Math.max(best, delta + dfs(pos + 1, introLeft, extroLeft - 1, newMask));
        }

        dp[pos][introLeft][extroLeft][mask] = best;
        return best;
    }
}

package referenz;

import java.util.*;

public class Solution {
    private static final int INTROVERT = 1;
    private static final int EXTROVERT = 2;
    private static final int[] BASE_HAPPINESS = {0, 120, 40};
    private static final int[] EFFECT = {0, -30, 20}; // index by person type

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int cols = n;
        int totalMasks = (int) Math.pow(3, cols);
        int[] introCnt = new int[totalMasks];
        int[] extroCnt = new int[totalMasks];
        int[] rowScore = new int[totalMasks];
        int[][] verticalScore = new int[totalMasks][totalMasks];

        // Pre‑compute counts and row internal scores
        for (int mask = 0; mask < totalMasks; mask++) {
            int tmp = mask;
            int[] cell = new int[cols];
            for (int i = 0; i < cols; i++) {
                cell[i] = tmp % 3;
                tmp /= 3;
                if (cell[i] == INTROVERT) introCnt[mask]++;
                else if (cell[i] == EXTROVERT) extroCnt[mask]++;
            }

            int score = 0;
            // base happiness
            for (int v : cell) {
                score += BASE_HAPPINESS[v];
            }
            // horizontal neighbor contributions
            for (int i = 0; i < cols - 1; i++) {
                int a = cell[i];
                int b = cell[i + 1];
                if (a != 0 && b != 0) {
                    score += pairContribution(a, b);
                }
            }
            rowScore[mask] = score;
        }

        // Pre‑compute vertical contributions between two rows
        for (int prev = 0; prev < totalMasks; prev++) {
            int[] prevCell = decode(prev, cols);
            for (int cur = 0; cur < totalMasks; cur++) {
                int[] curCell = decode(cur, cols);
                int vScore = 0;
                for (int i = 0; i < cols; i++) {
                    int a = prevCell[i];
                    int b = curCell[i];
                    if (a != 0 && b != 0) {
                        vScore += pairContribution(a, b);
                    }
                }
                verticalScore[prev][cur] = vScore;
            }
        }

        int maxI = introvertsCount;
        int maxE = extrovertsCount;
        int INF_NEG = Integer.MIN_VALUE / 4;

        int[][][] dpPrev = new int[totalMasks][maxI + 1][maxE + 1];
        for (int[][] layer : dpPrev) {
            for (int[] row : layer) {
                Arrays.fill(row, INF_NEG);
            }
        }

        // first row (previous mask = 0)
        for (int mask = 0; mask < totalMasks; mask++) {
            int iCnt = introCnt[mask];
            int eCnt = extroCnt[mask];
            if (iCnt <= maxI && eCnt <= maxE) {
                dpPrev[mask][iCnt][eCnt] = rowScore[mask];
            }
        }

        // process remaining rows
        for (int r = 1; r < m; r++) {
            int[][][] dpCurr = new int[totalMasks][maxI + 1][maxE + 1];
            for (int[][] layer : dpCurr) {
                for (int[] row : layer) {
                    Arrays.fill(row, INF_NEG);
                }
            }

            for (int prevMask = 0; prevMask < totalMasks; prevMask++) {
                for (int iUsed = 0; iUsed <= maxI; iUsed++) {
                    for (int eUsed = 0; eUsed <= maxE; eUsed++) {
                        int prevVal = dpPrev[prevMask][iUsed][eUsed];
                        if (prevVal == INF_NEG) continue;
                        for (int curMask = 0; curMask < totalMasks; curMask++) {
                            int addI = introCnt[curMask];
                            int addE = extroCnt[curMask];
                            int newI = iUsed + addI;
                            int newE = eUsed + addE;
                            if (newI > maxI || newE > maxE) continue;
                            int newVal = prevVal + rowScore[curMask] + verticalScore[prevMask][curMask];
                            if (newVal > dpCurr[curMask][newI][newE]) {
                                dpCurr[curMask][newI][newE] = newVal;
                            }
                        }
                    }
                }
            }
            dpPrev = dpCurr;
        }

        int answer = 0;
        for (int mask = 0; mask < totalMasks; mask++) {
            for (int i = 0; i <= maxI; i++) {
                for (int e = 0; e <= maxE; e++) {
                    answer = Math.max(answer, dpPrev[mask][i][e]);
                }
            }
        }
        return answer;
    }

    private static int pairContribution(int a, int b) {
        // total effect of a neighbor b on both persons
        return EFFECT[a] + EFFECT[b];
    }

    private static int[] decode(int mask, int cols) {
        int[] res = new int[cols];
        int tmp = mask;
        for (int i = 0; i < cols; i++) {
            res[i] = tmp % 3;
            tmp /= 3;
        }
        return res;
    }
}

