import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        // prefix of port changes
        int[] portChanges = new int[n + 1];
        portChanges[0] = 0;
        for (int i = 1; i <= n; i++) {
            if (i == 1) {
                portChanges[i] = 0;
            } else {
                portChanges[i] = portChanges[i - 1] +
                        (boxes[i - 1][0] != boxes[i - 2][0] ? 1 : 0);
            }
        }

        int[] dp = new int[n + 1];
        dp[0] = 0;

        Deque<Integer> deque = new ArrayDeque<>();
        deque.addLast(0); // candidate index j = 0

        long curWeight = 0;
        int left = 0; // left pointer of the sliding window (0‑based)

        for (int i = 1; i <= n; i++) {
            // add box i‑1 to the current window
            curWeight += boxes[i - 1][1];

            // shrink window to satisfy constraints
            while (i - left > maxBoxes || curWeight > maxWeight) {
                curWeight -= boxes[left][1];
                left++;
            }

            // remove indices that are out of the window
            while (!deque.isEmpty() && deque.peekFirst() < left) {
                deque.pollFirst();
            }

            // compute dp[i] using the best candidate at the front of deque
            int j = deque.peekFirst();
            dp[i] = 2 + portChanges[i] + (dp[j] - portChanges[j + 1]);

            // prepare candidate for future positions (if not the last box)
            if (i < n) {
                int value = dp[i] - portChanges[i + 1];
                while (!deque.isEmpty()) {
                    int last = deque.peekLast();
                    int lastValue = dp[last] - portChanges[last + 1];
                    if (lastValue >= value) {
                        deque.pollLast();
                    } else {
                        break;
                    }
                }
                deque.addLast(i);
            }
        }

        return dp[n];
    }
}

