import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] port = new int[n + 1];
        int[] weight = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            port[i] = boxes[i - 1][0];
            weight[i] = boxes[i - 1][1];
        }

        int[] diff = new int[n + 1]; // cumulative port changes
        for (int i = 2; i <= n; i++) {
            diff[i] = diff[i - 1] + (port[i] != port[i - 1] ? 1 : 0);
        }

        int[] dp = new int[n + 1];
        dp[0] = 0;

        Deque<Integer> deque = new ArrayDeque<>();
        int left = 1;
        long curWeight = 0;

        for (int i = 1; i <= n; i++) {
            curWeight += weight[i];

            while (i - left + 1 > maxBoxes || curWeight > maxWeight) {
                curWeight -= weight[left];
                if (!deque.isEmpty() && deque.peekFirst() == left) {
                    deque.pollFirst();
                }
                left++;
            }

            // candidate start index j = i
            int candidateVal = dp[i - 1] - diff[i];
            while (!deque.isEmpty()) {
                int lastIdx = deque.peekLast();
                int lastVal = dp[lastIdx - 1] - diff[lastIdx];
                if (lastVal <= candidateVal) {
                    break;
                }
                deque.pollLast();
            }
            deque.addLast(i);

            // best candidate within window
            int bestIdx = deque.peekFirst();
            dp[i] = diff[i] + 1 + (dp[bestIdx - 1] - diff[bestIdx]);
        }

        return dp[n];
    }
}

