public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] weightPrefix = new int[n + 1];
        int[] portChanges = new int[n + 1];
        // prefix sums for weight and number of port changes
        for (int i = 1; i <= n; i++) {
            weightPrefix[i] = weightPrefix[i - 1] + boxes[i - 1][1];
            if (i == 1) {
                portChanges[i] = 0;
            } else {
                portChanges[i] = portChanges[i - 1] + (boxes[i - 1][0] == boxes[i - 2][0] ? 0 : 1);
            }
        }

        int[] dp = new int[n + 1];
        dp[0] = 0;

        Deque<Integer> deque = new ArrayDeque<>();
        int left = 0;
        for (int i = 1; i <= n; i++) {
            // shrink window to satisfy constraints
            while (i - left > maxBoxes || weightPrefix[i] - weightPrefix[left] > maxWeight) {
                left++;
            }
            // remove indices that are out of the current window
            while (!deque.isEmpty() && deque.peekFirst() < left) {
                deque.pollFirst();
            }

            // maintain monotonicity of (dp[j] - portChanges[j])
            int candidate = i - 1;
            while (!deque.isEmpty() &&
                    (dp[deque.peekLast()] - portChanges[deque.peekLast()]) >= (dp[candidate] - portChanges[candidate])) {
                deque.pollLast();
            }
            deque.offerLast(candidate);

            int bestIdx = deque.peekFirst();
            dp[i] = dp[bestIdx] + (portChanges[i] - portChanges[bestIdx]) + 1;
        }

        return dp[n];
    }
}

