        int[] weight = new int[n];
        for (int i = 0; i < n; i++) {
            port[i] = boxes[i][0];
            weight[i] = boxes[i][1];
        }

        // prefix sums of weight
        int[] preWeight = new int[n + 1];
        // prefix count of port changes (cnt)
        int[] cnt = new int[n + 2]; // extra element for cnt[n+1]
        for (int i = 1; i <= n; i++) {
            preWeight[i] = preWeight[i - 1] + weight[i - 1];
            cnt[i] = cnt[i - 1];
            if (i > 1 && port[i - 1] != port[i - 2]) {
                cnt[i]++;
            }
        }
        cnt[n + 1] = cnt[n]; // sentinel

        int[] dp = new int[n + 1];
        Deque<Integer> deque = new ArrayDeque<>();
        deque.addLast(0); // start index

        int left = 0; // earliest index that can be start of current window
        for (int i = 1; i <= n; i++) {
            // shrink window to satisfy constraints
            while (i - left > maxBoxes || preWeight[i] - preWeight[left] > maxWeight) {
                left++;
            }

            // remove indices that are out of the window
            while (!deque.isEmpty() && deque.peekFirst() < left) {
                deque.pollFirst();
            }

            // compute dp[i] using best candidate at deque front
            int j = deque.peekFirst();
            dp[i] = dp[j] + 1 + cnt[i] - cnt[j + 1];

            // prepare value for monotonic queue: dp[i] - cnt[i+1]
            int curVal = dp[i] - cnt[i + 1];
            while (!deque.isEmpty()) {
                int last = deque.peekLast();
                int lastVal = dp[last] - cnt[last + 1];
                if (lastVal <= curVal) {
                    break;
                }
                deque.pollLast();
            }
            deque.addLast(i);
        }

        return dp[n];
    }
}

