public class Solution {
    public String getSmallestString(int n, int k) {
        char[] chars = new char[n];
        // Initialize all positions with 'a' (value 1)
        for (int i = 0; i < n; i++) {
            chars[i] = 'a';
        }
        int remaining = k - n; // extra value to distribute
        for (int i = n - 1; i >= 0 && remaining > 0; i--) {
            int add = Math.min(25, remaining); // each position can increase by at most 25 ('a' -> 'z')
            chars[i] = (char) (chars[i] + add);
            remaining -= add;
        }
        return new String(chars);
    }
}

