import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public List<Boolean> checkArithmeticSubarrays(int[] nums, int[] l, int[] r) {
        List<Boolean> answer = new ArrayList<>(l.length);
        for (int i = 0; i < l.length; i++) {
            int left = l[i];
            int right = r[i];
            int len = right - left + 1;
            if (len <= 2) {
                answer.add(true);
                continue;
            }

            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            for (int j = left; j <= right; j++) {
                int val = nums[j];
                if (val < min) min = val;
                if (val > max) max = val;
            }

            // If all numbers are the same
            if (min == max) {
                answer.add(true);
                continue;
            }

            // The common difference must be integer
            if ((max - min) % (len - 1) != 0) {
                answer.add(false);
                continue;
            }

            int diff = (max - min) / (len - 1);
            // diff cannot be zero here because min != max
            boolean[] seen = new boolean[len];
            boolean ok = true;
            for (int j = left; j <= right; j++) {
                int val = nums[j];
                int offset = val - min;
                if (offset % diff != 0) {
                    ok = false;
                    break;
                }
                int pos = offset / diff;
                if (pos < 0 || pos >= len || seen[pos]) {
                    ok = false;
                    break;
                }
                seen[pos] = true;
            }
            answer.add(ok);
        }
        return answer;
    }
}

