import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        // Count frequencies of each unique number
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }
        int[] freq = new int[countMap.size()];
        int idx = 0;
        for (int v : countMap.values()) {
            freq[idx++] = v;
        }

        int m = quantity.length;
        int totalMask = 1 << m;

        // Pre‑compute sum of quantities for every subset mask
        int[] sum = new int[totalMask];
        for (int mask = 1; mask < totalMask; mask++) {
            int lsb = mask & -mask;                     // lowest set bit
            int bitIdx = Integer.numberOfTrailingZeros(lsb);
            sum[mask] = sum[mask ^ lsb] + quantity[bitIdx];
        }

        boolean[] dp = new boolean[totalMask];
        dp[0] = true; // no customers satisfied yet

        for (int f : freq) {
            boolean[] next = dp.clone();
            for (int mask = 0; mask < totalMask; mask++) {
                if (!dp[mask]) continue;
                int remaining = (totalMask - 1) ^ mask; // customers not yet satisfied
                // iterate over all non‑empty submasks of remaining
                for (int sub = remaining; sub > 0; sub = (sub - 1) & remaining) {
                    if (sum[sub] <= f) {
                        next[mask | sub] = true;
                    }
                }
            }
            dp = next;
        }

        return dp[totalMask - 1];
    }
}

