public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        // Count frequencies of each unique number in nums
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }
        int[] counts = new int[freqMap.size()];
        int idx = 0;
        for (int v : freqMap.values()) {
            counts[idx++] = v;
        }

        int m = quantity.length;
        int fullMask = (1 << m) - 1;

        // Pre‑compute total quantity for every subset of customers
        int[] sum = new int[1 << m];
        for (int mask = 1; mask <= fullMask; mask++) {
            // isolate the lowest set bit
            int lsb = mask & -mask;
            int bitIdx = Integer.numberOfTrailingZeros(lsb);
            int prevMask = mask ^ lsb;
            sum[mask] = sum[prevMask] + quantity[bitIdx];
        }

        boolean[] dp = new boolean[1 << m];
        dp[0] = true; // no customer satisfied yet

        for (int cnt : counts) {
            boolean[] next = dp.clone(); // we may also choose not to use this count
            for (int mask = 0; mask <= fullMask; mask++) {
                if (!dp[mask]) continue;
                int remaining = fullMask ^ mask; // customers still unsatisfied
                // iterate over all non‑empty subsets of remaining
                for (int sub = remaining; sub > 0; sub = (sub - 1) & remaining) {
                    if (sum[sub] <= cnt) {
                        next[mask | sub] = true;
                    }
                }
            }
            dp = next;
        }

        return dp[fullMask];
    }
}

