            int lsb = Integer.numberOfTrailingZeros(mask);
            int prev = mask ^ (1 << lsb);
            subsetSum[mask] = subsetSum[prev] + quantity[lsb];
        }

        boolean[] dp = new boolean[1 << m];
        dp[0] = true; // no customer satisfied yet

        // Try to use each frequency to satisfy some subset of remaining customers
        for (int f : freq) {
            boolean[] next = dp.clone();
            for (int mask = 0; mask <= fullMask; mask++) {
                if (!dp[mask]) continue;
                int remaining = fullMask ^ mask; // customers not yet satisfied
                // Enumerate all non‑empty subsets of remaining customers
                for (int sub = remaining; sub > 0; sub = (sub - 1) & remaining) {
                    if (subsetSum[sub] <= f) {
                        next[mask | sub] = true;
                    }
                }
            }
            dp = next;
        }

        return dp[fullMask];
    }
}

