import java.util.*;

public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        // Count frequencies of each unique number
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }
        int[] freq = new int[map.size()];
        int idx = 0;
        for (int v : map.values()) {
            freq[idx++] = v;
        }
        // Sort frequencies descending to improve pruning
        Arrays.sort(freq);
        for (int i = 0, j = freq.length - 1; i < j; i++, j--) {
            int tmp = freq[i];
            freq[i] = freq[j];
            freq[j] = tmp;
        }

        int m = quantity.length;
        int fullMask = (1 << m) - 1;

        // Pre‑compute sum of quantities for every subset mask
        int[] subsetSum = new int[1 << m];
        for (int mask = 1; mask < (1 << m); mask++) {
            int lsb = Integer.numberOfTrailingZeros(mask);
            subsetSum[mask] = subsetSum[mask ^ (1 << lsb)] + quantity[lsb];
        }

        // Memoization: dp[idx][mask] -> can we satisfy 'mask' using frequencies from idx onward
        Boolean[][] memo = new Boolean[freq.length + 1][1 << m];

        return dfs(0, fullMask, freq, subsetSum, memo);
    }

    private boolean dfs(int idx, int mask, int[] freq, int[] subsetSum, Boolean[][] memo) {
        if (mask == 0) {
            return true; // all customers satisfied
        }
        if (idx == freq.length) {
            return false; // no more numbers to use
        }
        if (memo[idx][mask] != null) {
            return memo[idx][mask];
        }

        // Try to give a non‑empty subset of remaining customers to current frequency
        // Iterate over all subsets of mask
        for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
            if (subsetSum[sub] <= freq[idx]) {
                if (dfs(idx + 1, mask ^ sub, freq, subsetSum, memo)) {
                    memo[idx][mask] = true;
                    return true;
                }
            }
        }
        // Also consider skipping this frequency entirely
        if (dfs(idx + 1, mask, freq, subsetSum, memo)) {
            memo[idx][mask] = true;
            return true;
        }

        memo[idx][mask] = false;
        return false;
    }
}

