public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        // count frequency of each distinct number
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : nums) {
            map.merge(num, 1, Integer::sum);
        }
        int[] cnt = new int[map.size()];
        int idx = 0;
        for (int v : map.values()) {
            cnt[idx++] = v;
        }
        // sort frequencies descending (helps pruning)
        Arrays.sort(cnt);
        for (int i = 0, j = cnt.length - 1; i < j; i++, j--) {
            int tmp = cnt[i];
            cnt[i] = cnt[j];
            cnt[j] = tmp;
        }

        int m = quantity.length;
        int[] qty = quantity.clone();
        // sort customer quantities descending
        Arrays.sort(qty);
        for (int i = 0, j = m - 1; i < j; i++, j--) {
            int tmp = qty[i];
            qty[i] = qty[j];
            qty[j] = tmp;
        }

        int totalMask = 1 << m;
        int[] sum = new int[totalMask];
        // pre‑compute sum of quantities for every subset mask
        for (int mask = 1; mask < totalMask; mask++) {
            int lsb = mask & -mask;
            int bit = Integer.numberOfTrailingZeros(lsb);
            sum[mask] = sum[mask ^ lsb] + qty[bit];
        }

        Boolean[][] memo = new Boolean[cnt.length][totalMask];
        return dfs(0, totalMask - 1, cnt, qty, sum, memo);
    }

    private boolean dfs(int i, int mask, int[] cnt, int[] qty, int[] sum, Boolean[][] memo) {
        if (mask == 0) {
            return true; // all customers satisfied
        }
        if (i == cnt.length) {
            return false; // no more distinct numbers
        }
        if (memo[i][mask] != null) {
            return memo[i][mask];
        }
        // try every sub‑mask of the remaining customers
        for (int sub = mask; ; sub = (sub - 1) & mask) {
            if (sum[sub] <= cnt[i]) {
                if (dfs(i + 1, mask ^ sub, cnt, qty, sum, memo)) {
                    memo[i][mask] = true;
                    return true;
                }
            }
            if (sub == 0) {
                break;
            }
        }
        memo[i][mask] = false;
        return false;
    }
}

