public class Solution {
    private static final int MOD = 1_000_000_007;

    public int createSortedArray(int[] instructions) {
        int n = instructions.length;
        int[] sorted = instructions.clone();
        Arrays.sort(sorted);
        Map<Integer, Integer> compress = new HashMap<>();
        int idx = 1;
        for (int v : sorted) {
            if (!compress.containsKey(v)) {
                compress.put(v, idx++);
            }
        }
        FenwickTree ft = new FenwickTree(idx);
        long cost = 0;
        for (int i = 0; i < n; i++) {
            int val = compress.get(instructions[i]);
            long less = ft.query(val - 1);
            long greater = i - ft.query(val);
            cost += Math.min(less, greater);
            if (cost >= MOD) {
                cost %= MOD;
            }
            ft.update(val, 1);
        }
        return (int) (cost % MOD);
    }

    private static class FenwickTree {
        private final int[] tree;

        FenwickTree(int size) {
            tree = new int[size + 2];
        }

        void update(int i, int delta) {
            while (i < tree.length) {
                tree[i] += delta;
                i += i & -i;
            }
        }

        int query(int i) {
            int sum = 0;
            while (i > 0) {
                sum += tree[i];
                i -= i & -i;
            }
            return sum;
        }
    }
}

