public class Solution {
    private static final int MOD = 1_000_000_007;

    private static class FenwickTree {
        private final int[] tree;
        private final int n;

        FenwickTree(int size) {
            n = size;
            tree = new int[n + 2];
        }

        void update(int index, int delta) {
            while (index <= n) {
                tree[index] += delta;
                index += index & -index;
            }
        }

        int query(int index) {
            int sum = 0;
            while (index > 0) {
                sum += tree[index];
                index -= index & -index;
            }
            return sum;
        }
    }

    public int createSortedArray(int[] instructions) {
        int n = instructions.length;
        if (n == 0) return 0;

        // Coordinate compression
        int[] sorted = instructions.clone();
        Arrays.sort(sorted);
        int m = 0;
        Map<Integer, Integer> map = new HashMap<>();
        for (int value : sorted) {
            if (!map.containsKey(value)) {
                map.put(value, ++m);
            }
        }

        FenwickTree bit = new FenwickTree(m);
        long totalCost = 0L;

        for (int i = 0; i < n; i++) {
            int idx = map.get(instructions[i]);

            int less = bit.query(idx - 1);
            int greater = i - bit.query(idx); // i is number of already inserted elements

            totalCost += Math.min(less, greater);
            if (totalCost >= MOD) totalCost %= MOD;

            bit.update(idx, 1);
        }

        return (int) (totalCost % MOD);
    }
}

