public class Solution {
    private static final int MOD = 1_000_000_007;

    public int createSortedArray(int[] instructions) {
        int n = instructions.length;
        // Find maximum value for BIT size
        int maxVal = 0;
        for (int v : instructions) {
            if (v > maxVal) maxVal = v;
        }
        FenwickTree bit = new FenwickTree(maxVal + 2); // 1‑based indexing

        long totalCost = 0L;
        for (int i = 0; i < n; i++) {
            int val = instructions[i];
            long less = bit.query(val - 1);
            long greater = i - bit.query(val); // elements already inserted minus those ≤ val
            totalCost += Math.min(less, greater);
            if (totalCost >= MOD) totalCost %= MOD;
            bit.update(val, 1);
        }
        return (int) (totalCost % MOD);
    }

    /** Fenwick Tree (Binary Indexed Tree) for prefix sums */
    private static class FenwickTree {
        private final long[] tree;
        private final int size;

        FenwickTree(int size) {
            this.size = size;
            this.tree = new long[size];
        }

        // add delta at index i (1‑based)
        void update(int i, long delta) {
            for (int idx = i; idx < size; idx += idx & -idx) {
                tree[idx] += delta;
            }
        }

        // sum of values in [1, i] (inclusive)
        long query(int i) {
            long sum = 0L;
            for (int idx = i; idx > 0; idx -= idx & -idx) {
                sum += tree[idx];
            }
            return sum;
        }
    }
}

