public class Solution {
    private static final int MOD = 1_000_000_007;

    private static class BIT {
        private final int[] tree;
        private final int n;

        BIT(int size) {
            this.n = size;
            this.tree = new int[n + 2];
        }

        void update(int index, int delta) {
            while (index <= n) {
                tree[index] += delta;
                index += index & -index;
            }
        }

        int query(int index) {
            int sum = 0;
            while (index > 0) {
                sum += tree[index];
                index -= index & -index;
            }
            return sum;
        }
    }

    public int createSortedArray(int[] instructions) {
        // Coordinate compression
        int[] sorted = instructions.clone();
        Arrays.sort(sorted);
        Map<Integer, Integer> rank = new HashMap<>();
        int r = 1;
        for (int val : sorted) {
            if (!rank.containsKey(val)) {
                rank.put(val, r++);
            }
        }

        BIT bit = new BIT(rank.size() + 2);
        long totalCost = 0;
        int inserted = 0;

        for (int val : instructions) {
            int idx = rank.get(val);
            int less = bit.query(idx - 1);
            int greater = inserted - bit.query(idx);
            totalCost += Math.min(less, greater);
            if (totalCost >= MOD) totalCost %= MOD;
            bit.update(idx, 1);
            inserted++;
        }

        return (int) (totalCost % MOD);
    }
}

