public class Solution {
    private static final int MOD = 1_000_000_007;

    public int createSortedArray(int[] instructions) {
        int n = instructions.length;

        // coordinate compression
        int[] sorted = instructions.clone();
        Arrays.sort(sorted);
        int[] uniq = new int[n];
        int m = 0;
        for (int v : sorted) {
            if (m == 0 || v != uniq[m - 1]) {
                uniq[m++] = v;
            }
        }

        FenwickTree bit = new FenwickTree(m);
        long answer = 0;
        int totalInserted = 0;

        for (int v : instructions) {
            int idx = Arrays.binarySearch(uniq, 0, m, v) + 1; // 1‑based index for BIT
            int less = bit.query(idx - 1);
            int lessOrEqual = bit.query(idx);
            int greater = totalInserted - lessOrEqual;

            answer += Math.min(less, greater);
            if (answer >= MOD) {
                answer %= MOD;
            }

            bit.update(idx, 1);
            totalInserted++;
        }

        return (int) (answer % MOD);
    }

    private static class FenwickTree {
        private final int[] tree;
        private final int size;

        FenwickTree(int size) {
            this.size = size;
            this.tree = new int[size + 2];
        }

        void update(int index, int delta) {
            while (index <= size) {
                tree[index] += delta;
                index += index & -index;
            }
        }

        int query(int index) {
            int sum = 0;
            while (index > 0) {
                sum += tree[index];
                index -= index & -index;
            }
            return sum;
        }
    }
}

