        }
        int groupSize = n / k;
        // frequency check: no element may appear more than k times
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
            if (freq.get(v) > k) {
                return -1;
            }
        }
        if (groupSize == 1) {
            return 0; // each subset has one element, incompatibility is zero
        }

        int totalMask = (1 << n) - 1;
        int[] incompatibility = new int[1 << n];
        Arrays.fill(incompatibility, -1);

        // Pre‑compute incompatibility for every subset of size groupSize with all distinct values
        for (int mask = 0; mask <= totalMask; mask++) {
            if (Integer.bitCount(mask) != groupSize) {
                continue;
            }
            Set<Integer> seen = new HashSet<>();
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            boolean duplicate = false;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    int val = nums[i];
                    if (!seen.add(val)) {
                        duplicate = true;
                        break;
                    }
                    if (val < min) min = val;
                    if (val > max) max = val;
                }
            }
            if (!duplicate) {
                incompatibility[mask] = max - min;
            }
        }

        int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[1 << n];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int mask = 0; mask <= totalMask; mask++) {
            if (dp[mask] == INF) continue;
            int remaining = totalMask ^ mask;
            // iterate over submasks of remaining
            for (int sub = remaining; sub > 0; sub = (sub - 1) & remaining) {
                if (incompatibility[sub] == -1) continue; // not a valid group
                int newMask = mask | sub;
                dp[newMask] = Math.min(dp[newMask], dp[mask] + incompatibility[sub]);
            }
        }

        int ans = dp[totalMask];
        return ans == INF ? -1 : ans;
    }
}

