public class Solution {
    public boolean checkPalindromeFormation(String a, String b) {
        return canForm(a, b) || canForm(b, a);
    }

    private boolean canForm(String first, String second) {
        int i = 0;
        int j = first.length() - 1;
        while (i < j && first.charAt(i) == second.charAt(j)) {
            i++;
            j--;
        }
        // If the remaining substring in either string is a palindrome, we can succeed
        return isPalindrome(first, i, j) || isPalindrome(second, i, j);
    }

    private boolean isPalindrome(String s, int left, int right) {
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

