public class Solution {
    public int maximumUniqueSubarray(int[] nums) {
        Map<Integer, Integer> lastPos = new HashMap<>();
        long currentSum = 0;
        long maxSum = 0;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            int val = nums[right];
            if (lastPos.containsKey(val) && lastPos.get(val) >= left) {
                // Move left pointer past the previous occurrence
                int prevIndex = lastPos.get(val);
                while (left <= prevIndex) {
                    currentSum -= nums[left];
                    left++;
                }
            }
            currentSum += val;
            lastPos.put(val, right);
            if (currentSum > maxSum) {
                maxSum = currentSum;
            }
        }
        return (int) maxSum;
    }
}

