    public int[] mostCompetitive(int[] nums, int k) {
        int n = nums.length;
        int[] stack = new int[k];
        int top = 0;
        for (int i = 0; i < n; i++) {
            int cur = nums[i];
            while (top > 0 && stack[top - 1] > cur && (top - 1 + (n - i) >= k)) {
                top--;
            }
            if (top < k) {
                stack[top++] = cur;
            }
        }
        return stack;
    }
}

