        int n = nums.length;
        int[] stack = new int[k];
        int stackSize = 0;
        for (int i = 0; i < n; i++) {
            int remaining = n - i - 1;
            while (stackSize > 0 && nums[i] < stack[stackSize - 1] && (stackSize - 1 + remaining + 1) >= k) {
                stackSize--;
            }
            if (stackSize < k) {
                stack[stackSize++] = nums[i];
            }
        }
        return Arrays.copyOf(stack, k);
    }
