public class Solution {
    public int[] mostCompetitive(int[] nums, int k) {
        int n = nums.length;
        int[] stack = new int[k];
        int top = 0; // number of elements in stack

        for (int i = 0; i < n; i++) {
            // While we can remove the previous element to make the sequence smaller
            while (top > 0 && nums[i] < stack[top - 1] && (n - i) > (k - (top - 1))) {
                top--;
            }
            // If we still need more elements, push current number
            if (top < k) {
                stack[top++] = nums[i];
            }
        }
        return stack;
    }
}

