import java.util.Arrays;

public class Solution {
    public double trimMean(int[] arr) {
        int n = arr.length;
        int remove = (int) (n * 0.05); // number of elements to remove from each end
        Arrays.sort(arr);
        long sum = 0L;
        for (int i = remove; i < n - remove; i++) {
            sum += arr[i];
        }
        int remaining = n - 2 * remove;
        return (double) sum / remaining;
    }
}

