public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        int[][] left = new int[n + 1][m + 1];   // common suffix lengths
        int[][] right = new int[n + 1][m + 1];  // common prefix lengths

        // compute left (suffix) DP
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            for (int j = 0; j < m; j++) {
                if (cs == t.charAt(j)) {
                    left[i + 1][j + 1] = left[i][j] + 1;
                } else {
                    left[i + 1][j + 1] = 0;
                }
            }
        }

        // compute right (prefix) DP
        for (int i = n - 1; i >= 0; i--) {
            char cs = s.charAt(i);
            for (int j = m - 1; j >= 0; j--) {
                if (cs == t.charAt(j)) {
                    right[i][j] = right[i + 1][j + 1] + 1;
                } else {
                    right[i][j] = 0;
                }
            }
        }

        long ans = 0L;
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            for (int j = 0; j < m; j++) {
                if (cs != t.charAt(j)) {
                    long leftMatch = left[i][j];          // equal chars before (i,j)
                    long rightMatch = right[i + 1][j + 1]; // equal chars after (i,j)
                    ans += (leftMatch + 1) * (rightMatch + 1);
                }
            }
        }
        return (int) ans;
    }
}

