public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        int[][] pre = new int[n + 1][m + 1];          // common suffix length ending at (i-1, j-1)
        int[][] suf = new int[n + 2][m + 2];          // common prefix length starting at (i, j)

        // compute pre (suffixes)
        for (int i = 1; i <= n; i++) {
            char cs = s.charAt(i - 1);
            for (int j = 1; j <= m; j++) {
                if (cs == t.charAt(j - 1)) {
                    pre[i][j] = pre[i - 1][j - 1] + 1;
                } else {
                    pre[i][j] = 0;
                }
            }
        }

        // compute suf (prefixes) from the end
        for (int i = n - 1; i >= 0; i--) {
            char cs = s.charAt(i);
            for (int j = m - 1; j >= 0; j--) {
                if (cs == t.charAt(j)) {
                    suf[i][j] = suf[i + 1][j + 1] + 1;
                } else {
                    suf[i][j] = 0;
                }
            }
        }

        long ans = 0L;
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            for (int j = 0; j < m; j++) {
                if (cs != t.charAt(j)) {
                    int left = pre[i][j];          // matching characters to the left
                    int right = suf[i + 1][j + 1]; // matching characters to the right
                    ans += (long) (left + 1) * (right + 1);
                }
            }
        }
        return (int) ans;
    }
}

