public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        int[][] pref = new int[n + 1][m + 1];   // longest common prefix starting at i,j
        for (int i = n - 1; i >= 0; i--) {
            char cs = s.charAt(i);
            for (int j = m - 1; j >= 0; j--) {
                if (cs == t.charAt(j)) {
                    pref[i][j] = pref[i + 1][j + 1] + 1;
                }
            }
        }

        int[][] suf = new int[n][m]; // longest common suffix ending at i-1,j-1 (i.e., up to i,j)
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            for (int j = 0; j < m; j++) {
                if (cs == t.charAt(j)) {
                    if (i > 0 && j > 0) {
                        suf[i][j] = suf[i - 1][j - 1] + 1;
                    } else {
                        suf[i][j] = 1;
                    }
                }
            }
        }

        long ans = 0L;
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            for (int j = 0; j < m; j++) {
                if (cs != t.charAt(j)) {
                    int left = (i > 0 && j > 0) ? suf[i - 1][j - 1] : 0;
                    int right = (i + 1 < n && j + 1 < m) ? pref[i + 1][j + 1] : 0;
                    ans += (long) (left + 1) * (right + 1);
                }
            }
        }
        return (int) ans;
    }
}

