public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        // f[i][j] = length of longest common prefix of s starting at i and t starting at j
        int[][] f = new int[n + 1][m + 1];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (s.charAt(i) == t.charAt(j)) {
                    f[i][j] = 1 + f[i + 1][j + 1];
                } else {
                    f[i][j] = 0;
                }
            }
        }

        // g[i][j] = length of longest common suffix ending at i in s and j in t
        int[][] g = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s.charAt(i) == t.charAt(j)) {
                    if (i > 0 && j > 0) {
                        g[i][j] = 1 + g[i - 1][j - 1];
                    } else {
                        g[i][j] = 1;
                    }
                } else {
                    g[i][j] = 0;
                }
            }
        }

        long ans = 0L;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s.charAt(i) != t.charAt(j)) {
                    int left = (i > 0 && j > 0) ? g[i - 1][j - 1] : 0;
                    int right = (i + 1 < n && j + 1 < m) ? f[i + 1][j + 1] : 0;
                    ans += (long) (left + 1) * (right + 1);
                }
            }
        }
        return (int) ans;
    }
}

