public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        // pref[i+1][j+1] = length of longest common prefix ending at s[i] and t[j]
        int[][] pref = new int[n + 1][m + 1];
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            for (int j = 0; j < m; j++) {
                if (cs == t.charAt(j)) {
                    pref[i + 1][j + 1] = pref[i][j] + 1;
                } // else 0 (default)
            }
        }

        // suff[i][j] = length of longest common suffix starting at s[i] and t[j]
        int[][] suff = new int[n + 1][m + 1];
        for (int i = n - 1; i >= 0; i--) {
            char cs = s.charAt(i);
            for (int j = m - 1; j >= 0; j--) {
                if (cs == t.charAt(j)) {
                    suff[i][j] = suff[i + 1][j + 1] + 1;
                } // else 0 (default)
            }
        }

        long ans = 0L;
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            for (int j = 0; j < m; j++) {
                if (cs != t.charAt(j)) {
                    int left = pref[i][j];      // matching chars before the mismatch
                    int right = suff[i + 1][j + 1]; // matching chars after the mismatch
