public class Solution {
    private static final int MAX = 30; // maximum row + column (constraints are small)
    private static final long[][] C = new long[MAX + 1][MAX + 1];

    static {
        for (int n = 0; n <= MAX; n++) {
            C[n][0] = C[n][n] = 1L;
            for (int k = 1; k < n; k++) {
                C[n][k] = C[n - 1][k - 1] + C[n - 1][k];
                // cap to avoid overflow, though not needed for given constraints
                if (C[n][k] < 0) C[n][k] = Long.MAX_VALUE;
            }
        }
    }

    public String kthSmallestPath(int[] destination, int k) {
        int down = destination[0];   // number of 'V'
        int right = destination[1];  // number of 'H'
        StringBuilder sb = new StringBuilder();

        while (down > 0 || right > 0) {
            if (right == 0) {
                // only vertical moves left
                sb.append('V');
                down--;
                continue;
            }
            if (down == 0) {
                // only horizontal moves left
                sb.append('H');
                right--;
                continue;
            }

            // number of strings if we place 'H' now
            long cnt = C[down + right - 1][down];
            if (k <= cnt) {
                sb.append('H');
                right--;
            } else {
                sb.append('V');
                k -= cnt;
                down--;
            }
        }

        return sb.toString();
    }
}

