import java.util.*;

public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int row = destination[0];
        int col = destination[1];
        int total = row + col;

        long[][] comb = new long[total + 1][total + 1];
        for (int i = 0; i <= total; i++) {
            comb[i][0] = comb[i][i] = 1L;
            for (int j = 1; j < i; j++) {
                long val = comb[i - 1][j - 1] + comb[i - 1][j];
                comb[i][j] = Math.min(val, Long.MAX_VALUE);
            }
        }

        StringBuilder sb = new StringBuilder();
        int remainingV = row;
        int remainingH = col;
        long kk = k;

        while (remainingV > 0 || remainingH > 0) {
            if (remainingH == 0) {
                sb.append('V');
                remainingV--;
            } else if (remainingV == 0) {
                sb.append('H');
                remainingH--;
            } else {
                long count = comb[remainingH + remainingV - 1][remainingV];
                if (kk <= count) {
                    sb.append('H');
                    remainingH--;
                } else {
                    sb.append('V');
                    kk -= count;
                    remainingV--;
                }
            }
        }

        return sb.toString();
    }
}

