        // capping values to Long.MAX_VALUE to avoid overflow.
        long[][] comb = new long[total + 1][total + 1];
        for (int i = 0; i <= total; i++) {
            comb[i][0] = comb[i][i] = 1L;
            for (int j = 1; j < i; j++) {
                long val = comb[i - 1][j - 1] + comb[i - 1][j];
                comb[i][j] = (val < 0) ? Long.MAX_VALUE : Math.min(val, Long.MAX_VALUE);
            }
        }

        StringBuilder sb = new StringBuilder();
        long kth = k; // use long for safety

        while (rows > 0 && cols > 0) {
            // Number of paths that start with an 'H' (horizontal move)
            long count = comb[rows + cols - 1][rows]; // choose positions for the remaining vertical moves
            if (kth <= count) {
                sb.append('H');
                cols--;
            } else {
                sb.append('V');
                kth -= count;
                rows--;
            }
        }

        // Append remaining moves (only one direction left)
        while (cols-- > 0) sb.append('H');
        while (rows-- > 0) sb.append('V');

        return sb.toString();
    }
}

