public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int row = destination[0];
        int col = destination[1];
        StringBuilder sb = new StringBuilder();
        long kk = k; // use long to avoid overflow

        while (row > 0 && col > 0) {
            long count = combination(row + col - 1, row - 1); // ways starting with 'H'
            if (kk <= count) {
                sb.append('H');
                col--;
            } else {
                sb.append('V');
                kk -= count;
                row--;
            }
        }

        while (col > 0) {
            sb.append('H');
            col--;
        }
        while (row > 0) {
            sb.append('V');
            row--;
        }

        return sb.toString();
    }

    private long combination(int n, int r) {
        if (r < 0 || r > n) return 0;
        r = Math.min(r, n - r);
        long result = 1;
        for (int i = 1; i <= r; i++) {
            result = result * (n - r + i) / i;
            // cap the result to avoid unnecessary overflow; values larger than Long.MAX_VALUE are not needed
            if (result > Long.MAX_VALUE / 2) {
                result = Long.MAX_VALUE / 2;
            }
        }
        return result;
    }
}

