import java.math.BigInteger;

public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int rows = destination[0];
        int cols = destination[1];
        int n = rows + cols;

        // Pre‑compute binomial coefficients C[i][j] = i choose j
        BigInteger[][] C = new BigInteger[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            C[i][0] = BigInteger.ONE;
            C[i][i] = BigInteger.ONE;
            for (int j = 1; j < i; j++) {
                C[i][j] = C[i - 1][j - 1].add(C[i - 1][j]);
            }
        }

        StringBuilder sb = new StringBuilder();
        int h = cols; // remaining horizontal moves ('H')
        int v = rows; // remaining vertical moves ('V')
        BigInteger kBig = BigInteger.valueOf(k);

        while (h > 0 || v > 0) {
            if (h == 0) {
                sb.append('V');
                v--;
                continue;
            }
            if (v == 0) {
                sb.append('H');
                h--;
                continue;
            }

            // Number of paths if we place an 'H' now:
            // choose (h-1 + v) positions for the remaining v vertical moves
            BigInteger cnt = C[h + v - 1][v];

            if (kBig.compareTo(cnt) <= 0) {
                sb.append('H');
                h--;
            } else {
                sb.append('V');
                kBig = kBig.subtract(cnt);
                v--;
            }
        }

        return sb.toString();
    }
}

