import java.util.*;

public class Solution {
    private static class Cell {
        int row;
        int col;
        int val;
        Cell(int r, int c, int v) {
            this.row = r;
            this.col = c;
            this.val = v;
        }
    }

    private static class UnionFind {
        int[] parent;
        int[] size;
        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                parent[ra] = rb;
                size[rb] += size[ra];
            } else {
                parent[rb] = ra;
                size[ra] += size[rb];
            }
        }
    }

    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        if (m == 0) return new int[0][];
        int n = matrix[0].length;

        int total = m * n;
        Cell[] cells = new Cell[total];
        int idx = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells[idx++] = new Cell(i, j, matrix[i][j]);
            }
        }

        Arrays.sort(cells, Comparator.comparingInt(c -> c.val));

        int[] rowRank = new int[m];
        int[] colRank = new int[n];
        int[][] answer = new int[m][n];

        int i = 0;
        while (i < total) {
            int j = i;
            // group cells with same value
            while (j < total && cells[j].val == cells[i].val) j++;

            int groupSize = j - i;
            UnionFind uf = new UnionFind(groupSize);
            Map<Integer, Integer> rowMap = new HashMap<>();
            Map<Integer, Integer> colMap = new HashMap<>();

            // union cells sharing row or column within this group
            for (int k = i; k < j; k++) {
                int localIdx = k - i;
                Cell c = cells[k];
                if (rowMap.containsKey(c.row)) {
                    uf.union(localIdx, rowMap.get(c.row));
                } else {
                    rowMap.put(c.row, localIdx);
                }
                if (colMap.containsKey(c.col)) {
                    uf.union(localIdx, colMap.get(c.col));
                } else {
                    colMap.put(c.col, localIdx);
                }
            }

            // compute max rank needed for each component
            Map<Integer, Integer> compMax = new HashMap<>();
            for (int k = i; k < j; k++) {
                int localIdx = k - i;
                Cell c = cells[k];
                int root = uf.find(localIdx);
                int cur = Math.max(rowRank[c.row], colRank[c.col]);
                compMax.put(root, Math.max(compMax.getOrDefault(root, 0), cur));
            }

            // temporary updates for rows and columns
            Map<Integer, Integer> rowUpdates = new HashMap<>();
            Map<Integer, Integer> colUpdates = new HashMap<>();

            // assign ranks
            for (int k = i; k < j; k++) {
                int localIdx = k - i;
                Cell c = cells[k];
                int root = uf.find(localIdx);
                int rank = compMax.get(root) + 1;
                answer[c.row][c.col] = rank;
                rowUpdates.put(c.row, Math.max(rowUpdates.getOrDefault(c.row, 0), rank));
                colUpdates.put(c.col, Math.max(colUpdates.getOrDefault(c.col, 0), rank));
            }

            // apply updates after processing the whole value group
            for (Map.Entry<Integer, Integer> e : rowUpdates.entrySet()) {
                rowRank[e.getKey()] = e.getValue();
            }
            for (Map.Entry<Integer, Integer> e : colUpdates.entrySet()) {
                colRank[e.getKey()] = e.getValue();
            }

            i = j;
        }

        return answer;
    }
}

