public class Solution {
    private static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return;
            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
            } else if (rank[rx] > rank[ry]) {
                parent[ry] = rx;
            } else {
                parent[ry] = rx;
                rank[rx]++;
            }
        }
    }

    private static class Cell {
        int value;
        int row;
        int col;

        Cell(int value, int row, int col) {
            this.value = value;
            this.row = row;
            this.col = col;
        }
    }

    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] answer = new int[m][n];

        // Gather all cells
        List<Cell> cells = new ArrayList<>(m * n);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells.add(new Cell(matrix[i][j], i, j));
            }
        }

        // Sort by value
        cells.sort(Comparator.comparingInt(c -> c.value));

        // Rank arrays for rows and columns
        int[] rowRank = new int[m];
        int[] colRank = new int[n];

        int index = 0;
        while (index < cells.size()) {
            int start = index;
            int curVal = cells.get(index).value;
            // Find range of same value
            while (index < cells.size() && cells.get(index).value == curVal) {
                index++;
            }
            int end = index; // exclusive

            // Union-Find for this group
            UnionFind uf = new UnionFind(m + n);
            for (int i = start; i < end; i++) {
                Cell c = cells.get(i);
                uf.union(c.row, c.col + m);
            }

            // Compute max rank for each component
            Map<Integer, Integer> compMax = new HashMap<>();
            for (int i = start; i < end; i++) {
                Cell c = cells.get(i);
                int root = uf.find(c.row);
                int curMax = Math.max(rowRank[c.row], colRank[c.col]);
                compMax.merge(root, curMax, Math::max);
            }

            // Assign ranks and update row/col ranks
            for (int i = start; i < end; i++) {
                Cell c = cells.get(i);
                int root = uf.find(c.row);
                int rank = compMax.get(root) + 1;
                answer[c.row][c.col] = rank;
                rowRank[c.row] = rank;
                colRank[c.col] = rank;
            }
        }

        return answer;
    }
}

