import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxOperations(int[] nums, int k) {
        Map<Integer, Integer> countMap = new HashMap<>();
        int operations = 0;
        for (int num : nums) {
            int complement = k - num;
            Integer complementCount = countMap.get(complement);
            if (complementCount != null && complementCount > 0) {
                // Use one complement to form a pair
                countMap.put(complement, complementCount - 1);
                operations++;
            } else {
                // Store current number for future pairing
                countMap.put(num, countMap.getOrDefault(num, 0) + 1);
            }
        }
        return operations;
    }
}

