import java.util.Queue;
import java.util.ArrayDeque;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        int[] answer = new int[n - 1];
        int totalMask = 1 << n;

        for (int mask = 1; mask < totalMask; mask++) {
            int bits = Integer.bitCount(mask);
            if (bits < 2) continue; // diameter 0 not counted

            // find any node in the subset
            int start = Integer.numberOfTrailingZeros(mask);

            // check connectivity
            if (!isConnected(mask, start, bits, adj, n)) continue;

            // compute diameter using two BFS
            int farNode = bfsFarthest(start, mask, adj, n);
            int diameter = bfsMaxDistance(farNode, mask, adj, n);
            answer[diameter - 1]++; // diameter is at least 1
        }

        return answer;
    }

    private boolean isConnected(int mask, int start, int expectedSize,
                                List<Integer>[] adj, int n) {
        boolean[] visited = new boolean[n];
        Queue<Integer> q = new ArrayDeque<>();
        visited[start] = true;
        q.offer(start);
        int count = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            count++;
            for (int v : adj[u]) {
                if (((mask >> v) & 1) == 1 && !visited[v]) {
                    visited[v] = true;
                    q.offer(v);
                }
            }
        }
        return count == expectedSize;
    }

    private int bfsFarthest(int src, int mask, List<Integer>[] adj, int n) {
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = -1;
        Queue<Integer> q = new ArrayDeque<>();
        dist[src] = 0;
        q.offer(src);
        int farNode = src;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (((mask >> v) & 1) == 1 && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                    if (dist[v] > dist[farNode]) {
                        farNode = v;
                    }
                }
            }
        }
        return farNode;
    }

    private int bfsMaxDistance(int src, int mask, List<Integer>[] adj, int n) {
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = -1;
        Queue<Integer> q = new ArrayDeque<>();
        dist[src] = 0;
        q.offer(src);
        int maxDist = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (((mask >> v) & 1) == 1 && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                    if (dist[v] > maxDist) {
                        maxDist = dist[v];
                    }
                }
            }
        }
        return maxDist;
    }
}

