import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        // Build adjacency list
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0] - 1; // convert to 0‑based
            int v = e[1] - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        int[] answer = new int[n - 1];
        int totalMasks = 1 << n;

        // enumerate all non‑empty subsets
        for (int mask = 1; mask < totalMasks; mask++) {
            // need at least two nodes to have a positive diameter
            if (Integer.bitCount(mask) < 2) continue;

            // check connectivity of the induced subgraph
            if (!isConnected(mask, adj, n)) continue;

            // compute diameter of this connected subgraph
            int diameter = computeDiameter(mask, adj, n);
            // diameter is at least 1 and at most n‑1
            answer[diameter - 1]++;   // convert to 0‑based index
        }

        return answer;
    }

    // BFS limited to vertices whose bit is set in mask
    private boolean isConnected(int mask, List<Integer>[] adj, int n) {
        int start = Integer.numberOfTrailingZeros(mask); // any set bit
        boolean[] visited = new boolean[n];
        Queue<Integer> q = new ArrayDeque<>();
        q.offer(start);
        visited[start] = true;
        int visitedCount = 1;

        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int nb : adj[cur]) {
                if (((mask >> nb) & 1) == 1 && !visited[nb]) {
                    visited[nb] = true;
                    visitedCount++;
                    q.offer(nb);
                }
            }
        }
        return visitedCount == Integer.bitCount(mask);
    }

    // Returns the diameter (longest shortest path) inside the subset mask
    private int computeDiameter(int mask, List<Integer>[] adj, int n) {
        // first BFS to find farthest node from any node in the subset
        int any = Integer.numberOfTrailingZeros(mask);
        int farNode = bfsFarthest(any, mask, adj, n);
        // second BFS from farNode to get the maximum distance
        return bfsDistance(farNode, mask, adj, n);
    }

    // BFS that returns the node farthest (by distance) from start within mask
    private int bfsFarthest(int start, int mask, List<Integer>[] adj, int n) {
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = -1;
        Queue<Integer> q = new ArrayDeque<>();
        q.offer(start);
        dist[start] = 0;
        int far = start;

        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int nb : adj[cur]) {
                if (((mask >> nb) & 1) == 1 && dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    q.offer(nb);
                    if (dist[nb] > dist[far]) far = nb;
                }
            }
        }
        return far;
    }

    // BFS that returns the greatest distance from start within mask
    private int bfsDistance(int start, int mask, List<Integer>[] adj, int n) {
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = -1;
        Queue<Integer> q = new ArrayDeque<>();
        q.offer(start);
        dist[start] = 0;
        int maxDist = 0;

        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int nb : adj[cur]) {
                if (((mask >> nb) & 1) == 1 && dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    q.offer(nb);
                    if (dist[nb] > maxDist) maxDist = dist[nb];
                }
            }
        }
        return maxDist;
    }
}

