public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            g[u].add(v);
            g[v].add(u);
        }

        int[] ans = new int[n - 1];
        int total = 1 << n;

        for (int mask = 1; mask < total; mask++) {
            int cnt = Integer.bitCount(mask);
            if (cnt < 2) continue;

            // find a start node in the subset
            int start = Integer.numberOfTrailingZeros(mask);
            // check connectivity
            if (!isConnected(mask, start, g, n, cnt)) continue;

            // compute diameter using two BFS
            int farNode = bfsFarthest(start, mask, g, n)[0];
            int diameter = bfsFarthest(farNode, mask, g, n)[1];
            ans[diameter - 1]++;
        }

        return ans;
    }

    private boolean isConnected(int mask, int start, List<Integer>[] g, int n, int required) {
        boolean[] visited = new boolean[n];
        Queue<Integer> q = new ArrayDeque<>();
        q.add(start);
        visited[start] = true;
        int seen = 0;

        while (!q.isEmpty()) {
            int cur = q.poll();
            if ((mask & (1 << cur)) == 0) continue;
            seen++;
            for (int nb : g[cur]) {
                if ((mask & (1 << nb)) != 0 && !visited[nb]) {
                    visited[nb] = true;
                    q.add(nb);
                }
            }
        }
        return seen == required;
    }

    // returns array {farthestNode, distanceFromStart}
    private int[] bfsFarthest(int start, int mask, List<Integer>[] g, int n) {
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = -1;
        Queue<Integer> q = new ArrayDeque<>();
        q.add(start);
        dist[start] = 0;
        int farNode = start;
        int farDist = 0;

        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int nb : g[cur]) {
                if ((mask & (1 << nb)) == 0) continue;
                if (dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
