import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        // Build adjacency list (0‑based index)
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        int[] answer = new int[n - 1];
        int totalMask = 1 << n;

        // Enumerate all non‑empty subsets
        for (int mask = 1; mask < totalMask; mask++) {
            int bits = Integer.bitCount(mask);
            if (bits < 2) continue; // diameter 0, not needed

            // Find any node inside the subset to start BFS
            int start = Integer.numberOfTrailingZeros(mask);

            // ----- connectivity check -----
            boolean[] visited = new boolean[n];
            Queue<Integer> q = new ArrayDeque<>();
            visited[start] = true;
            q.add(start);
            int visitedCount = 0;

            while (!q.isEmpty()) {
                int cur = q.poll();
                visitedCount++;
                for (int nb : adj[cur]) {
                    if (((mask >> nb) & 1) == 1 && !visited[nb]) {
                        visited[nb] = true;
                        q.add(nb);
                    }
                }
            }
            if (visitedCount != bits) continue; // not connected

            // ----- diameter calculation (two BFS) -----
            int farNode = bfsFarthestNode(start, mask, adj);
            int diameter = bfsMaxDistance(farNode, mask, adj);

            // Record the result (diameter is at least 1)
            answer[diameter - 1]++;
        }

        return answer;
    }

    // Returns the node farthest from src within the subset defined by mask
    private int bfsFarthestNode(int src, int mask, List<Integer>[] adj) {
        int n = adj.length;
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = -1;

        Queue<Integer> q = new ArrayDeque<>();
        dist[src] = 0;
        q.add(src);
        int farNode = src;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (((mask >> v) & 1) == 1 && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                    if (dist[v] > dist[farNode]) {
                        farNode = v;
                    }
                }
            }
        }
        return farNode;
    }

    // Returns the maximum distance from src within the subset defined by mask
    private int bfsMaxDistance(int src, int mask, List<Integer>[] adj) {
        int n = adj.length;
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = -1;

        Queue<Integer> q = new ArrayDeque<>();
        dist[src] = 0;
        q.add(src);
        int maxDist = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (((mask >> v) & 1) == 1 && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                    if (dist[v] > maxDist) {
                        maxDist = dist[v];
                    }
                }
            }
        }
        return maxDist;
    }
}

