        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        int[] answer = new int[n - 1]; // index d-1 stores count for diameter d

        int totalMasks = 1 << n;
        for (int mask = 1; mask < totalMasks; mask++) {
            int sz = Integer.bitCount(mask);
            if (sz == 1) continue; // single node has diameter 0, not needed

            // find any node in the subset to start BFS
            int start = Integer.numberOfTrailingZeros(mask);

            // BFS to check connectivity and also collect nodes visited
            boolean[] visited = new boolean[n];
            ArrayDeque<Integer> q = new ArrayDeque<>();
            q.add(start);
            visited[start] = true;
            int visitedCount = 0;

            while (!q.isEmpty()) {
                int cur = q.poll();
                visitedCount++;
                for (int nb : adj[cur]) {
                    if (!visited[nb] && ((mask >> nb) & 1) == 1) {
                        visited[nb] = true;
                        q.add(nb);
                    }
                }
            }

            if (visitedCount != sz) continue; // not a connected subgraph

            // first BFS to find farthest node from start within the subset
            int farNode = bfsFarthest(start, mask, adj);
            // second BFS from farNode to get diameter
            int diameter = bfsFarthestDistance(farNode, mask, adj);
            // diameter is number of edges, range 1..n-1
            answer[diameter - 1]++; // convert to 0‑based index
        }

        return answer;
    }

    // returns the node farthest from src within the nodes indicated by mask
    private int bfsFarthest(int src, int mask, List<Integer>[] adj) {
        int n = adj.length;
        int[] dist = new int[n];
