        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(src);
        dist[src] = 0;
        int farNode = src;

        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int nb : adj[cur]) {
                if (dist[nb] == -1 && ((mask >> nb) & 1) == 1) {
                    dist[nb] = dist[cur] + 1;
                    q.add(nb);
                    if (dist[nb] > dist[farNode]) {
                        farNode = nb;
                    }
                }
            }
        }
        return farNode;
    }

    // returns the maximum distance from src within the subset (i.e., the diameter)
    private int bfsFarthestDistance(int src, int mask, List<Integer>[] adj) {
        int n = adj.length;
        int[] dist = new int[n];
        for (int i = 0; i < n; i++) dist[i] = -1;

        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(src);
        dist[src] = 0;
        int maxDist = 0;

        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int nb : adj[cur]) {
                if (dist[nb] == -1 && ((mask >> nb) & 1) == 1) {
                    dist[nb] = dist[cur] + 1;
                    q.add(nb);
                    if (dist[nb] > maxDist) {
