public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numWays(String[] words, String target) {
        if (words == null || words.length == 0 || target == null) {
            return 0;
        }
        int m = words[0].length();          // length of each word
        int n = target.length();            // length of target

        // count[c][pos] = number of words having character c at position pos
        int[][] count = new int[26][m];
        for (String w : words) {
            for (int pos = 0; pos < m; pos++) {
                char ch = w.charAt(pos);
                count[ch - 'a'][pos]++;
            }
        }

        long[] dp = new long[n + 1];
        dp[0] = 1; // empty target

        // iterate over each column (position in words)
        for (int pos = 0; pos < m; pos++) {
            // update dp in reverse to avoid overwriting needed values
            for (int t = n - 1; t >= 0; t--) {
                char need = target.charAt(t);
                int ways = count[need - 'a'][pos];
                if (ways > 0) {
                    dp[t + 1] = (dp[t + 1] + dp[t] * ways) % MOD;
                }
            }
        }

        return (int) dp[n];
    }
}

