public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numWays(String[] words, String target) {
        int m = words[0].length();
        int n = target.length();
        if (n > m) {
            return 0;
        }

        // frequency of each character at each position
        int[][] freq = new int[m][26];
        for (String w : words) {
            for (int i = 0; i < m; i++) {
                freq[i][w.charAt(i) - 'a']++;
            }
        }

        long[] dpPrev = new long[m + 1];
        long[] dpCurr = new long[m + 1];

        // dp[0][j] = 1 for all j
        for (int j = 0; j <= m; j++) {
            dpPrev[j] = 1;
        }

        for (int i = 1; i <= n; i++) {
            dpCurr[0] = 0; // cannot form non‑empty target with 0 positions
            int ch = target.charAt(i - 1) - 'a';
            for (int j = 1; j <= m; j++) {
                // Not using position j‑1
                long ways = dpCurr[j - 1];
                // Use position j‑1 if possible
                if (freq[j - 1][ch] > 0) {
                    ways += (long) freq[j - 1][ch] * dpPrev[j - 1];
                }
                dpCurr[j] = ways % MOD;
            }
            // swap arrays for next iteration
            long[] temp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = temp;
        }

        return (int) (dpPrev[m] % MOD);
    }
}

