public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numWays(String[] words, String target) {
        int n = words.length;
        int m = words[0].length();
        int t = target.length();

        // If target longer than word length, impossible
        if (t > m) {
            return 0;
        }

        // freq[pos][c] = number of words that have character c at position pos
        int[][] freq = new int[m][26];
        for (String w : words) {
            for (int i = 0; i < m; i++) {
                freq[i][w.charAt(i) - 'a']++;
            }
        }

        // dp[i] = ways to form first i characters of target using processed columns so far
        long[] dp = new long[t + 1];
        dp[0] = 1; // empty target

        for (int col = 0; col < m; col++) {
            // iterate backwards to avoid overwriting dp[i-1] needed for current column
            for (int i = t; i >= 1; i--) {
                int chIdx = target.charAt(i - 1) - 'a';
                long add = dp[i - 1] * freq[col][chIdx] % MOD;
                dp[i] = (dp[i] + add) % MOD;
            }
        }

        return (int) dp[t];
    }
}

