public class Solution {
    public int minDeletions(String s) {
        // Count frequencies of each character
        Map<Character, Integer> freqMap = new HashMap<>();
        for (char ch : s.toCharArray()) {
            freqMap.put(ch, freqMap.getOrDefault(ch, 0) + 1);
        }

        Set<Integer> usedFrequencies = new HashSet<>();
        int deletions = 0;

        for (int freq : freqMap.values()) {
            // Reduce frequency until it becomes unique (or zero)
            while (freq > 0 && !usedFrequencies.add(freq)) {
                freq--;
                deletions++;
            }
            // If freq becomes 0, we just don't add it to the set (already unique by being absent)
        }

        return deletions;
    }
}

