Implementation steps:

if (a == 0) { // replace from head
    // find node after b
    ListNode cur = list1;
    for (int i = 0; i < b; i++) cur = cur.next;
    ListNode postB = cur.next;
    // find tail of list2
    ListNode tail2 = list2;
