import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Queue;

public class Solution {
    public String findLexSmallestString(String s, int a, int b) {
        int n = s.length();
        HashSet<String> visited = new HashSet<>();
        Queue<String> queue = new ArrayDeque<>();
        visited.add(s);
        queue.offer(s);
        String best = s;

        while (!queue.isEmpty()) {
            String cur = queue.poll();
            if (cur.compareTo(best) < 0) {
                best = cur;
            }

            // Operation 1: add a to all odd indices
            char[] charsAdd = cur.toCharArray();
            for (int i = 1; i < n; i += 2) {
                int digit = charsAdd[i] - '0';
                digit = (digit + a) % 10;
                charsAdd[i] = (char) (digit + '0');
            }
            String added = new String(charsAdd);
            if (!visited.contains(added)) {
                visited.add(added);
                queue.offer(added);
            }

            // Operation 2: rotate right by b positions
            String rotated = cur.substring(n - b) + cur.substring(0, n - b);
            if (!visited.contains(rotated)) {
                visited.add(rotated);
                queue.offer(rotated);
            }
        }

        return best;
    }
}

