public class Solution {
    public String findLexSmallestString(String s, int a, int b) {
        String min = s;
        HashSet<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        visited.add(s);
        queue.offer(s);
        while (!queue.isEmpty()) {
            String cur = queue.poll();
            if (cur.compareTo(min) < 0) {
                min = cur;
            }
            // operation 1: add a to all odd indices
            String added = addA(cur, a);
            if (!visited.contains(added)) {
                visited.add(added);
                queue.offer(added);
            }
            // operation 2: rotate right by b
            String rotated = rotate(cur, b);
            if (!visited.contains(rotated)) {
                visited.add(rotated);
                queue.offer(rotated);
            }
        }
        return min;
    }

    private String addA(String s, int a) {
        char[] chars = s.toCharArray();
        for (int i = 1; i < chars.length; i += 2) {
            int digit = chars[i] - '0';
            digit = (digit + a) % 10;
            chars[i] = (char) (digit + '0');
        }
        return new String(chars);
    }

    private String rotate(String s, int b) {
        int n = s.length();
        b = b % n;
        if (b == 0) {
            return s;
        }
        String part1 = s.substring(n - b);
        String part2 = s.substring(0, n - b);
        return part1 + part2;
    }
}

