import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        if (angle >= 360) {
            // All points are visible regardless of direction
            return points.size();
        }

        int sameLocationCount = 0;
        List<Double> angles = new ArrayList<>();

        int locX = location.get(0);
        int locY = location.get(1);

        for (List<Integer> p : points) {
            int x = p.get(0);
            int y = p.get(1);
            if (x == locX && y == locY) {
                sameLocationCount++;
                continue;
            }
            double dx = x - locX;
            double dy = y - locY;
            double theta = Math.toDegrees(Math.atan2(dy, dx));
            if (theta < 0) {
                theta += 360.0;
            }
            angles.add(theta);
        }

        Collections.sort(angles);
        int n = angles.size();
        if (n == 0) {
            return sameLocationCount;
        }

        // Extend the list to handle circular wrap‑around
        List<Double> extended = new ArrayList<>(2 * n);
        extended.addAll(angles);
        for (int i = 0; i < n; i++) {
            extended.add(angles.get(i) + 360.0);
        }

        int maxInWindow = 0;
        int j = 0;
        double eps = 1e-9; // tolerance for floating point comparison

        for (int i = 0; i < n; i++) {
            while (j < i + n && extended.get(j) - extended.get(i) <= angle + eps) {
                j++;
            }
            maxInWindow = Math.max(maxInWindow, j - i);
        }

        return maxInWindow + sameLocationCount;
    }
}

