        for (int i = 0; i < n; i++) {
            ext[i] = angles.get(i);
            ext[i + n] = angles.get(i) + 360.0;
        }

        int maxVisible = 0;
        int j = 0;
        for (int i = 0; i < n; i++) {
            while (j < i + n && ext[j] - ext[i] <= angle + 1e-9) {
                j++;
            }
            maxVisible = Math.max(maxVisible, j - i);
        }

        return maxVisible + sameLocationCount;
    }
}

