public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];
        if (k == 0) {
            // all zeros already
            return result;
        }
        if (k > 0) {
            // sum of next k elements
            int sum = 0;
            // initial sum for i = 0 (elements 1..k)
            for (int i = 1; i <= k; i++) {
                sum += code[i % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = sum;
                // slide window: remove element at i+1, add element at i+1+k
                int removeIdx = (i + 1) % n;
                int addIdx = (i + 1 + k) % n;
                sum = sum - code[removeIdx] + code[addIdx];
            }
        } else { // k < 0
            int kNeg = -k;
            // sum of previous kNeg elements
            int sum = 0;
            // initial sum for i = 0 (elements n-1, n-2, ..., n-kNeg)
            for (int i = 1; i <= kNeg; i++) {
                sum += code[(n - i) % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = sum;
                // slide window: remove element at (i - kNeg) , add element at i
                int removeIdx = (i - kNeg + n) % n;
                int addIdx = i;
                sum = sum - code[removeIdx] + code[addIdx];
            }
        }
        return result;
    }
}

