public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];
        if (k == 0) {
            Arrays.fill(result, 0);
            return result;
        }

        int steps = Math.abs(k);
        int sum = 0;

        if (k > 0) {
            // initial window: next 'steps' elements after index 0
            for (int i = 1; i <= steps; i++) {
                sum += code[i % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = sum;
                // slide window: remove element leaving, add new element entering
                sum -= code[(i + 1) % n];
                sum += code[(i + steps + 1) % n];
            }
        } else { // k < 0
            // initial window: previous 'steps' elements before index 0
            for (int i = 1; i <= steps; i++) {
                sum += code[(n - i) % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = sum;
                // slide window: remove element that is now out of range, add the new preceding element
                sum -= code[(i - steps + n) % n];
                sum += code[i];
            }
        }

        return result;
    }
}

