public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];
        if (k == 0) {
            // all zeros already
            return result;
        }

        // Build extended array for easy circular sums
        int[] ext = new int[2 * n];
        for (int i = 0; i < 2 * n; i++) {
            ext[i] = code[i % n];
        }

        // Prefix sums
        long[] pref = new long[2 * n + 1];
        for (int i = 0; i < 2 * n; i++) {
            pref[i + 1] = pref[i] + ext[i];
        }

        if (k > 0) {
            for (int i = 0; i < n; i++) {
                long sum = pref[i + k + 1] - pref[i + 1];
                result[i] = (int) sum;
            }
        } else { // k < 0
            int m = -k;
            for (int i = 0; i < n; i++) {
                // use position i + n to ensure we have enough preceding elements
                long sum = pref[i + n] - pref[i + n - m];
                result[i] = (int) sum;
            }
        }
        return result;
    }
}

