public class Solution {
    private static class Pair {
        int pos;
        boolean backward;
        Pair(int p, boolean b) {
            this.pos = p;
            this.backward = b;
        }
    }

    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        Set<Integer> forbidSet = new HashSet<>();
        int maxForbidden = 0;
        for (int f : forbidden) {
            forbidSet.add(f);
            if (f > maxForbidden) maxForbidden = f;
        }
        int limit = Math.max(maxForbidden, x) + a + b + 2000;
        boolean[][] visited = new boolean[limit + 1][2]; // 0: arrived after forward (or start), 1: arrived after backward
        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(0, false));
        visited[0][0] = true;
        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Pair cur = queue.poll();
                if (cur.pos == x) {
                    return steps;
                }
                // forward jump
                int nextForward = cur.pos + a;
                if (nextForward <= limit && !forbidSet.contains(nextForward) && !visited[nextForward][0]) {
                    visited[nextForward][0] = true;
                    queue.offer(new Pair(nextForward, false));
                }
                // backward jump (cannot follow another backward)
                if (!cur.backward) {
                    int nextBackward = cur.pos - b;
                    if (nextBackward >= 0 && !forbidSet.contains(nextBackward) && !visited[nextBackward][1]) {
                        visited[nextBackward][1] = true;
                        queue.offer(new Pair(nextBackward, true));
                    }
                }
            }
            steps++;
        }
        return -1;
    }
}

