public class Solution {
    public int[] bestCoordinate(int[][] towers, int radius) {
        if (towers == null || towers.length == 0) {
            return new int[]{0, 0};
        }

        int minX = Integer.MAX_VALUE;
        int maxX = Integer.MIN_VALUE;
        int minY = Integer.MAX_VALUE;
        int maxY = Integer.MIN_VALUE;

        for (int[] t : towers) {
            int x = t[0];
            int y = t[1];
            minX = Math.min(minX, x);
            maxX = Math.max(maxX, x);
            minY = Math.min(minY, y);
            maxY = Math.max(maxY, y);
        }

        // Restrict search to non‑negative coordinates as required
        minX = Math.max(0, minX - radius);
        minY = Math.max(0, minY - radius);
        maxX = maxX + radius;
        maxY = maxY + radius;

        long bestQuality = -1;
        int bestX = 0;
        int bestY = 0;

        double radiusSq = (double) radius * radius;

        for (int x = minX; x <= maxX; x++) {
            for (int y = minY; y <= maxY; y++) {
                long total = 0;
                for (int[] t : towers) {
                    int tx = t[0];
                    int ty = t[1];
                    int q = t[2];
                    long dx = tx - x;
                    long dy = ty - y;
                    double distSq = dx * dx + dy * dy;
                    if (distSq > radiusSq) {
                        continue;
                    }
                    double dist = Math.sqrt(distSq);
                    total += (int) Math.floor(q / (1.0 + dist));
                }
                if (total > bestQuality ||
                    (total == bestQuality && (x < bestX || (x == bestX && y < bestY)))) {
                    bestQuality = total;
                    bestX = x;
                    bestY = y;
                }
            }
        }

        return new int[]{bestX, bestY};
    }
}

