import java.util.*;

public class Solution {
    public int[] bestCoordinate(int[][] towers, int radius) {
        if (towers == null || towers.length == 0) {
            return new int[]{0, 0};
        }

        int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE;
        int minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;

        for (int[] t : towers) {
            minX = Math.min(minX, t[0]);
            maxX = Math.max(maxX, t[0]);
            minY = Math.min(minY, t[1]);
            maxY = Math.max(maxY, t[1]);
        }

        int startX = Math.max(0, minX - radius);
        int endX = maxX + radius;
        int startY = Math.max(0, minY - radius);
        int endY = maxY + radius;

        long bestQuality = -1;
        int bestX = 0, bestY = 0;

        double radiusSq = (double) radius * radius;

        for (int x = startX; x <= endX; x++) {
            for (int y = startY; y <= endY; y++) {
                long total = 0;
                for (int[] t : towers) {
                    int tx = t[0];
                    int ty = t[1];
                    int q = t[2];

                    double dx = tx - x;
                    double dy = ty - y;
                    double distSq = dx * dx + dy * dy;

                    if (distSq <= radiusSq) {
                        double dist = Math.sqrt(distSq);
                        int signal = (int) (q / (1.0 + dist));
                        total += signal;
                    }
                }
                if (total > bestQuality) {
                    bestQuality = total;
                    bestX = x;
                    bestY = y;
                } else if (total == bestQuality) {
                    if (x < bestX || (x == bestX && y < bestY)) {
                        bestX = x;
                        bestY = y;
                    }
                }
            }
        }

        return new int[]{bestX, bestY};
    }
}

