public class Solution {
    public int waysToMakeFair(int[] nums) {
        int n = nums.length;
        // prefix sums for even and odd indices
        long[] prefEven = new long[n];
        long[] prefOdd = new long[n];
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                prefEven[i] = (i % 2 == 0) ? nums[i] : 0;
                prefOdd[i] = (i % 2 != 0) ? nums[i] : 0;
            } else {
                prefEven[i] = prefEven[i - 1] + ((i % 2 == 0) ? nums[i] : 0);
                prefOdd[i] = prefOdd[i - 1] + ((i % 2 != 0) ? nums[i] : 0);
            }
        }
        long totalEven = prefEven[n - 1];
        long totalOdd = prefOdd[n - 1];
        int count = 0;
        for (int i = 0; i < n; i++) {
            long leftEven = i > 0 ? prefEven[i - 1] : 0;
            long leftOdd = i > 0 ? prefOdd[i - 1] : 0;
            // sums of the part to the right of i (including i)
            long rightEven = totalEven - prefEven[i];
            long rightOdd = totalOdd - prefOdd[i];
            // after removal, right side indices flip parity
            long newEven = leftEven + rightOdd;
            long newOdd = leftOdd + rightEven;
            if (newEven == newOdd) {
                count++;
            }
        }
        return count;
    }
}

