import java.util.*;

public class Solution {
    public int countStudents(int[] students, int[] sandwiches) {
        int[] prefCount = new int[2];
        for (int s : students) {
            prefCount[s]++;
        }
        for (int sandwich : sandwiches) {
            if (prefCount[sandwich] > 0) {
                prefCount[sandwich]--;
            } else {
                // No student wants this sandwich, all remaining students cannot eat
                return prefCount[0] + prefCount[1];
            }
        }
        // All sandwiches taken
        return 0;
    }
}

