import java.util.Arrays;

public class Solution {
    public int minimumMountainRemovals(int[] nums) {
        int n = nums.length;
        int[] lis = new int[n];
        int[] lds = new int[n];

        // Longest Increasing Subsequence ending at each index
        int[] tails = new int[n];
        int size = 0;
        for (int i = 0; i < n; i++) {
            int pos = Arrays.binarySearch(tails, 0, size, nums[i]);
            if (pos < 0) {
                pos = -pos - 1;
            }
            tails[pos] = nums[i];
            lis[i] = pos + 1;
            if (pos == size) {
                size++;
            }
        }

        // Longest Decreasing Subsequence starting at each index
        Arrays.fill(tails, 0);
        size = 0;
        for (int i = n - 1; i >= 0; i--) {
            int pos = Arrays.binarySearch(tails, 0, size, nums[i]);
            if (pos < 0) {
                pos = -pos - 1;
            }
            tails[pos] = nums[i];
            lds[i] = pos + 1;
            if (pos == size) {
                size++;
            }
        }

        int maxMountain = 0;
        for (int i = 0; i < n; i++) {
            if (lis[i] > 1 && lds[i] > 1) {
                int length = lis[i] + lds[i] - 1;
                if (length > maxMountain) {
                    maxMountain = length;
                }
            }
        }

        return n - maxMountain;
    }
}

