public class Solution {
    public int minimumMountainRemovals(int[] nums) {
        int n = nums.length;
        int[] lis = new int[n];
        int[] lds = new int[n];

        // Compute LIS ending at each i
        int[] tails = new int[n];
        int size = 0;
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            int pos = Arrays.binarySearch(tails, 0, size, x);
            if (pos < 0) pos = -pos - 1;
            tails[pos] = x;
            if (pos == size) size++;
            lis[i] = pos + 1;
        }

        // Compute LDS starting at each i (LIS on reversed array)
        size = 0;
        for (int i = n - 1; i >= 0; i--) {
            int x = nums[i];
            int pos = Arrays.binarySearch(tails, 0, size, x);
            if (pos < 0) pos = -pos - 1;
            tails[pos] = x;
            if (pos == size) size++;
            lds[i] = pos + 1;
        }

        int best = 0;
        for (int i = 1; i < n - 1; i++) {
            if (lis[i] > 1 && lds[i] > 1) {
                best = Math.max(best, lis[i] + lds[i] - 1);
            }
        }
        return n - best;
    }
}

