        int[] dec = new int[n]; // LDS starting at i (computed as LIS on reversed)

        List<Integer> tails = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            int idx = Collections.binarySearch(tails, x);
            if (idx < 0) {
                idx = -idx - 1;
            }
            if (idx == tails.size()) {
                tails.add(x);
            } else {
                tails.set(idx, x);
            }
            inc[i] = idx + 1;
        }

        List<Integer> tailsRev = new ArrayList<>();
        for (int i = n - 1; i >= 0; i--) {
            int x = nums[i];
            int idx = Collections.binarySearch(tailsRev, x);
            if (idx < 0) {
                idx = -idx - 1;
            }
            if (idx == tailsRev.size()) {
                tailsRev.add(x);
            } else {
                tailsRev.set(idx, x);
            }
            dec[i] = idx + 1;
        }

        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            if (inc[i] > 1 && dec[i] > 1) {
                int len = inc[i] + dec[i] - 1;
                if (len > maxLen) {
                    maxLen = len;
                }
            }
        }

        return n - maxLen;
    }
