import java.util.PriorityQueue;
import java.util.Comparator;

public class Solution {
    public int minimumEffortPath(int[][] heights) {
        if (heights == null || heights.length == 0 || heights[0].length == 0) {
            return 0;
        }
        int rows = heights.length;
        int cols = heights[0].length;
        int[][] dist = new int[rows][cols];
        final int INF = Integer.MAX_VALUE;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                dist[i][j] = INF;
            }
        }
        // min-heap ordered by effort
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        dist[0][0] = 0;
        pq.offer(new int[]{0, 0, 0}); // {effort, row, col}
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int effort = cur[0];
            int r = cur[1];
            int c = cur[2];

            if (r == rows - 1 && c == cols - 1) {
                return effort;
            }

            // If we have already found a better path to this cell, skip
            if (effort > dist[r][c]) {
                continue;
            }

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                int edge = Math.abs(heights[nr][nc] - heights[r][c]);
                int newEffort = Math.max(effort, edge);
                if (newEffort < dist[nr][nc]) {
                    dist[nr][nc] = newEffort;
                    pq.offer(new int[]{newEffort, nr, nc});
                }
            }
        }
        // Should never reach here because a path always exists
        return -1;
    }
}

