public class Solution {
    public int stoneGameVII(int[] stones) {
        int n = stones.length;
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + stones[i];
        }

        int[][] dp = new int[n][n]; // dp[i][j] = max difference for subarray i..j

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                int sumRemoveLeft = prefix[j + 1] - prefix[i + 1]; // sum of stones i+1..j
                int sumRemoveRight = prefix[j] - prefix[i];       // sum of stones i..j-1

                int leftChoice = sumRemoveLeft - dp[i + 1][j];
                int rightChoice = sumRemoveRight - dp[i][j - 1];

                dp[i][j] = Math.max(leftChoice, rightChoice);
            }
        }

        return dp[0][n - 1];
    }
}

