import java.math.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    private long modPow(long base, long exp) {
        long result = 1L;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    public int numberOfSets(int n, int k) {
        if (k == 0) return 1;
        long N = (long) n + k - 1;          // total items to choose from
        int M = 2 * k;                      // number of items to choose
        if (N < M) return 0;                // not enough points

        long numerator = 1L;
        for (long i = N - M + 1; i <= N; i++) {
            numerator = (numerator * (i % MOD)) % MOD;
        }

        long denominator = 1L;
        for (int i = 2; i <= M; i++) {
            denominator = (denominator * i) % MOD;
        }

        long invDenominator = modPow(denominator, MOD - 2);
        long result = (numerator * invDenominator) % MOD;
        return (int) result;
    }
}

