import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    private static long modPow(long a, long e) {
        long res = 1L;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * a) % MOD;
            }
            a = (a * a) % MOD;
            e >>= 1;
        }
        return res;
    }

    private static long modInv(long a) {
        return modPow(a, MOD - 2);
    }

    private static long binom(int n, int k, long[] fact, long[] invFact) {
        if (k < 0 || k > n) return 0;
        return (((fact[n] * invFact[k]) % MOD) * invFact[n - k]) % MOD;
    }

    public int numberOfSets(int n, int k) {
        if (k == 0) return 1;
        if (n < k + 1) return 0;
        int N = n + k - 1;
        int R = 2 * k;
        long[] fact = new long[N + 1];
        long[] invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        invFact[N] = modInv(fact[N]);
        for (int i = N; i > 0; i--) {
            invFact[i - 1] = (invFact[i] * i) % MOD;
        }
        long ans = binom(N, R, fact, invFact);
        return (int) ans;
    }
}

