public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfSets(int n, int k) {
        // dp[i][j]: number of ways using first i points (0..i-1) with exactly j segments
        int[][] dp = new int[n + 1][k + 1];
        int[][] pref = new int[n + 1][k + 1];

        dp[0][0] = 1;
        pref[0][0] = 1;
        // pref[0][j] for j>0 stays 0 (already default)

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                // start with configurations that do not use point i-1 as right endpoint
                int val = dp[i - 1][j];

                if (j > 0) {
                    // add configurations where a new segment ends at i-1
                    int add = pref[i - 1][j - 1];
                    if (j == 1) {
                        // subtract the case where the previous part is empty (dp[0][0])
                        add = (add - 1 + MOD) % MOD;
                    }
                    val = (val + add) % MOD;
                }

                dp[i][j] = val;
                pref[i][j] = (pref[i - 1][j] + dp[i][j]) % MOD;
            }
        }

        return dp[n][k];
    }
}

