import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.TreeSet;

public class Solution {
    private static class BusyServer {
        int id;
        long finishTime;

        BusyServer(int id, long finishTime) {
            this.id = id;
            this.finishTime = finishTime;
        }
    }

    public List<Integer> busiestServers(int k, int[] arrival, int[] load) {
        int n = arrival.length;
        int[] requestCount = new int[k];
        TreeSet<Integer> available = new TreeSet<>();
        for (int i = 0; i < k; i++) {
            available.add(i);
        }

        PriorityQueue<BusyServer> busy = new PriorityQueue<>(
                (a, b) -> Long.compare(a.finishTime, b.finishTime));

        for (int i = 0; i < n; i++) {
            long curTime = arrival[i];

            // Release servers that have finished by curTime
            while (!busy.isEmpty() && busy.peek().finishTime <= curTime) {
                BusyServer freed = busy.poll();
                available.add(freed.id);
            }

            if (available.isEmpty()) {
                // all servers busy, drop request
                continue;
            }

            int target = i % k;
            Integer serverId = available.ceiling(target);
            if (serverId == null) {
                serverId = available.first();
            }

            // Assign request to serverId
            available.remove(serverId);
            requestCount[serverId]++;
            long finish = curTime + load[i];
            busy.offer(new BusyServer(serverId, finish));
        }

        int max = 0;
        for (int cnt : requestCount) {
            if (cnt > max) {
                max = cnt;
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (requestCount[i] == max) {
                result.add(i);
            }
        }
        return result;
    }
}

