            if ((turn & 1) == 0) { // Alice's turn
                aliceScore += aliceValues[i];
            } else { // Bob's turn
                bobScore += bobValues[i];
            }
        }

        if (aliceScore > bobScore) {
            return 1;
        } else if (aliceScore < bobScore) {
            return -1;
        } else {
            return 0;
        }
    }
