public class Solution {
    // Disjoint Set Union (Union-Find) implementation
    private static class Dsu {
        private final int[] parent;
        private final int[] rank;

        public Dsu(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return;
            // union by rank
            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
            } else if (rank[rx] > rank[ry]) {
                parent[ry] = rx;
            } else {
                parent[ry] = rx;
                rank[rx]++;
            }
        }
    }

    // Query holder with original index
    private static class Query implements Comparable<Query> {
        int p, q, limit, idx;

        Query(int p, int q, int limit, int idx) {
            this.p = p;
            this.q = q;
            this.limit = limit;
            this.idx = idx;
        }

        @Override
        public int compareTo(Query o) {
            return Integer.compare(this.limit, o.limit);
        }
    }

    /**
     * Determines for each query whether there exists a path between p and q
     * using only edges with distance strictly less than limit.
     *
     * @param n        number of nodes (0 .. n-1)
     * @param edgeList edges where edgeList[i] = [u, v, distance]
     * @param queries  queries where queries[i] = [p, q, limit]
     * @return boolean array of answers
     */
    public boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        // Sort edges by distance ascending
        Arrays.sort(edgeList, (a, b) -> Integer.compare(a[2], b[2]));

        // Prepare queries with original indices
        Query[] qs = new Query[queries.length];
        for (int i = 0; i < queries.length; i++) {
            qs[i] = new Query(queries[i][0], queries[i][1], queries[i][2], i);
        }
        Arrays.sort(qs);

        boolean[] answer = new boolean[queries.length];
        Dsu dsu = new Dsu(n);
        int eIdx = 0;

        // Process each query in order of increasing limit
        for (Query q : qs) {
            // Union all edges with weight < current limit
            while (eIdx < edgeList.length && edgeList[eIdx][2] < q.limit) {
                dsu.union(edgeList[eIdx][0], edgeList[eIdx][1]);
                eIdx++;
            }
            // Check connectivity
            answer[q.idx] = dsu.find(q.p) == dsu.find(q.q);
        }
        return answer;
    }
}

