import java.util.HashMap;
import java.util.Map;

public class Solution {
    private final Map<Integer, Integer> memo = new HashMap<>();

    public int minimumOneBitOperations(int n) {
        return dfs(n);
    }

    private int dfs(int n) {
        if (n == 0) {
            return 0;
        }
        if (memo.containsKey(n)) {
            return memo.get(n);
        }
        int msbPos = 31 - Integer.numberOfLeadingZeros(n); // position of highest set bit
        int msb = 1 << msbPos;                               // 2^msbPos
        int allOnes = (1 << (msbPos + 1)) - 1;               // binary string of (msbPos+1) ones
        int result = allOnes - dfs(n - msb);
        memo.put(n, result);
        return result;
    }
}

