public class Solution {
    public int specialArray(int[] nums) {
        if (nums == null || nums.length == 0) {
            return -1;
        }
        // Sort in descending order
        Arrays.sort(nums);
        int n = nums.length;
        // After sorting ascending, we can access from the end for descending order
        for (int i = 0; i < n; i++) {
            int x = i + 1; // candidate value: exactly x numbers should be >= x
            int val = nums[n - 1 - i]; // i-th largest element
            if (val >= x) {
                // Check the next element (i+1)-th largest, if it exists, is < x
                if (i == n - 1 || nums[n - 2 - i] < x) {
                    return x;
                }
            }
        }
        return -1;
    }
