public class Solution {
    public int specialArray(int[] nums) {
        if (nums == null) {
            return -1;
        }
        Arrays.sort(nums);
        int n = nums.length;
        // possible x ranges from 0 to n (inclusive)
        for (int x = 0; x <= n; x++) {
            // find first index where nums[idx] >= x using binary search
            int idx = firstGreaterOrEqual(nums, x);
            int count = n - idx; // numbers >= x
            if (count == x) {
                return x;
            }
        }
        return -1;
    }

    // returns the smallest index i such that arr[i] >= target,
    // or arr.length if all elements are < target
    private int firstGreaterOrEqual(int[] arr, int target) {
        int left = 0;
        int right = arr.length; // exclusive
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

