public class Solution {
    public int minimumDeletions(String s) {
        int n = s.length();
        if (n == 0) return 0;

        // total number of 'a' characters in the whole string
        int totalA = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == 'a') totalA++;
        }

        int bSeen = 0;      // number of 'b' characters seen so far (to be deleted if they appear before the split)
        int aSeen = 0;      // number of 'a' characters seen so far
        int minDeletions = Integer.MAX_VALUE;

        // consider split before each character (including before first and after last)
        // split at position i means characters [0, i-1] are kept as 'a's, characters [i, n-1] are kept as 'b's
        // deletions = bSeen (b's before split) + (totalA - aSeen) (a's after split)
        for (int i = 0; i <= n; i++) {
            int deletions = bSeen + (totalA - aSeen);
            if (deletions < minDeletions) {
                minDeletions = deletions;
            }
            if (i == n) break; // avoid out of bounds
            char c = s.charAt(i);
            if (c == 'b') {
                bSeen++;
            } else { // c == 'a'
                aSeen++;
            }
        }

        return minDeletions;
    }
}

