public class Solution {
    public int minimumDeletions(String s) {
        int deletionsAllA = 0; // deletions to make prefix all 'a'
        int deletionsBalanced = 0; // deletions to make prefix balanced (a* b*)
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == 'a') {
                // keep 'a' for all-a prefix, no extra deletion
                // for balanced prefix, either delete this 'a' (deletionsBalanced+1)
                // or treat whole prefix as all-a (deletionsAllA)
                deletionsBalanced = Math.min(deletionsAllA, deletionsBalanced + 1);
                // deletionsAllA stays the same
            } else { // c == 'b'
                // to keep all-a prefix, we must delete this 'b'
                deletionsAllA = deletionsAllA + 1;
                // for balanced prefix, we can keep this 'b' (no extra deletion) or delete it
                deletionsBalanced = Math.min(deletionsAllA, deletionsBalanced);
            }
        }
        return deletionsBalanced;
    }
