public class Solution {
    public int minimumDeletions(String s) {
        int n = s.length();
        // prefixB[i] = number of 'b' in s[0..i-1]
        int[] prefixB = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            prefixB[i] = prefixB[i - 1] + (s.charAt(i - 1) == 'b' ? 1 : 0);
        }
        // suffixA[i] = number of 'a' in s[i..n-1]
        int[] suffixA = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffixA[i] = suffixA[i + 1] + (s.charAt(i) == 'a' ? 1 : 0);
        }
        int ans = n; // worst case delete all characters
        for (int i = 0; i <= n; i++) {
            int deletions = prefixB[i] + suffixA[i];
            if (deletions < ans) {
                ans = deletions;
            }
        }
        return ans;
    }
}

