            players[i][0] = ages[i];
            players[i][1] = scores[i];
        }

        Arrays.sort(players, (a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]); // sort by age
            }
            return Integer.compare(a[1], b[1]); // then by score
        });

        int[] dp = new int[n];
        int maxScore = 0;
        for (int i = 0; i < n; i++) {
            dp[i] = players[i][1]; // team consisting of only this player
            for (int j = 0; j < i; j++) {
                if (players[j][1] <= players[i][1]) { // no conflict
                    dp[i] = Math.max(dp[i], dp[j] + players[i][1]);
                }
            }
            maxScore = Math.max(maxScore, dp[i]);
        }
        return maxScore;
    }
}

