import java.util.Arrays;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        int n = inventory.length;
        // work from largest to smallest, add a sentinel 0 at the beginning for easier handling
        long[] inv = new long[n + 1];
        for (int i = 0; i < n; i++) {
            inv[i + 1] = inventory[n - 1 - i]; // descending order
        }
        // inv[0] = 0 sentinel (already 0)
        long result = 0;
        int i = 1; // current index in inv (1‑based, inv[1] is the largest count)
        while (orders > 0 && i <= n) {
            long cur = inv[i];
            long next = (i == n) ? 0 : inv[i + 1];
            long cnt = i; // number of colors with at least 'cur' balls
            long diff = cur - next; // how many levels we can drop completely
            long totalBalls = cnt * diff;
            if (orders >= totalBalls) {
                // take all balls from cur down to next+1
                long sum = arithmeticSum(next + 1, cur);
                result = (result + (cnt % MOD) * (sum % MOD)) % MOD;
                orders -= totalBalls;
                i++;
            } else {
                // we can only drop partially
                long fullLevels = orders / cnt; // complete levels we can drop
                long remainder = orders % cnt;
                long low = cur - fullLevels + 1;
                long high = cur;
                long sum = arithmeticSum(low, high);
                result = (result + (cnt % MOD) * (sum % MOD)) % MOD;
                // add the remaining balls, each valued at (cur - fullLevels)
                long val = cur - fullLevels;
                result = (result + (remainder % MOD) * (val % MOD)) % MOD;
                orders = 0;
            }
        }
        return (int) (result % MOD);
    }

    // sum of integers from l to r inclusive, assuming l <= r
    private long arithmeticSum(long l, long r) {
        long count = r - l + 1;
        // use formula count * (l + r) / 2, careful with overflow
        return (count % MOD) * ((l + r) % MOD) % MOD * inv2() % MOD;
    }

    // modular inverse of 2 under MOD (since MOD is prime)
    private long inv2() {
        return (MOD + 1) / 2; // 500000004
    }
}

