public class Solution {
    private static final int MOD = 1_000_000_007;

    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        int n = inventory.length;
        long profit = 0;
        int idx = n - 1; // start from largest
        long cur = inventory[idx];
        while (orders > 0 && cur > 0) {
            // count how many colors have the current value
            int count = 0;
            while (idx >= 0 && inventory[idx] == cur) {
                count++;
                idx--;
            }
            // next lower value (or 0 if none left)
            long next = idx >= 0 ? inventory[idx] : 0;
            long diff = cur - next; // how many levels we can drop
            long ballsAvailable = diff * count; // total balls we could sell down to 'next'

            if (orders >= ballsAvailable) {
                // sell all balls down to 'next'
                long sum = arithmeticSum(next + 1, cur) % MOD;
                profit = (profit + (sum * count) % MOD) % MOD;
                orders -= ballsAvailable;
                cur = next;
            } else {
                // we can only sell part of these levels
                long fullLevels = orders / count; // complete layers we can sell
                long remainder = orders % count;   // extra balls at the next lower price

                long low = cur - fullLevels + 1;
                long high = cur;
                long sumFull = arithmeticSum(low, high) % MOD;
                profit = (profit + (sumFull * count) % MOD) % MOD;

                long priceForRemainder = cur - fullLevels;
                profit = (profit + (priceForRemainder % MOD) * (remainder % MOD)) % MOD;

                orders = 0; // all orders fulfilled
            }
        }
        return (int) (profit % MOD);
    }

    // sum of integers from low to high inclusive
    private long arithmeticSum(long low, long high) {
        long count = high - low + 1;
        // Use formula count * (low + high) / 2, handle even/odd to avoid overflow
        if ((count & 1) == 0) {
            count /= 2;
        } else {
            long sum = low + high;
            if ((sum & 1) == 0) {
                sum /= 2;
                return (count % MOD) * (sum % MOD) % MOD;
            } else {
                // both odd, multiply then divide
                return (count % MOD) * ((low + high) % MOD) % MOD * ((MOD + 1) / 2) % MOD;
            }
        }
        return (count % MOD) * ((low + high) % MOD) % MOD;
    }
}

