public class Solution {
    public int maxHeight(int[][] arr) {
        if (arr == null || arr.length == 0) {
            return 0;
        }

        // Normalize each cuboid by sorting its dimensions (allow rotation)
        for (int[] cuboid : arr) {
            Arrays.sort(cuboid);
        }

        // Sort cuboids lexicographically by dimensions
        Arrays.sort(arr, new Comparator<int[]>() {
