public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int maxSum = 2 * limit;
        int[] diff = new int[maxSum + 2]; // extra slot for high+1

        // Initially assume 2 moves for every possible sum
        diff[2] += 2;
        diff[maxSum + 1] -= 2;

        for (int i = 0; i < n / 2; i++) {
            int a = nums[i];
            int b = nums[n - 1 - i];
            int low = Math.min(a, b) + 1;
            int high = Math.max(a, b) + limit;
            int sum = a + b;

            // sums that can be achieved with 1 move (instead of 2)
            diff[low] -= 1;
            diff[high + 1] += 1;

            // exact sum needs 0 moves (instead of 1)
            diff[sum] -= 1;
            diff[sum + 1] += 1;
        }

        int minMoves = Integer.MAX_VALUE;
        int cur = 0;
        for (int s = 2; s <= maxSum; s++) {
            cur += diff[s];
            if (cur < minMoves) {
                minMoves = cur;
            }
        }
        return minMoves;
    }
}

