public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int pairs = n / 2;
        int maxSum = 2 * limit;
        int[] diff = new int[maxSum + 2];   // for range updates
        int[] exact = new int[maxSum + 2];  // counts of sums that need 0 moves

        for (int i = 0; i < pairs; i++) {
            int a = nums[i];
            int b = nums[n - 1 - i];
            int sum = a + b;
            exact[sum]++;

            int low = Math.min(a, b) + 1;
            int high = Math.max(a, b) + limit;

            diff[low] += 1;
            diff[high + 1] -= 1;
        }

        int minMoves = Integer.MAX_VALUE;
        int cur = 0; // number of pairs that can be fixed with at most 1 move for current sum
        for (int s = 2; s <= maxSum; s++) {
            cur += diff[s];
            // pairs - cur need 2 moves, cur - exact[s] need 1 move, exact[s] need 0 moves
            int moves = (pairs - cur) * 2 + (cur - exact[s]) * 1;
            if (moves < minMoves) {
                minMoves = moves;
            }
        }
        return minMoves;
    }
}

