public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int pairs = n / 2;
        int maxSum = 2 * limit;
        int[] diff = new int[maxSum + 2]; // difference array

        for (int i = 0; i < pairs; i++) {
