            // zero move needed for the current sum
            int curSum = a + b;
            diff[curSum] -= 1;
            if (curSum + 1 <= maxSum) {
                diff[curSum + 1] += 1;
            }
        }

        int minMoves = Integer.MAX_VALUE;
        int curAdjustment = 0;
        int base = 2 * pairs; // assume 2 moves per pair

        for (int sum = 2; sum <= maxSum; sum++) {
            curAdjustment += diff[sum];
            int moves = base + curAdjustment;
            if (moves < minMoves) {
                minMoves = moves;
            }
        }

        return minMoves;
    }
}

