import java.util.HashMap;
import java.util.Map;

public class Solution {
    // count the characters of every sticker
    // For each character, save the sticker index which has this character
    public int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        int[][] stickerCounts = new int[n][26];
        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) {
                stickerCounts[i][c - 'a']++;
            }
        }
        Map<String, Integer> memo = new HashMap<>();
        memo.put("", 0);
        int result = dfs(target, stickerCounts, memo);
        return result;
    }

    private int dfs(String target, int[][] stickers, Map<String, Integer> memo) {
        if (memo.containsKey(target)) {
            return memo.get(target);
        }

        int[] targetCount = new int[26];
        for (char c : target.toCharArray()) {
            targetCount[c - 'a']++;
        }

        int ans = Integer.MAX_VALUE;
        // try each sticker
        for (int[] sticker : stickers) {
            // optimization: skip stickers that don't contain the first needed character
            if (sticker[target.charAt(0) - 'a'] == 0) {
                continue;
            }

            // build the remaining string after using this sticker
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 26; i++) {
                int remain = targetCount[i] - sticker[i];
                for (int k = 0; k < remain; k++) {
                    sb.append((char) ('a' + i));
                }
            }
            String next = sb.toString();
            if (next.length() < target.length()) { // progress made
                int sub = dfs(next, stickers, memo);
                if (sub != -1) {
                    ans = Math.min(ans, 1 + sub);
                }
            }
        }

        int res = (ans == Integer.MAX_VALUE) ? -1 : ans;
        memo.put(target, res);
        return res;
    }
}

