import java.util.*;

public class Solution {
    public int minStickers(String[] stickers, String target) {
        int m = target.length();
        if (m == 0) return 0;

        // count of each sticker
        int[][] stickerCounts = new int[stickers.length][26];
        for (int i = 0; i < stickers.length; i++) {
            for (char c : stickers[i].toCharArray()) {
                stickerCounts[i][c - 'a']++;
            }
        }

        // DP over subsets of target positions
        int fullMask = (1 << m) - 1;
        int[] dp = new int[1 << m];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        // Precompute target chars for quick access
        char[] targetChars = target.toCharArray();

        for (int mask = 0; mask <= fullMask; mask++) {
            if (dp[mask] == Integer.MAX_VALUE) continue; // unreachable state
            for (int[] cnt : stickerCounts) {
                int[] curCnt = cnt.clone();
                int newMask = mask;
                // try to apply this sticker to uncovered positions
                for (int i = 0; i < m; i++) {
                    if ((newMask & (1 << i)) != 0) continue; // already covered
                    int idx = targetChars[i] - 'a';
                    if (curCnt[idx] > 0) {
                        curCnt[idx]--;
                        newMask |= (1 << i);
                    }
                }
