    private int dfs(int mask, int fullMask, char[] targetChars, int[][] stickerCounts, Integer[] memo) {
        if (mask == fullMask) {
            return 0;
        }
        if (memo[mask] != null) {
            return memo[mask];
        }
        int m = targetChars.length;
        int best = Integer.MAX_VALUE;

        for (int[] sticker : stickerCounts) {
            // optimization: skip stickers that don't contain the first uncovered character
            int firstUncoveredIdx = -1;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) == 0) {
                    firstUncoveredIdx = i;
                    break;
