                continue; // this sticker cannot help with the current uncovered part
            }

            int newMask = applySticker(mask, targetChars, sticker);
            if (newMask != mask) { // sticker made progress
                int sub = dfs(newMask, fullMask, targetChars, stickerCounts, memo);
                if (sub != Integer.MAX_VALUE) {
                    best = Math.min(best, 1 + sub);
                }
            }
        }

        memo[mask] = best;
        return best;
    }

