                if (cnt[c - 'a'] > 0) {
                    useful = true;
                    break;
                }
            }
            if (useful) {
                usefulStickers.add(cnt);
            }
        }

        // memoization for DP over masks
        int[] memo = new int[1 << m];
        Arrays.fill(memo, -1);
        memo[fullMask] = 0; // all characters covered needs 0 stickers

        int ans = dfs(0, target.toCharArray(), usefulStickers, memo, fullMask);
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }

    private int dfs(int mask, char[] target, List<int[]> stickers,
                    int[] memo, int fullMask) {
        if (mask == fullMask) return 0;
        if (memo[mask] != -1) return memo[mask];

        int best = Integer.MAX_VALUE;
        for (int[] sticker : stickers) {
            // try to apply this sticker
            int[] cnt = sticker.clone();
            int newMask = mask;
            for (int i = 0; i < target.length; i++) {
                if ((newMask >> i & 1) == 0) { // not yet covered
