public class Solution {
    public boolean hasAlternatingBits(int n) {
        // XOR the number with its right-shifted version.
        // If the bits are alternating, the result will be a sequence of all 1's.
        int x = n ^ (n >> 1);
        // A number that is a sequence of all 1's has the property that x & (x + 1) == 0.
        return (x & (x + 1)) == 0;
    }
}

