        for (int i = 0; i < m; i++) {
            if (windowSum[i] > windowSum[bestIdx]) {
                bestIdx = i;
            }
            left[i] = bestIdx;
        }

        // right[i] = index of max sum window in [i..m-1]
        int[] right = new int[m];
        bestIdx = m - 1;
        for (int i = m - 1; i >= 0; i--) {
            if (windowSum[i] >= windowSum[bestIdx]) { // >= to keep earlier index on ties
                bestIdx = i;
            }
            right[i] = bestIdx;
        }

        int maxTotal = -1;
        int[] answer = new int[3];
