import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    private static class Tree {
        int height;
        int row;
        int col;
        Tree(int h, int r, int c) {
            this.height = h;
            this.row = r;
            this.col = c;
        }
    }

    public int cutOffTree(List<List<Integer>> forest) {
        if (forest == null || forest.isEmpty() || forest.get(0).isEmpty()) {
            return -1;
        }
        int rows = forest.size();
        int cols = forest.get(0).size();

        // Collect all trees
        List<Tree> trees = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int val = forest.get(r).get(c);
                if (val > 1) {
                    trees.add(new Tree(val, r, c));
                }
            }
        }

        // Sort by height
        Collections.sort(trees, Comparator.comparingInt(t -> t.height));

        int totalSteps = 0;
        int curRow = 0;
        int curCol = 0;

        // If starting cell is blocked, impossible
        if (forest.get(0).get(0) == 0) {
            return -1;
        }

        for (Tree tree : trees) {
            int steps = bfs(forest, curRow, curCol, tree.row, tree.col);
            if (steps == -1) {
                return -1;
            }
            totalSteps += steps;
            // cut the tree
            forest.get(tree.row).set(tree.col, 1);
            curRow = tree.row;
            curCol = tree.col;
        }

        return totalSteps;
    }

    private int bfs(List<List<Integer>> forest, int sr, int sc, int tr, int tc) {
        if (sr == tr && sc == tc) {
            return 0;
        }
        int rows = forest.size();
        int cols = forest.get(0).size();
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{sr, sc, 0});
        visited[sr][sc] = true;
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, 1, 0, -1};

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0];
            int c = cur[1];
            int d = cur[2];
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (visited[nr][nc]) continue;
                if (forest.get(nr).get(nc) == 0) continue; // obstacle
                if (nr == tr && nc == tc) {
                    return d + 1;
                }
                visited[nr][nc] = true;
                q.offer(new int[]{nr, nc, d + 1});
            }
        }
        return -1; // unreachable
    }
}

