        PriorityQueue<int[]> trees = new PriorityQueue<>(
                (a, b) -> Integer.compare(a[0], b[0])); // a[0]=height, a[1]=r, a[2]=c

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int val = forest.get(r).get(c);
                if (val > 1) {
                    trees.offer(new int[]{val, r, c});
                }
            }
        }

        int totalSteps = 0;
        int curR = 0, curC = 0;

        while (!trees.isEmpty()) {
            int[] tree = trees.poll();
            int targetR = tree[1];
            int targetC = tree[2];

            int steps = bfs(forest, curR, curC, targetR, targetC);
            if (steps == -1) {
                return -1;
            }
            totalSteps += steps;

            // Cut the tree: turn cell into empty ground (1)
            forest.get(targetR).set(targetC, 1);
            curR = targetR;
            curC = targetC;
        }

        return totalSteps;
    }

    private int bfs(List<List<Integer>> forest, int sr, int sc, int tr, int tc) {
        if (sr == tr && sc == tc) {
            return 0;
        }

        int rows = forest.size();
        int cols = forest.get(0).size();
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{sr, sc, 0});
        visited[sr][sc] = true;

        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, 1, 0, -1};

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            int dist = cur[2];

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];

                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                if (visited[nr][nc] || forest.get(nr).get(nc) == 0) {
                    continue;
                }
                if (nr == tr && nc == tc) {
                    return dist + 1;
                }
                visited[nr][nc] = true;
                queue.offer(new int[]{nr, nc, dist + 1});
            }
        }

        return -1; // target not reachable
    }
}

