public class Solution {
    /**
     * Returns the number of palindromic substrings in the given string.
     *
     * @param s the input string
     * @return the count of palindromic substrings
     */
    public int countSubstrings(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        int n = s.length();
        int count = 0;

        // Expand around each possible center (both odd and even length palindromes)
        for (int center = 0; center < 2 * n - 1; center++) {
            int left = center / 2;
            int right = left + center % 2; // right = left for odd, left+1 for even

            while (left >= 0 && right < n && s.charAt(left) == s.charAt(right)) {
                count++;
                left--;
                right++;
            }
        }

        return count;
    }
}

