public class Solution {
    /**
     * Returns the number of palindromic substrings in the given string.
     *
     * @param s the input string
     * @return the count of palindromic substrings
     */
    public int countSubstrings(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        int n = s.length();
        int count = 0;

        // Expand around each possible center (both odd and even length)
        for (int center = 0; center < n; center++) {
            // Odd length palindromes, single character center
            count += expandAroundCenter(s, center, center);
            // Even length palindromes, between center and center+1
            count += expandAroundCenter(s, center, center + 1);
        }

        return count;
    }

    /**
     * Expands around the given left and right indices and counts palindromes.
     *
     * @param s the input string
     * @param left the left index of the center
     * @param right the right index of the center
     * @return number of palindromic substrings found during expansion
     */
    private int expandAroundCenter(String s, int left, int right) {
        int n = s.length();
        int cnt = 0;
        while (left >= 0 && right < n && s.charAt(left) == s.charAt(right)) {
            cnt++;
            left--;
            right++;
        }
        return cnt;
    }
}

