public class Solution {
    public int findKthNumber(int m, int n, int k) {
        long low = 1;
        long high = (long) m * n;
        while (low < high) {
            long mid = low + (high - low) / 2;
            long cnt = 0;
            for (int i = 1; i <= m; i++) {
                cnt += Math.min(n, (int) (mid / i));
                if (cnt >= k) {
                    break;
                }
            }
            if (cnt >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return (int) low;
    }
}

