    private double[] compute(double a, double b) {
        // +, -, *, /
        // For non‑commutative operations we need both orders
        double[] res = new double[6];
        int idx = 0;
        res[idx++] = a + b;
        res[idx++] = a - b;
        res[idx++] = b - a;
