                double[] candidates = new double[6];
                int cnt = 0;

                // addition
                candidates[cnt++] = a + b;
                // subtraction a - b
                candidates[cnt++] = a - b;
                // subtraction b - a
                candidates[cnt++] = b - a;
                // multiplication
                candidates[cnt++] = a * b;
                // division a / b
                if (Math.abs(b) > EPS) {
                    candidates[cnt++] = a / b;
                }
                // division b / a
                if (Math.abs(a) > EPS) {
                    candidates[cnt++] = b / a;
