import java.util.List;

public class Solution {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word = null; // stores the root word when this node marks end of a root
    }

    private final TrieNode root = new TrieNode();

    private void insert(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
        }
        node.word = word; // mark end of a root
    }

    private String searchRoot(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                break;
            }
            node = node.children[idx];
            if (node.word != null) {
                return node.word; // shortest root found
            }
        }
        return word; // no root matches
    }

    public String replaceWords(List<String> dictionary, String sentence) {
        // Build trie from dictionary
        for (String rootWord : dictionary) {
            if (rootWord != null && !rootWord.isEmpty()) {
                insert(rootWord);
            }
        }

        StringBuilder sb = new StringBuilder();
        int n = sentence.length();
        int i = 0;
        while (i < n) {
            // skip leading spaces (should not happen in well‑formed input)
            while (i < n && sentence.charAt(i) == ' ') {
                sb.append(' ');
                i++;
            }
            if (i >= n) break;

            // extract next word
            int start = i;
            while (i < n && sentence.charAt(i) != ' ') {
                i++;
            }
            String word = sentence.substring(start, i);
            String replacement = searchRoot(word);
            sb.append(replacement);
        }
        return sb.toString();
    }
}

