import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.TreeSet;

public class Solution {
    private static class SegmentTree {
        private final int n;
        private final int[] tree;
        private final int[] lazy;

        SegmentTree(int n) {
            this.n = n;
            this.tree = new int[4 * n];
            this.lazy = new int[4 * n];
            for (int i = 0; i < lazy.length; i++) {
                lazy[i] = -1; // -1 means no pending assignment
            }
        }

        private void push(int node, int l, int r) {
            if (lazy[node] != -1) {
                tree[node] = lazy[node];
                if (l != r) {
                    lazy[node << 1] = lazy[node];
                    lazy[(node << 1) | 1] = lazy[node];
                }
                lazy[node] = -1;
            }
        }

        int query(int node, int l, int r, int ql, int qr) {
            push(node, l, r);
            if (qr < l || ql > r) {
                return 0;
            }
            if (ql <= l && r <= qr) {
                return tree[node];
            }
            int mid = (l + r) >>> 1;
            return Math.max(
                    query(node << 1, l, mid, ql, qr),
                    query((node << 1) | 1, mid + 1, r, ql, qr)
            );
        }

        void update(int node, int l, int r, int ul, int ur, int val) {
            push(node, l, r);
            if (ur < l || ul > r) {
                return;
            }
            if (ul <= l && r <= ur) {
                lazy[node] = val;
                push(node, l, r);
                return;
            }
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ul, ur, val);
            update((node << 1) | 1, mid + 1, r, ul, ur, val);
            tree[node] = Math.max(tree[node << 1], tree[(node << 1) | 1]);
        }
    }

    public List<Integer> fallingSquares(int[][] positions) {
        // 1. coordinate compression
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] p : positions) {
            int left = p[0];
            int size = p[1];
            set.add(left);
            set.add(left + size);
        }
        List<Integer> coords = new ArrayList<>(set);
        Collections.sort(coords);
        HashMap<Integer, Integer> indexMap = new HashMap<>();
        for (int i = 0; i < coords.size(); i++) {
            indexMap.put(coords.get(i), i);
        }

        int intervals = coords.size() - 1; // number of elementary intervals
        SegmentTree seg = new SegmentTree(intervals);

        List<Integer> answer = new ArrayList<>();
        int globalMax = 0;

        for (int[] p : positions) {
            int left = p[0];
            int size = p[1];
            int right = left + size;

            int lIdx = indexMap.get(left);
            int rIdx = indexMap.get(right) - 1; // inclusive interval index

            int curHeight = seg.query(1, 0, intervals - 1, lIdx, rIdx);
            int newHeight = curHeight + size;

            seg.update(1, 0, intervals - 1, lIdx, rIdx, newHeight);

            globalMax = Math.max(globalMax, newHeight);
            answer.add(globalMax);
        }

        return answer;
    }
}

