public class Solution {
    private int[] tree;
    private int[] lazy;

    private void push(int node) {
        if (lazy[node] != 0) {
            tree[node] = lazy[node];
            if (node * 2 < lazy.length) {
                lazy[node * 2] = lazy[node];
                lazy[node * 2 + 1] = lazy[node];
            }
            lazy[node] = 0;
        }
    }

    private int query(int node, int l, int r, int ql, int qr) {
        push(node);
        if (qr < l || ql > r) {
            return 0;
        }
        if (ql <= l && r <= qr) {
            return tree[node];
        }
        int mid = (l + r) >> 1;
        return Math.max(
                query(node * 2, l, mid, ql, qr),
                query(node * 2 + 1, mid + 1, r, ql, qr)
        );
    }

    private void update(int node, int l, int r, int ul, int ur, int value) {
        if (ur < l || ul > r) {
            return;
        }
        if (ul <= l && r <= ur) {
            tree[node] = value;
            lazy[node] = value;
            return;
        }
        push(node);
        int mid = (l + r) >> 1;
        update(node * 2, l, mid, ul, ur, value);
        update(node * 2 + 1, mid + 1, r, ul, ur, value);
        tree[node] = Math.max(tree[node * 2], tree[node * 2 + 1]);
    }

    public List<Integer> fallingSquares(int[][] positions) {
        // Coordinate compression
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] p : positions) {
            int left = p[0];
            int size = p[1];
            set.add(left);
            set.add(left + size);
        }
        List<Integer> coordList = new ArrayList<>(set);
        Collections.sort(coordList);
        HashMap<Integer, Integer> idxMap = new HashMap<>();
        for (int i = 0; i < coordList.size(); i++) {
            idxMap.put(coordList.get(i), i);
        }

        int n = coordList.size();
        if (n <= 1) {
            // No interval, all heights are just the sizes themselves
            List<Integer> res = new ArrayList<>();
            int max = 0;
            for (int[] p : positions) {
                max = Math.max(max, p[1]);
                res.add(max);
            }
            return res;
        }

        // number of intervals = n-1
        int intervals = n - 1;
        tree = new int[intervals * 4];
        lazy = new int[intervals * 4];

        List<Integer> answer = new ArrayList<>();
        int globalMax = 0;

        for (int[] p : positions) {
            int left = p[0];
            int size = p[1];
            int right = left + size;

            int l = idxMap.get(left);
            int r = idxMap.get(right) - 1; // inclusive interval index

            int curMax = query(1, 0, intervals - 1, l, r);
            int newHeight = curMax + size;
            update(1, 0, intervals - 1, l, r, newHeight);
            globalMax = Math.max(globalMax, newHeight);
            answer.add(globalMax);
        }

        return answer;
    }
}

