public class Solution {
    private static class SegmentTree {
        private final int n;
        private final int[] tree;
        private final int[] lazy;
        private final boolean[] hasLazy;

        SegmentTree(int size) {
            this.n = size;
            // allocate 4 * n to be safe
            this.tree = new int[4 * n];
            this.lazy = new int[4 * n];
            this.hasLazy = new boolean[4 * n];
        }

        private void push(int node, int l, int r) {
            if (!hasLazy[node]) return;
            tree[node] = lazy[node];
            if (l != r) {
                int leftChild = node << 1;
                int rightChild = leftChild | 1;
                lazy[leftChild] = lazy[node];
                lazy[rightChild] = lazy[node];
                hasLazy[leftChild] = true;
                hasLazy[rightChild] = true;
            }
            hasLazy[node] = false;
        }

        public int query(int ql, int qr) {
            return query(1, 0, n - 1, ql, qr);
        }

        private int query(int node, int l, int r, int ql, int qr) {
            push(node, l, r);
            if (qr < l || r < ql) return 0;
            if (ql <= l && r <= qr) return tree[node];
            int mid = (l + r) >>> 1;
            int left = query(node << 1, l, mid, ql, qr);
            int right = query((node << 1) | 1, mid + 1, r, ql, qr);
            return Math.max(left, right);
        }

        public void update(int ul, int ur, int val) {
            update(1, 0, n - 1, ul, ur, val);
        }

        private void update(int node, int l, int r, int ul, int ur, int val) {
            push(node, l, r);
            if (ur < l || r < ul) return;
            if (ul <= l && r <= ur) {
                lazy[node] = val;
                hasLazy[node] = true;
                push(node, l, r);
                return;
            }
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ul, ur, val);
            update((node << 1) | 1, mid + 1, r, ul, ur, val);
            tree[node] = Math.max(tree[node << 1], tree[(node << 1) | 1]);
        }
    }

    public List<Integer> fallingSquares(int[][] positions) {
        // coordinate compression
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] p : positions) {
            int left = p[0];
            int size = p[1];
            set.add(left);
            set.add(left + size);
        }
        List<Integer> coords = new ArrayList<>(set);
        Map<Integer, Integer> indexMap = new HashMap<>();
        for (int i = 0; i < coords.size(); i++) {
            indexMap.put(coords.get(i), i);
        }

        // number of elementary intervals between coordinates
        int intervals = Math.max(0, coords.size() - 1);
        SegmentTree st = new SegmentTree(intervals == 0 ? 1 : intervals);
        List<Integer> answer = new ArrayList<>();
        int globalMax = 0;

        for (int[] p : positions) {
            int left = p[0];
            int size = p[1];
            int l = indexMap.get(left);
            int r = indexMap.get(left + size) - 1; // inclusive interval indices

            int curHeight = 0;
            if (intervals > 0 && l <= r) {
                curHeight = st.query(l, r);
            }
            int newHeight = curHeight + size;

            if (intervals > 0 && l <= r) {
                st.update(l, r, newHeight);
            }

            globalMax = Math.max(globalMax, newHeight);
            answer.add(globalMax);
        }

        return answer;
    }
}

