public class Solution {
    public int strangePrinter(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        // Remove consecutive duplicate characters to reduce problem size
        StringBuilder sb = new StringBuilder();
        char prev = 0;
        for (char c : s.toCharArray()) {
            if (c != prev) {
                sb.append(c);
                prev = c;
            }
        }
        char[] chars = sb.toString().toCharArray();
        int n = chars.length;
        int[][] dp = new int[n][n];

        // Base case: single character needs one turn
        for (int i = 0; i < n; i++) {
            dp[i][i] = 1;
        }

        // Fill DP table for increasing lengths
        for (int len = 2; len <= n; len++) {
            for (int l = 0; l + len - 1 < n; l++) {
                int r = l + len - 1;
                // Initialize with worst case: print chars[l..r-1] then chars[r] separately
                dp[l][r] = dp[l][r - 1] + 1;
                // Try to merge printing of chars[r] with a previous same character
                for (int k = l; k < r; k++) {
                    if (chars[k] == chars[r]) {
                        int left = dp[l][k];
                        int middle = (k + 1 <= r - 1) ? dp[k + 1][r - 1] : 0;
                        dp[l][r] = Math.min(dp[l][r], left + middle);
                    }
                }
            }
        }

        return dp[0][n - 1];
    }
}

