        int[][] dp = new int[n][n];

        // DP over intervals, fill from shorter to longer
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1; // single character needs one turn
            for (int j = i + 1; j < n; j++) {
                // worst case: print chars[i..j-1] then print chars[j] separately
                dp[i][j] = dp[i][j - 1] + 1;
                // try to merge printing of chars[j] with a previous same character
                for (int k = i; k < j; k++) {
                    if (chars[k] == chars[j]) {
                        int merged = dp[i][k] + (k + 1 <= j - 1 ? dp[k + 1][j - 1] : 0);
                        if (merged < dp[i][j]) {
                            dp[i][j] = merged;
                        }
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
