public class Solution {
    private static final int MOD = 1_000_000_007;

    public int kInversePairs(int n, int k) {
        // Maximum possible inverse pairs for n numbers
        long maxPairs = (long) n * (n - 1) / 2;
        if (k > maxPairs) {
            return 0;
        }

        int[] dp = new int[k + 1];
        dp[0] = 1; // empty array has 0 inverse pairs

        for (int i = 1; i <= n; i++) {
            int[] next = new int[k + 1];
            next[0] = 1; // only one way to have 0 inverse pairs with i numbers
            for (int j = 1; j <= k; j++) {
                // Using prefix sum to compute dp[i][j]
                int val = (next[j - 1] + dp[j]) % MOD;
                if (j >= i) {
                    val = (val - dp[j - i] + MOD) % MOD;
                }
                next[j] = val;
            }
            dp = next;
        }

        return dp[k];
    }
}

