public class Solution {
    public List<List<String>> findDuplicate(String[] paths) {
        Map<String, List<String>> contentToPaths = new HashMap<>();

        for (String entry : paths) {
            if (entry == null || entry.isEmpty()) continue;

            // Split by space: first part is directory, rest are file entries
            String[] parts = entry.split(" ");
            if (parts.length < 2) continue; // no files

            String dir = parts[0];
            for (int i = 1; i < parts.length; i++) {
                String filePart = parts[i];
                int idxOpen = filePart.indexOf('(');
                int idxClose = filePart.lastIndexOf(')');
                if (idxOpen == -1 || idxClose == -1 || idxClose <= idxOpen) continue;

                String fileName = filePart.substring(0, idxOpen);
                String content = filePart.substring(idxOpen + 1, idxClose);
                String fullPath = dir + "/" + fileName;

                contentToPaths.computeIfAbsent(content, k -> new ArrayList<>()).add(fullPath);
            }
        }

        List<List<String>> result = new ArrayList<>();
        for (List<String> group : contentToPaths.values()) {
            if (group.size() > 1) {
                result.add(group);
            }
        }
        return result;
    }
}

