public class Solution {
    public String solveEquation(String equation) {
        String[] parts = equation.split("=");
        int[] left = parseSide(parts[0]);
        int[] right = parseSide(parts[1]);

        // left[0] = coeff of x on left, left[1] = constant on left
        // right[0] = coeff of x on right, right[1] = constant on right
        int coeff = left[0] - right[0];          // bring x terms to left
        int constant = right[1] - left[1];      // bring constants to right

        if (coeff == 0) {
            if (constant == 0) {
                return "Infinite solutions";
            } else {
                return "No solution";
            }
        } else {
            int x = constant / coeff;
            return "x=" + x;
        }
    }

    private int[] parseSide(String s) {
        int coeff = 0;
        int constant = 0;
        int i = 0;
        int n = s.length();
        int sign = 1; // current sign

        while (i < n) {
            char ch = s.charAt(i);
            if (ch == '+') {
                sign = 1;
                i++;
            } else if (ch == '-') {
                sign = -1;
                i++;
            } else {
                int num = 0;
                boolean isNumber = false;
                while (i < n && Character.isDigit(s.charAt(i))) {
                    num = num * 10 + (s.charAt(i) - '0');
                    i++;
                    isNumber = true;
                }
                if (i < n && s.charAt(i) == 'x') {
                    // term with x
                    if (!isNumber) {
                        num = 1; // implicit coefficient
                    }
                    coeff += sign * num;
                    i++; // skip 'x'
                } else {
                    // constant term
                    constant += sign * num;
                }
                // after processing a term, reset sign to positive for next unless overridden
                sign = 1;
            }
        }
        return new int[]{coeff, constant};
    }
}

