                    num = num * 10 + (s.charAt(i) - '0');
                    i++;
                }
                if (i < n && s.charAt(i) == 'x') {
                    // term with x
                    int value = isNumber ? num : 1;
                    coeff += sign * value;
                    i++; // skip 'x'
                } else {
                    // constant term
                    constant += sign * num;
                }
                // after processing term, reset sign to default '+' for next term
                sign = 1;
            }
        }
        return new int[]{coeff, constant};
    }
}

