public class Solution {
    public int[] findErrorNums(int[] nums) {
        int n = nums.length;
        int xor = 0;
        for (int i = 0; i < n; i++) {
            xor ^= nums[i];
            xor ^= (i + 1);
        }

        int diffBit = xor & -xor;
        int x = 0, y = 0;
        for (int i = 0; i < n; i++) {
            int val = nums[i];
            if ((val & diffBit) != 0) {
                x ^= val;
            } else {
                y ^= val;
            }

            int idx = i + 1;
            if ((idx & diffBit) != 0) {
                x ^= idx;
            } else {
                y ^= idx;
            }
        }

        int duplicate = -1, missing = -1;
        for (int v : nums) {
            if (v == x) {
                duplicate = x;
                missing = y;
                break;
            }
        }
        if (duplicate == -1) {
            duplicate = y;
            missing = x;
        }

        return new int[]{duplicate, missing};
    }
}

