public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        // To record the two edges causing a node to have two parents
        int[] candA = null;
        int[] candB = null;

        // Step 1: check whether there is a node with two parents
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (parent[v] == 0) {
                parent[v] = u;
            } else {
                // v already has a parent
                candA = new int[]{parent[v], v}; // first edge
                candB = new int[]{u, v};         // second edge (the one we will try to remove)
                // Mark this edge as invalid for now
                edge[0] = -1;
                edge[1] = -1;
            }
        }

        // Union-Find initialization
        int[] dsu = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            dsu[i] = i;
        }

        // Helper functions for Union-Find
        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            @Override
            public int applyAsInt(int x) {
                if (dsu[x] != x) {
                    dsu[x] = applyAsInt(dsu[x]);
                }
                return dsu[x];
            }
        };

        // Step 2: process edges, skipping the second candidate edge if it exists
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (u == -1 && v == -1) {
                // this edge was the second parent edge; skip it
                continue;
            }
            int pu = find.applyAsInt(u);
            int pv = find.applyAsInt(v);
            if (pu == pv) {
                // Cycle detected
                if (candA == null) {
                    // No node with two parents, return current edge
                    return new int[]{u, v};
                } else {
                    // Node with two parents exists, return the first edge
                    return candA;
                }
            }
            dsu[pv] = pu; // union
        }

        // If we reach here, there was a node with two parents but no cycle
        // Return the second edge (the one we initially marked)
        return candB;
    }
}

