public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] firstParent = new int[n + 1]; // stores the first parent of each node
        int[] cand1 = null; // earlier edge causing two parents
        int[] cand2 = null; // later edge causing two parents

        // Detect a node with two parents
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (firstParent[v] == 0) {
                firstParent[v] = u;
            } else {
                // node v has two incoming edges
                cand1 = new int[] { firstParent[v], v };
                cand2 = new int[] { u, v };
                // we continue scanning to keep the structure of firstParent unchanged
            }
        }

        DSU dsu = new DSU(n);

        // Perform Union-Find, optionally skipping cand2
        for (int[] edge : edges) {
            if (cand2 != null && edge[0] == cand2[0] && edge[1] == cand2[1]) {
                // skip the later edge when a node has two parents
                continue;
            }
            int u = edge[0];
            int v = edge[1];
            int pu = dsu.find(u);
            int pv = dsu.find(v);
            if (pu == pv) {
                // Cycle detected
                if (cand1 != null) {
                    // Two‑parent situation exists; the earlier edge must be removed
                    return cand1;
                } else {
                    // No two‑parent situation; this edge creates the cycle
                    return edge;
                }
            }
            dsu.union(pu, pv);
        }

        // If we reach here, skipping cand2 eliminated the cycle
        // Hence cand2 (the later edge) is the redundant one
        return cand2;
    }

    // Union‑Find (Disjoint Set Union) with path compression and union by rank
    private static class DSU {
        private final int[] parent;
        private final int[] rank;

        DSU(int size) {
            parent = new int[size + 1];
            rank = new int[size + 1];
            for (int i = 0; i <= size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return;
            }
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }
}

