                cand2 = new int[]{u, v};
                // mark this edge to be ignored later
                e[0] = -1; // temporary marker
            }
        }

        // Union-Find functions
        class DSU {
            int[] p;
            int[] rank;
            DSU(int size) {
                p = new int[size];
                rank = new int[size];
                for (int i = 0; i < size; i++) p[i] = i;
            }
            int find(int x) {
                if (p[x] != x) p[x] = find(p[x]);
                return p[x];
            }
            boolean union(int x, int y) {
                int rx = find(x);
                int ry = find(y);
                if (rx == ry) return false;
                if (rank[rx] < rank[ry]) {
                    p[rx] = ry;
                } else if (rank[rx] > rank[ry]) {
                    p[ry] = rx;
                } else {
                    p[ry] = rx;
                    rank[rx]++;
                }
                return true;
