public class Solution {
    public int repeatedStringMatch(String a, String b) {
        if (a == null || b == null) {
            return -1;
        }
        int aLen = a.length();
        int bLen = b.length();
        if (aLen == 0) {
            return bLen == 0 ? 0 : -1;
        }

        // Minimum repetitions needed to cover b length
        int minRepeats = (bLen + aLen - 1) / aLen; // ceil(bLen / aLen)

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < minRepeats; i++) {
            sb.append(a);
        }
        if (sb.indexOf(b) != -1) {
            return minRepeats;
        }
        // One more repetition might be required
        sb.append(a);
        if (sb.indexOf(b) != -1) {
            return minRepeats + 1;
        }
        return -1;
    }
}

