        // Sort courses by their lastDay (deadline) ascending
        Arrays.sort(courses, (a, b) -> Integer.compare(a[1], b[1]));

        // Max-heap to keep durations of courses we have taken
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);

        long totalTime = 0; // use long to avoid overflow

        for (int[] course : courses) {
            int duration = course[0];
            int lastDay = course[1];

            totalTime += duration;
            maxHeap.offer(duration);

            // If we exceed the current deadline, remove the longest duration course
            if (totalTime > lastDay) {
                int longest = maxHeap.poll();
                totalTime -= longest;
            }
        }

        return maxHeap.size();
    }
}

