import java.util.Arrays;
import java.util.Collections;
import java.util.PriorityQueue;

public class Solution {
    public int scheduleCourse(int[][] courses) {
        // Sort courses by their deadlines (lastDay)
        Arrays.sort(courses, (a, b) -> Integer.compare(a[1], b[1]));

        // Max-heap to keep durations of courses we have taken
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        int totalTime = 0;

        for (int[] course : courses) {
            int duration = course[0];
            int lastDay = course[1];

            if (totalTime + duration <= lastDay) {
                // We can take this course directly
                totalTime += duration;
                maxHeap.offer(duration);
            } else if (!maxHeap.isEmpty() && maxHeap.peek() > duration) {
                // Replace the longest course taken so far with the current shorter one
                totalTime += duration - maxHeap.poll();
                maxHeap.offer(duration);
            }
            // else: cannot take this course, skip it
        }

        return maxHeap.size();
    }
}

