public class Solution {
    private static final int[] DR = { -2, -2, -1, -1, 1, 1, 2, 2 };
    private static final int[] DC = { -1, 1, -2, 2, -2, 2, -1, 1 };

    public double knightProbability(int n, int k, int row, int column) {
        if (k == 0) {
            return 1.0;
        }

        double[][] dp = new double[n][n];
        dp[row][column] = 1.0;

        for (int step = 0; step < k; step++) {
            double[][] next = new double[n][n];
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    double prob = dp[r][c];
                    if (prob == 0.0) {
                        continue;
                    }
                    double share = prob / 8.0;
                    for (int m = 0; m < 8; m++) {
                        int nr = r + DR[m];
                        int nc = c + DC[m];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                            next[nr][nc] += share;
                        }
                    }
                }
            }
            dp = next;
        }

        double result = 0.0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                result += dp[r][c];
            }
        }
        return result;
    }
}

