public class Solution {
    public int findSecondMinimumValue(TreeNode root) {
        if (root == null) {
            return -1;
        }
        int second = dfs(root, root.val);
        return second == Integer.MAX_VALUE ? -1 : second;
    }

    private int dfs(TreeNode node, int min) {
        if (node == null) {
            return Integer.MAX_VALUE;
        }
        // If we find a value greater than min, it could be a candidate.
        if (node.val > min) {
            return node.val;
        }
        // node.val == min, need to search both subtrees.
        int left = dfs(node.left, min);
        int right = dfs(node.right, min);
        return Math.min(left, right);
    }
}

