import java.util.Deque;

public class Solution {
    public int calPoints(String[] ops) {
        Deque<Integer> stack = new ArrayDeque<>();
        int total = 0;
        for (String op : ops) {
            switch (op) {
                case "+":
                    int top = stack.pop();
                    int newScore = top + stack.peek();
                    stack.push(top); // put back the first popped value
                    stack.push(newScore);
                    total += newScore;
                    break;
                case "D":
                    int doubled = 2 * stack.peek();
                    stack.push(doubled);
                    total += doubled;
                    break;
                case "C":
                    int removed = stack.pop();
                    total -= removed;
                    break;
                default:
                    int val = Integer.parseInt(op);
                    stack.push(val);
                    total += val;
                    break;
            }
        }
        return total;
    }
}

