import java.util.HashMap;
import java.util.Map;

public class Solution {

    private static class Value {
        int count;
        int start;
        int end;

        Value(int index) {
            this.count = 1;
            this.start = index;
            this.end = index;
        }

        void update(int index) {
            this.count++;
            this.end = index;
        }
    }

    public int findShortestSubArray(int[] nums) {
        Map<Integer, Value> map = new HashMap<>();
        int degree = 0;

        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            Value v = map.get(num);
            if (v == null) {
                v = new Value(i);
                map.put(num, v);
            } else {
                v.update(i);
            }
            degree = Math.max(degree, v.count);
        }

        int minLength = Integer.MAX_VALUE;
        for (Value v : map.values()) {
            if (v.count == degree) {
                int length = v.end - v.start + 1;
                if (length < minLength) {
                    minLength = length;
                }
            }
        }

        return minLength;
    }
}

