import java.util.List;
import java.util.PriorityQueue;
import java.util.Comparator;

public class Solution {
    private static class Node {
        int value;
        int row;
        int col;
        Node(int value, int row, int col) {
            this.value = value;
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Finds the smallest range that includes at least one number from each of the k sorted lists.
     *
     * @param nums a list containing k sorted integer lists (non‑decreasing order)
     * @return an int array of size 2 where result[0] is the start of the range and result[1] is the end
     */
    public int[] smallestRange(List<List<Integer>> nums) {
        if (nums == null || nums.isEmpty()) {
            return new int[0];
        }

        int k = nums.size();
        PriorityQueue<Node> minHeap = new PriorityQueue<>(Comparator.comparingInt(n -> n.value));
        int currentMax = Integer.MIN_VALUE;

        // Initialize heap with the first element of each list
        for (int i = 0; i < k; i++) {
            List<Integer> list = nums.get(i);
            if (list == null || list.isEmpty()) {
                // If any list is empty, no valid range exists
                return new int[0];
            }
            int val = list.get(0);
            minHeap.offer(new Node(val, i, 0));
            if (val > currentMax) {
                currentMax = val;
            }
        }

        int bestStart = 0;
        int bestEnd = Integer.MAX_VALUE;
        int bestLen = bestEnd - bestStart;

        while (true) {
            Node minNode = minHeap.poll();
            int currentMin = minNode.value;

            // Update best range if current is better
