public class Solution {
    private Map<String, Integer> memo = new HashMap<>();

    public int minPrice(int[] price, int[][] special, int[] needs) {
        return dfs(price, special, needs);
    }

    private int dfs(int[] price, int[][] special, int[] needs) {
        String key = encode(needs);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        // Cost without any special offers
        int min = 0;
        for (int i = 0; i < needs.length; i++) {
            min += needs[i] * price[i];
        }

        // Try every special offer
        for (int[] offer : special) {
            int[] nextNeeds = new int[needs.length];
            boolean valid = true;
            for (int i = 0; i < needs.length; i++) {
                if (offer[i] > needs[i]) {
                    valid = false;
                    break;
                }
                nextNeeds[i] = needs[i] - offer[i];
            }
            if (!valid) {
                continue;
            }
            int offerPrice = offer[needs.length];
            int total = offerPrice + dfs(price, special, nextNeeds);
            if (total < min) {
                min = total;
            }
        }

        memo.put(key, min);
        return min;
    }

    private String encode(int[] needs) {
