                int sum = 0;
                int count = 0;
                for (int di = -1; di <= 1; di++) {
                    int ni = i + di;
                    if (ni < 0 || ni >= m) continue;
                    for (int dj = -1; dj <= 1; dj++) {
                        int nj = j + dj;
                        if (nj < 0 || nj >= n) continue;
                        sum += matrix[ni][nj];
                        count++;
                    }
                }
                result[i][j] = sum / count; // integer division floors automatically
            }
        }
        return result;
    }
}

