public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        if (k <= 0) return false;
        int n = nums.length;
        int total = 0;
        for (int num : nums) total += num;
        if (total % k != 0) return false;
        int target = total / k;

        // sort descending for better pruning
        Arrays.sort(nums);
        for (int i = 0; i < n / 2; i++) {
            int tmp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = tmp;
        }
        if (nums[0] > target) return false;

        int fullMask = (1 << n) - 1;
        // memo[mask] = 1 (true), 0 (false), -1 (unknown)
        byte[] memo = new byte[1 << n];
        Arrays.fill(memo, (byte) -1);

        return dfs(0, 0, 0, nums, k, target, fullMask, memo);
    }

    private boolean dfs(int usedMask, int curSum, int subsetsFormed,
                        int[] nums, int k, int target, int fullMask, byte[] memo) {
        if (subsetsFormed == k - 1) {
            // last subset will automatically have required sum
            return true;
        }
        if (curSum == target) {
            // start building next subset
            boolean res = dfs(usedMask, 0, subsetsFormed + 1, nums, k, target, fullMask, memo);
            memo[usedMask] = (byte) (res ? 1 : 0);
            return res;
        }
        if (memo[usedMask] != -1) {
            return memo[usedMask] == 1;
        }

        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int bit = 1 << i;
            if ((usedMask & bit) != 0) continue; // already used
            int nextSum = curSum + nums[i];
            if (nextSum > target) continue;
            // choose nums[i]
            if (dfs(usedMask | bit, nextSum, subsetsFormed, nums, k, target, fullMask, memo)) {
                memo[usedMask] = 1;
                return true;
            }
            // pruning: if curSum is 0, then placing this element didn't lead to solution,
            // no need to try other elements of same value as first element of this subset
            if (curSum == 0) break;
            // pruning: if nextSum == target and it failed, no need to try further elements
            if (nextSum == target) break;
            // skip duplicates
            while (i + 1 < n && nums[i] == nums[i + 1]) i++;
        }

        memo[usedMask] = 0;
        return false;
    }
}

