            nums[n - 1 - i] = tmp;
        }

        int fullMask = (1 << n) - 1;
        int[] memo = new int[1 << n]; // -1 unknown, 0 false, 1 true
        Arrays.fill(memo, -1);

        return dfs(0, 0, 0, nums, target, k, memo, fullMask);
    }

    private boolean dfs(int usedMask, int curSum, int startIdx,
                        int[] nums, int target, int k,
                        int[] memo, int fullMask) {
        if (usedMask == fullMask) {
            // All numbers used, all subsets formed successfully
            return true;
        }

        if (curSum == target) {
            // Current subset completed, start building next subset
            boolean res = dfs(usedMask, 0, 0, nums, target, k, memo, fullMask);
            memo[usedMask] = res ? 1 : 0;
            return res;
        }

        if (memo[usedMask] != -1) {
            return memo[usedMask] == 1;
        }

        int n = nums.length;
        for (int i = startIdx; i < n; i++) {
            if ((usedMask & (1 << i)) != 0) continue; // already used
            int nextSum = curSum + nums[i];
            if (nextSum > target) continue;

            if (dfs(usedMask | (1 << i), nextSum, i + 1, nums, target, k, memo, fullMask)) {
                memo[usedMask] = 1;
                return true;
            }

            // Prune: if we placed first element of a subset and it didn't lead to solution,
            // no need to try other elements at this position.
            if (curSum == 0) break;
            // Prune: if element exactly fills the subset but leads to dead end,
            // no need to try further elements.
            if (nextSum == target) break;
        }

        memo[usedMask] = 0;
        return false;
    }
