import java.util.Arrays;

public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        for (int n : nums) total += n;
        if (k <= 0 || total % k != 0) return false;
        int target = total / k;
        int n = nums.length;
        if (k > n) return false;

        // sort descending to improve pruning
        Arrays.sort(nums);
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            int tmp = nums[i];
            nums[i] = nums[j];
            nums[j] = tmp;
        }
        if (nums[0] > target) return false;

        boolean[] memo = new boolean[1 << n];
        boolean[] visited = new boolean[1 << n];
        return dfs(0, 0, 0, nums, k, target, memo, visited);
    }

    private boolean dfs(int usedMask, int curSum, int startIdx, int[] nums, int k,
                        int target, boolean[] memo, boolean[] visited) {
        if (k == 1) {
            // only one bucket left, remaining numbers must sum to target
            return true;
        }
        if (curSum == target) {
            // current bucket completed, move to next bucket
            boolean res = dfs(usedMask, 0, 0, nums, k - 1, target, memo, visited);
            memo[usedMask] = res;
            visited[usedMask] = true;
            return res;
        }
        if (visited[usedMask]) {
            return memo[usedMask];
        }

        for (int i = startIdx; i < nums.length; i++) {
            int bit = 1 << i;
            if ((usedMask & bit) != 0) continue; // already used
            if (curSum + nums[i] > target) continue; // exceeds target

            if (dfs(usedMask | bit, curSum + nums[i], i + 1, nums, k, target, memo, visited)) {
                memo[usedMask] = true;
                visited[usedMask] = true;
                return true;
            }
        }

        memo[usedMask] = false;
        visited[usedMask] = true;
        return false;
    }
}

