import java.util.Arrays;

public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        if (nums == null || nums.length == 0) {
            return false;
        }
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if (total % k != 0) {
            return false;
        }
        int target = total / k;
        for (int num : nums) {
            if (num > target) {
                return false;
            }
        }
        // Optional: sort descending to improve pruning (not required for DP)
        Arrays.sort(nums);
        // reverse to descending
        for (int i = 0, j = nums.length - 1; i < j; i++, j--) {
            int tmp = nums[i];
            nums[i] = nums[j];
            nums[j] = tmp;
        }

        int n = nums.length;
        int fullMask = (1 << n) - 1;
        int[] dp = new int[1 << n];
        Arrays.fill(dp, -1);
        dp[0] = 0; // sum modulo target for empty set

        for (int mask = 0; mask <= fullMask; mask++) {
            if (dp[mask] == -1) {
                continue;
            }
            // try to add each unused element
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue; // already used
                }
                int newSum = dp[mask] + nums[i];
                if (newSum > target) {
                    continue; // would exceed target
                }
                int newMask = mask | (1 << i);
                // store the modulo sum for the new mask if not set yet
                if (dp[newMask] == -1) {
                    dp[newMask] = newSum % target;
                }
            }
        }
        return dp[fullMask] == 0;
    }
}

