public class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        int n = arr.length;
        // Binary search to find the insertion point of x
        int left = 0;
        int right = n - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] < x) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        // After the loop, left is the first index >= x
        int l = left - 1; // candidate on the left side
        int r = left;     // candidate on the right side

        // Select the closest k elements
        while (k > 0) {
            if (l < 0) {
                r++;
            } else if (r >= n) {
                l--;
            } else {
                int diffL = Math.abs(arr[l] - x);
                int diffR = Math.abs(arr[r] - x);
                if (diffL <= diffR) {
                    l--;
                } else {
                    r++;
                }
            }
            k--;
        }

        // Build result list from (l+1) to (r-1) inclusive
        List<Integer> result = new ArrayList<>(r - l - 1);
        for (int i = l + 1; i < r; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

