public class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        int n = arr.length;
        // Edge cases where k equals array length
        if (k >= n) {
            List<Integer> result = new ArrayList<>(n);
            for (int num : arr) {
                result.add(num);
            }
