                // The right side is closer
                left = mid + 1;
            } else {
                // The left side is closer or equal (favor smaller elements)
                right = mid;
            }
        }

        List<Integer> result = new ArrayList<>(k);
        for (int i = left; i < left + k; i++) {
            result.add(arr[i]);
        }
        return result;
    }
