            // Compare distances between x and the two potential border elements
            int distLeft = Math.abs(x - arr[mid]);
            int distRight = Math.abs(arr[mid + k] - x);

            if (distLeft > distRight) {
                // The window should move to the right
                left = mid + 1;
            } else {
                // The window stays or moves to the left
                right = mid;
            }
        }

        List<Integer> result = new ArrayList<>(k);
        for (int i = left; i < left + k; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

