        if (node == null) {
            return;
        }
        if (currentDepth == targetDepth - 1) {
            TreeNode left = new TreeNode(val);
            left.left = node.left;
            node.left = left;

            TreeNode right = new TreeNode(val);
            right.right = node.right;
            node.right = right;
        } else {
            addRow(node.left, val, targetDepth, currentDepth + 1);
            addRow(node.right, val, targetDepth, currentDepth + 1);
        }
    }
}

