public class Solution {
    public int[] constructArray(int n, int k) {
        int[] ans = new int[n];
        if (k == 0) {
            for (int i = 0; i < n; i++) {
                ans[i] = i + 1;
            }
            return ans;
        }
        int low = 1, high = n;
        int i = 0;
        // create k distinct differences
        for (; i < k; i++) {
            if ((i & 1) == 0) {
                ans[i] = low++;
            } else {
                ans[i] = high--;
            }
        }
        // fill the rest without introducing new differences
        if ((k & 1) == 0) {
            // last placed was from low side, continue descending from high
            for (; i < n; i++) {
                ans[i] = high--;
            }
        } else {
            // last placed was from high side, continue ascending from low
            for (; i < n; i++) {
                ans[i] = low++;
            }
        }
        return ans;
    }
