import com_github_leetcode.TreeNode;
import java.util.LinkedList;
import java.util.Queue;

public class Solution {

    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) {
            return 0;
        }
        long maxWidth = 0;
        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(root, 0L));

        while (!queue.isEmpty()) {
            int size = queue.size();
            long levelStart = queue.peek().idx; // index of first node at this level
            long firstIdx = 0, lastIdx = 0;
            for (int i = 0; i < size; i++) {
                Pair cur = queue.poll();
                // normalize index to avoid overflow
                long curIdx = cur.idx - levelStart;
                if (i == 0) {
                    firstIdx = curIdx;
                }
                if (i == size - 1) {
                    lastIdx = curIdx;
                }
                if (cur.node.left != null) {
                    queue.offer(new Pair(cur.node.left, curIdx * 2 + 1));
                }
                if (cur.node.right != null) {
                    queue.offer(new Pair(cur.node.right, curIdx * 2 + 2));
                }
            }
            long width = lastIdx - firstIdx + 1;
            if (width > maxWidth) {
                maxWidth = width;
            }
        }
        return (int) maxWidth;
    }

    private static class Pair {
        TreeNode node;
        long idx;

        Pair(TreeNode node, long idx) {
            this.node = node;
            this.idx = idx;
        }
    }
}

