import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        // Count frequencies
        Map<String, Integer> freqMap = new HashMap<>();
        for (String w : words) {
            freqMap.put(w, freqMap.getOrDefault(w, 0) + 1);
        }

        // Create a list of unique words
        List<String> uniqueWords = new ArrayList<>(freqMap.keySet());

        // Sort by frequency descending, then lexicographically ascending
        Collections.sort(uniqueWords, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                int freqA = freqMap.get(a);
                int freqB = freqMap.get(b);
                if (freqA != freqB) {
                    return Integer.compare(freqB, freqA); // higher frequency first
                }
                return a.compareTo(b); // lexicographical order
            }
        });

        // Take first k elements
        List<String> result = new ArrayList<>();
        for (int i = 0; i < k && i < uniqueWords.size(); i++) {
            result.add(uniqueWords.get(i));
        }
        return result;
    }
}

