import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Collections;
import java.util.Comparator;

public class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        // Count frequencies
        Map<String, Integer> freqMap = new HashMap<>();
        for (String w : words) {
            freqMap.put(w, freqMap.getOrDefault(w, 0) + 1);
        }

        // Min-heap to keep top k elements
        Comparator<Map.Entry<String, Integer>> heapComp = (e1, e2) -> {
            int freqCmp = Integer.compare(e1.getValue(), e2.getValue());
            if (freqCmp != 0) {
                return freqCmp; // lower frequency first
            }
            // For same frequency, higher lexical order first so that the lower lexical stays in heap longer
            return e2.getKey().compareTo(e1.getKey());
        };

        PriorityQueue<Map.Entry<String, Integer>> heap = new PriorityQueue<>(k, heapComp);

        for (Map.Entry<String, Integer> entry : freqMap.entrySet()) {
            if (heap.size() < k) {
                heap.offer(entry);
            } else if (heapComp.compare(entry, heap.peek()) > 0) {
                heap.poll();
                heap.offer(entry);
            }
        }

        // Extract results from heap (from lowest to highest), then reverse
        List<String> result = new ArrayList<>();
        while (!heap.isEmpty()) {
            result.add(heap.poll().getKey());
        }
        Collections.reverse(result);
        return result;
    }
}

