                return e1.getKey().compareTo(e2.getKey()); // ascending lexicographical
            }
        });

        List<String> result = new ArrayList<>();
        int limit = Math.min(k, entries.size());
        for (int i = 0; i < limit; i++) {
            result.add(entries.get(i).getKey());
        }
        return result;
    }
