public class Solution {
    public String reverseWords(String s) {
        if (s == null) {
            return "";
        }
        char[] arr = s.toCharArray();
        int n = arr.length;

        // Reverse the whole string
        reverse(arr, 0, n - 1);

        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < n) {
            // Skip spaces
            while (i < n && arr[i] == ' ') {
                i++;
            }
            if (i >= n) {
                break;
            }
            int start = i;
            // Find end of the word
            while (i < n && arr[i] != ' ') {
                i++;
            }
            // Reverse the current word to restore its order
            reverse(arr, start, i - 1);
            // Append word to result
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(arr, start, i - start);
        }
        return sb.toString();
    }

    private void reverse(char[] a, int left, int right) {
        while (left < right) {
            char tmp = a[left];
            a[left] = a[right];
            a[right] = tmp;
            left++;
            right--;
        }
    }
}

