            return profit;
        }

        int[] dpPrev = new int[n];
        int[] dpCurr = new int[n];

        for (int t = 1; t <= k; t++) {
            int maxDiff = -prices[0];
            dpCurr[0] = 0;
            for (int i = 1; i < n; i++) {
                dpCurr[i] = Math.max(dpCurr[i - 1], prices[i] + maxDiff);
                maxDiff = Math.max(maxDiff, dpPrev[i] - prices[i]);
            }
            // swap references for next iteration
            int[] temp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = temp;
        }
        return dpPrev[n - 1];
    }
}

