    /**
     * Reverses the bits of a 32‑bit unsigned integer.
     * In Java the value is stored in a signed int, but the bit pattern
     * remains the same, so we can treat it as unsigned using unsigned
     * right shift (>>>).
     *
     * @param n the integer whose bits are to be reversed
     * @return the integer resulting from reversing the bits of {@code n}
     */
    public int reverseBits(int n) {
        int result = 0;
        for (int i = 0; i < 32; i++) {
            result <<= 1;            // make room for the next bit
            result |= (n & 1);       // copy the least‑significant bit of n
            n >>>= 1;                // unsigned shift n to process next bit
        }
        return result;
    }
}

