public class Solution {
    public int singleNumber(int[] nums) {
        int ones = 0, twos = 0;
        for (int num : nums) {
            // Update twos with bits that have appeared twice
            twos |= ones & num;
            // Update ones with bits that have appeared once
            ones ^= num;
            // Common bits in ones and twos are those that have appeared three times
            int commonMask = ones & twos;
            // Remove common bits from ones and twos
            ones &= ~commonMask;
            twos &= ~commonMask;
        }
        return ones;
    }
}

