public class Solution {
    public int majorityElement(int[] arr) {
        // Boyer-Moore Voting Algorithm
        int candidate = 0;
        int count = 0;
        for (int num : arr) {
            if (count == 0) {
                candidate = num;
                count = 1;
            } else if (num == candidate) {
                count++;
            } else {
                count--;
            }
        }
        // Since the problem guarantees a majority element exists,
        // the candidate is the majority element.
        return candidate;
    }
}

