        row.set(0, 1); // first row is always [1]

        for (int i = 1; i <= rowIndex; i++) {
            // Update the current row from right to left to avoid overwriting needed values
            for (int j = i; j > 0; j--) {
                int val = row.get(j) + row.get(j - 1);
                row.set(j, val);
            }
        }
        return row;
    }
}

