import com_github_leetcode.Node;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;

public class Solution {
    public Node cloneGraph(Node node) {
        if (node == null) {
            return null;
        }

        Map<Node, Node> clonedMap = new HashMap<>();
        Queue<Node> queue = new LinkedList<>();

        // Clone the root node
        Node rootClone = new Node();
        rootClone.val = node.val;
        rootClone.neighbors = new ArrayList<>();
        clonedMap.put(node, rootClone);
        queue.add(node);

        while (!queue.isEmpty()) {
            Node current = queue.poll();
            Node currentClone = clonedMap.get(current);

            List<Node> neighbors = current.neighbors;
            if (neighbors == null) {
                continue;
            }

            for (Node neighbor : neighbors) {
                if (!clonedMap.containsKey(neighbor)) {
                    // Clone neighbor node
                    Node neighborClone = new Node();
                    neighborClone.val = neighbor.val;
                    neighborClone.neighbors = new ArrayList<>();
                    clonedMap.put(neighbor, neighborClone);
                    queue.add(neighbor);
                }
                // Add the cloned neighbor to the current cloned node's neighbor list
                currentClone.neighbors.add(clonedMap.get(neighbor));
            }
        }

        return rootClone;
    }
}

