            // skip the dot
            if (i < n1 && version1.charAt(i) == '.') {
                i++;
            }

            long num2 = 0;
            while (j < n2 && version2.charAt(j) != '.') {
                num2 = num2 * 10 + (version2.charAt(j) - '0');
                j++;
            }
            // skip the dot
            if (j < n2 && version2.charAt(j) == '.') {
                j++;
            }

            if (num1 < num2) {
                return -1;
            } else if (num1 > num2) {
                return 1;
            }
            // else continue loop (they are equal for this revision)
        }
        return 0;
    }
}

