public class Solution {
    public int compareVersion(String version1, String version2) {
        int i = 0, j = 0;
        int n1 = version1.length(), n2 = version2.length();

        while (i < n1 || j < n2) {
            // extract next revision from version1
            int start1 = i;
            while (i < n1 && version1.charAt(i) != '.') {
                i++;
            }
            String rev1 = version1.substring(start1, i);
            i++; // skip the dot

            // extract next revision from version2
            int start2 = j;
            while (j < n2 && version2.charAt(j) != '.') {
                j++;
            }
            String rev2 = version2.substring(start2, j);
            j++; // skip the dot

            // remove leading zeros
            rev1 = rev1.replaceFirst("^0+", "");
            rev2 = rev2.replaceFirst("^0+", "");

            if (rev1.isEmpty()) rev1 = "0";
            if (rev2.isEmpty()) rev2 = "0";

            // compare by length first
            if (rev1.length() > rev2.length()) {
                return 1;
            } else if (rev1.length() < rev2.length()) {
                return -1;
            } else {
                int cmp = rev1.compareTo(rev2);
                if (cmp != 0) {
                    return cmp > 0 ? 1 : -1;
                }
            }
        }
        return 0;
    }
}

