public class Solution {
    public int compareVersion(String version1, String version2) {
        int i = 0, j = 0;
        int n1 = version1.length();
        int n2 = version2.length();

        while (i < n1 || j < n2) {
            // extract next revision from version1
            StringBuilder rev1Builder = new StringBuilder();
            while (i < n1 && version1.charAt(i) != '.') {
                rev1Builder.append(version1.charAt(i));
                i++;
            }
            // skip the dot
            if (i < n1 && version1.charAt(i) == '.') {
                i++;
            }

            // extract next revision from version2
            StringBuilder rev2Builder = new StringBuilder();
            while (j < n2 && version2.charAt(j) != '.') {
                rev2Builder.append(version2.charAt(j));
                j++;
            }
            // skip the dot
            if (j < n2 && version2.charAt(j) == '.') {
                j++;
            }

            String rev1 = stripLeadingZeros(rev1Builder.toString());
            String rev2 = stripLeadingZeros(rev2Builder.toString());

            // compare lengths first
            if (rev1.length() != rev2.length()) {
                return rev1.length() < rev2.length() ? -1 : 1;
            }
            // same length, compare lexicographically
            int cmp = rev1.compareTo(rev2);
            if (cmp != 0) {
                return cmp < 0 ? -1 : 1;
            }
            // otherwise this revision is equal, continue loop
        }
        return 0;
    }

    private String stripLeadingZeros(String s) {
        int idx = 0;
        int len = s.length();
        while (idx < len && s.charAt(idx) == '0') {
            idx++;
        }
        return idx == len ? "0" : s.substring(idx);
    }
}

