import java.util.List;

public class Solution {
    public int minimumTotal(List<List<Integer>> triangle) {
        if (triangle == null || triangle.isEmpty()) {
            return 0;
        }
        int n = triangle.size();
        // dp will hold the minimum path sums for the current row
        int[] dp = new int[n];
        // Initialize dp with the last row values
        List<Integer> lastRow = triangle.get(n - 1);
        for (int i = 0; i < n; i++) {
            dp[i] = lastRow.get(i);
        }
        // Iterate from the second last row up to the top
        for (int row = n - 2; row >= 0; row--) {
            List<Integer> current = triangle.get(row);
            for (int i = 0; i <= row; i++) {
                dp[i] = current.get(i) + Math.min(dp[i], dp[i + 1]);
            }
        }
        return dp[0];
    }
}

