public class Solution {
    private Map<Integer, Integer> inorderIndexMap = new HashMap<>();
    private int preorderIndex = 0;

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        // Build a map to quickly find the index of any value in inorder array
        for (int i = 0; i < inorder.length; i++) {
            inorderIndexMap.put(inorder[i], i);
        }
        return buildSubTree(preorder, 0, inorder.length - 1);
    }

    private TreeNode buildSubTree(int[] preorder, int left, int right) {
        if (left > right) {
            return null;
        }

        // The current root value is at preorderIndex in preorder traversal
        int rootVal = preorder[preorderIndex++];
        TreeNode root = new TreeNode(rootVal);

        // Find the position of the root in inorder traversal
        int inorderPos = get(rootVal);

        // Recursively build left and right subtrees
        root.left = buildSubTree(preorder, left, inorderPos - 1);
        root.right = buildSubTree(preorder, inorderPos + 1, right);

        return root;
    }

    // Returns the index of the given key in the inorder array (or -1 if not found)
    public int get(int key) {
        Integer idx = inorderIndexMap.get(key);
        return idx == null ? -1 : idx;
    }
