import com_github_leetcode.TreeNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    private Map<Integer, Integer> inorderIndexMap;
    private int[] preorder;

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        if (preorder == null || inorder == null || preorder.length != inorder.length) {
            return null;
        }
        this.preorder = preorder;
        inorderIndexMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderIndexMap.put(inorder[i], i);
        }
        return build(0, 0, preorder.length - 1);
    }

    private TreeNode build(int preStart, int inStart, int preEnd) {
        if (preStart > preEnd) {
            return null;
        }
        int rootVal = preorder[preStart];
        TreeNode root = new TreeNode(rootVal);
        int inRootIdx = get(rootVal);
        int leftSize = inRootIdx - inStart;
        root.left = build(preStart + 1, inStart, preStart + leftSize);
        root.right = build(preStart + leftSize + 1, inRootIdx + 1, preEnd);
        return root;
    }

    public int get(int key) {
        Integer val = inorderIndexMap.get(key);
        return val == null ? -1 : val;
    }
}

