public class Solution {
    public int minCut(String s) {
        if (s == null || s.length() <= 1) {
            return 0;
        }
        int n = s.length();
        int[] cuts = new int[n];
        for (int i = 0; i < n; i++) {
            cuts[i] = i; // maximum cuts
        }

        for (int i = 0; i < n; i++) {
            // odd length palindromes centered at i
            for (int l = i, r = i; l >= 0 && r < n && s.charAt(l) == s.charAt(r); l--, r++) {
                if (l == 0) {
                    cuts[r] = 0;
                } else {
                    cuts[r] = Math.min(cuts[r], cuts[l - 1] + 1);
                }
            }
            // even length palindromes centered between i-1 and i
            for (int l = i - 1, r = i; l >= 0 && r < n && s.charAt(l) == s.charAt(r); l--, r++) {
                if (l == 0) {
                    cuts[r] = 0;
                } else {
                    cuts[r] = Math.min(cuts[r], cuts[l - 1] + 1);
                }
            }
        }
        return cuts[n - 1];
    }
}

