import java.util.*;

public class Solution {
    public int minCut(String s) {
        int n = s.length();
        // cuts[i] = minimum cuts for substring s[0..i-1]
        int[] cuts = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            cuts[i] = i - 1; // maximum cuts
        }

        for (int center = 0; center < n; center++) {
            // odd length palindromes
            for (int radius = 0;
                 center - radius >= 0 && center + radius < n && s.charAt(center - radius) == s.charAt(center + radius);
                 radius++) {
                int left = center - radius;
                int right = center + radius;
                cuts[right + 1] = Math.min(cuts[right + 1], 1 + cuts[left]);
            }

            // even length palindromes
            for (int radius = 0;
                 center - radius >= 0 && center + 1 + radius < n && s.charAt(center - radius) == s.charAt(center + 1 + radius);
                 radius++) {
                int left = center - radius;
                int right = center + 1 + radius;
                cuts[right + 1] = Math.min(cuts[right + 1], 1 + cuts[left]);
            }
        }

        return cuts[n];
    }
}

