import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public List<String> findRepeatedDnaSequences(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() < 10) {
            return result;
        }

        // Encode each nucleotide with 2 bits: A->00, C->01, G->10, T->11
        int[] map = new int[128];
        map['A'] = 0;
        map['C'] = 1;
        map['G'] = 2;
        map['T'] = 3;

        int hash = 0;
        int mask = (1 << 20) - 1; // keep only last 20 bits (10 * 2 bits)

        Set<Integer> seen = new HashSet<>();
        Set<String> added = new HashSet<>();

        for (int i = 0; i < s.length(); i++) {
            hash = ((hash << 2) | map[s.charAt(i)]) & mask;
            if (i >= 9) { // we have a full 10-letter window
                if (!seen.add(hash)) { // hash already seen
                    String seq = s.substring(i - 9, i + 1);
                    if (added.add(seq)) {
                        result.add(seq);
                    }
                }
            }
        }

        return result;
    }
}

