import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public List<String> findRepeatedDnaSequences(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() < 10) {
            return result;
        }

        // Map each nucleotide to 2 bits
        int[] charMap = new int[26];
        charMap['A' - 'A'] = 0; // 00
        charMap['C' - 'A'] = 1; // 01
        charMap['G' - 'A'] = 2; // 10
        charMap['T' - 'A'] = 3; // 11

        Set<Integer> seen = new HashSet<>();
        Set<Integer> added = new HashSet<>();

        int hash = 0;
        int mask = (1 << 20) - 1; // keep only last 20 bits (10 chars * 2 bits)

        // Build the initial hash for first 10 characters
        for (int i = 0; i < 10; i++) {
            hash = (hash << 2) | charMap[s.charAt(i) - 'A'];
        }
        seen.add(hash);

        for (int i = 10; i < s.length(); i++) {
            // slide window: shift left 2 bits, add new char, and mask out overflow
            hash = ((hash << 2) & mask) | charMap[s.charAt(i) - 'A'];
            if (!seen.add(hash)) { // already seen before
                if (added.add(hash)) { // first time we record as duplicate
                    result.add(s.substring(i - 9, i + 1));
                }
            }
        }

        return result;
    }
}

