public class Solution {
    private int encode(char c) {
        switch (c) {
            case 'A': return 0;
            case 'C': return 1;
            case 'G': return 2;
            case 'T': return 3;
            default:  return 0; // should not happen
        }
    }

    public List<String> findRepeatedDnaSequences(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() < 10) {
            return result;
        }

        final int L = 10;
        final int mask = (1 << (L * 2)) - 1; // keep only last 20 bits
        int hash = 0;

        // build initial hash for first 10 characters
        for (int i = 0; i < L; i++) {
            hash = (hash << 2) | encode(s.charAt(i));
        }

        Set<Integer> seen = new HashSet<>();
        Set<Integer> added = new HashSet<>();
        seen.add(hash);

        for (int i = L; i < s.length(); i++) {
            // slide window: shift left 2 bits, add new char, keep only last 20 bits
            hash = ((hash << 2) & mask) | encode(s.charAt(i));
            if (!seen.add(hash)) { // already existed
                if (added.add(hash)) { // first time we record it as duplicate
                    result.add(s.substring(i - L + 1, i + 1));
                }
            }
        }

        return result;
    }
}

