public class Solution {
    /**
     * Finds the minimum element in a rotated sorted array of unique integers.
     *
     * @param nums the rotated sorted array
     * @return the minimum element
     */
    public int findMin(int[] nums) {
        if (nums == null || nums.length == 0) {
            throw new IllegalArgumentException("Array must contain at least one element.");
        }
        int left = 0;
        int right = nums.length - 1;

        // If the array is not rotated (the smallest element is at the beginning)
        if (nums[left] < nums[right]) {
            return nums[left];
        }

        while (left < right) {
            int mid = left + (right - left) / 2;

            // If mid element is greater than the rightmost element,
            // the minimum must be to the right of mid.
            if (nums[mid] > nums[right]) {
                left = mid + 1;
            } else {
                // Otherwise, the minimum is at mid or to the left of mid.
                right = mid;
            }
        }
        // At this point left == right pointing to the smallest element.
        return nums[left];
    }
}

