public class Solution {
    public int numDistinct(String text, String text2) {
        if (text2.length() == 0) {
            return 1;
        }
        if (text.length() == 0) {
            return 0;
        }

        int n = text.length();
        int m = text2.length();

        // dp[j] = number of ways to form text2[0..j-1] using processed characters of text
        long[] dp = new long[m + 1];
        dp[0] = 1; // empty string can always be formed

        for (int i = 1; i <= n; i++) {
            char c = text.charAt(i - 1);
            // iterate backwards to avoid overwriting dp[j-1] needed for current i
            for (int j = m; j >= 1; j--) {
                if (c == text2.charAt(j - 1)) {
                    dp[j] += dp[j - 1];
                }
            }
        }

        return (int) dp[m];
    }
}

