import com_github_leetcode.ListNode;
import com_github_leetcode.TreeNode;

public class Solution {
    public TreeNode sortedListToBST(ListNode head) {
        if (head == null) {
            return null;
        }
        if (head.next == null) {
            return new TreeNode(head.val);
        }

        ListNode prev = null;
        ListNode slow = head;
        ListNode fast = head;

        // Find middle node (slow) and its predecessor (prev)
        while (fast != null && fast.next != null) {
            prev = slow;
            slow = slow.next;
            fast = fast.next.next;
        }

        // Disconnect left half from middle
        if (prev != null) {
            prev.next = null;
        }

        TreeNode root = new TreeNode(slow.val);
        // Build left subtree from the left part of the list
        root.left = (prev == null) ? null : sortedListToBST(head);
        // Build right subtree from the right part of the list
        root.right = sortedListToBST(slow.next);

        return root;
    }
}

