public class Solution {
    private ListNode current;

    public TreeNode sortedListToBST(ListNode head) {
        // Compute the size of the linked list
        int size = 0;
        for (ListNode node = head; node != null; node = node.next) {
            size++;
        }
        // Initialize the pointer used during inorder construction
        current = head;
        return buildBST(0, size - 1);
    }

    private TreeNode buildBST(int left, int right) {
        if (left > right) {
            return null;
        }

        int mid = left + (right - left) / 2;

        // Recursively build the left subtree
        TreeNode leftChild = buildBST(left, mid - 1);

        // The current ListNode becomes the root node
        TreeNode root = new TreeNode(current.val);
        root.left = leftChild;

        // Move to the next ListNode
        current = current.next;

        // Recursively build the right subtree
        root.right = buildBST(mid + 1, right);

        return root;
    }
}

