import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) {
            return Collections.emptyList();
        }

        // Map each word to its list of predecessors in the shortest paths
        Map<String, List<String>> parents = new HashMap<>();

        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);

        Set<String> visited = new HashSet<>();
        visited.add(beginWord);

        boolean found = false;
        int wordLen = beginWord.length();

        while (!queue.isEmpty() && !found) {
            int size = queue.size();
            Set<String> levelVisited = new HashSet<>();

            for (int i = 0; i < size; i++) {
                String cur = queue.poll();
                char[] curArr = cur.toCharArray();

                for (int pos = 0; pos < wordLen; pos++) {
                    char originalChar = curArr[pos];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == originalChar) continue;
                        curArr[pos] = c;
                        String next = new String(curArr);
                        if (!wordSet.contains(next)) continue;

                        // Record parent relationship
                        parents.computeIfAbsent(next, k -> new ArrayList<>()).add(cur);

                        if (next.equals(endWord)) {
                            found = true;
                        }

                        if (!visited.contains(next)) {
                            if (!levelVisited.contains(next)) {
                                queue.offer(next);
                                levelVisited.add(next);
                            }
                        }
                    }
                    curArr[pos] = originalChar;
                }
            }
            visited.addAll(levelVisited);
        }

        if (!found) {
            return Collections.emptyList();
        }

        List<List<String>> results = new ArrayList<>();
        List<String> path = new LinkedList<>();
        dfsBuild(endWord, beginWord, parents, path, results);
        return results;
    }

    private void dfsBuild(String word, String beginWord,
                          Map<String, List<String>> parents,
                          List<String> path,
                          List<List<String>> results) {
        path.add(0, word); // prepend to keep order from begin to end
        if (word.equals(beginWord)) {
            results.add(new ArrayList<>(path));
        } else {
            List<String> preds = parents.get(word);
            if (preds != null) {
                for (String pred : preds) {
                    dfsBuild(pred, beginWord, parents, path, results);
                }
            }
        }
        path.remove(0);
    }
}

