        if (!wordSet.contains(endWord)) {
            return results;
        }
        // Ensure beginWord is not considered as a visited word initially
        wordSet.remove(beginWord);

        // BFS variables
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);

        // For each word, store its predecessors in the shortest paths
        Map<String, List<String>> parents = new HashMap<>();

        // To keep track of words visited at current BFS level
        Set<String> visitedThisLevel = new HashSet<>();

        boolean found = false;

        while (!queue.isEmpty() && !found) {
            int size = queue.size();
            visitedThisLevel.clear();

            for (int i = 0; i < size; i++) {
                String current = queue.poll();
                char[] curArr = current.toCharArray();

                for (int pos = 0; pos < curArr.length; pos++) {
                    char originalChar = curArr[pos];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == originalChar) continue;
                        curArr[pos] = c;
                        String neighbor = new String(curArr);
                        if (!wordSet.contains(neighbor) && !neighbor.equals(endWord)) {
                            continue;
                        }
                        if (neighbor.equals(endWord) || wordSet.contains(neighbor)) {
                            // Record parent relationship
                            parents.computeIfAbsent(neighbor, k -> new ArrayList<>()).add(current);

                            if (neighbor.equals(endWord)) {
                                found = true;
                            }
                            if (!visitedThisLevel.contains(neighbor)) {
                                visitedThisLevel.add(neighbor);
                                queue.offer(neighbor);
                            }
                        }
                    }
                    curArr[pos] = originalChar; // restore
                }
            }
            // Remove all words visited at this level from the global set to prevent cycles
            wordSet.removeAll(visitedThisLevel);
        }

        if (!found) {
            return results;
        }

        // Backtrack from endWord to beginWord using the parents map
        List<String> path = new LinkedList<>();
        dfsBuildPaths(endWord, beginWord, parents, path, results);
        return results;
    }

    private void dfsBuildPaths(String word, String beginWord,
                               Map<String, List<String>> parents,
                               List<String> path,
                               List<List<String>> results) {
