                String cur = queue.poll();
                char[] chars = cur.toCharArray();

                for (int pos = 0; pos < chars.length; pos++) {
                    char original = chars[pos];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) continue;
                        chars[pos] = c;
                        String next = new String(chars);
                        if (!wordSet.contains(next)) continue;

                        // Record parent relationship
                        parents.computeIfAbsent(next, k -> new ArrayList<>()).add(cur);

                        if (!visited.contains(next) && !thisLevelVisited.contains(next)) {
                            thisLevelVisited.add(next);
                            queue.offer(next);
                        }
                        if (next.equals(endWord)) {
                            found = true;
                        }
                    }
                    chars[pos] = original;
                }
            }
            visited.addAll(thisLevelVisited);
        }

        List<List<String>> result = new ArrayList<>();
        if (!found) return result;

        LinkedList<String> path = new LinkedList<>();
        dfs(endWord, beginWord, parents, path, result);
        return result;
    }

    private void dfs(String word, String beginWord,
                     Map<String, List<String>> parents,
                     LinkedList<String> path,
                     List<List<String>> result) {
        path.addFirst(word);
        if (word.equals(beginWord)) {
            result.add(new ArrayList<>(path));
        } else {
            List<String> preds = parents.get(word);
            if (preds != null) {
                for (String pred : preds) {
                    dfs(pred, beginWord, parents, path, result);
                }
            }
        }
        path.removeFirst();
    }
}

