import com_github_leetcode.left_right.Node;

public class Solution {
    public Node connect(Node root) {
        if (root == null) {
            return null;
        }

        Node nextLevelHead = null; // head of the next level
        Node prev = null;          // previous node on the next level
        Node curr = root;          // current node on the current level

        while (curr != null) {
            while (curr != null) {
                if (curr.left != null) {
                    if (prev != null) {
                        prev.next = curr.left;
                    } else {
                        nextLevelHead = curr.left;
                    }
                    prev = curr.left;
                }
                if (curr.right != null) {
                    if (prev != null) {
                        prev.next = curr.right;
                    } else {
                        nextLevelHead = curr.right;
                    }
                    prev = curr.right;
                }
                curr = curr.next;
            }
            // move to the next level
            curr = nextLevelHead;
            nextLevelHead = null;
            prev = null;
        }

        return root;
    }
}

