import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String fractionToDecimal(int numerator, int denominator) {
        if (numerator == 0) {
            return "0";
        }

        StringBuilder sb = new StringBuilder();

        // Determine sign
        long num = numerator;
        long den = denominator;
        if ((num < 0) ^ (den < 0)) {
            sb.append("-");
        }

        // Work with absolute values to avoid overflow
        num = Math.abs(num);
        den = Math.abs(den);

        // Append integer part
        long integerPart = num / den;
        sb.append(integerPart);

        long remainder = num % den;
        if (remainder == 0) {
            return sb.toString();
        }

        sb.append('.');

        // Map to store previously seen remainders and their positions in the result
        Map<Long, Integer> remainderPos = new HashMap<>();

        while (remainder != 0) {
            // If this remainder has been seen before, it's a repeating fraction
            if (remainderPos.containsKey(remainder)) {
                int index = remainderPos.get(remainder);
                sb.insert(index, '(');
                sb.append(')');
                break;
            }

            // Store the position where this remainder first appears
            remainderPos.put(remainder, sb.length());

            remainder *= 10;
            long digit = remainder / den;
            sb.append(digit);
            remainder %= den;
        }

        return sb.toString();
    }
}

