            return sb.toString();
        }

        sb.append('.');

        // Map to store seen remainders and their positions in the result
        Map<Long, Integer> remainderIndexMap = new HashMap<>();

        while (remainder != 0) {
            // If we have seen this remainder before, it's a repeating part
            if (remainderIndexMap.containsKey(remainder)) {
                int index = remainderIndexMap.get(remainder);
                sb.insert(index, '(');
                sb.append(')');
                break;
            }

            // Record the position of this remainder
            remainderIndexMap.put(remainder, sb.length());

            remainder *= 10;
            sb.append(remainder / d);
            remainder %= d;
        }

        return sb.toString();
    }
}

