public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        Arrays.sort(arr2);
        int n = arr1.length;
        int m = arr2.length;
        final int INF = 1_000_000_0;

        int[] dp = new int[m];
        Arrays.fill(dp, INF);
        int best = 0; // minimal operations when the last element is arr1[i-1] (or empty prefix)

        for (int i = 0; i < n; i++) {
            int[] ndp = new int[m];
            Arrays.fill(ndp, INF);
            int newBest = INF;

            // Keep arr1[i] if possible
            int minPrev = best;
            for (int j = 0; j < m && arr2[j] < arr1[i]; j++) {
                minPrev = Math.min(minPrev, dp[j]);
            }
            if (minPrev < INF) {
                newBest = minPrev; // no extra operation
            }

            // Replace with arr2[j]
            int cur = best;
            for (int j = 0; j < m; j++) {
                cur = Math.min(cur, dp[j]);
                ndp[j] = cur + 1;
            }

            dp = ndp;
            best = newBest;
        }

        int ans = best;
        for (int v : dp) {
            ans = Math.min(ans, v);
        }
        return ans >= INF ? -1 : ans;
    }
}

