import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        // Remove duplicates and sort arr2 for binary search
        int[] sortedArr2 = Arrays.stream(arr2).distinct().sorted().toArray();

        final int INF = Integer.MAX_VALUE / 2;
        // dp maps the last value of the processed prefix to the minimal operations used
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(-1, 0); // sentinel: before the first element we can consider -1 (smaller than any positive int)

        for (int val : arr1) {
            Map<Integer, Integer> next = new HashMap<>();

            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int prev = entry.getKey();
                int cost = entry.getValue();

                // 1) Keep current element if it keeps the sequence strictly increasing
                if (val > prev) {
                    int existing = next.getOrDefault(val, INF);
                    if (cost < existing) {
                        next.put(val, cost);
                    }
                }

                // 2) Replace current element with the smallest element from arr2 that is > prev
                int idx = Arrays.binarySearch(sortedArr2, prev + 1);
                if (idx < 0) {
                    idx = -idx - 1;
                }
                if (idx < sortedArr2.length) {
                    int replaceVal = sortedArr2[idx];
                    int newCost = cost + 1;
                    int existing = next.getOrDefault(replaceVal, INF);
                    if (newCost < existing) {
                        next.put(replaceVal, newCost);
                    }
                }
            }

            dp = next;
            if (dp.isEmpty()) {
                // No possible states, early exit
                return -1;
            }
        }

        int answer = INF;
        for (int cost : dp.values()) {
            if (cost < answer) {
                answer = cost;
            }
        }
        return answer == INF ? -1 : answer;
    }
}

