public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        // Sort and deduplicate arr2
        int[] sorted = Arrays.stream(arr2).distinct().sorted().toArray();

        // dp maps the last value of the processed prefix to the minimal operations used
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(Integer.MIN_VALUE, 0); // sentinel previous value

        for (int a : arr1) {
            Map<Integer, Integer> next = new HashMap<>();

            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int prev = entry.getKey();
                int ops = entry.getValue();

                // Keep current element if it keeps the sequence strictly increasing
                if (a > prev) {
                    next.merge(a, ops, Math::min);
                }

                // Replace current element with the smallest arr2 value greater than prev
                int idx = upperBound(sorted, prev);
                if (idx < sorted.length) {
                    int val = sorted[idx];
                    next.merge(val, ops + 1, Math::min);
                }
            }

            dp = next;
            if (dp.isEmpty()) {
                return -1; // no possible sequences at this position
            }
        }

        int answer = Integer.MAX_VALUE;
        for (int ops : dp.values()) {
            answer = Math.min(answer, ops);
        }
        return answer == Integer.MAX_VALUE ? -1 : answer;
    }

    // Returns the first index i such that arr[i] > target
    private int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

