public class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;
        if (n == 0) {
            return 0;
        }
        if (n == 1) {
            return arr[0];
        }

        int[] forward = new int[n];
        int[] backward = new int[n];

        forward[0] = arr[0];
        for (int i = 1; i < n; i++) {
            forward[i] = Math.max(arr[i], forward[i - 1] + arr[i]);
        }

        backward[n - 1] = arr[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            backward[i] = Math.max(arr[i], backward[i + 1] + arr[i]);
        }

        int maxSum = Integer.MIN_VALUE;
        // No deletion
        for (int i = 0; i < n; i++) {
            if (forward[i] > maxSum) {
                maxSum = forward[i];
            }
        }

        // Delete one element (except first and last)
        for (int i = 1; i < n - 1; i++) {
            int combined = forward[i - 1] + backward[i + 1];
            if (combined > maxSum) {
                maxSum = combined;
            }
        }

        return maxSum;
    }
}

