            this.count = count;
        }
    }

    /**
     * Returns the length of the longest substring consisting of the same character
     * after performing at most one swap of any two characters in the string.
     *
     * @param text the input string consisting of lowercase English letters
     * @return the maximum possible length of a repeated‑character substring
     */
    public int maxRepOpt1(String text) {
        int n = text.length();
        if (n == 0) {
            return 0;
        }

        // total occurrences of each character
        int[] total = new int[26];
        for (int i = 0; i < n; i++) {
            total[text.charAt(i) - 'a']++;
        }

        // compress the string into blocks of identical characters
        List<Pair> groups = new ArrayList<>();
        int i = 0;
        while (i < n) {
            char ch = text.charAt(i);
            int j = i;
            while (j < n && text.charAt(j) == ch) {
                j++;
            }
            groups.add(new Pair(ch, j - i));
            i = j;
        }

        int max = 0;

        // Case 1: extend a single block by swapping in one more same character if available
        for (Pair g : groups) {
            int cur = g.count;
            if (total[g.c - 'a'] > g.count) {
                cur++; // we can bring one more from elsewhere
            }
            max = Math.max(max, cur);
        }

        // Case 2: merge two blocks of the same character separated by a single different character
        for (int k = 0; k < groups.size() - 2; k++) {
            Pair left = groups.get(k);
            Pair middle = groups.get(k + 1);
            Pair right = groups.get(k + 2);
