            int j = i;
            while (j < n && arr[j] == cur) {
                j++;
            }
            blocks.add(new Block(cur, j - i));
            i = j;
        }

        int answer = 0;

        // Case 1: extend a single block by swapping in one more same character
        for (Block b : blocks) {
            int possible = Math.min(b.len + 1, totalCount.get(b.c));
            answer = Math.max(answer, possible);
        }

        // Case 2: merge two blocks separated by a single different character
        for (int k = 2; k < blocks.size(); k++) {
            Block left = blocks.get(k - 2);
            Block middle = blocks.get(k - 1);
