public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        long movesEvenPeaks = 0; // even indices are peaks
        long movesOddPeaks = 0;  // odd indices are peaks

        for (int i = 0; i < n; i++) {
            int left = (i > 0) ? nums[i - 1] : Integer.MIN_VALUE;
            int right = (i + 1 < n) ? nums[i + 1] : Integer.MIN_VALUE;

            // moves needed to make nums[i] a peak
            int needLeft = left >= nums[i] ? left - nums[i] + 1 : 0;
            int needRight = right >= nums[i] ? right - nums[i] + 1 : 0;
            int totalNeed = needLeft + needRight;

            if ((i & 1) == 0) {
                // i is even, should be a peak in the first pattern
                movesEvenPeaks += totalNeed;
            } else {
                // i is odd, should be a peak in the second pattern
                movesOddPeaks += totalNeed;
            }

            // For the opposite pattern, the current index should be a valley,
            // so we don't add anything here (valley condition requires no moves).
        }

        // The opposite patterns require the other set of indices to be peaks.
        // Since we only accumulated moves for indices that are peaks in each pattern,
        // we need to compute the moves for the other pattern by swapping roles.
        // To avoid double computation, we can recompute similarly:
        long movesEvenValley = 0; // even indices are valleys (odd peaks)
        long movesOddValley = 0;  // odd indices are valleys (even peaks)

        for (int i = 0; i < n; i++) {
            int left = (i > 0) ? nums[i - 1] : Integer.MIN_VALUE;
            int right = (i + 1 < n) ? nums[i + 1] : Integer.MIN_VALUE;

            // moves needed to make nums[i] a peak (same as before)
            int needLeft = left >= nums[i] ? left - nums[i] + 1 : 0;
            int needRight = right >= nums[i] ? right - nums[i] + 1 : 0;
            int totalNeed = needLeft + needRight;

            if ((i & 1) == 0) {
                // i is even, should be a valley in the second pattern (odd peaks)
                movesEvenValley += totalNeed;
            } else {
                // i is odd, should be a valley in the first pattern (even peaks)
                movesOddValley += totalNeed;
            }
        }

        // Total moves for each pattern:
        long totalEvenPeaks = movesEvenPeaks; // even indices are peaks, odd are valleys
        long totalOddPeaks = movesOddPeaks;   // odd indices are peaks, even are valleys

        // The computed valley sums are actually the same as the opposite peak sums,
        // so we can directly take the minimum of the two totals.
        return (int) Math.min(totalEvenPeaks, totalOddPeaks);
    }
}

