            if ((i & 1) == 0) {
                // even index: in first pattern it must be a valley, in second pattern it must be a peak
                movesEvenValley += neededDecrease; // make even index a valley
            } else {
                // odd index: in first pattern it must be a peak, in second pattern it must be a valley
                movesOddValley += neededDecrease; // make odd index a valley
            }
        }

        // To get moves for the opposite pattern, we need to recompute using the same logic
        // but swapping the roles of even and odd indices.
        // Instead of recomputing, we can compute both sums in one pass:
        long movesEvenPeak = 0; // even indices are peaks (i.e., odd indices are valleys)
        long movesOddPeak = 0;  // odd indices are peaks (i.e., even indices are valleys)

        for (int i = 0; i < nums.length; i++) {
