            int right = (i + 1 < nums.length) ? nums[i + 1] : Integer.MAX_VALUE;
            int minNeighbor = Math.min(left, right);
            int neededDecrease = Math.max(0, nums[i] - minNeighbor + 1);

            if ((i & 1) == 0) {
                movesEvenPeak += neededDecrease; // even index should be a peak, so we count its reduction when it needs to be a valley (which is not needed)
            } else {
                movesOddPeak += neededDecrease;
            }
        }

        // Actually the above double counting is unnecessary. The correct approach:
        // Compute moves when odd indices are valleys (pattern A[0] > A[1] < A[2] > ...):
        long movesPattern1 = 0;
        // Compute moves when even indices are valleys (pattern A[0] < A[1] > A[2] < ...):
        long movesPattern2 = 0;

        for (int i = 0; i < nums.length; i++) {
            int left = (i > 0) ? nums[i - 1] : Integer.MAX_VALUE;
            int right = (i + 1 < nums.length) ? nums[i + 1] : Integer.MAX_VALUE;
            int minNeighbor = Math.min(left, right);
            int neededDecrease = Math.max(0, nums[i] - minNeighbor + 1);

            if ((i & 1) == 1) {
                // odd index should be valley for pattern1
                movesPattern1 += neededDecrease;
            } else {
                // even index should be valley for pattern2
                movesPattern2 += neededDecrease;
            }
        }

        return (int) Math.min(movesPattern1, movesPattern2);
