public class Solution {
    private int leftSubtreeSize;
    private int rightSubtreeSize;

    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        computeSizes(root, x);
        int parentSide = n - (leftSubtreeSize + rightSubtreeSize + 1);
        int maxRegion = Math.max(leftSubtreeSize, Math.max(rightSubtreeSize, parentSide));
        return maxRegion > n / 2;
    }

    // Returns the size of the subtree rooted at 'node'.
    // While traversing, captures the sizes of the left and right subtrees of node with value x.
    private int computeSizes(TreeNode node, int x) {
        if (node == null) {
            return 0;
        }
        int leftSize = computeSizes(node.left, x);
        int rightSize = computeSizes(node.right, x);
        int totalSize = leftSize + rightSize + 1;

        if (node.val == x) {
            leftSubtreeSize = leftSize;
            rightSubtreeSize = rightSize;
        }
        return totalSize;
    }
}

