import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int mctFromLeafValues(int[] arr) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(Integer.MAX_VALUE); // sentinel to avoid empty checks
        int result = 0;
        for (int num : arr) {
            while (stack.peek() <= num) {
                int mid = stack.pop();
                int cost = mid * Math.min(stack.peek(), num);
                result += cost;
            }
            stack.push(num);
        }
        while (stack.size() > 2) { // more than sentinel and one leaf left
            int mid = stack.pop();
            result += mid * stack.peek();
        }
        return result;
    }
}

