            while (stack.peek() <= num) {
                int mid = stack.pop();
                int left = stack.peek();
                int right = num;
                cost += (long) mid * Math.min(left, right);
            }
            stack.push(num);
        }

        // Process remaining elements in the stack
        while (stack.size() > 2) {
            int mid = stack.pop();
            cost += (long) mid * stack.peek();
        }

        return (int) cost;
