public class Solution {
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        int[] suffix = new int[n + 1];
        // suffix[i] = total stones from i to end
        for (int i = n - 1; i >= 0; i--) {
            suffix[i] = suffix[i + 1] + piles[i];
        }
        // memo[i][M] : maximum stones the current player can obtain starting at index i with current M
        int[][] memo = new int[n][n + 1];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }
        return dfs(0, 1, piles, suffix, memo);
    }

    private int dfs(int i, int M, int[] piles, int[] suffix, int[][] memo) {
        int n = piles.length;
        if (i >= n) {
            return 0;
        }
        if (memo[i][M] != -1) {
            return memo[i][M];
        }
        // If we can take all remaining piles, take them.
        if (i + 2 * M >= n) {
            memo[i][M] = suffix[i];
            return memo[i][M];
        }
        int max = 0;
        // Try taking X piles where 1 <= X <= 2M
        for (int x = 1; x <= 2 * M; x++) {
            int nextIndex = i + x;
            int opponentBest = dfs(nextIndex, Math.max(M, x), piles, suffix, memo);
            int currentGain = suffix[i] - opponentBest;
            if (currentGain > max) {
                max = currentGain;
            }
        }
        memo[i][M] = max;
        return max;
    }
}

