            return 0;
        }
        if (memo[i][M] != -1) {
            return memo[i][M];
        }
        int maxTake = Math.min(2 * M, n - i);
        // If we can take all remaining piles, take them all.
        if (maxTake == n - i) {
            memo[i][M] = suffix[i];
            return memo[i][M];
        }
        int best = 0;
        // Try taking X piles where 1 <= X <= 2M
        for (int X = 1; X <= maxTake; X++) {
            int nextM = Math.max(M, X);
            int opponent = dfs(i + X, nextM);
            int current = suffix[i] - opponent;
            if (current > best) {
                best = current;
            }
        }
        memo[i][M] = best;
        return best;
    }
