public class Solution {
    public int[] smallestSufficientTeam(String[] skills, List<List<String>> people) {
        int m = skills.length;
        // Map each skill to a bit position
        Map<String, Integer> skillIndex = new HashMap<>();
        for (int i = 0; i < m; i++) {
            skillIndex.put(skills[i], i);
        }

        // Convert each person's skill list to a bitmask
        int[] personMask = new int[people.size()];
        for (int i = 0; i < people.size(); i++) {
            int mask = 0;
            for (String s : people.get(i)) {
                Integer idx = skillIndex.get(s);
                if (idx != null) {
                    mask |= 1 << idx;
                }
            }
            personMask[i] = mask;
        }

        int fullMask = (1 << m) - 1;
        @SuppressWarnings("unchecked")
        List<Integer>[] dp = new List[1 << m];
        dp[0] = new ArrayList<>();

        for (int i = 0; i < personMask.length; i++) {
            int pMask = personMask[i];
            if (pMask == 0) continue; // this person adds no new skill
            // iterate over a snapshot of current dp states
            for (int mask = 0; mask <= fullMask; mask++) {
                if (dp[mask] == null) continue;
                int newMask = mask | pMask;
                if (dp[newMask] == null || dp[mask].size() + 1 < dp[newMask].size()) {
                    List<Integer> newTeam = new ArrayList<>(dp[mask]);
                    newTeam.add(i);
                    dp[newMask] = newTeam;
                }
            }
        }

        List<Integer> answerList = dp[fullMask];
        int[] answer = new int[answerList.size()];
        for (int i = 0; i < answerList.size(); i++) {
            answer[i] = answerList.get(i);
        }
        return answer;
    }
