        for (int i = 0; i < people.size(); i++) {
            int pMask = personMask[i];
            if (pMask == 0) {
                continue; // this person adds no new skills
            }
            int[][] next = dp.clone(); // shallow copy of references
            for (int mask = 0; mask <= fullMask; mask++) {
                if (dp[mask] == null) {
                    continue;
