import java.util.HashMap;

public class Solution {
    public int longestWPI(int[] hours) {
        // Threshold for a tiring day is 8 hours (as per the classic problem definition)
        int n = hours.length;
        // Prefix sum where we add +1 for tiring day (>8) and -1 otherwise
        int prefix = 0;
        int maxLen = 0;
        // Map to store the first occurrence index of each prefix sum value
        HashMap<Integer, Integer> firstIndex = new HashMap<>();
        firstIndex.put(0, -1); // base case: prefix sum 0 occurs before the array starts

        for (int i = 0; i < n; i++) {
            // Update prefix sum
            if (hours[i] > 8) {
                prefix += 1;
            } else {
                prefix -= 1;
            }

            // If current prefix sum is positive, the interval [0, i] itself is well‑performing
            if (prefix > 0) {
                maxLen = i + 1;
            } else {
                // Record the first occurrence of this prefix sum
                firstIndex.putIfAbsent(prefix, i);
                // Look for a previous prefix sum that is one less (i.e., prefix - 1)
                Integer prevIdx = firstIndex.get(prefix - 1);
                if (prevIdx != null) {
                    int len = i - prevIdx;
                    if (len > maxLen) {
                        maxLen = len;
                    }
                }
            }
        }
        return maxLen;
    }
}

