public class Solution {
    public int longestWPI(int[] hours) {
        int n = hours.length;
        // Transform hours to +1 for tiring (>8) and -1 otherwise
        int[] transformed = new int[n];
        for (int i = 0; i < n; i++) {
            transformed[i] = hours[i] > 8 ? 1 : -1;
        }

        // Prefix sum and hashmap to store earliest index of each sum
        HashMap<Integer, Integer> firstIndex = new HashMap<>();
        int prefix = 0;
        int maxLen = 0;
        firstIndex.put(0, -1); // sum 0 occurs before the array starts

        for (int i = 0; i < n; i++) {
            prefix += transformed[i];

            if (prefix > 0) {
                // Whole interval [0..i] is well‑performing
                maxLen = i + 1;
            } else {
                // Need a previous prefix sum that is one less than current
                if (firstIndex.containsKey(prefix - 1)) {
                    int prevIdx = firstIndex.get(prefix - 1);
                    maxLen = Math.max(maxLen, i - prevIdx);
                }
            }

            // Record earliest occurrence of this prefix sum
            firstIndex.putIfAbsent(prefix, i);
        }

        return maxLen;
    }
}

