import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

public class Solution {
    public boolean parseBoolExpr(String expression) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char ch : expression.toCharArray()) {
            if (ch != ')') {
                // push everything except closing parenthesis
                stack.push(ch);
            } else {
                // evaluate sub‑expression
                List<Boolean> vals = new ArrayList<>();
                while (!stack.isEmpty() && stack.peek() != '(') {
                    char val = stack.pop();
                    if (val == 't') {
                        vals.add(true);
                    } else if (val == 'f') {
                        vals.add(false);
                    }
                    // commas are ignored
                }
                // discard '('
                if (!stack.isEmpty() && stack.peek() == '(') {
                    stack.pop();
                }
                // operator is just before '('
                char op = stack.pop();
                boolean result;
                if (op == '!') {
                    // NOT has exactly one operand
                    result = !vals.get(0);
                } else if (op == '&') {
                    result = true;
                    for (boolean b : vals) {
                        result = result && b;
                    }
                } else { // op == '|'
                    result = false;
                    for (boolean b : vals) {
                        result = result || b;
                    }
                }
                // push result back as character
                stack.push(result ? 't' : 'f');
            }
        }
        // final result is the only remaining character
        return stack.peek() == 't';
    }
}

