public class Solution {
    public boolean parseBoolExpr(String expression) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : expression.toCharArray()) {
            if (c == ',') {
                continue;
            }
            if (c != ')') {
                stack.push(c);
            } else {
                List<Boolean> values = new ArrayList<>();
                while (!stack.isEmpty() && stack.peek() != '(') {
                    char val = stack.pop();
                    if (val == 't') {
                        values.add(true);
                    } else if (val == 'f') {
                        values.add(false);
                    }
                }
                // pop '('
                stack.pop();
                // operator
                char op = stack.pop();
                boolean result;
                if (op == '!') {
                    result = !values.get(0);
                } else if (op == '&') {
                    result = true;
                    for (boolean b : values) {
                        result = result && b;
                        if (!result) break;
                    }
                } else { // op == '|'
                    result = false;
                    for (boolean b : values) {
                        result = result || b;
                        if (result) break;
                    }
                }
                stack.push(result ? 't' : 'f');
            }
        }
        return stack.pop() == 't';
    }
}

