public class Solution {
    public String lastSubstring(String s) {
        if (s == null || s.length() == 0) {
            return s;
        }
        int n = s.length();
        int i = 0; // candidate start
        int j = 1; // next candidate start
        int k = 0; // offset for comparison

        while (j + k < n) {
            char a = s.charAt(i + k);
            char b = s.charAt(j + k);
            if (a == b) {
                k++;
            } else if (a < b) {
                // candidate i is worse, move i forward
                i = i + k + 1;
                if (i <= j) {
                    i = j + 1;
                }
                k = 0;
                j = i + 1;
            } else { // a > b
                // candidate j is worse, move j forward
                j = j + k + 1;
                k = 0;
            }
        }
        int start = Math.min(i, j);
        return s.substring(start);
    }
}

