public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int kConcatenationMaxSum(int[] arr, int k) {
        long totalSum = 0;
        long maxPrefix = Long.MIN_VALUE;
        long cur = 0;
        for (int num : arr) {
            totalSum += num;
            cur += num;
            if (cur > maxPrefix) {
                maxPrefix = cur;
            }
        }

        long maxSuffix = Long.MIN_VALUE;
        cur = 0;
        for (int i = arr.length - 1; i >= 0; i--) {
            cur += arr[i];
            if (cur > maxSuffix) {
                maxSuffix = cur;
            }
        }

        long kadaneSingle = kadane(arr);
        long kadaneDouble = kadaneDouble(arr);

        long result;
        if (k == 1) {
            result = kadaneSingle;
        } else {
            if (totalSum > 0) {
                long cross = maxPrefix + maxSuffix + totalSum * (k - 2);
                result = Math.max(kadaneDouble, cross);
            } else {
                result = kadaneDouble;
            }
        }

        result = Math.max(result, 0); // empty subarray allowed
        return (int) (result % MOD);
    }

    private long kadane(int[] arr) {
        long maxEndingHere = 0;
        long maxSoFar = 0;
        for (int num : arr) {
            maxEndingHere = Math.max(0, maxEndingHere + num);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }
        return maxSoFar;
    }

    private long kadaneDouble(int[] arr) {
        long maxEndingHere = 0;
        long maxSoFar = 0;
        int n = arr.length;
        for (int i = 0; i < 2 * n; i++) {
            int num = arr[i % n];
            maxEndingHere = Math.max(0, maxEndingHere + num);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }
        return maxSoFar;
    }
}

