import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        // Determine the depth (level) of the given label
        int level = 0;
        int temp = label;
        while (temp > 0) {
            level++;
            temp >>= 1;
        }

        LinkedList<Integer> path = new LinkedList<>();
        int current = label;
        int currentLevel = level;

        while (currentLevel >= 1) {
            // prepend current node to the path
            path.addFirst(current);
            if (currentLevel == 1) {
                break; // reached the root
            }
            // Compute the parent label using the zig‑zag transformation formula
            int start = 1 << (currentLevel - 1);               // first label of this level in normal order
            int end = (1 << currentLevel) - 1;                 // last label of this level in normal order
            int parent = (start + (end - current)) / 2;        // parent in the next upper level
            current = parent;
            currentLevel--;
        }

        return path;
    }
}

