public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        LinkedList<Integer> path = new LinkedList<>();
        while (label != 0) {
            path.addFirst(label);
            if (label == 1) {
                break;
            }
            int level = 32 - Integer.numberOfLeadingZeros(label);
            int left = 1 << (level - 1);
            int right = (1 << level) - 1;
            label = left + right - label;
            label >>= 1;
        }
        return path;
    }
}

