import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        LinkedList<Integer> result = new LinkedList<>();
        if (label <= 0) {
            return result;
        }

        // Determine the depth (row) of the given label.
        int depth = 0;
        int temp = label;
        while (temp > 0) {
            depth++;
            temp >>= 1;
        }

        int currentLabel = label;
        int currentDepth = depth;

        while (currentDepth > 0) {
            result.addFirst(currentLabel);

            // Convert current label to the "normal" left‑to‑right label of its row.
            int start = 1 << (currentDepth - 1);
            int end = (1 << currentDepth) - 1;
            int normalLabel = (currentDepth % 2 == 0) ? (start + end - currentLabel) : currentLabel;

            // Parent in the normal tree.
            int parentNormal = normalLabel / 2;
            currentDepth--;

            if (currentDepth == 0) {
                break;
            }

            // Convert parent normal label back to zigzag label for its row.
            int parentStart = 1 << (currentDepth - 1);
            int parentEnd = (1 << currentDepth) - 1;
            currentLabel = (currentDepth % 2 == 0) ? (parentStart + parentEnd - parentNormal) : parentNormal;
        }

        return result;
    }
}

