public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> normalPath = new ArrayList<>();
        int cur = label;
        while (cur > 0) {
            normalPath.add(cur);
            cur >>= 1;
        }
        Collections.reverse(normalPath);
        List<Integer> result = new ArrayList<>(normalPath.size());
        for (int i = 0; i < normalPath.size(); i++) {
            int level = i + 1;
            int val = normalPath.get(i);
            if ((level & 1) == 0) {
                int start = 1 << (level - 1);
                int end = (1 << level) - 1;
                val = start + end - val;
            }
            result.add(val);
        }
        return result;
    }
}

