public class Solution {
    public int[] relativeSortArray(int[] arr1, int[] arr2) {
        // Count frequencies of elements in arr1
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : arr1) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }

        int[] result = new int[arr1.length];
        int idx = 0;

        // Place elements according to the order in arr2
        for (int num : arr2) {
            Integer count = freq.get(num);
            if (count != null) {
                for (int i = 0; i < count; i++) {
                    result[idx++] = num;
                }
                freq.remove(num);
            }
        }

        // Collect remaining elements and sort them
        List<Integer> remaining = new ArrayList<>(freq.keySet());
        Collections.sort(remaining);

        // Append the remaining elements in ascending order
        for (int num : remaining) {
            int count = freq.get(num);
            for (int i = 0; i < count; i++) {
                result[idx++] = num;
            }
        }

        return result;
    }
}

