public class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] left = new int[rows][cols];
        int[][] up = new int[rows][cols];

        // Fill DP tables for consecutive 1s to the left and upwards
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 1) {
                    left[i][j] = (j > 0 ? left[i][j - 1] + 1 : 1);
                    up[i][j] = (i > 0 ? up[i - 1][j] + 1 : 1);
                } else {
                    left[i][j] = 0;
                    up[i][j] = 0;
                }
            }
        }

        int maxSide = 0;

        // Iterate over each cell as the bottom‑right corner of a square
        for (int i = rows - 1; i >= 0; i--) {
            for (int j = cols - 1; j >= 0; j--) {
                // The largest possible side length at this corner
                int possibleSide = Math.min(left[i][j], up[i][j]);
                while (possibleSide > maxSide) {
                    int topRow = i - possibleSide + 1;
                    int leftCol = j - possibleSide + 1;
                    if (topRow < 0 || leftCol < 0) {
                        possibleSide--;
                        continue;
                    }
                    // Check top border and left border
                    if (left[topRow][j] >= possibleSide && up[i][leftCol] >= possibleSide) {
                        maxSide = possibleSide;
                        break; // No need to try smaller sizes for this corner
                    }
                    possibleSide--;
                }
            }
        }

        return maxSide * maxSide;
    }
}

