public class Solution {
    public int longestDecomposition(String text) {
        if (text == null || text.isEmpty()) {
            return 0;
        }
        int n = text.length();
        int left = 0;
        int right = n - 1;
        int count = 0;

        while (left < right) {
            int len = 1;
            boolean matched = false;
            // try to find the smallest prefix starting at left that equals the suffix ending at right
            while (left + len - 1 < right) {
                String prefix = text.substring(left, left + len);
                String suffix = text.substring(right - len + 1, right + 1);
                if (prefix.equals(suffix)) {
                    matched = true;
                    break;
                }
                len++;
            }
            if (!matched) {
                break;
            }
            count += 2;          // one for the prefix, one for the suffix
            left += len;
            right -= len;
        }

        // If there is any remaining middle part (including a single character), it forms one more piece
        if (left <= right) {
            count += 1;
        }

        return count;
    }
}

