import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.ArrayDeque;

public class Solution {
    // red -> 0, blue -> 1
    public int[] shortestAlternatingPaths(int n, int[][] redEdges, int[][] blueEdges) {
        // adjacency lists for red and blue edges
        List<Integer>[] redAdj = new ArrayList[n];
        List<Integer>[] blueAdj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            redAdj[i] = new ArrayList<>();
            blueAdj[i] = new ArrayList<>();
        }
        for (int[] e : redEdges) {
            redAdj[e[0]].add(e[1]);
        }
        for (int[] e : blueEdges) {
            blueAdj[e[0]].add(e[1]);
        }

        // distance answer array, initialized to a large value
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            answer[i] = Integer.MAX_VALUE;
        }
        answer[0] = 0; // distance to self is zero

        // visited[node][color] where color 0 = red, 1 = blue
        boolean[][] visited = new boolean[n][2];
        // queue holds node and the color of the edge used to reach it
        Queue<int[]> q = new ArrayDeque<>();
        // start from node 0 with both possible previous colors
        q.offer(new int[]{0, 0}); // pretend we arrived via a red edge
        q.offer(new int[]{0, 1}); // pretend we arrived via a blue edge
        visited[0][0] = true;
        visited[0][1] = true;

        int steps = 0;
        while (!q.isEmpty()) {
            int size = q.size();
            for (int i = 0; i < size; i++) {
                int[] cur = q.poll();
                int node = cur[0];
                int prevColor = cur[1];
                // update answer for this node with current steps
                if (steps < answer[node]) {
                    answer[node] = steps;
                }
                // choose next edges of opposite color
                if (prevColor == 0) { // came via red, need blue edges
                    for (int nb : blueAdj[node]) {
                        if (!visited[nb][1]) {
                            visited[nb][1] = true;
                            q.offer(new int[]{nb, 1});
                        }
                    }
                } else { // came via blue, need red edges
                    for (int nb : redAdj[node]) {
                        if (!visited[nb][0]) {
                            visited[nb][0] = true;
                            q.offer(new int[]{nb, 0});
                        }
                    }
                }
            }
            steps++;
        }

        // replace unreachable entries with -1
        for (int i = 0; i < n; i++) {
            if (answer[i] == Integer.MAX_VALUE) {
                answer[i] = -1;
            }
        }
        return answer;
    }
}

