        }

        int INF = Integer.MAX_VALUE / 2;
        int[][] dist = new int[n][2];
        for (int i = 0; i < n; i++) {
            dist[i][0] = INF;
            dist[i][1] = INF;
        }
        Queue<int[]> q = new LinkedList<>();
        // start from node 0 with both possible previous colors
        dist[0][0] = 0;
        dist[0][1] = 0;
        q.offer(new int[]{0, 0}); // last edge was red
        q.offer(new int[]{0, 1}); // last edge was blue

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int node = cur[0];
            int lastColor = cur[1];
            int curDist = dist[node][lastColor];

