import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    // red -> 0, blue -> 1
    public int[] shortestAlternatingPaths(int n, int[][] redEdges, int[][] blueEdges) {
        // adjacency lists for each color
        List<Integer>[] redAdj = new ArrayList[n];
        List<Integer>[] blueAdj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            redAdj[i] = new ArrayList<>();
            blueAdj[i] = new ArrayList<>();
        }
        for (int[] e : redEdges) {
            redAdj[e[0]].add(e[1]);
        }
        for (int[] e : blueEdges) {
            blueAdj[e[0]].add(e[1]);
        }

        // distances ending with red (0) or blue (1)
        int[] distRed = new int[n];
        int[] distBlue = new int[n];
        Arrays.fill(distRed, -1);
        Arrays.fill(distBlue, -1);
        distRed[0] = 0;
        distBlue[0] = 0;

        // BFS queue: int[]{node, color}
        Queue<int[]> q = new LinkedList<>();
        // start from node 0 with both colors
        q.offer(new int[]{0, 0}); // pretend previous edge was red, next must be blue
        q.offer(new int[]{0, 1}); // pretend previous edge was blue, next must be red

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int node = cur[0];
            int color = cur[1]; // 0 = red, 1 = blue (color of the edge used to reach this node)
            int curDist = (color == 0) ? distRed[node] : distBlue[node];
            // next color must be opposite
            int nextColor = 1 - color;
            List<Integer> nextAdj = (nextColor == 0) ? redAdj[node] : blueAdj[node];
            for (int nb : nextAdj) {
                if (nextColor == 0) { // arriving via red edge
                    if (distRed[nb] == -1) {
                        distRed[nb] = curDist + 1;
                        q.offer(new int[]{nb, 0});
                    }
                } else { // arriving via blue edge
                    if (distBlue[nb] == -1) {
                        distBlue[nb] = curDist + 1;
                        q.offer(new int[]{nb, 1});
                    }
                }
            }
        }

        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            if (distRed[i] == -1 && distBlue[i] == -1) {
                answer[i] = -1;
            } else if (distRed[i] == -1) {
                answer[i] = distBlue[i];
            } else if (distBlue[i] == -1) {
                answer[i] = distRed[i];
            } else {
                answer[i] = Math.min(distRed[i], distBlue[i]);
            }
        }
        return answer;
    }
}

