        Map<Character, Integer> temp = new HashMap<>(source);
        for (char c : word.toCharArray()) {
            Integer cnt = temp.get(c);
            if (cnt == null || cnt == 0) {
                return false;
            }
            temp.put(c, cnt - 1);
        }
        return true;
    }
