public class Solution {
    public String alphabetBoardPath(String target) {
        StringBuilder sb = new StringBuilder();
        int curRow = 0, curCol = 0;
        for (char ch : target.toCharArray()) {
            int idx = ch - 'a';
            int targetRow = idx / 5;
            int targetCol = idx % 5;
            // special case for 'z' which is at (5,0)
            if (ch == 'z') {
                targetRow = 5;
                targetCol = 0;
            }

            int dr = targetRow - curRow;
            int dc = targetCol - curCol;

            if (dr < 0) { // move up first
                for (int i = 0; i < -dr; i++) sb.append('U');
                if (dc < 0) {
                    for (int i = 0; i < -dc; i++) sb.append('L');
                } else if (dc > 0) {
                    for (int i = 0; i < dc; i++) sb.append('R');
                }
            } else if (dr > 0) { // move down, horizontal first
                if (dc < 0) {
                    for (int i = 0; i < -dc; i++) sb.append('L');
                } else if (dc > 0) {
                    for (int i = 0; i < dc; i++) sb.append('R');
                }
                for (int i = 0; i < dr; i++) sb.append('D');
            } else { // same row, only horizontal moves
                if (dc < 0) {
                    for (int i = 0; i < -dc; i++) sb.append('L');
                } else if (dc > 0) {
                    for (int i = 0; i < dc; i++) sb.append('R');
                }
            }

            sb.append('!');
            curRow = targetRow;
            curCol = targetCol;
        }
        return sb.toString();
    }
}

