    /**
     * Returns the maximum value of |arr1[i] - arr1[j]| + |arr2[i] - arr2[j]| + |i - j|
     * over all pairs (i, j).
     *
     * @param arr1 first integer array
     * @param arr2 second integer array (same length as arr1)
     * @return the maximum achievable expression value
     */
    public int maxAbsValExpr(int[] arr1, int[] arr2) {
        int n = arr1.length;
        int answer = 0;

        // There are 2^3 = 8 possible sign combinations for the three terms.
        // For each combination we keep track of the minimum and maximum of the
        // transformed value p*arr1[i] + q*arr2[i] + r*i.
        for (int mask = 0; mask < 8; mask++) {
            int signA = ((mask & 1) == 0) ? 1 : -1;   // sign for arr1[i]
            int signB = ((mask & 2) == 0) ? 1 : -1;   // sign for arr2[i]
            int signI = ((mask & 4) == 0) ? 1 : -1;   // sign for index i

            int minVal = Integer.MAX_VALUE;
            int maxVal = Integer.MIN_VALUE;

            for (int i = 0; i < n; i++) {
                int cur = signA * arr1[i] + signB * arr2[i] + signI * i;
                if (cur < minVal) minVal = cur;
                if (cur > maxVal) maxVal = cur;
            }

            int candidate = maxVal - minVal;
            if (candidate > answer) answer = candidate;
        }

        return answer;
    }
