public class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int[] wordFreq = new int[words.length];
        for (int i = 0; i < words.length; i++) {
            wordFreq[i] = smallestCharFrequency(words[i]);
        }
        Arrays.sort(wordFreq);

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int qFreq = smallestCharFrequency(queries[i]);
            int idx = upperBound(wordFreq, qFreq);
            answer[i] = wordFreq.length - idx;
        }
        return answer;
    }

    private int smallestCharFrequency(String s) {
        char minChar = 'z' + 1;
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < minChar) {
                minChar = c;
                count = 1;
            } else if (c == minChar) {
                count++;
            }
        }
        return count;
    }

    // Returns first index of element > target (upper bound)
    private int upperBound(int[] arr, int target) {
        int left = 0, right = arr.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (arr[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

