import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    private List<List<Integer>> result;
    private List<Integer>[] graph;
    private int[] rank;

    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // initialize structures
        result = new ArrayList<>();
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (List<Integer> edge : connections) {
            int a = edge.get(0);
            int b = edge.get(1);
            graph[a].add(b);
            graph[b].add(a);
        }
        rank = new int[n];
        Arrays.fill(rank, -2); // -2 means unvisited

        // start DFS from node 0 (graph is connected)
        dfs(0, 0, -1);
        return result;
    }

    private int dfs(int node, int depth, int parent) {
        rank[node] = depth;
        int minLow = depth;

        for (int nei : graph[node]) {
            if (nei == parent) {
                continue; // skip the edge leading back to parent
            }
            if (rank[nei] == -2) { // not visited
                int low = dfs(nei, depth + 1, node);
                // if low > depth, edge (node,nei) is a bridge
                if (low > depth) {
                    result.add(Arrays.asList(node, nei));
                }
                minLow = Math.min(minLow, low);
            } else {
                // back edge
                minLow = Math.min(minLow, rank[nei]);
            }
        }
        return minLow;
    }
}

