import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    private List<Integer>[] graph;
    private int[] rank;
    private List<List<Integer>> bridges;

    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // build adjacency list
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (List<Integer> edge : connections) {
            int u = edge.get(0);
            int v = edge.get(1);
            graph[u].add(v);
            graph[v].add(u);
        }

        rank = new int[n];
        Arrays.fill(rank, -2); // -2 indicates unvisited
        bridges = new ArrayList<>();

        // run DFS from node 0 (graph is connected)
        dfs(0, 0, -1);

        return bridges;
    }

    private int dfs(int node, int depth, int parent) {
        if (rank[node] >= 0) {
            // already visited, return its rank
            return rank[node];
        }
        rank[node] = depth;
        int minRank = depth;

        for (int nei : graph[node]) {
            if (nei == parent) {
                continue; // skip the edge we came from
            }
            int neiRank;
            if (rank[nei] == -2) {
                // not visited yet
                neiRank = dfs(nei, depth + 1, node);
                // if the lowest reachable rank from neighbor is greater than current depth,
                // the edge (node, nei) is a bridge
                if (neiRank > depth) {
                    bridges.add(Arrays.asList(node, nei));
                }
            } else {
                // visited neighbor, use its rank directly
                neiRank = rank[nei];
            }
            minRank = Math.min(minRank, neiRank);
        }

        rank[node] = minRank;
        return minRank;
    }
}

