                    List<Integer>[] graph, int[] rank,
                    List<List<Integer>> bridges) {
        rank[node] = depth;
        int minBack = depth;

        for (int nei : graph[node]) {
            if (nei == parent) {
                continue; // skip the edge leading back to parent
            }
            if (rank[nei] == -2) { // not visited
                int low = dfs(nei, depth + 1, node, graph, rank, bridges);
                if (low > depth) {
                    // edge (node, nei) is a bridge
                    bridges.add(Arrays.asList(node, nei));
                }
                minBack = Math.min(minBack, low);
            } else {
                // visited neighbor, update low with its discovery rank
                minBack = Math.min(minBack, rank[nei]);
            }
        }
        return minBack;
    }
}

