import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    private List<Integer>[] graph;
    private int[] rank;
    private int timer;
    private List<List<Integer>> bridges;

    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        // build graph
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (List<Integer> edge : connections) {
            int u = edge.get(0);
            int v = edge.get(1);
            graph[u].add(v);
            graph[v].add(u);
        }

        rank = new int[n];
        Arrays.fill(rank, -2); // -2 means unvisited
        timer = 0;
        bridges = new ArrayList<>();

        // run dfs from every unvisited node (graph is connected but safe)
        for (int i = 0; i < n; i++) {
            if (rank[i] == -2) {
                dfs(i, -1);
            }
        }

        return bridges;
    }

    private int dfs(int node, int parent) {
        rank[node] = timer++;
        int minReachable = rank[node];

        for (int nei : graph[node]) {
            if (nei == parent) {
                continue; // skip the edge we came from
            }
            if (rank[nei] == -2) { // not visited
                int childMin = dfs(nei, node);
                // if the lowest reachable rank from neighbor is greater than current node's rank,
                // the edge (node, nei) is a bridge
                if (childMin > rank[node]) {
                    bridges.add(Arrays.asList(node, nei));
                }
                minReachable = Math.min(minReachable, childMin);
            } else {
                // back edge, update minReachable with neighbor's rank
                minReachable = Math.min(minReachable, rank[nei]);
            }
        }

        return minReachable;
    }
}

