public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int minNonZeroProduct(int p) {
        long max = (1L << p) - 1;          // 2^p - 1
        long maxMinusOne = max - 1;        // 2^p - 2
        long exp = 1L << (p - 1);          // 2^{p-1}

        long part1 = modPow(maxMinusOne, exp, MOD);
        long part2 = modPow(max, exp - 1, MOD);

        long result = (part1 * part2) % MOD;
        return (int) result;
    }

    private long modPow(long base, long exp, long mod) {
        long result = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

