import java.util.*;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        // Count frequencies of all subset sums
        TreeMap<Integer, Integer> freq = new TreeMap<>();
        for (int v : sums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }

        List<Integer> answer = new ArrayList<>();
        List<Integer> curSums = new ArrayList<>();
        curSums.add(0); // empty subset sum

        // The empty subset sum (0) must exist exactly once
        decrement(freq, 0);

        while (answer.size() < n) {
            // smallest remaining sum is the next candidate element (could be negative)
            int candidate = freq.firstKey();

            List<Integer> added = new ArrayList<>();
            if (!tryRemove(candidate, curSums, freq, added)) {
                // candidate was wrong, try its opposite
                added.clear();
                candidate = -candidate;
                // this must succeed according to problem guarantees
                tryRemove(candidate, curSums, freq, added);
            }

            answer.add(candidate);
            curSums.addAll(added);
        }

        int[] res = new int[answer.size()];
        for (int i = 0; i < answer.size(); i++) {
            res[i] = answer.get(i);
        }
        return res;
    }

    // Decrease count of key in map, removing entry if count reaches zero
    private void decrement(TreeMap<Integer, Integer> map, int key) {
        int cnt = map.getOrDefault(key, 0);
        if (cnt == 1) {
            map.remove(key);
        } else if (cnt > 1) {
            map.put(key, cnt - 1);
        }
    }

    // Attempt to remove all sums generated by adding 'candidate' to existing sums.
    // Returns true if removal succeeded, false otherwise (map unchanged).
    private boolean tryRemove(int candidate, List<Integer> curSums,
                              TreeMap<Integer, Integer> map, List<Integer> added) {
        // Count needed frequencies
        HashMap<Integer, Integer> need = new HashMap<>();
        for (int s : curSums) {
            int val = s + candidate;
            need.put(val, need.getOrDefault(val, 0) + 1);
        }

        // Verify availability
        for (Map.Entry<Integer, Integer> e : need.entrySet()) {
            int key = e.getKey();
            int required = e.getValue();
            if (map.getOrDefault(key, 0) < required) {
                return false;
            }
        }

        // Perform removal and record added sums
        for (Map.Entry<Integer, Integer> e : need.entrySet()) {
            int key = e.getKey();
            int required = e.getValue();
            int remaining = map.get(key) - required;
            if (remaining == 0) {
                map.remove(key);
            } else {
                map.put(key, remaining);
            }
            for (int i = 0; i < required; i++) {
                added.add(key);
            }
        }
        return true;
    }
}

