public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        List<Integer> sumList = new ArrayList<>(sums.length);
        for (int v : sums) sumList.add(v);
        Collections.sort(sumList);
        List<Integer> result = new ArrayList<>(n);
        recover(n, sumList, result);
        int[] ans = new int[result.size()];
        for (int i = 0; i < ans.length; i++) ans[i] = result.get(i);
        return ans;
    }

    private void recover(int n, List<Integer> sums, List<Integer> result) {
        if (n == 0) return;
        // smallest sum is always the sum of the chosen subset without the smallest element (often 0)
        int smallest = sums.get(0);
        int second = sums.get(1);
        int candidate = second - smallest;

        // Partition sums into two groups: without candidate and with candidate
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : sums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }

        List<Integer> without = new ArrayList<>(sums.size() / 2);
        List<Integer> with = new ArrayList<>(sums.size() / 2);

        for (int v : sums) {
            int count = freq.getOrDefault(v, 0);
            if (count == 0) continue;
            // take v into 'without'
            without.add(v);
            freq.put(v, count - 1);
            // corresponding value in 'with' is v + candidate
            int w = v + candidate;
            freq.put(w, freq.get(w) - 1);
            with.add(w);
        }

        // Decide the sign of the element
        if (without.contains(0)) {
            // candidate is the actual element (could be zero)
            result.add(candidate);
            recover(n - 1, without, result);
        } else {
            // actual element is -candidate
            result.add(-candidate);
            recover(n - 1, with, result);
        }
    }
}

