public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        Arrays.sort(sums);
        List<Integer> curSums = new ArrayList<>();
        for (int v : sums) {
            curSums.add(v);
        }

        List<Integer> ans = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            // the smallest element in curSums is always 0
            int x = curSums.get(1) - curSums.get(0); // candidate element

            TreeMap<Integer, Integer> mult = new TreeMap<>();
            for (int v : curSums) {
                mult.put(v, mult.getOrDefault(v, 0) + 1);
            }

            List<Integer> without = new ArrayList<>();

            while (!mult.isEmpty()) {
                int smallest = mult.firstKey();
                without.add(smallest);
                decrement(mult, smallest);
                int with = smallest + x;
                decrement(mult, with);
            }

            if (without.contains(0)) {
                ans.add(x);
                curSums = without;
            } else {
                ans.add(-x);
                List<Integer> withGroup = new ArrayList<>();
                for (int v : without) {
                    withGroup.add(v + x);
                }
                curSums = withGroup;
            }
            // without (or withGroup) is already sorted because we extracted in order
        }

        int[] result = new int[ans.size()];
        for (int i = 0; i < ans.size(); i++) {
            result[i] = ans.get(i);
        }
        return result;
    }

    private void decrement(TreeMap<Integer, Integer> map, int key) {
        int cnt = map.get(key);
        if (cnt == 1) {
            map.remove(key);
        } else {
            map.put(key, cnt - 1);
        }
    }
}

