public class Solution {

    public int[] recoverArray(int n, int[] sums) {
        List<Integer> sumList = new ArrayList<>(sums.length);
        for (int v : sums) sumList.add(v);
        List<Integer> ansList = new ArrayList<>(n);
        recover(n, sumList, ansList);
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) ans[i] = ansList.get(i);
        return ans;
