    private void recover(int n, List<Integer> sums, List<Integer> result) {
        if (n == 0) {
            return;
        }
        Collections.sort(sums);
        int min = sums.get(0);
        int second = sums.get(1);
        int diff = second - min; // candidate absolute value of the next element

        // Try the candidate as positive diff
        if (tryCandidate(diff, n, sums, result)) {
            return;
        }
        // Otherwise try the candidate as negative diff
        tryCandidate(-diff, n, sums, result);
    }

    private boolean tryCandidate(int x, int n, List<Integer> sums, List<Integer> result) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int v : sums) {
            cnt.put(v, cnt.getOrDefault(v, 0) + 1);
        }

        List<Integer> without = new ArrayList<>(sums.size() / 2);
        for (int v : sums) {
            int c = cnt.getOrDefault(v, 0);
            if (c == 0) continue;
            // use v
            cnt.put(v, c - 1);
            int v2 = v + x;
            int c2 = cnt.getOrDefault(v2, 0);
            if (c2 == 0) {
                return false; // not a valid partition
            }
            cnt.put(v2, c2 - 1);
            without.add(v);
        }

        result.add(x);
        recover(n - 1, without, result);
        return true;
    }
}

