import java.util.*;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        List<Integer> sumList = new ArrayList<>();
        for (int v : sums) sumList.add(v);
        Collections.sort(sumList);
        List<Integer> answer = new ArrayList<>();

        while (answer.size() < n) {
            int min = sumList.get(0);
            int second = sumList.get(1);
            int candidate = second - min;

            Map<Integer, Integer> freq = new HashMap<>();
            for (int v : sumList) {
                freq.put(v, freq.getOrDefault(v, 0) + 1);
            }

            List<Integer> without = new ArrayList<>();
            List<Integer> with = new ArrayList<>();

            for (int v : sumList) {
                int cnt = freq.getOrDefault(v, 0);
                if (cnt == 0) continue;

                // v belongs to the group without the candidate element
                without.add(v);
                freq.put(v, cnt - 1);

                int vWith = v + candidate;
                freq.put(vWith, freq.get(vWith) - 1);
                with.add(vWith);
            }

            if (without.contains(0)) {
                answer.add(candidate);
                sumList = without;
            } else {
                answer.add(-candidate);
                sumList = with;
            }
        }

        int[] res = new int[answer.size()];
        for (int i = 0; i < answer.size(); i++) {
            res[i] = answer.get(i);
        }
        return res;
    }
}

