import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public String kthLargestNumber(String[] nums, int k) {
        // Sort the array in descending order based on numeric value.
        Arrays.sort(nums, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                // First compare by length (longer string means larger number)
                if (a.length() != b.length()) {
                    return b.length() - a.length(); // descending
                }
                // Lengths are equal, compare lexicographically
                return b.compareTo(a); // descending
            }
        });
        // k is 1‑based, array index is 0‑based
        return nums[k - 1];
    }
}

