public class Solution {
    public boolean canBeIncreasing(int[] nums) {
        int n = nums.length;
        if (n <= 2) {
            return true;
        }
        int violations = 0;
        int idx = -1;
        for (int i = 1; i < n; i++) {
            if (nums[i] <= nums[i - 1]) {
                violations++;
                idx = i;
                if (violations > 1) {
                    return false;
                }
            }
        }
        if (violations == 0) {
            return true;
        }
        // Only one violation at position idx
        // If removing nums[idx] or nums[idx-1] fixes the sequence
        if (idx == 1 || idx == n - 1) {
            return true;
        }
        // Check if removing nums[idx-1] works
        if (nums[idx] > nums[idx - 2]) {
            return true;
        }
        // Check if removing nums[idx] works
        if (idx + 1 < n && nums[idx + 1] > nums[idx - 1]) {
            return true;
        }
        return false;
    }
}

