public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int numberOfUniqueGoodSubsequences(String binary) {
        long dp0 = 0; // distinct good subsequences ending with '0' (starting with '1')
        long dp1 = 0; // distinct good subsequences ending with '1'
        boolean hasZero = false;

        for (int i = 0; i < binary.length(); i++) {
            char c = binary.charAt(i);
            if (c == '0') {
                hasZero = true;
                long totalPrev = (dp0 + dp1) % MOD;
                dp0 = totalPrev; // do not add the single "0" here
            } else { // c == '1'
                long totalPrev = (dp0 + dp1) % MOD;
                dp1 = (totalPrev + 1) % MOD; // add the subsequence consisting of this single '1'
            }
        }

        long result = (dp0 + dp1) % MOD;
        if (hasZero) {
            result = (result + 1) % MOD; // add the subsequence "0"
        }
        return (int) result;
    }
}

