        for (int i = 0; i < binary.length(); i++) {
            char c = binary.charAt(i);
            if (c == '1') {
                long add = (good + 1) % MOD;          // new subsequences formed by appending '1'
                long newGood = (good + add - lastAdd1) % MOD;
                if (newGood < 0) newGood += MOD;
                good = newGood;
                lastAdd1 = add;
            } else { // c == '0'
                zeroSeen = true;
                long add = good % MOD;                 // extend existing good subsequences with '0'
                long newGood = (good + add - lastAdd0) % MOD;
                if (newGood < 0) newGood += MOD;
                good = newGood;
                lastAdd0 = add;
            }
        }

        long result = good;
        if (zeroSeen) {
            result = (result + 1) % MOD; // count the subsequence "0"
        }
        return (int) result;
    }
}

