public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfUniqueGoodSubsequences(String binary) {
        long total = 0;                 // distinct good subsequences that start with '1'
        long[] last = new long[2];      // last contribution for '0' and '1'
        boolean hasZero = false;

        for (int i = 0; i < binary.length(); i++) {
            char ch = binary.charAt(i);
            int idx = ch - '0';
            if (ch == '0') hasZero = true;

            long prevTotal = total;

            long add;
            if (ch == '1') {
                // start new subsequence "1" or extend any existing good subsequence
                add = (prevTotal + 1) % MOD;
            } else { // '0'
                // can only extend existing good subsequences that already start with '1'
                add = prevTotal % MOD;
            }

            // remove duplicates caused by previous occurrence of the same character
            add = (add - last[idx] + MOD) % MOD;

            total = (total + add) % MOD;

            // store the raw contribution for this character for future duplicate removal
            if (ch == '1') {
                last[idx] = (prevTotal + 1) % MOD;
            } else {
                last[idx] = prevTotal % MOD;
            }
        }

        long result = total;
        if (hasZero) {
            result = (result + 1) % MOD; // add the subsequence "0"
        }
        return (int) result;
    }
}

