import java.util.Arrays;

public class Solution {
    public int[] rearrangeArray(int[] nums) {
        int n = nums.length;
        if (n < 3) {
            // Any arrangement works when length is less than 3
            return nums.clone();
        }
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int[] result = new int[n];
        int smallSize = (n + 1) / 2; // size of the smaller half
        int smallIdx = 0;
        int largeIdx = smallSize;
        int pos = 0;
        while (smallIdx < smallSize && largeIdx < n) {
            result[pos++] = sorted[smallIdx++];
            result[pos++] = sorted[largeIdx++];
        }
        // If there is an extra element in the small half (when n is odd)
        while (smallIdx < smallSize) {
            result[pos++] = sorted[smallIdx++];
        }
        return result;
    }
}

