public class Solution {
    public int eliminateMaximum(int[] dist, int[] speed) {
        int n = dist.length;
        int[] reachTime = new int[n];
        for (int i = 0; i < n; i++) {
            // time (in whole minutes) when the monster reaches the city
            // if it reaches exactly at minute k, we lose before we can act at minute k
            // therefore we use ceiling of dist/speed
            reachTime[i] = (dist[i] + speed[i] - 1) / speed[i];
        }
        Arrays.sort(reachTime);
        int eliminated = 0;
        for (int i = 0; i < n; i++) {
            // at minute i we can eliminate one monster
            if (reachTime[i] <= i) {
                break;
            }
            eliminated++;
        }
        return eliminated;
    }
}

