public class Solution {
    public long maxMatrixSum(int[][] matrix) {
        long sumAbs = 0L;
        int negCount = 0;
        int minAbs = Integer.MAX_VALUE;
        for (int[] row : matrix) {
            for (int val : row) {
                int absVal = Math.abs(val);
                sumAbs += absVal;
                if (val < 0) {
                    negCount++;
                }
                if (absVal < minAbs) {
                    minAbs = absVal;
                }
            }
        }
        if (negCount % 2 == 0) {
            return sumAbs;
        } else {
            return sumAbs - 2L * minAbs;
        }
    }
}

