public class Solution {
    public int minSwaps(String s) {
        int balance = 0;
        int minBalance = 0; // most negative balance encountered
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') {
                balance++;
            } else { // c == ']'
                balance--;
            }
            if (balance < minBalance) {
                minBalance = balance;
            }
        }
        // minBalance is <= 0. Each swap can fix two positions, so the answer is ceil(-minBalance / 2)
        return (-minBalance + 1) / 2;
    }
}

