public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int layers = Math.min(m, n) / 2;
        for (int layer = 0; layer < layers; layer++) {
            int top = layer;
            int left = layer;
            int bottom = m - 1 - layer;
            int right = n - 1 - layer;

            List<Integer> elements = new ArrayList<>();

            // top row
            for (int col = left; col <= right; col++) {
                elements.add(grid[top][col]);
            }
            // right column
            for (int row = top + 1; row <= bottom - 1; row++) {
                elements.add(grid[row][right]);
            }
            // bottom row
            for (int col = right; col >= left; col--) {
                elements.add(grid[bottom][col]);
            }
            // left column
            for (int row = bottom - 1; row >= top + 1; row--) {
                elements.add(grid[row][left]);
            }

            int len = elements.size();
            int shift = k % len;
            if (shift != 0) {
                List<Integer> rotated = new ArrayList<>(len);
                for (int i = 0; i < len; i++) {
                    rotated.add(elements.get((i + shift) % len));
                }
                elements = rotated;
            }

            int idx = 0;
            // write back top row
            for (int col = left; col <= right; col++) {
                grid[top][col] = elements.get(idx++);
            }
            // write back right column
            for (int row = top + 1; row <= bottom - 1; row++) {
                grid[row][right] = elements.get(idx++);
            }
            // write back bottom row
            for (int col = right; col >= left; col--) {
                grid[bottom][col] = elements.get(idx++);
            }
            // write back left column
            for (int row = bottom - 1; row >= top + 1; row--) {
                grid[row][left] = elements.get(idx++);
            }
        }
        return grid;
    }
}

