            for (int i = top + 1; i <= bottom - 1; i++) {
                grid[i][right] = elements.get(idx++);
            }
            // bottom row
            for (int j = right; j >= left; j--) {
                grid[bottom][j] = elements.get(idx++);
            }
            // left column
            for (int i = bottom - 1; i >= top + 1; i--) {
                grid[i][left] = elements.get(idx++);
            }
        }
        return grid;
    }
}

