public class Solution {
    private int[][] score;
    private int m;
    private int[] memo;

    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        m = students.length;
        score = new int[m][m];
        // Pre‑compute compatibility scores
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int cnt = 0;
                for (int k = 0; k < students[i].length; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        cnt++;
                    }
                }
                score[i][j] = cnt;
            }
        }
        memo = new int[1 << m];
        Arrays.fill(memo, -1);
        return dfs(0);
    }

    private int dfs(int mask) {
        int studentIdx = Integer.bitCount(mask);
        if (studentIdx == m) {
            return 0;
        }
        if (memo[mask] != -1) {
            return memo[mask];
        }
        int best = 0;
        for (int mentor = 0; mentor < m; mentor++) {
            if ((mask & (1 << mentor)) == 0) {
                int candidate = score[studentIdx][mentor] + dfs(mask | (1 << mentor));
                if (candidate > best) {
                    best = candidate;
                }
            }
        }
        memo[mask] = best;
        return best;
    }
}

