public class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.length;
        int n = students[0].length;
        int[][] score = new int[m][m];

        // Pre‑compute compatibility scores for every student‑mentor pair
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int same = 0;
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        same++;
                    }
                }
                score[i][j] = same;
            }
        }

        int totalMasks = 1 << m;
        int[] dp = new int[totalMasks];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        // DP over subsets: mask indicates which mentors are already assigned
        for (int mask = 0; mask < totalMasks; mask++) {
            if (dp[mask] < 0) continue; // unreachable state
            int studentIdx = Integer.bitCount(mask); // next student to assign
            if (studentIdx >= m) continue;
            for (int mentor = 0; mentor < m; mentor++) {
                if ((mask & (1 << mentor)) == 0) {
                    int nextMask = mask | (1 << mentor);
                    int candidate = dp[mask] + score[studentIdx][mentor];
                    if (candidate > dp[nextMask]) {
                        dp[nextMask] = candidate;
                    }
                }
            }
        }

        return dp[totalMasks - 1];
    }
}

