public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] ans = new int[n];
        int[] tails = new int[n];
        int len = 0;
        for (int i = 0; i < n; i++) {
            int x = obstacles[i];
            int lo = 0, hi = len;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails[mid] <= x) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            int pos = lo;
            tails[pos] = x;
            if (pos == len) {
                len++;
            }
            ans[i] = pos + 1;
        }
        return ans;
    }
}

