public class Solution {
    public int maxProductDifference(int[] nums) {
        // Initialize max values to smallest possible and min values to largest possible
        int max1 = Integer.MIN_VALUE, max2 = Integer.MIN_VALUE;
        int min1 = Integer.MAX_VALUE, min2 = Integer.MAX_VALUE;

        for (int num : nums) {
            // Update max values
            if (num > max1) {
                max2 = max1;
                max1 = num;
            } else if (num > max2) {
                max2 = num;
            }

            // Update min values
            if (num < min1) {
                min2 = min1;
                min1 = num;
            } else if (num < min2) {
                min2 = num;
            }
        }

        long productMax = (long) max1 * max2;
        long productMin = (long) min1 * min2;
        return (int) (productMax - productMin);
    }
}

